            collection: FIRST_SEEN_COLLECTION,
            key: key,
            userId: SYSTEM_USER,
            value: { userId: userId, gameId: gameId, firstSeenDate: dateStr, firstSeenUnix: unixTs || utils.getUnixTimestamp() },
            permissionRead: 2,
            permissionWrite: 0,
            version: "*"
