function __ModuleInit_18(ctx, logger, nk, initializer) {
    __rpc_analytics_rollup_run = __rpc_analytics_rollup_run || (rpcAnalyticsRollupRun);
    // Alias: dashboard Admin panel calls analytics_run_rollup; forward to same handler.
    __rpc_analytics_run_rollup = __rpc_analytics_run_rollup || (rpcAnalyticsRollupRun);
    __rpc_analytics_rollup_backfill = __rpc_analytics_rollup_backfill || (rpcAnalyticsRollupBackfill);
    __rpc_analytics_rollup_status = __rpc_analytics_rollup_status || (rpcAnalyticsRollupStatus);
    __rpc_analytics_modes_daily_read = __rpc_analytics_modes_daily_read || (rpcAnalyticsModesDailyRead);
    __rpc_analytics_dropoff_daily_read = __rpc_analytics_dropoff_daily_read || (rpcAnalyticsDropoffDailyRead);
    __rpc_analytics_question_daily_read = __rpc_analytics_question_daily_read || (rpcAnalyticsQuestionDailyRead);
    __rpc_analytics_offer_daily_read = __rpc_analytics_offer_daily_read || (rpcAnalyticsOfferDailyRead);
    __rpc_analytics_revenue_verify = __rpc_analytics_revenue_verify || (rpcAnalyticsRevenueVerify);
    __rpc_analytics_revenue_purge = __rpc_analytics_revenue_purge || (rpcAnalyticsRevenuePurge);
    __rpc_analytics_events_purge = __rpc_analytics_events_purge || (rpcAnalyticsEventsPurge);
    logger.info("[analytics_rollup] Module registered: 11 RPCs (run, run_alias, backfill, status, modes_daily_read, dropoff_daily_read, question_daily_read, offer_daily_read, revenue_verify, revenue_purge, events_purge)");
}


// --- Module: analytics\satori_identity\analytics_satori_identity.js ---
// analytics_satori_identity.js — Phase 5 (2026-05) Satori identity sync.
//
// Goal: use analytics as truth, Satori as targeting/delivery.
//
// This module computes 10 analytical identity traits from each player's
// GPA (game_player_analytics) document and pushes them to Satori as
// custom identity properties via sdPropertiesUpdate. Once these traits are
// in Satori, the live-ops team can build audiences, run experiments, and
// fire personalised push/offer campaigns without writing backend queries.
//
// ─── The 10 traits ──────────────────────────────────────────────────────────
//
//   skill_band          "beginner" | "intermediate" | "expert"
//                       Derived from eng.avg_accuracy + eng.total_answered.
//
//   favorite_mode       string (most-played quiz mode from fav_mode)
//
//   favorite_topic      string (top key from mode_counts as best available proxy;
//                       null when no data)
//
//   spend_tier          "non_spender" | "low" | "mid" | "high"
//                       Derived from money.iap_count + money.spend_usd.
//
//   ad_tolerance        "low" | "medium" | "high"
//                       Derived from money.ad_completions / (ad_completions + ad_skips).
//
//   churn_risk          "low" | "medium" | "high"
//                       Derived from days since last active (last_active_utc).
//
//   price_sensitivity   "sensitive" | "moderate" | "low"
//                       Derived from paywall_shown_count vs iap_count.
//
//   best_play_hour      "0"–"23" UTC hour of peak session activity, or null.
//                       Derived by scanning gpa.sessions start timestamps.
//
//   country_tier        "t1" | "t2" | "t3"
//                       T1 = US/UK/AU/CA/JP/KR/DE/FR/NL/SE/NO/DK/CH/SG/HK
//                       T2 = BR/MX/TR/PL/RU/ZA/TH/MY/ID/PH/NG/UA/CZ/RO
//                       T3 = everything else
//
//   install_age_days    days since first_seen_utc (integer, capped at 9999)
//
// ─── Registered RPCs ────────────────────────────────────────────────────────
//
//   satori_identity_sync
//     Compute traits for ONE user and push to Satori.
//     Payload: { user_id: "<uuid>", game_id?, force?: bool }
//     Admin-gated; also callable by the user for their own profile.
//
//   satori_identity_batch
//     Scan GPA docs and sync up to `limit` users per call.
//     Payload: { game_id?, limit?: 50–500, cursor? }
//     Designed for a cron tick or manual backfill. Idempotent.
//
//   satori_get_flags
//     Fetch Satori flags for the calling user (or admin-specified user_id)
//     via sdFlagsList, then fire a `flag_exposure` event for each returned
//     flag so A/B coverage is visible in analytics.
//     Payload: { user_id? (admin only) }
//
// ─── Identity-sync state ────────────────────────────────────────────────────
//
//   Last-sync timestamp stored in analytics_satori_id_state/<userId>_<gameId>
//   so batch runs skip recently-synced identities and batch operations can
//   resume where they left off.  Re-sync frequency: 24 h by default.

var SI_SYSTEM_USER      = "00000000-0000-0000-0000-000000000000";
var SI_ADMIN_COLLECTION = "admin_users";
var SI_GPA_COLLECTION   = "game_player_analytics";
var SI_STATE_COLLECTION = "analytics_satori_id_state";
var SI_DEFAULT_GAME_ID  = "126bf539-dae2-4bcf-964d-316c0fa1f92b"; // QuizVerse

// Minimum seconds between re-syncs for the same user. The batch RPC
// skips anyone synced more recently than this threshold so a single
// cron call doesn't hammer Satori with redundant PUT /v1/properties.
var SI_RESYNC_INTERVAL_SEC = 24 * 3600; // 24 hours

// Re-probe backoff for users that had NO GPA doc at sync time. The old code
// wrote synced_at on the no_gpa path even though nothing was pushed, which
// blocked retries for the full 24h window. We now record probed_at instead,
// and only skip if the last probe was within this much shorter interval —
// so a user whose GPA doc appears minutes later gets synced within the hour.
var SI_NO_GPA_PROBE_INTERVAL_SEC = 3600; // 1 hour

// Max users to sync per batch call (caller can request less).
var SI_BATCH_MAX = 500;
var SI_BATCH_DEFAULT = 100;

// ─── Country-tier lookup ─────────────────────────────────────────────────────
var SI_COUNTRY_T1 = {
    "US":1,"GB":1,"AU":1,"CA":1,"JP":1,"KR":1,"DE":1,"FR":1,"NL":1,
    "SE":1,"NO":1,"DK":1,"FI":1,"CH":1,"AT":1,"IE":1,"NZ":1,"SG":1,
    "HK":1,"IL":1,"BE":1,"LU":1,"IT":1,"ES":1
};
var SI_COUNTRY_T2 = {
    "BR":1,"MX":1,"TR":1,"PL":1,"RU":1,"ZA":1,"TH":1,"MY":1,"ID":1,
    "PH":1,"NG":1,"UA":1,"CZ":1,"RO":1,"HU":1,"AR":1,"CL":1,"CO":1,
    "PE":1,"VN":1,"EG":1,"SA":1,"AE":1,"QA":1,"KW":1,"PK":1,"BD":1
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function siParse(payload) {
    try { return JSON.parse(payload || "{}"); } catch (e) { return {}; }
}

function siOk(data) {
    var out = { success: true };
    if (data) for (var k in data) if (Object.prototype.hasOwnProperty.call(data, k)) out[k] = data[k];
    return JSON.stringify(out);
}

function siErr(msg, code) {
    return JSON.stringify({ success: false, error: msg || "error", code: code || 400 });
}

function siEnv(ctx, key) {
    if (key === "DASHBOARD_SECRET" && typeof AA_FALLBACK_DASHBOARD_SECRET === "string") {
        return AA_FALLBACK_DASHBOARD_SECRET;
    }
    try {
        if (ctx && ctx.env && ctx.env[key]) {
            var v = String(ctx.env[key]).trim();
            if (v.length > 0) return v;
        }
    } catch (e) { /* */ }
    return "";
}

function siIsAdmin(ctx, nk) {
    if (!ctx.userId) return false;
    if (ctx.userId === SI_SYSTEM_USER) return true;
    if (!ctx.username || ctx.username.indexOf("admin:") !== 0) return false;
    try {
        var recs = nk.storageRead([{ collection: SI_ADMIN_COLLECTION, key: "profile", userId: ctx.userId }]);
        if (!recs || recs.length === 0) return false;
        var r = recs[0].value || {};
        if (!r.isAdmin) return false;
        if (r.expiresAt && r.expiresAt < Math.floor(Date.now() / 1000)) return false;
        return true;
    } catch (e) { return false; }
}

function siRequireAdmin(ctx, nk, data) {
    var secret = siEnv(ctx, "DASHBOARD_SECRET");
    if (secret && data && data.dashboard_secret === secret) return { ok: true, bypass: "secret" };
    if (siIsAdmin(ctx, nk)) return { ok: true, bypass: "session" };
    return { ok: false, reason: "admin authentication required" };
}

function siResolveGameId(g) {
    if (!g) return g;
    try { if (typeof resolveGameIdAlias === "function") return resolveGameIdAlias(g); } catch (e) { /* */ }
    return g;
}

function siReadOne(nk, collection, key, userId) {
    try {
        var r = nk.storageRead([{ collection: collection, key: key, userId: userId || SI_SYSTEM_USER }]);
        return (r && r.length > 0) ? (r[0].value || null) : null;
    } catch (e) { return null; }
}

function siWriteOne(nk, collection, key, userId, value) {
    try {
        nk.storageWrite([{
            collection: collection, key: key, userId: userId || SI_SYSTEM_USER,
            value: value, permissionRead: 0, permissionWrite: 0
        }]);
    } catch (e) { /* best-effort */ }
}

// ─── Core: compute identity traits from a GPA doc ────────────────────────────

/**
 * Derives the 10 Satori identity properties from a GPA document.
 *
 * All values are returned as strings (Satori's /v1/properties API only
 * accepts string values). Missing/insufficient data results in "unknown"
 * rather than null so Satori always has a value to segment on.
 *
 * @param  {object} gpa  A GPA doc as returned by gpaReadProfile.
 * @param  {string} nowSec  Current Unix seconds (for churn_risk + install_age).
 * @returns {object}  { custom: { k: "v" } }  ready for sdPropertiesUpdate.
 */
function siComputeTraits(gpa, nowSec) {
    nowSec = nowSec || Math.floor(Date.now() / 1000);

    // ── skill_band ─────────────────────────────────────────
    var eng = gpa.eng || {};
    var avgAcc = (typeof eng.avg_accuracy === "number") ? eng.avg_accuracy : -1;
    var totalAnswered = (typeof eng.total_answered === "number") ? eng.total_answered : 0;
    var skillBand;
    if (totalAnswered < 10 || avgAcc < 0) {
        skillBand = "beginner";  // insufficient data — safe default
    } else if (avgAcc >= 70) {
        skillBand = "expert";
    } else if (avgAcc >= 40) {
        skillBand = "intermediate";
    } else {
        skillBand = "beginner";
    }

    // ── favorite_mode ──────────────────────────────────────
    var favMode = gpa.fav_mode || null;
    if (!favMode || favMode === "") {
        // Derive from mode_counts if fav_mode not set
        var modeCounts = gpa.mode_counts || {};
        var bestMode = null, bestN = 0;
        for (var mk in modeCounts) {
            if (Object.prototype.hasOwnProperty.call(modeCounts, mk)) {
                var n = modeCounts[mk] || 0;
                if (n > bestN) { bestN = n; bestMode = mk; }
            }
        }
        favMode = bestMode;
    }

    // ── favorite_topic ─────────────────────────────────────
    // GPA doesn't store per-category counts; use mode as proxy.
    // When true category tracking is added (future GPA schema v2), swap in.
    var favTopic = favMode; // best available proxy

    // ── spend_tier ─────────────────────────────────────────
    var money = gpa.money || {};
    var iapCount  = money.iap_count  || 0;
    var spendUsd  = money.spend_usd  || 0;
    var spendTier;
    if (iapCount === 0) {
        spendTier = "non_spender";
    } else if (iapCount <= 2 || spendUsd < 10) {
        spendTier = "low";
    } else if (iapCount <= 5 || spendUsd < 50) {
        spendTier = "mid";
    } else {
        spendTier = "high";
    }

    // ── ad_tolerance ───────────────────────────────────────
    var adComp  = money.ad_completions || 0;
    var adSkips = money.ad_skips       || 0;
    var adViews = money.ad_views       || adComp + adSkips;
    var adTol;
    if (adViews < 3) {
        adTol = "unknown"; // too few data points
    } else {
        var skipRate = adViews > 0 ? (adSkips / adViews) : 0;
        if (skipRate > 0.5)       adTol = "low";
        else if (skipRate > 0.2)  adTol = "medium";
        else                      adTol = "high";
    }

    // ── churn_risk ─────────────────────────────────────────
    var lastActiveSec = gpa.last_active_utc || 0;
    var daysSinceActive = lastActiveSec > 0
        ? Math.floor((nowSec - lastActiveSec) / 86400)
        : null;
    var churnRisk;
    if (daysSinceActive === null) {
        churnRisk = "unknown";
    } else if (daysSinceActive <= 3) {
        churnRisk = "low";
    } else if (daysSinceActive <= 14) {
        churnRisk = "medium";
    } else {
        churnRisk = "high";
    }

    // ── price_sensitivity ──────────────────────────────────
    var paywallShown = money.paywall_shown_count || 0;
    var priceSens;
    if (iapCount > 0) {
        priceSens = "low";         // already bought → low sensitivity
    } else if (paywallShown >= 3) {
        priceSens = "sensitive";   // seen paywall many times, still not buying
    } else if (paywallShown >= 1) {
        priceSens = "moderate";
    } else {
        priceSens = "unknown";     // never shown a paywall
    }

    // ── best_play_hour ─────────────────────────────────────
    // Derived from gpa.sessions (each entry has a start timestamp).
    var bestPlayHour = null;
    try {
        var sessions = gpa.sessions || [];
        if (sessions.length > 0) {
            var hourCounts = {};
            for (var si = 0; si < sessions.length; si++) {
                var s = sessions[si];
                var ts = parseInt(s.start || s.startUtc || s.ts || 0, 10);
                if (ts > 0) {
                    var h = new Date(ts > 1e12 ? ts : ts * 1000).getUTCHours();
                    hourCounts[h] = (hourCounts[h] || 0) + 1;
                }
            }
            var bestH = -1, bestHCount = 0;
            for (var hk in hourCounts) {
                if (Object.prototype.hasOwnProperty.call(hourCounts, hk)) {
                    if (hourCounts[hk] > bestHCount) {
                        bestHCount = hourCounts[hk];
                        bestH = parseInt(hk, 10);
                    }
                }
            }
            if (bestH >= 0) bestPlayHour = String(bestH);
        }
    } catch (e) { bestPlayHour = null; }

    // ── country_tier ───────────────────────────────────────
    var country = (gpa.country || "??").toUpperCase();
    var countryTier;
    if (SI_COUNTRY_T1[country]) countryTier = "t1";
    else if (SI_COUNTRY_T2[country]) countryTier = "t2";
    else if (country === "??" || country === "") countryTier = "unknown";
    else countryTier = "t3";

    // ── install_age_days ───────────────────────────────────
    var firstSeen = gpa.first_seen_utc || 0;
    var installAgeDays = firstSeen > 0
        ? Math.min(9999, Math.floor((nowSec - firstSeen) / 86400))
        : null;

    // ─── Assemble output ───────────────────────────────────
    // All values are strings (Satori /v1/properties type restriction).
    var custom = {};
    custom["skill_band"]        = skillBand;
    if (favMode)     custom["favorite_mode"]  = String(favMode).slice(0, 64);
    if (favTopic)    custom["favorite_topic"] = String(favTopic).slice(0, 64);
    custom["spend_tier"]        = spendTier;
    custom["ad_tolerance"]      = adTol;
    custom["churn_risk"]        = churnRisk;
    custom["price_sensitivity"] = priceSens;
    if (bestPlayHour !== null) custom["best_play_hour"] = bestPlayHour;
    custom["country_tier"]      = countryTier;
    if (installAgeDays !== null) custom["install_age_days"] = String(installAgeDays);

    return { custom: custom };
}

// ─── Core: sync one user to Satori ──────────────────────────────────────────

/**
 * Reads the GPA doc for userId+gameId, computes traits, and pushes them
 * to Satori via sdPropertiesUpdate. Records the sync time so batch runs
 * can skip recently-synced identities.
 *
 * @returns { ok: bool, skipped: bool, traits: object, satori_resp: object }
 */
function siSyncUser(ctx, nk, logger, userId, gameId) {
    gameId = siResolveGameId(gameId || SI_DEFAULT_GAME_ID);
    var nowSec = Math.floor(Date.now() / 1000);

    // Read last-sync state.
    var stateKey = userId + "_" + gameId;
    var state    = siReadOne(nk, SI_STATE_COLLECTION, stateKey, SI_SYSTEM_USER) || {};
    var lastSync = state.synced_at || 0;

    if ((nowSec - lastSync) < SI_RESYNC_INTERVAL_SEC) {
        return { ok: true, skipped: true, reason: "recently_synced" };
    }

    // no_gpa probes use a much shorter backoff than full syncs: skip only if
    // we probed (and found no GPA) within the last hour. Do NOT consult
    // synced_at here — a no_gpa probe never pushed anything to Satori.
    var lastProbe = state.probed_at || 0;
    if ((nowSec - lastProbe) < SI_NO_GPA_PROBE_INTERVAL_SEC) {
        return { ok: true, skipped: true, reason: "recently_probed" };
    }

    // Read GPA.
    var gpaKey = gameId + ":" + userId;
    var gpa    = null;
    try {
        var recs = nk.storageRead([{ collection: SI_GPA_COLLECTION, key: gpaKey, userId: userId }]);
        if (recs && recs.length > 0) gpa = recs[0].value || null;
    } catch (e) { /* not found */ }

    if (!gpa) {
        // No GPA doc yet — record probed_at (NOT synced_at: nothing was
        // pushed) so the next tick retries after the short probe backoff
        // instead of being blocked for the full 24h re-sync window.
        siWriteOne(nk, SI_STATE_COLLECTION, stateKey, SI_SYSTEM_USER, {
            user_id: userId, game_id: gameId,
            synced_at: lastSync,
            probed_at: nowSec,
            reason: "no_gpa"
        });
        return { ok: true, skipped: true, reason: "no_gpa" };
    }

    // Compute traits.
    var props = siComputeTraits(gpa, nowSec);

    // Also include durable identity fields (country, platform, etc.)
    // as Satori "default" properties so they appear in the standard columns.
    var def = {};
    if (gpa.country && gpa.country !== "??") def["country"] = gpa.country;
    if (gpa.platform && gpa.platform !== "unknown") def["platform"] = gpa.platform;
    if (gpa.locale)    def["language"]    = gpa.locale;
    if (gpa.app_version) def["app_version"] = gpa.app_version;
    if (Object.keys(def).length > 0) props["default"] = def;

    // Push to Satori.
    var satResp = null;
    var pushOk  = false;
    try {
        if (typeof sdPropertiesUpdate === "function") {
            satResp  = sdPropertiesUpdate(ctx, nk, logger, userId, props);
            pushOk   = (satResp === null); // sdPropertiesUpdate returns null on success
        } else {
            satResp  = { ok: false, code: 0, body: "sdPropertiesUpdate not available" };
        }
    } catch (e) {
        satResp = { ok: false, code: 0, body: e.message };
    }

    // Optionally fire a satori_identity_synced event so the sync is
    // visible in the analytics timeline and can be correlated with
    // offer/experiment assignment changes.
    if (pushOk) {
        try {
            if (typeof sdEventsPublish === "function") {
                sdEventsPublish(ctx, nk, logger, userId, [{
                    name: "satori_identity_synced",
                    id: "si_" + userId + "_" + nowSec,
                    timestamp: nowSec,
                    value: gameId,
                    metadata: {
                        skill_band:   props.custom.skill_band,
                        spend_tier:   props.custom.spend_tier,
                        churn_risk:   props.custom.churn_risk,
                        country_tier: props.custom.country_tier
                    }
                }]);
            }
        } catch (e) { /* best-effort */ }
    }

    // Record sync state.
    siWriteOne(nk, SI_STATE_COLLECTION, stateKey, SI_SYSTEM_USER, {
        user_id: userId, game_id: gameId, synced_at: nowSec,
        push_ok: pushOk, traits: props.custom
    });

    return {
        ok:         pushOk,
        skipped:    false,
        traits:     props.custom,
        satori_ok:  pushOk,
        satori_body: satResp ? (typeof satResp.body === "string" ? satResp.body.slice(0, 300) : null) : null
    };
}

// ─── RPC: satori_identity_sync (single-user) ────────────────────────────────

/**
 * Compute traits for one user and push to Satori.
 * Admin can target any user; a player can sync their own profile.
 *
 * Payload: { user_id?, game_id?, force?: true }
 *   force=true   bypasses the 24-h re-sync cooldown
 */
function rpcSatoriIdentitySync(ctx, logger, nk, payload) {
    var data = siParse(payload);

    var targetId = data.user_id || ctx.userId;
    if (!targetId) return siErr("user_id required", 400);

    var isAdmin  = siIsAdmin(ctx, nk);
    var secret   = siEnv(ctx, "DASHBOARD_SECRET");
    var bySecret = (secret && data.dashboard_secret === secret);

    if (targetId !== ctx.userId && !isAdmin && !bySecret) {
        return siErr("admin authentication required", 401);
    }

    var gameId = siResolveGameId(data.game_id || data.gameId || SI_DEFAULT_GAME_ID);

    // force=true resets the last-sync state so siSyncUser won't skip.
    if (data.force === true || data.force === "true") {
        siWriteOne(nk, SI_STATE_COLLECTION, targetId + "_" + gameId, SI_SYSTEM_USER, {
            user_id: targetId, game_id: gameId, synced_at: 0, reason: "force_reset"
        });
    }

    var result = siSyncUser(ctx, nk, logger, targetId, gameId);
    return siOk({
        user_id:    targetId,
        game_id:    gameId,
        result:     result,
        computed_at: new Date().toISOString()
    });
}

// ─── RPC: satori_identity_batch ─────────────────────────────────────────────

/**
 * Scan GPA docs and sync up to `limit` users. Designed for cron ticks.
 * Skips users synced within the last 24 h unless force=true.
 *
 * Payload: { game_id?, limit?: 50–500, cursor?, force?: bool,
 *            dashboard_secret? }
 *
 * Response: { synced, skipped, errors, next_cursor, has_more }
 */
function rpcSatoriIdentityBatch(ctx, logger, nk, payload) {
    var data = siParse(payload);
    var gate = siRequireAdmin(ctx, nk, data);
    if (!gate.ok) return siErr(gate.reason, 401);

    var gameId = siResolveGameId(data.game_id || data.gameId || SI_DEFAULT_GAME_ID);
    var limit  = Math.min(SI_BATCH_MAX, Math.max(50, parseInt(data.limit, 10) || SI_BATCH_DEFAULT));
    var cursor = data.cursor || "";
    var force  = (data.force === true || data.force === "true");

    var synced     = 0;
    var skipped    = 0;
    var errors     = 0;
    var nextCursor = null;
    var processed  = 0;
    // Per-reason skip tally (recently_synced, recently_probed, no_gpa,
    // game_id_filter, ...) so ops can see WHY records skip, not just counts.
    var skipReasons = {};
    function siTallySkip(reason) {
        var r = reason || "unknown";
        skipReasons[r] = (skipReasons[r] || 0) + 1;
    }

    try {
        var scanLimit = limit * 3; // scan 3x more than needed to account for skips
        var result    = nk.storageList(SI_SYSTEM_USER, SI_GPA_COLLECTION, scanLimit, cursor);
        var items     = (result && result.objects) ? result.objects : [];
        nextCursor    = (result && result.cursor)  ? result.cursor  : null;

        for (var i = 0; i < items.length && (synced + skipped + errors) < limit * 3; i++) {
            var obj = items[i];
            var v   = obj && obj.value;
            if (!v) continue;

            var userId = v.user_id || obj.userId;
            var docGameId = v.game_id || gameId;
            if (!userId) continue;

            // Filter by game_id if specified.
            if (gameId && gameId !== "all" && docGameId !== gameId) { skipped++; siTallySkip("game_id_filter"); continue; }

            processed++;
            if (synced >= limit) break; // reached the sync quota for this call

            // For force=true, reset the state to bypass the cooldown.
            if (force) {
                siWriteOne(nk, SI_STATE_COLLECTION, userId + "_" + docGameId, SI_SYSTEM_USER, {
                    user_id: userId, game_id: docGameId, synced_at: 0, reason: "batch_force"
                });
            }

            try {
                var r = siSyncUser(ctx, nk, logger, userId, docGameId);
                if (r.skipped) {
                    skipped++;
                    siTallySkip(r.reason);
                } else if (r.ok) {
                    synced++;
                } else {
                    errors++;
                    logger.warn("[satori_identity] batch sync error uid=" + userId + ": " +
                        (r.satori_body || "unknown"));
                }
            } catch (eu) {
                errors++;
                logger.warn("[satori_identity] batch exception uid=" + userId + ": " + eu.message);
            }
        }
    } catch (e) {
        logger.warn("[satori_identity] batch scan error: " + e.message);
        return siErr("scan error: " + e.message, 500);
    }

    return siOk({
        synced:     synced,
        skipped:    skipped,
        skip_reasons: skipReasons,
        errors:     errors,
        processed:  processed,
        next_cursor: nextCursor || null,
        has_more:    !!(nextCursor),
        game_id:    gameId,
        limit:      limit,
        computed_at: new Date().toISOString()
    });
}

// ─── RPC: satori_get_flags ───────────────────────────────────────────────────

/**
 * Fetch Satori flags for the calling user (or admin-specified user_id).
 *
 * After fetching flags, this RPC fires a `flag_exposure` event for each
 * returned flag via sdEventsPublish, so A/B test coverage is visible in
 * the analytics timeline and can be sliced by segment in the dashboard.
 *
 * Payload: { user_id? (admin only), game_id? }
 *
 * Response: { flags: [...], exposure_count, satori_ok }
 *
 * Idempotent: repeated calls within the same session are allowed — Satori
 * deduplicates flag events by (identity, event_id) so the Satori dashboard
 * won't double-count.
 */
function rpcSatoriGetFlags(ctx, logger, nk, payload) {
    var data = siParse(payload);

    var targetId = data.user_id || ctx.userId;
    if (!targetId) return siErr("user_id required", 400);

    var isAdmin  = siIsAdmin(ctx, nk);
    var secret   = siEnv(ctx, "DASHBOARD_SECRET");
    var bySecret = (secret && data.dashboard_secret === secret);

    if (targetId !== ctx.userId && !isAdmin && !bySecret) {
        return siErr("admin authentication required", 401);
    }

    // Fetch flags from Satori.
    var flags = [];
    var satoriOk = false;
    try {
        if (typeof sdFlagsList === "function") {
            flags    = sdFlagsList(ctx, nk, logger, targetId);
            satoriOk = true;
        }
    } catch (e) {
        logger.warn("[satori_identity] sdFlagsList error: " + e.message);
    }

    // Fire flag_exposure events.
    var nowSec        = Math.floor(Date.now() / 1000);
    var exposureCount = 0;

    if (satoriOk && flags && flags.length > 0) {
        try {
            if (typeof sdEventsPublish === "function") {
                var exposureEvents = [];
                for (var fi = 0; fi < flags.length; fi++) {
                    var flag = flags[fi];
                    var flagName  = (flag.name  || flag.id   || "unknown").slice(0, 64);
                    var flagValue = (flag.value  !== undefined) ? String(flag.value).slice(0, 64)
                                                                : (flag.enabled ? "true" : "false");
                    exposureEvents.push({
                        name: "flag_exposure",
                        id:   "fe_" + targetId + "_" + flagName + "_" + nowSec,
                        timestamp: nowSec,
                        value: flagValue,
                        metadata: {
                            flag_name:     flagName,
                            flag_value:    flagValue,
                            experiment_id: flag.experiment_id || flag.experimentId || null
                        }
                    });
                    exposureCount++;
                }
                sdEventsPublish(ctx, nk, logger, targetId, exposureEvents);
            }
        } catch (e) {
            logger.warn("[satori_identity] flag_exposure publish error: " + e.message);
        }
    }

    // Shape the response to match what Unity expects:
    // a list of { name, value, enabled } flags.
    var flagList = [];
    if (Array.isArray(flags)) {
        for (var i = 0; i < flags.length; i++) {
            var f = flags[i];
            flagList.push({
                name:          f.name  || f.id    || "unknown",
                value:         f.value !== undefined ? f.value : null,
                enabled:       f.enabled !== undefined ? f.enabled : true,
                experiment_id: f.experiment_id || f.experimentId || null
            });
        }
    }

    return siOk({
        user_id:        targetId,
        flags:          flagList,
        flag_count:     flagList.length,
        exposure_count: exposureCount,
        satori_ok:      satoriOk,
        fetched_at:     new Date().toISOString()
    });
}

// ─── Piggyback auto-sync (Phase 8 wiring) ─────────────────────────────────────
//
// Called from analytics_log_event on every ingest. Debounced to at most one
// batch of 50 users per hour per Nakama process instance so the ingest hot
// path never takes a Satori hit outside the normal batch window.
//
// Pattern mirrors abAutoRunIfNeeded in analytics_backfill.js.

var siPiggybackNextAllowedSec  = 0;   // process-local: 0 = run immediately
var SI_PIGGYBACK_DEBOUNCE_SEC  = 3600; // 1 h between piggyback runs
var SI_PIGGYBACK_BATCH_LIMIT   = 50;   // users per piggyback tick
// Well-known key in SI_STATE_COLLECTION storing the storageList cursor the
// piggyback batch should resume from. Without this, every tick restarted
// from the FIRST page of game_player_analytics, so only the first ~150 GPA
// docs were ever considered and the rest of the population never synced.
var SI_PIGGYBACK_CURSOR_KEY    = "__piggyback_cursor__";

// DEPRECATED ingest-path piggyback. No longer called from rpcAnalyticsLogEvent
// (see analytics.js, 2026-06-14): the `siPiggybackNextAllowedSec` debounce is a
// module-level variable, and Goja's VM pool resets module scope on every RPC
// call, so the 1-h gate never engaged and the batch ran inline on most ingest
// calls — multi-second stalls + client timeouts. The real work now runs
// out-of-band via rpcSatoriIdentityAutoKick (DASHBOARD_SECRET / admin guarded).
// Retained only so any lingering reference resolves; it simply delegates to the
// shared tick core with the (ineffective) process-local debounce intact.
function siAutoRunIfNeeded(ctx, nk, logger) {
    try {
        var now = Math.floor(Date.now() / 1000);
        if (now < siPiggybackNextAllowedSec) return null;
        siPiggybackNextAllowedSec = now + SI_PIGGYBACK_DEBOUNCE_SEC;
        return siRunPiggybackTick(ctx, nk, logger);
    } catch (e) {
        if (logger && logger.warn) {
            logger.warn("[satori_identity] piggyback error: " + (e.message || e));
        }
        return null;
    }
}

// Shared identity-sync tick core. Runs ONE resume-cursor page of
// rpcSatoriIdentityBatch, advances/persists the cursor, and writes a sync
// heartbeat. Used by both the deprecated ingest piggyback and the
// out-of-band rpcSatoriIdentityAutoKick RPC.
function siRunPiggybackTick(ctx, nk, logger) {
    try {
        // Resume the GPA scan from where the previous tick left off (persisted,
        // so it advances across process restarts too). When the cursor is
        // exhausted we wrap back to the start of the collection.
        var savedCursor = "";
        try {
            var curDoc = siReadOne(nk, SI_STATE_COLLECTION, SI_PIGGYBACK_CURSOR_KEY, SI_SYSTEM_USER);
            if (curDoc && typeof curDoc.cursor === "string") savedCursor = curDoc.cursor;
        } catch (eCur) { /* best-effort — fall back to start */ }

        // Use a system-user context so the admin gate inside
        // rpcSatoriIdentityBatch always passes. This core is invoked only from
        // trusted callers: the out-of-band rpcSatoriIdentityAutoKick RPC
        // (DASHBOARD_SECRET / admin guarded) and the deprecated piggyback.
        var sysCtx = { userId: SI_SYSTEM_USER, env: (ctx && ctx.env) || {} };
        var batchData = { limit: SI_PIGGYBACK_BATCH_LIMIT, cursor: savedCursor };
        var fakePayload = JSON.stringify(batchData);
        var result = JSON.parse(rpcSatoriIdentityBatch(sysCtx, logger, nk, fakePayload) || "{}");

        // Persist the next cursor so the following tick continues through the
        // population. An exhausted cursor (no next_cursor) wraps to "".
        try {
            siWriteOne(nk, SI_STATE_COLLECTION, SI_PIGGYBACK_CURSOR_KEY, SI_SYSTEM_USER, {
                cursor: (result && result.next_cursor) ? String(result.next_cursor) : "",
                updated_at: new Date().toISOString()
            });
        } catch (eCw) { /* best-effort */ }

        if (logger && logger.info) {
            logger.info("[satori_identity] piggyback synced=" + (result.synced || 0) +
                        " skipped=" + (result.skipped || 0) +
                        " errors=" + (result.errors || 0) +
                        " skip_reasons=" + JSON.stringify(result.skip_reasons || {}) +
                        " resumed_cursor=" + (savedCursor ? "yes" : "no") +
                        " wrapped=" + ((result && result.next_cursor) ? "no" : "yes"));
        }

        // Write a sync heartbeat so the Pipeline Health freshness check knows
        // the Satori identity-sync stage is running, even when all users were
        // recently synced (skipped > 0) and no new state docs were written.
        try {
            nk.storageWrite([{
                collection: "analytics_rollup_meta",
                key:        "satori_sync_heartbeat",
                userId:     SI_SYSTEM_USER,
                value:      {
                    timestamp:  new Date().toISOString(),
                    synced:     result.synced  || 0,
                    skipped:    result.skipped || 0,
                    skip_reasons: result.skip_reasons || {},
                    errors:     result.errors  || 0,
                    has_more:   result.has_more || false
                },
                permissionRead: 0, permissionWrite: 0
            }]);
        } catch (eHb) { /* best-effort — never block the piggyback */ }

        return result;
    } catch (e) {
        if (logger && logger.warn) {
            logger.warn("[satori_identity] piggyback error: " + (e.message || e));
        }
        return null;
    }
}

// ─── Out-of-band cron entry point ──────────────────────────────────────────
//
// rpcSatoriIdentityAutoKick replaces the (broken) ingest-path piggyback. The
// external scheduler calls it on a cadence (e.g. every few minutes) with the
// shared DASHBOARD_SECRET; an admin dashboard session also works. Each call
// runs exactly ONE resume-cursor page of identity sync via siRunPiggybackTick,
// so calling it on a timer walks the whole population over time WITHOUT ever
// blocking a user-facing analytics_log_event request.
function rpcSatoriIdentityAutoKick(ctx, logger, nk, payload) {
    var data = siParse(payload);
    var gate = siRequireAdmin(ctx, nk, data);
    if (!gate.ok) return siErr(gate.reason, 401);
    var result = siRunPiggybackTick(ctx, nk, logger);
    return siOk(result || { ran: false });
}

// ─── Registration ─────────────────────────────────────────────────────────

function __ModuleInit_19(ctx, logger, nk, initializer) {
    __rpc_satori_identity_sync = __rpc_satori_identity_sync || (rpcSatoriIdentitySync);
    __rpc_satori_identity_batch = __rpc_satori_identity_batch || (rpcSatoriIdentityBatch);
    __rpc_satori_identity_auto_kick = __rpc_satori_identity_auto_kick || (rpcSatoriIdentityAutoKick);
    __rpc_satori_get_flags = __rpc_satori_get_flags || (rpcSatoriGetFlags);
    logger.info("[analytics_satori_identity] Registered: satori_identity_sync, " +
                "satori_identity_batch, satori_identity_auto_kick, satori_get_flags. " +
                "Traits: skill_band, favorite_mode, favorite_topic, spend_tier, " +
                "ad_tolerance, churn_risk, price_sensitivity, best_play_hour, " +
                "country_tier, install_age_days");
}


// --- Module: analytics\segments\analytics_segments.js ---
// analytics_segments.js — Phase 5 (2026-05) Satori live-ops segments.
//
// Satori's "audiences" are rule-based groups of identities matching some
// event/property combination. The cleanest way to drive them from our
// side is to:
//
//   1. Compute the segment membership in Nakama (we have the GPA doc
//      with all the lifetime stats — last_active_utc, lt_quiz_plays,
//      money.iap_count, money.paywall_shown_count, etc.).
//   2. For each member, fire a "trigger" event into Satori
//      (`winback_eligible`, `preiap_nudge_eligible`) and update the
//      identity property `*_segment = true`.
//   3. The live-ops team configures Satori audiences as "users who fired
//      <trigger event> in the last N days" — one rule per segment.
//
// This module also exposes `satori_register_taxonomy` which pings every
// canonical event from SD_EVENT_ALLOWLIST once, so Satori's Console
// auto-registers every name we use. Run once after each deploy that
// adds new canonical events (or just leave it on the auto-tick).
//
// Registered RPCs:
//   - satori_register_taxonomy : admin-gated. Fires one warm-up event per
//     canonical event name to a system identity. Idempotent — Satori
//     dedupes on event name.
//   - satori_segments_winback  : admin-gated. Scans GPA, fires
//     `winback_eligible` events for users matching the win-back rule.
//   - satori_segments_preiap   : admin-gated. Scans GPA, fires
//     `preiap_nudge_eligible` events for users matching the pre-IAP rule.
//   - satori_segments_run      : admin-gated. Runs both winback+preiap.
//   - satori_segments_status   : admin-gated. Returns last-run summary.
//
// Cooldowns (avoid spamming the same user every day):
//   - winback : 7 days  (a user re-emits if they're STILL inactive)
//   - preiap  : 3 days  (a user re-emits if they're STILL un-converted)
//
// State: stored in `analytics_segments_state/<userId>` per user with
//   { winback_last_sent_utc, preiap_last_sent_utc }.
// Last-run summary stored in `analytics_segments_meta/last_run`.

var SEG_SYSTEM_USER          = "00000000-0000-0000-0000-000000000000";
var SEG_GPA_COLLECTION       = "game_player_analytics";
var SEG_STATE_COLLECTION     = "analytics_segments_state";
var SEG_META_COLLECTION      = "analytics_segments_meta";
var SEG_META_LAST_RUN_KEY    = "last_run";

// Win-back rule: inactive ≥ 7 days AND lifetime ≥ 5 quiz plays.
// (Threshold copied verbatim from the user-approved Phase 5 plan.)
var SEG_WINBACK_INACTIVE_DAYS = 7;
var SEG_WINBACK_MIN_QUIZ_PLAYS = 5;
var SEG_WINBACK_COOLDOWN_SEC   = 7 * 86400;   // re-fire after a week if still inactive

// Pre-IAP rule: paywall_shown ≥ 1 AND iap_count === 0.
var SEG_PREIAP_MIN_PAYWALL_SHOWN = 1;
var SEG_PREIAP_COOLDOWN_SEC      = 3 * 86400;

// Per-RPC scan caps. The dashboard auto-tick calls this often, so we
// page through all users over multiple ticks rather than scanning the
// entire collection in one request (which would time out at 1M+ users).
var SEG_MAX_PAGES_PER_RUN     = 8;
var SEG_PAGE_SIZE             = 100;

// ─── Helpers ──────────────────────────────────────────────

function segParse(payload) {
    try { return JSON.parse(payload || "{}"); } catch (e) { return {}; }
}

function segOk(data) {
    var out = { success: true };
    if (data) for (var k in data) if (data.hasOwnProperty(k)) out[k] = data[k];
    return JSON.stringify(out);
}

function segErr(msg, code) {
    return JSON.stringify({ success: false, error: msg || "error", code: code || 400 });
}

// Auth: reuse aaRequireAdmin from analytics_admin.js (hoisted to global
// scope by postbuild concatenation). Falls through to the dashboard
// secret bypass when an operator runs from CI.
function segRequireAdmin(ctx, nk, logger, data) {
    if (typeof aaRequireAdmin === "function") {
        return aaRequireAdmin(ctx, nk, logger, data);
    }
    return { ok: false, reason: "aaRequireAdmin not available" };
}

function segNowUtc() {
    return Math.floor(Date.now() / 1000);
}

function segReadState(nk, userId) {
    try {
        var r = nk.storageRead([{
            collection: SEG_STATE_COLLECTION,
            key: userId,
            userId: SEG_SYSTEM_USER
        }]);
        if (r && r.length > 0) return r[0].value || {};
    } catch (e) { /* missing state = first time */ }
    return {};
}

function segWriteState(nk, userId, state) {
    try {
        nk.storageWrite([{
            collection: SEG_STATE_COLLECTION,
            key: userId,
            userId: SEG_SYSTEM_USER,
            value: state,
            permissionRead: 0,
            permissionWrite: 0
        }]);
        return true;
    } catch (e) { return false; }
}

function segWriteMeta(nk, payload) {
    try {
        nk.storageWrite([{
            collection: SEG_META_COLLECTION,
            key: SEG_META_LAST_RUN_KEY,
            userId: SEG_SYSTEM_USER,
            value: payload,
            permissionRead: 2,    // admin-readable for the dashboard
            permissionWrite: 0
        }]);
    } catch (e) { /* swallow — meta is best-effort */ }
}

function segReadMeta(nk) {
    try {
        var r = nk.storageRead([{
            collection: SEG_META_COLLECTION,
            key: SEG_META_LAST_RUN_KEY,
            userId: SEG_SYSTEM_USER
        }]);
        if (r && r.length > 0) return r[0].value || null;
    } catch (e) { /* ignore */ }
    return null;
}

// ─── Satori event helper ──────────────────────────────────

// Send a single segment trigger event. We bypass the per-identity
// batching (sdEnqueueOrFlush) here because segment runs already batch
// many events per second — going straight to the wire keeps latency
// bounded regardless of buffer state. Falls back gracefully if Satori
// is unavailable (the local state still records the attempt so the
// next run honours the cooldown).
function segPublishToSatori(ctx, nk, logger, identifier, eventName, metadata) {
    if (typeof sdEventsPublish !== "function") return false;
    var nowSec = segNowUtc();
    var ev = {
        name: eventName,
        timestamp: nowSec,
        metadata: metadata || {}
    };
    try {
        var res = sdEventsPublish(ctx, nk, logger, identifier, [ev]);
        // sdEventsPublish returns null on success and {ok:false,...} on failure.
        return !res;
    } catch (e) {
        if (logger && logger.warn) logger.warn("[segments] satori publish failed: " + (e.message || e));
        return false;
    }
}

// Update a single Satori identity property bag. Used when transitioning
// a user INTO a segment so live-ops can target them via property filter
// in addition to event-based audiences.
function segMarkSatoriProperty(ctx, nk, logger, identifier, key, value) {
    if (typeof sdPropertiesUpdate !== "function") return false;
    var props = {};
    props[key] = String(value);
    try {
        var res = sdPropertiesUpdate(ctx, nk, logger, identifier, props);
        return !res;
    } catch (e) {
        if (logger && logger.warn) logger.warn("[segments] satori property update failed: " + (e.message || e));
        return false;
    }
}

// ─── Canonical event taxonomy registration ─────────────────

// Mirrors satori_direct.js::SD_EVENT_ALLOWLIST. Kept in sync manually —
// when SD_EVENT_ALLOWLIST changes, this list should be updated too. The
// system-identity warm-up is best-effort: Satori auto-registers names on
// first ingest, so any drift gets corrected on the next real event.
var SEG_TAXONOMY_EVENTS = [
    "session_start", "session_end", "app_open", "app_launched", "first_open",
    "registration_completed", "login_success",
    "onboarding_started", "onboarding_complete", "onboarding_abandoned",
    "quiz_started", "quiz_completed", "quiz_abandoned", "answer_submitted",
    "purchase_started", "purchase_completed", "purchase_failed",
    "iap_impression", "iap_failed",
    "ad_shown", "ad_completed", "ad_revenue",
    "paywall_shown", "paywall_converted", "paywall_dismissed", "premium_conversion",
    "store_opened",
    "retention_day_1", "retention_day_7", "retention_day_30", "user_returned",
    "mp_game_started", "mp_game_completed", "milestone_first_multiplayer",
    "error_logged", "auth_failure",
    "dau_synthetic",
    // Phase 5 — segment trigger events. Live-ops team builds Satori
    // audiences keyed off these.
    "winback_eligible", "preiap_nudge_eligible"
];

// System identity used for taxonomy warm-up events. Reserved UUID used
// throughout the codebase for system-owned writes.
var SEG_TAXONOMY_IDENTITY = "00000000-0000-0000-0000-000000000001";

function rpcSatoriRegisterTaxonomy(ctx, logger, nk, payload) {
    var data = segParse(payload);
    var gate = segRequireAdmin(ctx, nk, logger, data);
    if (!gate.ok) return segErr(gate.reason, 401);

    if (typeof sdEventsPublish !== "function") {
        return segErr("Satori client (satori_direct.js) not loaded", 500);
    }

    var nowSec = segNowUtc();
    var sent = 0, failed = 0, skipped = 0;
    var failures = [];

    for (var i = 0; i < SEG_TAXONOMY_EVENTS.length; i++) {
        var name = SEG_TAXONOMY_EVENTS[i];
        var ev = {
            name: name,
            timestamp: nowSec,
            metadata: {
                taxonomy_warmup: "true",
                source: "analytics_segments.rpcSatoriRegisterTaxonomy",
                bundle_version: "phase5-2026-05"
            }
        };
        try {
            var res = sdEventsPublish(ctx, nk, logger, SEG_TAXONOMY_IDENTITY, [ev]);
            if (res && res.ok === false) {
                // Code 3 (INVALID_ARGUMENT) means Satori already has this event
                // registered from real user events with a richer metadata schema.
                // Treat as "already registered / skipped" — not a real failure.
                if (res.code === 400 || res.code === 3) {
                    skipped++;
                } else {
                    failed++;
                    failures.push({ name: name, code: res.code, body: res.body });
                }
            } else {
                sent++;
            }
        } catch (e) {
            failed++;
            failures.push({ name: name, error: e.message || String(e) });
        }
    }

    var summary = {
        registered: sent,
        skipped: skipped,
        failed: failed,
        total: SEG_TAXONOMY_EVENTS.length,
        completed_at: new Date().toISOString(),
        bypass: gate.bypass
    };
    if (failures.length > 0) summary.failures = failures.slice(0, 10);
    if (logger && logger.info) {
        logger.info("[segments] taxonomy: registered=" + sent + " skipped(already-exists)=" +
            skipped + " failed=" + failed + " total=" + SEG_TAXONOMY_EVENTS.length);
    }
    return segOk(summary);
}

// ─── GPA scan helpers ─────────────────────────────────────

// Walk the game_player_analytics collection one page at a time and
// invoke `processFn(userId, gpaDoc)` for each profile. Stops after
// SEG_MAX_PAGES_PER_RUN pages or when storageList exhausts.
function segScanGpa(nk, logger, processFn, cursorIn, maxPages) {
    var cursor = cursorIn || null;
    var pages = 0;
    var pageCap = (typeof maxPages === "number" && maxPages > 0) ? maxPages : SEG_MAX_PAGES_PER_RUN;
    var totalSeen = 0;

    while (pages < pageCap) {
        var page;
        try {
            // GPA docs are written under their owning userId, so we list
            // across ALL users by passing null or undefined to storageList.
            // Older Nakama versions accepted "", but >= 3.24.0 requires
            // null/undefined for "list all users" mode ("expects empty or
            // valid user id" reject path).
            page = nk.storageList(undefined, SEG_GPA_COLLECTION, SEG_PAGE_SIZE, cursor);
        } catch (e) {
            if (logger && logger.warn) logger.warn("[segments] storageList GPA failed: " + (e.message || e));
            break;
        }
        if (!page || !page.objects || page.objects.length === 0) break;

        for (var i = 0; i < page.objects.length; i++) {
            var obj = page.objects[i];
            var doc = obj.value || {};
            var userId = doc.user_id || obj.userId || "";
            if (!userId) continue;
            totalSeen++;
            try {
                processFn(userId, doc);
            } catch (eFn) {
                if (logger && logger.warn) logger.warn("[segments] processFn error for " + userId + ": " + (eFn.message || eFn));
            }
        }

        pages++;
        if (!page.cursor) { cursor = null; break; }
        cursor = page.cursor;
    }

    return { pages: pages, total_seen: totalSeen, next_cursor: cursor };
}

// ─── Win-back segment ─────────────────────────────────────

function segRunWinback(ctx, nk, logger, cursorIn, maxPages) {
    var nowSec = segNowUtc();
    var inactiveCutoffSec = nowSec - SEG_WINBACK_INACTIVE_DAYS * 86400;

    var eligible = 0;
    var fired = 0;
    var cooldown = 0;
    var ineligible = 0;

    var scan = segScanGpa(nk, logger, function (userId, doc) {
        var lastActive = parseInt(doc.last_active_utc, 10) || 0;
        var ltPlays    = parseInt(doc.lt_quiz_plays, 10) || 0;

        // Rule: inactive ≥ N days AND ≥ M quiz plays.
        if (lastActive === 0 || lastActive >= inactiveCutoffSec) { ineligible++; return; }
        if (ltPlays < SEG_WINBACK_MIN_QUIZ_PLAYS) { ineligible++; return; }
        eligible++;

        var state = segReadState(nk, userId);
        var lastSent = parseInt(state.winback_last_sent_utc, 10) || 0;
        if (lastSent && (nowSec - lastSent) < SEG_WINBACK_COOLDOWN_SEC) {
            cooldown++;
            return;
        }

        var daysInactive = Math.floor((nowSec - lastActive) / 86400);
        var meta = {
            days_inactive: String(daysInactive),
            lt_quiz_plays: String(ltPlays),
            lt_revenue_usd: String(((doc.money || {}).spend_usd) || 0),
            fav_mode: String(doc.fav_mode || ""),
            country: String(doc.country || "??"),
            platform: String(doc.platform || "unknown"),
            segment_rule: "winback_v1"
        };

        var pubOk = segPublishToSatori(ctx, nk, logger, userId, "winback_eligible", meta);
        // Best-effort property update — gives live-ops a property filter
        // alternative on the Satori side. Failures don't block the segment.
        segMarkSatoriProperty(ctx, nk, logger, userId, "winback_segment", true);

        // Always update local state on attempt — Satori failures still
        // count for cooldown so we don't hammer the API on every run.
        state.winback_last_sent_utc = nowSec;
        state.winback_last_sent_ok  = !!pubOk;
        segWriteState(nk, userId, state);
        if (pubOk) fired++;
    }, cursorIn, maxPages);

    return {
        scanned: scan.total_seen,
        pages: scan.pages,
        next_cursor: scan.next_cursor,
        eligible: eligible,
        fired: fired,
        cooldown_skipped: cooldown,
        ineligible: ineligible,
        rule: "last_active>" + SEG_WINBACK_INACTIVE_DAYS + "d AND lt_quiz_plays>=" + SEG_WINBACK_MIN_QUIZ_PLAYS
    };
}

function rpcSatoriSegmentsWinback(ctx, logger, nk, payload) {
    var data = segParse(payload);
    var gate = segRequireAdmin(ctx, nk, logger, data);
    if (!gate.ok) return segErr(gate.reason, 401);

    var maxPages = parseInt(data.max_pages, 10) || SEG_MAX_PAGES_PER_RUN;
    var cursor   = data.cursor || null;
    var summary  = segRunWinback(ctx, nk, logger, cursor, maxPages);
    summary.completed_at = new Date().toISOString();
    summary.bypass = gate.bypass;

    if (logger && logger.info) {
        logger.info("[segments] winback run: scanned=" + summary.scanned +
            " eligible=" + summary.eligible + " fired=" + summary.fired +
            " cooldown=" + summary.cooldown_skipped);
    }
    return segOk(summary);
}

// ─── Pre-IAP segment ──────────────────────────────────────

function segRunPreIAP(ctx, nk, logger, cursorIn, maxPages) {
    var nowSec = segNowUtc();
    var eligible = 0;
    var fired = 0;
    var cooldown = 0;
    var ineligible = 0;

    var scan = segScanGpa(nk, logger, function (userId, doc) {
        var money = doc.money || {};
        var paywallShown = parseInt(money.paywall_shown_count, 10) || 0;
        var iapCount     = parseInt(money.iap_count, 10) || 0;

        // Rule: paywall shown ≥ 1 AND zero IAP completions.
        if (paywallShown < SEG_PREIAP_MIN_PAYWALL_SHOWN) { ineligible++; return; }
        if (iapCount > 0) { ineligible++; return; }
        eligible++;

        var state = segReadState(nk, userId);
        var lastSent = parseInt(state.preiap_last_sent_utc, 10) || 0;
        if (lastSent && (nowSec - lastSent) < SEG_PREIAP_COOLDOWN_SEC) {
            cooldown++;
            return;
        }

        var lastPaywall = parseInt(money.paywall_last_utc, 10) || 0;
        var hoursSincePaywall = lastPaywall > 0 ? Math.floor((nowSec - lastPaywall) / 3600) : -1;
        var meta = {
            paywall_shown_count: String(paywallShown),
            paywall_dismissed_count: String(money.paywall_dismissed_count || 0),
            iap_started_count: String(money.iap_started_count || 0),
            iap_failed_count: String(money.iap_failed_count || 0),
            hours_since_last_paywall: String(hoursSincePaywall),
            lt_quiz_plays: String(doc.lt_quiz_plays || 0),
            country: String(doc.country || "??"),
            platform: String(doc.platform || "unknown"),
            segment_rule: "preiap_v1"
        };

        var pubOk = segPublishToSatori(ctx, nk, logger, userId, "preiap_nudge_eligible", meta);
        segMarkSatoriProperty(ctx, nk, logger, userId, "preiap_segment", true);

        state.preiap_last_sent_utc = nowSec;
        state.preiap_last_sent_ok  = !!pubOk;
        segWriteState(nk, userId, state);
        if (pubOk) fired++;
    }, cursorIn, maxPages);

    return {
        scanned: scan.total_seen,
        pages: scan.pages,
        next_cursor: scan.next_cursor,
        eligible: eligible,
        fired: fired,
        cooldown_skipped: cooldown,
        ineligible: ineligible,
        rule: "paywall_shown_count>=" + SEG_PREIAP_MIN_PAYWALL_SHOWN + " AND iap_count===0"
    };
}

function rpcSatoriSegmentsPreIAP(ctx, logger, nk, payload) {
    var data = segParse(payload);
    var gate = segRequireAdmin(ctx, nk, logger, data);
    if (!gate.ok) return segErr(gate.reason, 401);

    var maxPages = parseInt(data.max_pages, 10) || SEG_MAX_PAGES_PER_RUN;
    var cursor   = data.cursor || null;
    var summary  = segRunPreIAP(ctx, nk, logger, cursor, maxPages);
    summary.completed_at = new Date().toISOString();
    summary.bypass = gate.bypass;

    if (logger && logger.info) {
        logger.info("[segments] preiap run: scanned=" + summary.scanned +
            " eligible=" + summary.eligible + " fired=" + summary.fired +
            " cooldown=" + summary.cooldown_skipped);
    }
    return segOk(summary);
}

// ─── Combined run RPC ─────────────────────────────────────

function rpcSatoriSegmentsRun(ctx, logger, nk, payload) {
    var data = segParse(payload);
    var gate = segRequireAdmin(ctx, nk, logger, data);
    if (!gate.ok) return segErr(gate.reason, 401);

    var maxPages = parseInt(data.max_pages, 10) || SEG_MAX_PAGES_PER_RUN;

    var winback = segRunWinback(ctx, nk, logger, null, maxPages);
    var preiap  = segRunPreIAP(ctx, nk, logger, null, maxPages);

    var summary = {
        winback: winback,
        preiap: preiap,
        completed_at: new Date().toISOString(),
        bypass: gate.bypass
    };
    segWriteMeta(nk, summary);

    if (logger && logger.info) {
        logger.info("[segments] combined run done: " +
            "winback fired=" + winback.fired + " preiap fired=" + preiap.fired);
    }
    return segOk(summary);
}

// ─── Status RPC ───────────────────────────────────────────

function rpcSatoriSegmentsStatus(ctx, logger, nk, payload) {
    var data = segParse(payload);
    var gate = segRequireAdmin(ctx, nk, logger, data);
    if (!gate.ok) return segErr(gate.reason, 401);

    var meta = segReadMeta(nk);
    return segOk({
        last_run: meta || null,
        config: {
            winback: {
                inactive_days: SEG_WINBACK_INACTIVE_DAYS,
                min_quiz_plays: SEG_WINBACK_MIN_QUIZ_PLAYS,
                cooldown_days: SEG_WINBACK_COOLDOWN_SEC / 86400,
                trigger_event: "winback_eligible",
                property: "winback_segment"
            },
            preiap: {
                min_paywall_shown: SEG_PREIAP_MIN_PAYWALL_SHOWN,
                cooldown_days: SEG_PREIAP_COOLDOWN_SEC / 86400,
                trigger_event: "preiap_nudge_eligible",
                property: "preiap_segment"
            },
            scan: {
                page_size: SEG_PAGE_SIZE,
                max_pages_per_run: SEG_MAX_PAGES_PER_RUN
            }
        }
    });
}

// ─── Auto-tick hook (called from analytics_admin.js admin_login) ──

// Called from rpcAdminLogin's piggyback path so opening the dashboard
// kicks one segments run. Best-effort — failures don't break the login
// flow. Throttled by an in-memory timestamp so opening the dashboard
// twice in a minute doesn't double-fire (process-local state, resets on
// Nakama restart, which is fine).
var SEG_AUTO_LAST_RUN_MS = 0;
var SEG_AUTO_THROTTLE_MS = 5 * 60 * 1000; // 5 minutes between auto runs

function segAutoRunIfNeeded(ctx, nk, logger) {
    var now = Date.now();
    if (now - SEG_AUTO_LAST_RUN_MS < SEG_AUTO_THROTTLE_MS) return;
    SEG_AUTO_LAST_RUN_MS = now;
    try {
        // Tight cap — auto-run only walks a couple pages so login latency
        // stays bounded. Operators can call satori_segments_run with a
        // higher max_pages for a fuller sweep.
        var winback = segRunWinback(ctx, nk, logger, null, 2);
        var preiap  = segRunPreIAP(ctx, nk, logger, null, 2);
        segWriteMeta(nk, {
            winback: winback,
            preiap: preiap,
            completed_at: new Date().toISOString(),
            source: "auto_tick"
        });
    } catch (e) {
        if (logger && logger.warn) logger.warn("[segments] auto run failed: " + (e.message || e));
    }
}

// ─── Registration ─────────────────────────────────────────

function __ModuleInit_20(ctx, logger, nk, initializer) {
    __rpc_satori_register_taxonomy = __rpc_satori_register_taxonomy || (rpcSatoriRegisterTaxonomy);
    __rpc_satori_segments_winback = __rpc_satori_segments_winback || (rpcSatoriSegmentsWinback);
    __rpc_satori_segments_preiap = __rpc_satori_segments_preiap || (rpcSatoriSegmentsPreIAP);
    __rpc_satori_segments_run = __rpc_satori_segments_run || (rpcSatoriSegmentsRun);
    __rpc_satori_segments_status = __rpc_satori_segments_status || (rpcSatoriSegmentsStatus);
    if (logger && logger.info) {
        logger.info("[analytics_segments] Module registered: 5 RPCs " +
            "(satori_register_taxonomy, satori_segments_{winback,preiap,run,status})");
    }
}


// --- Module: analytics\tracking_plan\analytics_tracking_plan.js ---
// analytics_tracking_plan.js — Phase 2: Schema v2 contract + data quality RPCs
//
// Provides two public helpers used by analytics.js (bundled at global scope by postbuild.js):
//   tpValidateV2(rawEvent, eventName, eventData) → { warnings: string[] }
//   tpGetPrivacyTier(eventName)                  → 0 | 1 | 2
//
// Registers two admin-gated RPCs:
//   analytics_tracking_plan  — returns the full schema v2 contract.
//   analytics_data_quality   — coverage gaps + v2 warning summary.
//
// ─── Schema v2 contract ────────────────────────────────────────────────────
//
// Every v2 event payload must include at the TOP LEVEL (not inside eventData):
//   schema_version  : 2              (integer)
//   client_event_id : "<uuid>"       (client-generated UUID for idempotent dedup)
//   event_time      : ISO-8601 | unix-seconds  (client wall-clock time)
//
// Additionally RECOMMENDED on every v2 event:
//   session_id      : "<uuid>"       (must match the enclosing session_start)
//
// For quiz-related events, also recommended:
//   quiz_session_id : "<uuid>"       (unique per play-through, NOT the lobby session)
//   screen_id       : "<string>"     (which screen originated the event)
//
// Validation is ALWAYS warning-mode: v2 events are NEVER rejected for schema
// violations.  Warnings surface in the RPC response and daily metrics counters.

var TP_SCHEMA_VERSION = 2;

// Required top-level fields on every schema_version=2 payload.
// (schema_version itself is implied; these are the extra required fields.)
var TP_V2_REQUIRED = ["client_event_id", "event_time"];

// Recommended (soft warning) on every v2 event.
var TP_V2_RECOMMENDED = ["session_id"];

// Per-event additional recommended fields in v2 (beyond TP_V2_RECOMMENDED).
var TP_V2_PER_EVENT = {
    quiz_start:       ["quiz_session_id", "screen_id"],
    quiz_complete:    ["quiz_session_id", "screen_id"],
    quiz_abandoned:   ["quiz_session_id", "screen_id"],
    question_viewed:  ["quiz_session_id", "screen_id"],
    question_result:  ["quiz_session_id"],
    answer_submitted: ["quiz_session_id"],
    answer_selected:  ["quiz_session_id"],
    hint_used:        ["quiz_session_id"],
    time_expired:     ["quiz_session_id"],
    screen_viewed:    ["screen_id"],
    screen_left:      ["screen_id"],
    button_clicked:   ["screen_id"],
    modal_shown:      ["screen_id"],
    modal_closed:     ["screen_id"],
    loading_started:  ["screen_id"],
    loading_completed:["screen_id"]
};

// Privacy tier per event name.
//   0 = unclassified (internal / technical — no PII, no external forwarding needed)
//   1 = non_pii     (safe for Satori and any external analytics sink)
//   2 = pii_risk    (may contain free-text / user-generated content — scrub before 3rd-party)
var TP_PRIVACY_TIER = {
    // ── lifecycle / session ──
    session_start:       1,
    session_end:         1,
    session_heartbeat:   0,
    app_launched:        1,
    app_open:            1,
    app_backgrounded:    0,
    app_crashed:         2,
    // ── auth ──
    login_started:       1,
    login_success:       1,
    identity_linked:     1,
    onboarded:           1,
    registration_complete: 1,
    // ── navigation ──
    screen_viewed:       1,
    screen_left:         1,
    button_clicked:      1,
    modal_shown:         1,
    modal_closed:        1,
    loading_started:     0,
    loading_completed:   0,
    // ── quiz gameplay ──
    mode_selected:       1,
    topic_selected:      1,
    quiz_start:          1,
    quiz_complete:       1,
    quiz_abandoned:      1,
    question_viewed:     1,
    question_result:     1,
    answer_submitted:    1,
    answer_selected:     1,
    answer_changed:      1,
    hint_used:           1,
    time_expired:        1,
    // ── monetisation ──
    iap_clicked:         1,
    iap_purchased:       1,
    iap_failed:          1,
    paywall_shown:       1,
    purchase_intent:     1,
    purchase_failed:     1,
    // ── ads ──
    ad_requested:        1,
    ad_shown:            1,
    ad_completed:        1,
    ad_skipped:          1,
    ad_revenue:          1,
    ad_load_failed:      1,
    ad_impression:       1,
    ad_clicked:          1,
    // ── offers / Satori ──
    offer_eligible:      1,
    offer_assigned:      1,
    offer_viewed:        1,
    offer_clicked:       1,
    offer_purchased:     1,
    offer_dismissed:     1,
    offer_cooldown_blocked: 1,
    flag_exposed:        1,
    experiment_exposed:  1,
    satori_flags_loaded: 1,
    remote_config_applied: 0,
    // ── rewards ──
    reward_claimed:      1,
    // ── retention ──
    retention_d1:        1,
    retention_d7:        1,
    retention_d30:       1,
    // ── errors / diagnostics ──
    error_logged:        2,
    api_failure:         2,
    auth_failure:        2,
    nakama_rpc_error:    2,
    timeout_event:       2,
    crash_safe_log:      2,
    ai_host_used:        0
};

// ─── Public helpers ────────────────────────────────────────────────────────

/**
 * Validate a v2 event.  ONLY called when schema_version === 2.
 * Never throws.  Returns { warnings: string[] } — empty array means clean.
 *
 * Warning codes follow the pattern:
 *   v2_required_missing:<field>        — a TP_V2_REQUIRED field is absent
 *   v2_client_event_id_too_short       — client_event_id looks malformed
 *   v2_event_time_invalid              — event_time cannot be parsed
 *   v2_event_time_out_of_range         — unix timestamp outside sane range
 *   v2_recommended_missing:<field>     — a recommended field is absent
 *
 * @param {object} rawEvent   Top-level inbound JSON object.
 * @param {string} eventName  Canonical (post-alias) event name.
 * @param {object} eventData  Resolved eventData object.
 * @returns {{ warnings: string[] }}
 */
function tpValidateV2(rawEvent, eventName, eventData) {
    var warnings = [];
    var raw = rawEvent || {};
    var ed  = eventData  || {};

    // Required top-level v2 fields.
    // Accept them either at top-level or inside eventData (some clients wrap all fields).
    for (var ri = 0; ri < TP_V2_REQUIRED.length; ri++) {
        var rf  = TP_V2_REQUIRED[ri];
        var val = raw[rf];
        if (val === undefined || val === null || val === "") val = ed[rf];
        if (val === undefined || val === null || val === "") {
            warnings.push("v2_required_missing:" + rf);
        }
    }

    // client_event_id sanity: should be at least 8 chars (UUID is 36).
    var ceid = raw.client_event_id || ed.client_event_id;
    if (ceid !== undefined && ceid !== null && ceid !== "" &&
        (typeof ceid !== "string" || ceid.length < 8)) {
        warnings.push("v2_client_event_id_too_short");
    }

    // event_time must be parseable as unix-seconds (number or numeric string) or ISO-8601.
    // FIX: parseFloat("2026-06-03T...") returns 2026 (just the year prefix) which then
    // falsely triggers v2_event_time_out_of_range on every ISO-8601 value. Always try
    // ISO-8601 parsing first for strings; only treat as unix-seconds if purely numeric.
    var et = raw.event_time || ed.event_time;
    if (et !== undefined && et !== null && et !== "") {
        if (typeof et === "number") {
            // Unix seconds: sane range is 2001-01-01 … 2100-01-01.
            if (et < 978307200 || et > 4102444800) {
                warnings.push("v2_event_time_out_of_range");
            }
        } else if (typeof et === "string") {
            // Purely numeric string (e.g. "1748935200") → treat as unix seconds.
            // ISO-8601 strings (e.g. "2026-06-03T08:51:26Z") are NOT purely numeric.
            if (/^\d+(\.\d+)?$/.test(et)) {
                var tsSec = parseFloat(et);
                if (tsSec < 978307200 || tsSec > 4102444800) warnings.push("v2_event_time_out_of_range");
            } else {
                var d = new Date(et);
                if (isNaN(d.getTime())) {
                    warnings.push("v2_event_time_invalid");
                } else {
                    var tsFromIso = d.getTime() / 1000;
                    if (tsFromIso < 978307200 || tsFromIso > 4102444800) warnings.push("v2_event_time_out_of_range");
                }
            }
        } else {
            warnings.push("v2_event_time_invalid");
        }
    }

    // Recommended: session_id (soft warning).
    var sid = raw.session_id || ed.session_id;
    if (!sid) warnings.push("v2_recommended_missing:session_id");

    // Per-event recommended fields.
    var perEvent = TP_V2_PER_EVENT[eventName];
    if (perEvent) {
        for (var pi = 0; pi < perEvent.length; pi++) {
            var pf = perEvent[pi];
            var pv = raw[pf];
            if (pv === undefined || pv === null || pv === "") pv = ed[pf];
            if (pv === undefined || pv === null || pv === "") {
                warnings.push("v2_recommended_missing:" + pf);
            }
        }
    }

    return { warnings: warnings };
}

/**
 * Returns the privacy tier for an event name (0, 1, or 2).
 * Defaults to 1 (non-PII) for unknown event names — safe default for external sinks.
 */
function tpGetPrivacyTier(eventName) {
    if (!eventName) return 1;
    var t = TP_PRIVACY_TIER[eventName];
    return (t !== undefined && t !== null) ? t : 1;
}

// ─── Internal helpers ──────────────────────────────────────────────────────

var TP_SYSTEM_USER = "00000000-0000-0000-0000-000000000000";
var TP_ADMIN_USERS = "admin_users";

function tpParse(payload) { try { return JSON.parse(payload || "{}"); } catch (e) { return {}; } }
function tpOk(data) {
    var o = { success: true };
    if (data) { for (var k in data) { if (Object.prototype.hasOwnProperty.call(data, k)) o[k] = data[k]; } }
    return JSON.stringify(o);
}
function tpErr(msg, code) { return JSON.stringify({ success: false, error: msg || "error", code: code || 400 }); }
function tpEnv(ctx, key) {
    if (ctx && ctx.env && ctx.env[key] !== undefined && ctx.env[key] !== null) return String(ctx.env[key]);
    return "";
}

function tpIsAdmin(ctx, nk, data) {
    var secret = tpEnv(ctx, "DASHBOARD_SECRET");
    if (secret && data && data.dashboard_secret === secret) return true;
    if (!ctx || !ctx.userId) return false;
    if (!ctx.username || ctx.username.indexOf("admin:") !== 0) return false;
    try {
        var recs = nk.storageRead([{ collection: TP_ADMIN_USERS, key: "profile", userId: ctx.userId }]);
        if (!recs || recs.length === 0) return false;
        var rec = recs[0].value || {};
        if (!rec.isAdmin) return false;
        if (rec.expiresAt && rec.expiresAt < Math.floor(Date.now() / 1000)) return false;
        return true;
    } catch (e) { return false; }
}

// ─── RPC: analytics_tracking_plan ─────────────────────────────────────────

/**
 * Returns the full schema v2 contract: required/recommended fields, per-event
 * recommendations, and privacy tier map.
 *
 * Payload: {} or { dashboard_secret: "..." }
 */
function rpcAnalyticsTrackingPlan(ctx, logger, nk, payload) {
    var data = tpParse(payload);
    if (!tpIsAdmin(ctx, nk, data)) return tpErr("admin authentication required", 401);

    return tpOk({
        schema_version_current: TP_SCHEMA_VERSION,
        v2_required_top_level:  ["schema_version"].concat(TP_V2_REQUIRED),
        v2_recommended:         TP_V2_RECOMMENDED,
        v2_per_event_recommended: TP_V2_PER_EVENT,
        privacy_tiers: {
            "0": "unclassified — internal/technical, no forwarding requirement",
            "1": "non_pii — safe for Satori and any external analytics sink",
            "2": "pii_risk — may contain free-text/PII; scrub before 3rd-party forwarding"
        },
        privacy_tier_map: TP_PRIVACY_TIER,
        notes: [
            "schema_version absent or =1 means legacy v1 event — no v2 validation applied.",
            "schema_version=2 events run warning-mode validation; NEVER rejected.",
            "client_event_id: client-generated UUID per event, used for server-side dedup.",
            "event_time: client wall-clock ISO-8601 or unix-seconds. Server always adds unixTimestamp.",
            "quiz_session_id: one UUID per play-through, distinct from the lobby session_id.",
            "screen_id: which screen originated the event (e.g. 'quiz_lobby', 'quiz_result').",
            "privacy_tier=2 events are stored raw server-side but must NOT be forwarded to Satori."
        ]
    });
}

// ─── RPC: analytics_data_quality ──────────────────────────────────────────

/**
 * Returns a data-quality snapshot:
 *   - Today's schema v2 event / warning counts (from metrics counters).
 *   - Top coverage gaps from game_coverage_gap_log (EventEnricher writes these).
 *   - Top v2 warning types seen on recent stored events.
 *
 * Payload: { days?: 1-7, limit?: 1-200, dashboard_secret?: "..." }
 */
function rpcAnalyticsDataQuality(ctx, logger, nk, payload) {
    var data = tpParse(payload);
    if (!tpIsAdmin(ctx, nk, data)) return tpErr("admin authentication required", 401);

    var days  = Math.min(7,   parseInt(data.days,  10) || 1);
    var limit = Math.min(200, parseInt(data.limit, 10) || 100);

    // ── Today's metrics counter ───────────────────────────────────────────
    var today = new Date().toISOString().slice(0, 10);
    var todayC = null;
    try {
        var cr = nk.storageRead([{
            collection: "analytics_metrics_counters",
            key: "counter_" + today,
            userId: TP_SYSTEM_USER
        }]);
        if (cr && cr.length > 0) todayC = cr[0].value;
    } catch (e) { /* ignore */ }

    // ── Coverage gap log (written by EventEnricher.recordCoverageGap) ─────
    var gapsByField = {};
    var gapsByEvent = {};
    var gapTotal    = 0;
    try {
        var gapRes = nk.storageList(TP_SYSTEM_USER, "game_coverage_gap_log", limit, null);
        if (gapRes && gapRes.objects) {
            for (var gi = 0; gi < gapRes.objects.length; gi++) {
                var gobj = gapRes.objects[gi];
                var gv   = gobj && gobj.value;
                if (!gv) continue;
                gapTotal++;
                var geName = gv.eventName || "__unknown__";
                gapsByEvent[geName] = (gapsByEvent[geName] || 0) + 1;
                var gaps = gv.gaps || [];
                for (var gfi = 0; gfi < gaps.length; gfi++) {
                    var gf = gaps[gfi];
                    if (typeof gf === "string") gapsByField[gf] = (gapsByField[gf] || 0) + 1;
                }
            }
        }
    } catch (e) { /* collection may not exist yet on fresh deploys */ }

    // ── Recent v2 warnings from dash_* events ────────────────────────────
    var v2WarnTypes    = {};
    var v2EventsTotal  = 0;
    var v2WarnTotal    = 0;
    var cutoff = Math.floor(Date.now() / 1000) - days * 86400;
    try {
        var evRes = nk.storageList(TP_SYSTEM_USER, "analytics_events",
                                   Math.min(limit, 200), null);
        if (evRes && evRes.objects) {
            for (var ei = 0; ei < evRes.objects.length; ei++) {
                var eo = evRes.objects[ei];
                var ev = eo && eo.value;
                if (!ev || !eo.key || eo.key.indexOf("dash_") !== 0) continue;
                if (ev.unixTimestamp && ev.unixTimestamp < cutoff) continue;
                if (ev.schemaVersion !== 2) continue;
                v2EventsTotal++;
                var warns = ev.v2Warnings || [];
                v2WarnTotal += warns.length;
                for (var wi = 0; wi < warns.length; wi++) {
                    var wt = warns[wi];
                    if (typeof wt === "string") v2WarnTypes[wt] = (v2WarnTypes[wt] || 0) + 1;
                }
            }
        }
    } catch (e) { /* ignore */ }

    function topPairs(map, n) {
        var arr = [];
        for (var k in map) {
            if (Object.prototype.hasOwnProperty.call(map, k)) arr.push({ name: k, count: map[k] });
        }
        arr.sort(function (a, b) { return b.count - a.count; });
        return arr.slice(0, n || 20);
    }

    var warnRate = v2EventsTotal > 0
        ? Math.round((v2WarnTotal / v2EventsTotal) * 100) / 100
        : 0;

    return tpOk({
        checkedAt:                 new Date().toISOString(),
        days_window:               days,
        schema_v2_events_today:    (todayC && todayC.schema_v2_events)    || 0,
        schema_v2_warnings_today:  (todayC && todayC.schema_v2_warnings)  || 0,
        events_accepted_today:     (todayC && todayC.events_accepted)     || 0,
        events_rejected_today:     (todayC && todayC.events_rejected)     || 0,
        alias_normalized_today:    (todayC && todayC.alias_normalized)    || 0,
        satori_success_today:      (todayC && todayC.satori_publish_success)  || 0,
        satori_failure_today:      (todayC && todayC.satori_publish_failure)  || 0,
        coverage_gap_log_entries:  gapTotal,
        top_coverage_gap_fields:   topPairs(gapsByField, 20),
        top_coverage_gap_events:   topPairs(gapsByEvent, 20),
        v2_events_sampled:         v2EventsTotal,
        v2_warnings_total:         v2WarnTotal,
        v2_warnings_per_event_avg: warnRate,
        top_v2_warning_types:      topPairs(v2WarnTypes, 20),
        schema_contract: {
            version:        TP_SCHEMA_VERSION,
            v2_required:    ["schema_version"].concat(TP_V2_REQUIRED),
            v2_recommended: TP_V2_RECOMMENDED
        }
    });
}

// ─── Module registration ───────────────────────────────────────────────────

function __ModuleInit_21(ctx, logger, nk, initializer) {
    __rpc_analytics_tracking_plan = __rpc_analytics_tracking_plan || (rpcAnalyticsTrackingPlan);
    __rpc_analytics_data_quality = __rpc_analytics_data_quality || (rpcAnalyticsDataQuality);
    logger.info("[analytics_tracking_plan] Module registered: analytics_tracking_plan, analytics_data_quality");
}


// --- Module: analytics\v2\analytics_v2.js ---
// analytics_v2.js - Advanced Analytics RPCs for Nakama
// Self-contained, ES5 compatible, no imports/exports
//
// 2026-05 — Every top-level function is intentionally suffixed with `V2`
// (e.g. rpcAnalyticsV2Dashboard) to avoid shadowing the canonical
// implementations in analytics.js / analytics_extended.js via JS function-
// name hoisting at bundle time. None of these are registered as RPC IDs
// today; they live here as a parallel/experimental implementation pending
// migration to the unified `analytics_*` RPC surface.

var SYSTEM_USER = "00000000-0000-0000-0000-000000000000";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// Local wrapper around the global resolveGameIdAlias helper exposed by
// analytics.js (via postbuild bundling). Falls back to identity if the helper
// has not been bundled yet so this module remains loadable in isolation.
function avResolveGameId(gameId) {
  if (!gameId) return gameId;
  try {
    if (typeof resolveGameIdAlias === 'function') {
      return resolveGameIdAlias(gameId);
    }
  } catch (e) { /* helper not bundled — keep raw value */ }
  return gameId;
}

function analyticsNowSeconds() {
  return Math.floor(Date.now() / 1000);
}

function analyticsDateString(date) {
  var d = date || new Date();
  return d.getUTCFullYear() + "-" +
    ("0" + (d.getUTCMonth() + 1)).slice(-2) + "-" +
    ("0" + d.getUTCDate()).slice(-2);
}

function analyticsDaysAgo(n) {
  var d = new Date();
  d.setUTCDate(d.getUTCDate() - n);
  return analyticsDateString(d);
}

function analyticsDateFromString(str) {
  var parts = str.split("-");
  return new Date(Date.UTC(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10)));
}

function analyticsDaysBetween(dateStrA, dateStrB) {
  var a = analyticsDateFromString(dateStrA);
  var b = analyticsDateFromString(dateStrB);
  return Math.round(Math.abs(b - a) / 86400000);
}

function analyticsSafeRead(nk, collection, key, userId) {
  try {
    var recs = nk.storageRead([{ collection: collection, key: key, userId: userId }]);
    if (recs && recs.length > 0) return recs[0].value;
  } catch (_) { /* swallow */ }
  return null;
}

function analyticsSafeWrite(nk, collection, key, userId, value) {
  nk.storageWrite([{
    collection: collection,
    key: key,
    userId: userId,
    value: value,
    permissionRead: 1,
    permissionWrite: 0
  }]);
}

function analyticsSafeList(nk, userId, collection, limit, cursor) {
  try {
    return nk.storageList(userId, collection, limit, cursor);
  } catch (_) { /* swallow */ }
  return { objects: [], cursor: "" };
}

function analyticsSafeJsonParse(payload) {
  if (!payload || payload === "") return {};
  try {
    return JSON.parse(payload);
  } catch (_) {
    return {};
  }
}

function analyticsUniqueArray(arr) {
  var seen = {};
  var out = [];
  for (var i = 0; i < arr.length; i++) {
    if (!seen[arr[i]]) {
      seen[arr[i]] = true;
      out.push(arr[i]);
    }
  }
  return out;
}

function analyticsMedian(sorted) {
  if (sorted.length === 0) return 0;
  var mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[mid - 1] + sorted[mid]) / 2;
  }
  return sorted[mid];
}

function analyticsPercentile(sorted, p) {
  if (sorted.length === 0) return 0;
  var idx = Math.ceil(p / 100 * sorted.length) - 1;
  if (idx < 0) idx = 0;
  if (idx >= sorted.length) idx = sorted.length - 1;
  return sorted[idx];
}

function analyticsGini(values) {
  if (values.length === 0) return 0;
  var sorted = values.slice().sort(function (a, b) { return a - b; });
  var n = sorted.length;
  var sum = 0;
  var weightedSum = 0;
  for (var i = 0; i < n; i++) {
    sum += sorted[i];
    weightedSum += (i + 1) * sorted[i];
  }
  if (sum === 0) return 0;
  return (2 * weightedSum) / (n * sum) - (n + 1) / n;
}

function analyticsRound(val, decimals) {
  var factor = Math.pow(10, decimals || 2);
  return Math.round(val * factor) / factor;
}

// Read DAU record for a specific game + date
function readDauRecord(nk, gameId, dateStr) {
  var key = "dau_" + gameId + "_" + dateStr;
  return analyticsSafeRead(nk, "analytics_dau", key, SYSTEM_USER);
}

// Collect unique users from DAU records across a date range for a game
function collectDauUsers(nk, gameId, days) {
  var users = [];
  for (var i = 0; i < days; i++) {
    var dateStr = analyticsDaysAgo(i);
    var rec = readDauRecord(nk, gameId, dateStr);
    if (rec && rec.users) {
      for (var j = 0; j < rec.users.length; j++) {
        users.push(rec.users[j]);
      }
    }
  }
  return users;
}

// Discover game IDs from recent DAU entries by scanning system storage
function discoverGameIds(nk, days) {
  var gameIds = {};
  var result = analyticsSafeList(nk, SYSTEM_USER, "analytics_dau", 100, "");
  if (result && result.objects) {
    for (var i = 0; i < result.objects.length; i++) {
      var val = result.objects[i].value;
      if (val && val.gameId) {
        gameIds[avResolveGameId(val.gameId)] = true;
      }
    }
  }
  var out = [];
  for (var gid in gameIds) {
    if (gameIds.hasOwnProperty(gid)) {
      out.push(gid);
    }
  }
  return out;
}

// Sample user IDs from DAU or first_session storage
function sampleUserIds(nk, limit) {
  var userIds = [];
  var seen = {};
  var result = analyticsSafeList(nk, null, "first_session", limit || 100, "");
  if (result && result.objects) {
    for (var i = 0; i < result.objects.length; i++) {
      var uid = result.objects[i].userId;
      if (uid && !seen[uid]) {
        seen[uid] = true;
        userIds.push(uid);
      }
    }
  }
  return userIds;
}

// ---------------------------------------------------------------------------
// 1. rpcAnalyticsV2Dashboard
// ---------------------------------------------------------------------------

function rpcAnalyticsV2Dashboard(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameIds = data.game_id ? [avResolveGameId(data.game_id)] : discoverGameIds(nk, 7);
    var todayStr = analyticsDaysAgo(0);

    var dauUsersToday = [];
    var wauUsers = [];
    var mauUsers = [];
    var topGames = [];

    for (var g = 0; g < gameIds.length; g++) {
      var gid = gameIds[g];

      var todayRec = readDauRecord(nk, gid, todayStr);
      var gameDau = (todayRec && todayRec.users) ? todayRec.users.length : 0;
      topGames.push({ game_id: gid, dau: gameDau });

      var usersToday = (todayRec && todayRec.users) ? todayRec.users : [];
      for (var t = 0; t < usersToday.length; t++) dauUsersToday.push(usersToday[t]);

      var w = collectDauUsers(nk, gid, 7);
      for (var wi = 0; wi < w.length; wi++) wauUsers.push(w[wi]);

      var m = collectDauUsers(nk, gid, 30);
      for (var mi = 0; mi < m.length; mi++) mauUsers.push(m[mi]);
    }

    var dau = analyticsUniqueArray(dauUsersToday).length;
    var wau = analyticsUniqueArray(wauUsers).length;
    var mau = analyticsUniqueArray(mauUsers).length;
    var dauMauRatio = mau > 0 ? analyticsRound(dau / mau, 4) : 0;

    // Avg session duration from recent summaries
    var totalDuration = 0;
    var sessionCount = 0;
    var newUsersToday = 0;
    var returningUsersToday = 0;

    var uniqueToday = analyticsUniqueArray(dauUsersToday);
    for (var u = 0; u < uniqueToday.length; u++) {
      var uid = uniqueToday[u];
      var sessionList = analyticsSafeList(nk, uid, "analytics_session_summaries", 10, "");
      if (sessionList && sessionList.objects) {
        for (var s = 0; s < sessionList.objects.length; s++) {
          var sess = sessionList.objects[s].value;
          if (sess && sess.duration) {
            totalDuration += sess.duration;
            sessionCount++;
          }
        }
      }
      var firstSess = analyticsSafeRead(nk, "first_session", "session_data", uid);
      if (firstSess) {
        var firstDate = new Date(firstSess.firstSessionAt);
        if (analyticsDateString(firstDate) === todayStr) {
          newUsersToday++;
        } else {
          returningUsersToday++;
        }
      } else {
        newUsersToday++;
      }
    }
    var avgSessionDuration = sessionCount > 0 ? analyticsRound(totalDuration / sessionCount, 1) : 0;

    // 7-day DAU trend
    var dau7dAgo = 0;
    for (var gt = 0; gt < gameIds.length; gt++) {
      var rec7 = readDauRecord(nk, gameIds[gt], analyticsDaysAgo(7));
      if (rec7 && rec7.users) dau7dAgo += rec7.users.length;
    }
    var dau7dChangePct = dau7dAgo > 0 ? analyticsRound(((dau - dau7dAgo) / dau7dAgo) * 100, 1) : 0;

    topGames.sort(function (a, b) { return b.dau - a.dau; });

    return JSON.stringify({
      dau: dau,
      wau: wau,
      mau: mau,
      dau_mau_ratio: dauMauRatio,
      avg_session_duration_seconds: avgSessionDuration,
      new_users_today: newUsersToday,
      returning_users_today: returningUsersToday,
      top_games: topGames,
      period: "today",
      trends: { dau_7d_change_pct: dau7dChangePct }
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2Dashboard error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 2. rpcAnalyticsV2RetentionCohort
// ---------------------------------------------------------------------------

function rpcAnalyticsV2RetentionCohort(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var cohortDate = data.cohort_date || analyticsDaysAgo(1);
    var gameId = avResolveGameId(data.game_id);
    var gameIds = gameId ? [gameId] : discoverGameIds(nk, 30);

    var cohortStart = analyticsDateFromString(cohortDate).getTime();
    var cohortEnd = cohortStart + 86400000;

    // Find users whose first session falls on cohortDate
    var cohortUsers = [];
    var allUsers = sampleUserIds(nk, 100);
    for (var i = 0; i < allUsers.length; i++) {
      var fs = analyticsSafeRead(nk, "first_session", "session_data", allUsers[i]);
      if (fs && fs.firstSessionAt >= cohortStart && fs.firstSessionAt < cohortEnd) {
        cohortUsers.push(allUsers[i]);
      }
    }

    var checkDays = [1, 3, 7, 14, 30];
    var rawCounts = { d1: 0, d3: 0, d7: 0, d14: 0, d30: 0 };

    for (var ci = 0; ci < cohortUsers.length; ci++) {
      var uid = cohortUsers[ci];
      for (var di = 0; di < checkDays.length; di++) {
        var dayOffset = checkDays[di];
        var checkDate = new Date(cohortStart + dayOffset * 86400000);
        var checkDateStr = analyticsDateString(checkDate);
        var found = false;
        for (var gi = 0; gi < gameIds.length; gi++) {
          var dauRec = readDauRecord(nk, gameIds[gi], checkDateStr);
          if (dauRec && dauRec.users && dauRec.users.indexOf(uid) !== -1) {
            found = true;
            break;
          }
        }
        if (found) {
          rawCounts["d" + dayOffset]++;
        }
      }
    }

    var cohortSize = cohortUsers.length;
    var pct = function (count) {
      return cohortSize > 0 ? analyticsRound((count / cohortSize) * 100, 1) : 0;
    };

    return JSON.stringify({
      cohort_date: cohortDate,
      cohort_size: cohortSize,
      d1_pct: pct(rawCounts.d1),
      d3_pct: pct(rawCounts.d3),
      d7_pct: pct(rawCounts.d7),
      d14_pct: pct(rawCounts.d14),
      d30_pct: pct(rawCounts.d30),
      raw_counts: rawCounts
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2RetentionCohort error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 3. rpcAnalyticsV2EngagementScore
// ---------------------------------------------------------------------------

function rpcAnalyticsV2EngagementScore(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var userId = data.user_id || ctx.userId;
    var gameId = avResolveGameId(data.game_id);

    if (!userId) {
      return JSON.stringify({ error: "user_id required" });
    }

    // First session data
    var firstSess = analyticsSafeRead(nk, "first_session", "session_data", userId);
    var totalSessions = (firstSess && firstSess.totalSessions) ? firstSess.totalSessions : 0;
    var firstSessionAt = (firstSess && firstSess.firstSessionAt) ? firstSess.firstSessionAt : Date.now();
    var lastActive = (firstSess && firstSess.lastSessionAt) ? new Date(firstSess.lastSessionAt).toISOString() : "";
    var daysSinceFirst = Math.floor((Date.now() - firstSessionAt) / 86400000);

    // Sessions in last 7 days: count DAU appearances
    var sessionsLast7d = 0;
    var gameIds = gameId ? [gameId] : discoverGameIds(nk, 7);
    for (var d = 0; d < 7; d++) {
      var dateStr = analyticsDaysAgo(d);
      for (var gi = 0; gi < gameIds.length; gi++) {
        var dauRec = readDauRecord(nk, gameIds[gi], dateStr);
        if (dauRec && dauRec.users && dauRec.users.indexOf(userId) !== -1) {
          sessionsLast7d++;
          break;
        }
      }
    }

    // Events in last 7 days
    var eventsLast7d = 0;
    var eventResult = analyticsSafeList(nk, userId, "analytics_events", 100, "");
    var sevenDaysAgoSec = analyticsNowSeconds() - 7 * 86400;
    if (eventResult && eventResult.objects) {
      for (var ei = 0; ei < eventResult.objects.length; ei++) {
        var evt = eventResult.objects[ei].value;
        if (evt && evt.unixTimestamp && evt.unixTimestamp >= sevenDaysAgoSec) {
          if (!gameId || evt.gameId === gameId) eventsLast7d++;
        }
      }
    }

    // Friends count
    var friendsCount = 0;
    try {
      var fr = nk.friendsList(userId, null, 100, "");
      if (fr && fr.friends) friendsCount = fr.friends.length;
    } catch (_) { /* swallow */ }

    // Wallet transactions
    var txCount = 0;
    try {
      var ledger = nk.walletLedgerList(userId, 100, "");
      if (ledger && ledger.items) txCount = ledger.items.length;
    } catch (_) { /* swallow */ }

    // Has group
    var hasGroup = false;
    try {
      var groups = nk.userGroupsList(userId, 100, null, "");
      if (groups && groups.userGroups && groups.userGroups.length > 0) hasGroup = true;
    } catch (_) { /* swallow */ }

    // Score components (0-25 each except social which is 0-25)
    var sessionFrequency = Math.min(sessionsLast7d / 7, 1) * 25;
    var actionDensity = Math.min(eventsLast7d / 50, 1) * 25;
    var socialScore = Math.min(friendsCount / 10, 1) * 20 + (hasGroup ? 5 : 0);
    var spendingScore = Math.min(txCount / 20, 1) * 25;

    var score = analyticsRound(sessionFrequency + actionDensity + socialScore + spendingScore, 1);
    if (score > 100) score = 100;

    var riskLevel = "churning";
    if (score >= 80) riskLevel = "power_user";
    else if (score >= 60) riskLevel = "engaged";
    else if (score >= 40) riskLevel = "moderate";
    else if (score >= 20) riskLevel = "at_risk";

    return JSON.stringify({
      user_id: userId,
      engagement_score: score,
      risk_level: riskLevel,
      breakdown: {
        session_frequency: analyticsRound(sessionFrequency, 1),
        action_density: analyticsRound(actionDensity, 1),
        social_score: analyticsRound(socialScore, 1),
        spending_score: analyticsRound(spendingScore, 1)
      },
      last_active: lastActive,
      days_since_first: daysSinceFirst
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2EngagementScore error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 4. rpcAnalyticsV2SessionStats
// ---------------------------------------------------------------------------

function rpcAnalyticsV2SessionStats(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameId = avResolveGameId(data.game_id);
    var days = data.days || 7;
    var cutoffSec = analyticsNowSeconds() - days * 86400;

    var durations = [];
    var dailyMap = {};
    var hourBuckets = {};
    for (var h = 0; h < 24; h++) hourBuckets[h] = 0;

    // Scan session summaries from sampled users
    var userIds = sampleUserIds(nk, 100);
    for (var u = 0; u < userIds.length; u++) {
      var result = analyticsSafeList(nk, userIds[u], "analytics_session_summaries", 50, "");
      if (!result || !result.objects) continue;
      for (var s = 0; s < result.objects.length; s++) {
        var sess = result.objects[s].value;
        if (!sess || !sess.startTime) continue;
        if (sess.startTime < cutoffSec) continue;
        if (gameId && sess.gameId !== gameId) continue;

        var dur = sess.duration || 0;
        durations.push(dur);

        var sessDate = analyticsDateString(new Date(sess.startTime * 1000));
        if (!dailyMap[sessDate]) dailyMap[sessDate] = { sessions: 0, totalDur: 0 };
        dailyMap[sessDate].sessions++;
        dailyMap[sessDate].totalDur += dur;

        var sessHour = new Date(sess.startTime * 1000).getUTCHours();
        hourBuckets[sessHour]++;
      }
    }

    durations.sort(function (a, b) { return a - b; });

    var totalSessions = durations.length;
    var sumDur = 0;
    for (var di = 0; di < durations.length; di++) sumDur += durations[di];
    var avgDur = totalSessions > 0 ? analyticsRound(sumDur / totalSessions, 1) : 0;
    var medDur = analyticsMedian(durations);
    var p95Dur = analyticsPercentile(durations, 95);

    var peakHours = [];
    for (var ph = 0; ph < 24; ph++) {
      if (hourBuckets[ph] > 0) {
        peakHours.push({ hour: ph, count: hourBuckets[ph] });
      }
    }
    peakHours.sort(function (a, b) { return b.count - a.count; });

    var dailyBreakdown = [];
    for (var dk in dailyMap) {
      if (dailyMap.hasOwnProperty(dk)) {
        var entry = dailyMap[dk];
        dailyBreakdown.push({
          date: dk,
          sessions: entry.sessions,
          avg_duration: entry.sessions > 0 ? analyticsRound(entry.totalDur / entry.sessions, 1) : 0
        });
      }
    }
    dailyBreakdown.sort(function (a, b) { return a.date < b.date ? -1 : 1; });

    var sessPerDayAvg = days > 0 ? analyticsRound(totalSessions / days, 1) : 0;

    return JSON.stringify({
      total_sessions: totalSessions,
      avg_duration_seconds: avgDur,
      median_duration_seconds: medDur,
      p95_duration_seconds: p95Dur,
      min_duration_seconds: durations.length > 0 ? durations[0] : 0,
      max_duration_seconds: durations.length > 0 ? durations[durations.length - 1] : 0,
      sessions_per_day_avg: sessPerDayAvg,
      peak_hours: peakHours.slice(0, 5),
      daily_breakdown: dailyBreakdown
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2SessionStats error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 5. rpcAnalyticsV2Funnel
// ---------------------------------------------------------------------------

function rpcAnalyticsV2Funnel(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameId = avResolveGameId(data.game_id);
    var days = data.days || 30;

    var userIds = sampleUserIds(nk, 100);
    var totalUsers = userIds.length;

    var stepDefs = [
      { name: "account_created",      check: function () { return totalUsers; } },
      { name: "onboarding_started",   check: function () { return countOnboardingStep(nk, userIds, "started"); } },
      { name: "onboarding_completed", check: function () { return countOnboardingStep(nk, userIds, "completed"); } },
      { name: "first_quiz_played",    check: function () { return countOnboardingStep(nk, userIds, "first_quiz"); } },
      { name: "second_session",       check: function () { return countSessionMilestone(nk, userIds, 2); } },
      { name: "made_purchase",        check: function () { return countEventType(nk, userIds, gameId, "purchase"); } },
      { name: "joined_group",         check: function () { return countWithGroups(nk, userIds); } },
      { name: "played_multiplayer",   check: function () { return countEventType(nk, userIds, gameId, "match_complete"); } },
      { name: "day_7_return",         check: function () { return countD7Return(nk, userIds); } }
    ];

    var steps = [];
    var worstDropOff = { step: "", drop_pct: 0 };

    for (var i = 0; i < stepDefs.length; i++) {
      var count = stepDefs[i].check();
      var pctOfTotal = totalUsers > 0 ? analyticsRound((count / totalUsers) * 100, 1) : 0;
      var prevCount = (i > 0 && steps[i - 1]) ? steps[i - 1].count : totalUsers;
      var pctOfPrev = prevCount > 0 ? analyticsRound((count / prevCount) * 100, 1) : 0;
      var dropOff = 100 - pctOfPrev;

      steps.push({
        name: stepDefs[i].name,
        count: count,
        pct_of_total: pctOfTotal,
        pct_of_previous: pctOfPrev,
        drop_off_pct: analyticsRound(dropOff, 1)
      });

      if (i > 0 && dropOff > worstDropOff.drop_pct) {
        worstDropOff = { step: stepDefs[i].name, drop_pct: analyticsRound(dropOff, 1) };
      }
    }

    return JSON.stringify({
      steps: steps,
      total_users: totalUsers,
      worst_drop_off: worstDropOff
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2Funnel error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// Funnel helpers

function countOnboardingStep(nk, userIds, stepType) {
  var count = 0;
  for (var i = 0; i < userIds.length; i++) {
    var ob = analyticsSafeRead(nk, "onboarding_state", "state", userIds[i]);
    if (!ob) continue;
    if (stepType === "started" && ob.currentStep && ob.currentStep > 0) count++;
    else if (stepType === "completed" && ob.onboardingComplete === true) count++;
    else if (stepType === "first_quiz" && ob.firstQuizCompleted === true) count++;
  }
  return count;
}

function countSessionMilestone(nk, userIds, minSessions) {
  var count = 0;
  for (var i = 0; i < userIds.length; i++) {
    var fs = analyticsSafeRead(nk, "first_session", "session_data", userIds[i]);
    if (fs && fs.totalSessions >= minSessions) count++;
  }
  return count;
}

function countEventType(nk, userIds, gameId, eventName) {
  var count = 0;
  for (var i = 0; i < userIds.length; i++) {
    var result = analyticsSafeList(nk, userIds[i], "analytics_events", 100, "");
    if (!result || !result.objects) continue;
    var found = false;
    for (var j = 0; j < result.objects.length; j++) {
      var evt = result.objects[j].value;
      if (evt && evt.eventName === eventName) {
        if (!gameId || evt.gameId === gameId) { found = true; break; }
      }
    }
    if (found) count++;
  }
  return count;
}

function countWithGroups(nk, userIds) {
  var count = 0;
  for (var i = 0; i < userIds.length; i++) {
    try {
      var groups = nk.userGroupsList(userIds[i], 1, null, "");
      if (groups && groups.userGroups && groups.userGroups.length > 0) count++;
    } catch (_) { /* swallow */ }
  }
  return count;
}

function countD7Return(nk, userIds) {
  var count = 0;
  for (var i = 0; i < userIds.length; i++) {
    var fs = analyticsSafeRead(nk, "first_session", "session_data", userIds[i]);
    if (fs && fs.d7Returned === true) count++;
  }
  return count;
}

// ---------------------------------------------------------------------------
// 6. rpcAnalyticsV2EconomyHealth
// ---------------------------------------------------------------------------

function rpcAnalyticsV2EconomyHealth(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameId = avResolveGameId(data.game_id);

    var userIds = sampleUserIds(nk, 100);
    var sampleSize = userIds.length;
    if (sampleSize === 0) {
      return JSON.stringify({
        total_coins: 0, total_gems: 0, avg_coins: 0, median_coins: 0,
        max_coins: 0, min_coins: 0, gini_coefficient: 0,
        source_sink_ratio: { sources_total: 0, sinks_total: 0, ratio: 0 },
        whale_count: 0, sample_size: 0
      });
    }

    var coinBalances = [];
    var totalCoins = 0;
    var totalGems = 0;
    var sourcesTotal = 0;
    var sinksTotal = 0;

    // Batch fetch accounts
    var accounts = [];
    try {
      accounts = nk.accountsGetId(userIds);
    } catch (_) { /* swallow */ }

    for (var a = 0; a < accounts.length; a++) {
      var acct = accounts[a];
      var wallet = {};
      if (acct && acct.wallet) {
        if (typeof acct.wallet === "string") {
          try { wallet = JSON.parse(acct.wallet); } catch (_) { /* swallow */ }
        } else {
          wallet = acct.wallet;
        }
      }
      var coins = wallet.coins || wallet.tokens || 0;
      var gems = wallet.gems || wallet.diamonds || 0;
      totalCoins += coins;
      totalGems += gems;
      coinBalances.push(coins);
    }

    // Ledger sampling for source/sink
    var ledgerSampleSize = Math.min(userIds.length, 20);
    for (var li = 0; li < ledgerSampleSize; li++) {
      try {
        var ledger = nk.walletLedgerList(userIds[li], 50, "");
        if (ledger && ledger.items) {
          for (var lj = 0; lj < ledger.items.length; lj++) {
            var changeset = ledger.items[lj].changeset;
            if (typeof changeset === "string") {
              try { changeset = JSON.parse(changeset); } catch (_) { continue; }
            }
            for (var ck in changeset) {
              if (changeset.hasOwnProperty(ck)) {
                var val = changeset[ck];
                if (val > 0) sourcesTotal += val;
                else if (val < 0) sinksTotal += Math.abs(val);
              }
            }
          }
        }
      } catch (_) { /* swallow */ }
    }

    coinBalances.sort(function (a, b) { return a - b; });
    var avgCoins = sampleSize > 0 ? analyticsRound(totalCoins / sampleSize, 1) : 0;
    var medCoins = analyticsMedian(coinBalances);
    var maxCoins = coinBalances.length > 0 ? coinBalances[coinBalances.length - 1] : 0;
    var minCoins = coinBalances.length > 0 ? coinBalances[0] : 0;
    var gini = analyticsRound(analyticsGini(coinBalances), 4);

    // Whale detection: top 1%
    var whaleThresholdIdx = Math.floor(coinBalances.length * 0.99);
    var whaleCount = coinBalances.length - whaleThresholdIdx;

    var ssRatio = sinksTotal > 0 ? analyticsRound(sourcesTotal / sinksTotal, 2) : (sourcesTotal > 0 ? 999 : 0);

    return JSON.stringify({
      total_coins: totalCoins,
      total_gems: totalGems,
      avg_coins: avgCoins,
      median_coins: medCoins,
      max_coins: maxCoins,
      min_coins: minCoins,
      gini_coefficient: gini,
      source_sink_ratio: {
        sources_total: sourcesTotal,
        sinks_total: sinksTotal,
        ratio: ssRatio
      },
      whale_count: whaleCount,
      sample_size: sampleSize
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2EconomyHealth error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 7. rpcAnalyticsV2ErrorLog
// ---------------------------------------------------------------------------

function rpcAnalyticsV2ErrorLog(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameId = avResolveGameId(data.game_id);
    var days = data.days || 7;
    var cutoffSec = analyticsNowSeconds() - days * 86400;

    var result = analyticsSafeList(nk, SYSTEM_USER, "analytics_error_events", 100, "");
    var errors = [];
    if (result && result.objects) {
      for (var i = 0; i < result.objects.length; i++) {
        var val = result.objects[i].value;
        if (!val) continue;
        if (val.timestamp && val.timestamp < cutoffSec) continue;
        if (gameId && val.game_id && val.game_id !== gameId) continue;
        errors.push(val);
      }
    }

    // Group by rpc_name.
    // 2026-04 hardening — widen the bucket-name fallback so we don't
    // dump every "unstamped" client error into one giant "unknown" row.
    // For events that still end up in the unknown bucket, attach a small
    // redacted sample of the row so operators can see WHICH client/event
    // family is missing the rpc_name field upstream (almost always the
    // QuizVerse Unity client's QVAnalyticsService).
    function pickBucketName(err) {
      return err.rpc_name || err.rpcName || err.function || err.endpoint ||
             err.api || err.url || err.source || err.error_category ||
             err.exceptionType || err.errorType || err.eventName ||
             "unknown";
    }
    var rpcMap = {};
    var dailyMap = {};
    var unknownSamples = [];
    for (var ei = 0; ei < errors.length; ei++) {
      var err = errors[ei];
      var rpcName = pickBucketName(err);
      if (!rpcMap[rpcName]) {
        rpcMap[rpcName] = { count: 0, last_occurred: "", sample_error: "" };
      }
      rpcMap[rpcName].count++;
      var errTime = err.timestamp_iso || "";
      if (errTime > rpcMap[rpcName].last_occurred) {
        rpcMap[rpcName].last_occurred = errTime;
        rpcMap[rpcName].sample_error = err.error_message || err.message || err.error || "";
      }

      if (rpcName === "unknown" && unknownSamples.length < 3) {
        var sampleKeys = [];
        for (var sk in err) { if (err.hasOwnProperty(sk)) sampleKeys.push(sk); }
        unknownSamples.push({
          eventName: err.eventName || null,
          keys: sampleKeys.slice(0, 12),
          gameId: err.game_id || err.gameId || null,
          ts: err.timestamp_iso || err.timestamp || null
        });
      }

      var errDate = err.date || "";
      if (errDate) {
        if (!dailyMap[errDate]) dailyMap[errDate] = 0;
        dailyMap[errDate]++;
      }
    }

    var errorsByRpc = [];
    var mostFailing = { name: "", count: 0 };
    for (var rk in rpcMap) {
      if (rpcMap.hasOwnProperty(rk)) {
        var bucket = {
          rpc_name: rk,
          count: rpcMap[rk].count,
          last_occurred: rpcMap[rk].last_occurred,
          sample_error: rpcMap[rk].sample_error
        };
        if (rk === "unknown" && unknownSamples.length) bucket.samples = unknownSamples;
        errorsByRpc.push(bucket);
        if (rpcMap[rk].count > mostFailing.count) {
          mostFailing = { name: rk, count: rpcMap[rk].count };
        }
      }
    }
    errorsByRpc.sort(function (a, b) { return b.count - a.count; });

    var errorTrendDaily = [];
    for (var dk in dailyMap) {
      if (dailyMap.hasOwnProperty(dk)) {
        errorTrendDaily.push({ date: dk, count: dailyMap[dk] });
      }
    }
    errorTrendDaily.sort(function (a, b) { return a.date < b.date ? -1 : 1; });

    return JSON.stringify({
      total_errors: errors.length,
      errors_by_rpc: errorsByRpc,
      error_trend_daily: errorTrendDaily,
      most_failing_rpc: mostFailing
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2ErrorLog error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 8. rpcAnalyticsV2FeatureAdoption
// ---------------------------------------------------------------------------

function rpcAnalyticsV2FeatureAdoption(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var gameId = avResolveGameId(data.game_id);

    var userIds = sampleUserIds(nk, 100);
    var totalSampled = userIds.length;

    var featureDefs = [
      { name: "tournaments",    collection: "tournament_records" },
      { name: "challenges",     collection: "challenges_v2" },
      { name: "daily_missions", collection: "daily_missions" },
      { name: "weekly_goals",   collection: "weekly_goals" },
      { name: "season_pass",    collection: "season_pass" },
      { name: "mystery_box",    collection: "mystery_box" },
      { name: "bounties",       collection: "bounties" },
      { name: "duels",          collection: "duels" },
      { name: "team_quiz",      collection: "team_quiz" },
      { name: "daily_duo",      collection: "daily_duo" },
      { name: "knowledge_duel", collection: "knowledge_duel" },
      { name: "trivia_night",   collection: "trivia_night" },
      { name: "loadouts",       collection: "loadouts" },
      { name: "group_quests",   collection: "group_quests" }
    ];

    var features = [];
    var mostAdopted = { name: "", users_count: 0 };
    var leastAdopted = { name: "", users_count: totalSampled + 1 };

    for (var fi = 0; fi < featureDefs.length; fi++) {
      var def = featureDefs[fi];
      var usersWithFeature = 0;

      for (var ui = 0; ui < userIds.length; ui++) {
        var result = analyticsSafeList(nk, userIds[ui], def.collection, 1, "");
        if (result && result.objects && result.objects.length > 0) {
          usersWithFeature++;
        }
      }

      var adoptionPct = totalSampled > 0 ? analyticsRound((usersWithFeature / totalSampled) * 100, 1) : 0;
      features.push({
        name: def.name,
        users_count: usersWithFeature,
        adoption_pct: adoptionPct,
        collection: def.collection
      });

      if (usersWithFeature > mostAdopted.users_count) {
        mostAdopted = { name: def.name, users_count: usersWithFeature };
      }
      if (usersWithFeature < leastAdopted.users_count) {
        leastAdopted = { name: def.name, users_count: usersWithFeature };
      }
    }

    features.sort(function (a, b) { return b.users_count - a.users_count; });

    // Generate recommendations based on adoption
    var recommendations = [];
    for (var ri = 0; ri < features.length; ri++) {
      if (features[ri].adoption_pct < 10) {
        recommendations.push("Feature '" + features[ri].name + "' has very low adoption (" + features[ri].adoption_pct + "%). Consider improving discoverability or onboarding for this feature.");
      }
    }
    if (recommendations.length === 0) {
      recommendations.push("All features have reasonable adoption rates.");
    }

    return JSON.stringify({
      features: features,
      total_users_sampled: totalSampled,
      most_adopted: mostAdopted.name,
      least_adopted: leastAdopted.name,
      recommendations: recommendations
    });
  } catch (e) {
    logger.error("rpcAnalyticsV2FeatureAdoption error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}

// ---------------------------------------------------------------------------
// 9. rpcAnalyticsV2LogError (helper RPC for error tracking)
// ---------------------------------------------------------------------------

function rpcAnalyticsV2LogError(ctx, logger, nk, payload) {
  try {
    var data = analyticsSafeJsonParse(payload);
    var rpcName = data.rpc_name || "unknown";
    var errorMessage = data.error_message || "";
    var userId = data.user_id || ctx.userId || "";
    var gameId = avResolveGameId(data.game_id) || "";
    var stackTrace = data.stack_trace || "";
    var nowSec = analyticsNowSeconds();
    var todayStr = analyticsDaysAgo(0);

    var errorRecord = {
      rpc_name: rpcName,
      error_message: errorMessage,
      user_id: userId,
      game_id: gameId,
      stack_trace: stackTrace,
      timestamp: nowSec,
      timestamp_iso: new Date().toISOString(),
      date: todayStr
    };

    var key = "error_" + rpcName + "_" + nowSec + "_" + Math.floor(Math.random() * 10000);
    analyticsSafeWrite(nk, "analytics_error_events", key, SYSTEM_USER, errorRecord);

    logger.warn("Error logged for RPC '%s': %s", rpcName, errorMessage);

    return JSON.stringify({ success: true });
  } catch (e) {
    logger.error("rpcAnalyticsV2LogError error: %s", e.message || e);
    return JSON.stringify({ error: e.message || "Internal error" });
  }
}


