function checkCache(nk, cacheKey) {
    try {
        const cached = nk.storageRead([{
            collection: COLLECTIONS.AI_CACHE,
            key: cacheKey,
            userId: null
        }]);
        
        if (cached.length > 0) {
            const data = cached[0].value;
            if (Date.now() - data.cachedAt < data.ttl) {
                return data.data;
            }
        }
    } catch (e) {
        // ignore
    }
    return null;
}

function cacheResult(nk, cacheKey, data, ttl) {
    try {
        nk.storageWrite([{
            collection: COLLECTIONS.AI_CACHE,
            key: cacheKey,
            userId: null,
            value: {
                data,
                cachedAt: Date.now(),
                ttl
            },
            permissionRead: 2,
            permissionWrite: 0
        }]);
    } catch (e) {
        // ignore
    }
}

function logAIRequest(nk, userId, requestType, data) {
    try {
        nk.storageWrite([{
            collection: COLLECTIONS.AI_REQUESTS,
            key: `${requestType}_${Date.now()}`,
            userId: userId,
            value: {
                requestType,
                data,
                timestamp: Date.now()
            },
            permissionRead: 1,
            permissionWrite: 0
        }]);
    } catch (e) {
        // ignore
    }
}

