// --- Module: cross_game\cross_game.js ---
// cross_game.js - Cross-game RPCs for multi-game ecosystem features
// Compatible with Nakama V8 JavaScript runtime (no ES modules)

var SYSTEM_USER_ID = "00000000-0000-0000-0000-000000000000";

var KNOWN_GAMES = [
    "quizverse", "lasttolive",
    // Arcade mini-games
    "5c68cf9d-b738-4cca-bbb0-0ce80748239e",  // Chess Puzzles
    "650636ba-7fa7-4441-9223-08ecd79677ae",  // Crystal 2048
    "02290eb7-bdd5-4dc2-b5d3-619127eeaa99"   // Hex 2248
];

// ============================================================================
// HELPERS
// ============================================================================

function generateCrossGameUUID() {
    var d = new Date().getTime();
    var d2 = (typeof performance !== 'undefined' && performance.now && (performance.now() * 1000)) || 0;
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16;
        if (d > 0) {
            r = (d + r) % 16 | 0;
            d = Math.floor(d / 16);
        } else {
            r = (d2 + r) % 16 | 0;
            d2 = Math.floor(d2 / 16);
        }
        return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
}

function crossGameSafeRead(nk, collection, key, userId) {
    try {
        var recs = nk.storageRead([{ collection: collection, key: key, userId: userId }]);
        if (recs && recs.length > 0) return recs[0].value;
    } catch (_) { /* swallow */ }
    return null;
}

function crossGameSafeWrite(nk, collection, key, userId, value) {
    nk.storageWrite([{
        collection: collection,
        key: key,
        userId: userId,
        value: value,
        permissionRead: 1,
        permissionWrite: 0
    }]);
}

function nowISO() {
    return new Date().toISOString();
}

function resolveUserId(nk, data, ctx) {
    if (ctx.userId && ctx.userId !== SYSTEM_USER_ID) {
        return ctx.userId;
    }
    if (data.device_id) {
        try {
            var users = nk.usersGetId([data.device_id]);
            if (users && users.length > 0) return users[0].id;
        } catch (_) { /* fall through */ }
        try {
            var auth = nk.authenticateDevice(data.device_id, null, false);
            if (auth && auth.id) return auth.id;
        } catch (_) { /* fall through */ }
    }
    return ctx.userId || SYSTEM_USER_ID;
}

// ============================================================================
// RPC 1 – rpcCrossGameBonus
// ============================================================================

/**
 * When a player performs an action in one game, grant a bonus in another game.
 * Payload: { device_id, source_game_id, target_game_id, event_type }
 */
function rpcCrossGameBonus(ctx, logger, nk, payload) {
    logger.info("[cross_game] rpcCrossGameBonus called");

    try {
        var data = JSON.parse(payload || '{}');

        if (!data.source_game_id || !data.target_game_id) {
            return JSON.stringify({ success: false, error: "source_game_id and target_game_id are required" });
        }
        if (!data.event_type) {
            return JSON.stringify({ success: false, error: "event_type is required" });
        }

        var userId = resolveUserId(nk, data, ctx);
        var bonusId = generateCrossGameUUID();
        var bonusAmount = 50;

        var bonusRecord = {
            bonus_id: bonusId,
            source_game_id: data.source_game_id,
            target_game_id: data.target_game_id,
            event_type: data.event_type,
            coins_granted: bonusAmount,
            granted_at: nowISO()
        };

        crossGameSafeWrite(nk, "cross_game_bonuses", "bonus:" + bonusId, userId, bonusRecord);

        try {
            nk.walletUpdate(userId, { coins: bonusAmount }, {
                source: "cross_game_bonus",
                source_game: data.source_game_id,
                target_game: data.target_game_id,
                event_type: data.event_type
            }, true);
        } catch (walletErr) {
            logger.warn("[cross_game] Wallet update failed, using storage fallback: " + walletErr.message);
            var walletKey = "wallet:" + data.target_game_id;
            var wallet = crossGameSafeRead(nk, "cross_game_wallets", walletKey, userId) || { coins: 0 };
            wallet.coins = (wallet.coins || 0) + bonusAmount;
            wallet.updated_at = nowISO();
            crossGameSafeWrite(nk, "cross_game_wallets", walletKey, userId, wallet);
        }

        logger.info("[cross_game] Bonus granted: " + bonusAmount + " coins from " + data.source_game_id + " -> " + data.target_game_id);

        return JSON.stringify({
            success: true,
            bonus_granted: bonusAmount,
            source_game: data.source_game_id,
            target_game: data.target_game_id
        });

    } catch (err) {
        logger.error("[cross_game] rpcCrossGameBonus error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// RPC 2 – rpcCrossGameProfile
// ============================================================================

/**
 * Aggregate player data across all games.
 * Payload: { device_id }
 */
function rpcCrossGameProfile(ctx, logger, nk, payload) {
    logger.info("[cross_game] rpcCrossGameProfile called");

    try {
        var data = JSON.parse(payload || '{}');
        var userId = resolveUserId(nk, data, ctx);

        var gamesPlayed = [];
        var totalXP = 0;
        var totalCoins = 0;
        var achievementsCount = 0;

        for (var i = 0; i < KNOWN_GAMES.length; i++) {
            var gameId = KNOWN_GAMES[i];
            var profileKey = "profile_" + userId;
            var profile = crossGameSafeRead(nk, gameId + "_profiles", profileKey, userId);

            var walletKey = "wallet_" + userId;
            var wallet = crossGameSafeRead(nk, gameId + "_wallets", walletKey, userId);

            var achieveKey = "progress:" + gameId;
            var achievements = crossGameSafeRead(nk, "achievements_progress", achieveKey, userId);

            var level = 0;
            var xp = 0;
            var playtime = 0;
            var coins = 0;

            if (profile) {
                level = profile.level || 0;
                xp = profile.xp || 0;
                playtime = profile.playtime || 0;
            }

            if (wallet) {
                coins = wallet.balance || 0;
            }

            var gameAchievements = 0;
            if (achievements && achievements.events) {
                var keys = Object.keys(achievements.events);
                gameAchievements = keys.length;
            }

            gamesPlayed.push({
                game_id: gameId,
                level: level,
                xp: xp,
                playtime: playtime
            });

            totalXP += xp;
            totalCoins += coins;
            achievementsCount += gameAchievements;
        }

        return JSON.stringify({
            success: true,
            games_played: gamesPlayed,
            total_xp: totalXP,
            total_coins: totalCoins,
            achievements_count: achievementsCount
        });

    } catch (err) {
        logger.error("[cross_game] rpcCrossGameProfile error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// RPC 3 – rpcCrossGameChallenge
// ============================================================================

/**
 * Create a multi-game challenge between two players.
 * Payload: { device_id, target_user_id, game_ids }
 */
function rpcCrossGameChallenge(ctx, logger, nk, payload) {
    logger.info("[cross_game] rpcCrossGameChallenge called");

    try {
        var data = JSON.parse(payload || '{}');

        if (!data.target_user_id) {
            return JSON.stringify({ success: false, error: "target_user_id is required" });
        }
        if (!data.game_ids || !data.game_ids.length) {
            return JSON.stringify({ success: false, error: "game_ids array is required" });
        }

        var userId = resolveUserId(nk, data, ctx);
        var challengeId = generateCrossGameUUID();

        var challenge = {
            challenge_id: challengeId,
            challenger_id: userId,
            target_user_id: data.target_user_id,
            game_ids: data.game_ids,
            status: "pending",
            scores: {},
            created_at: nowISO()
        };

        for (var i = 0; i < data.game_ids.length; i++) {
            challenge.scores[data.game_ids[i]] = {
                challenger: 0,
                target: 0
            };
        }

        crossGameSafeWrite(nk, "cross_game_challenges", "challenge:" + challengeId, userId, challenge);
        crossGameSafeWrite(nk, "cross_game_challenges", "challenge:" + challengeId, data.target_user_id, challenge);

        try {
            // Code 7601 is outside friend lifecycle 1–6 / 100–105.
            nk.notificationsSend([{
                userId: data.target_user_id,
                subject: "Cross-Game Challenge!",
                content: {
                    type: "cross_game_challenge",
                    eventType: "cross_game_challenge",
                    challenge_id: challengeId,
                    challenger_id: userId,
                    games: data.game_ids
                },
                code: 7601,
                persistent: true,
                senderId: userId
            }]);
        } catch (notifErr) {
            logger.warn("[cross_game] Challenge notification failed: " + notifErr.message);
        }

        logger.info("[cross_game] Challenge created: " + challengeId + " across " + data.game_ids.length + " games");

        return JSON.stringify({
            success: true,
            challenge_id: challengeId,
            games: data.game_ids,
            status: "pending"
        });

    } catch (err) {
        logger.error("[cross_game] rpcCrossGameChallenge error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// RPC 4 – rpcGameDiscoveryReward
// ============================================================================

/**
 * First-time bonus for trying a new game.
 * Payload: { device_id, game_id }
 */
function rpcGameDiscoveryReward(ctx, logger, nk, payload) {
    logger.info("[cross_game] rpcGameDiscoveryReward called");

    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id) {
            return JSON.stringify({ success: false, error: "game_id is required" });
        }

        var userId = resolveUserId(nk, data, ctx);
        var claimKey = "discovery:" + data.game_id;

        var existing = crossGameSafeRead(nk, "cross_game_bonuses", claimKey, userId);
        if (existing) {
            return JSON.stringify({
                success: true,
                first_time: false,
                reward: null,
                message: "Discovery reward already claimed for " + data.game_id
            });
        }

        var reward = { coins: 100, gems: 25 };

        try {
            nk.walletUpdate(userId, { coins: reward.coins, gems: reward.gems }, {
                source: "game_discovery",
                game_id: data.game_id
            }, true);
        } catch (walletErr) {
            logger.warn("[cross_game] Discovery wallet update failed, using storage: " + walletErr.message);
            var walletKey = "wallet:" + data.game_id;
            var wallet = crossGameSafeRead(nk, "cross_game_wallets", walletKey, userId) || { coins: 0, gems: 0 };
            wallet.coins = (wallet.coins || 0) + reward.coins;
            wallet.gems = (wallet.gems || 0) + reward.gems;
            wallet.updated_at = nowISO();
            crossGameSafeWrite(nk, "cross_game_wallets", walletKey, userId, wallet);
        }

        var claimRecord = {
            game_id: data.game_id,
            reward: reward,
            claimed_at: nowISO()
        };
        crossGameSafeWrite(nk, "cross_game_bonuses", claimKey, userId, claimRecord);

        logger.info("[cross_game] Discovery reward granted for " + data.game_id + ": " + reward.coins + " coins + " + reward.gems + " gems");

        return JSON.stringify({
            success: true,
            first_time: true,
            reward: reward
        });

    } catch (err) {
        logger.error("[cross_game] rpcGameDiscoveryReward error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// RPC 5 – rpcGlobalLeaderboardComposite
// ============================================================================

/**
 * Read top scores from multiple game leaderboards, compute combined ranking.
 * Payload: { limit }
 */
function rpcGlobalLeaderboardComposite(ctx, logger, nk, payload) {
    logger.info("[cross_game] rpcGlobalLeaderboardComposite called");

    try {
        var data = JSON.parse(payload || '{}');
        var limit = data.limit || 10;
        if (limit < 1) limit = 1;
        if (limit > 100) limit = 100;

        var leaderboardIds = [
            "quizverse_weekly",
            "lasttolive_survivor_rank"
        ];

        var playerScores = {};

        for (var i = 0; i < leaderboardIds.length; i++) {
            var lbId = leaderboardIds[i];
            try {
                var result = nk.leaderboardRecordsList(lbId, null, 100, null, 0);
                var records = (result && result.records) ? result.records : [];

                for (var j = 0; j < records.length; j++) {
                    var rec = records[j];
                    var uid = rec.ownerId || rec.owner_id;
                    if (!uid) continue;

                    if (!playerScores[uid]) {
                        playerScores[uid] = {
                            user_id: uid,
                            username: rec.username || "",
                            total_score: 0,
                            game_scores: {}
                        };
                    }

                    var score = Number(rec.score) || 0;
                    playerScores[uid].game_scores[lbId] = score;
                    playerScores[uid].total_score += score;

                    if (rec.username && !playerScores[uid].username) {
                        playerScores[uid].username = rec.username;
                    }
                }
            } catch (lbErr) {
                logger.warn("[cross_game] Leaderboard " + lbId + " read failed: " + lbErr.message);
            }
        }

        var rankings = [];
        var uids = Object.keys(playerScores);
        for (var k = 0; k < uids.length; k++) {
            rankings.push(playerScores[uids[k]]);
        }

        rankings.sort(function (a, b) {
            return b.total_score - a.total_score;
        });

        if (rankings.length > limit) {
            rankings = rankings.slice(0, limit);
        }

        return JSON.stringify({
            success: true,
            rankings: rankings
        });

    } catch (err) {
        logger.error("[cross_game] rpcGlobalLeaderboardComposite error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// REGISTRATION
// ============================================================================

function registerCrossGameRPCs(initializer, logger) {
    logger.info('[CrossGame] Initializing Cross-Game RPC Module...');

    if (!globalThis.__registeredRPCs) {
        globalThis.__registeredRPCs = new Set();
    }

    var rpcs = [
        { id: 'cross_game_bonus', handler: rpcCrossGameBonus },
        { id: 'cross_game_profile', handler: rpcCrossGameProfile },
        { id: 'cross_game_challenge', handler: rpcCrossGameChallenge },
        { id: 'game_discovery_reward', handler: rpcGameDiscoveryReward },
        { id: 'global_leaderboard_composite', handler: rpcGlobalLeaderboardComposite }
    ];

    var registered = 0;
    var skipped = 0;

    for (var i = 0; i < rpcs.length; i++) {
        var rpc = rpcs[i];
        if (!globalThis.__registeredRPCs.has(rpc.id)) {
            try {
                initializer.registerRpc(rpc.id, rpc.handler);
                globalThis.__registeredRPCs.add(rpc.id);
                registered++;
            } catch (err) {
                logger.error('[CrossGame] Failed to register ' + rpc.id + ': ' + err.message);
            }
        } else {
            skipped++;
        }
    }

    logger.info('[CrossGame] Registration complete: ' + registered + ' registered, ' + skipped + ' skipped');
}


// --- Module: daily_missions\daily_missions.js ---
// daily_missions.js - Daily Missions System (Per gameId UUID)

/**
 * Mission configurations per gameId UUID
 * This can be extended or moved to storage for dynamic configuration
 */
var MISSION_CONFIGS = {
    // Default missions for any game
    "default": [
        {
            id: "login_daily",
            name: "Daily Login",
            description: "Log in to the game",
            objective: "login",
            targetValue: 1,
            rewards: { xp: 50, tokens: 5 }
        },
        {
            id: "play_matches",
            name: "Play Matches",
            description: "Complete 3 matches",
            objective: "matches_played",
            targetValue: 3,
            rewards: { xp: 100, tokens: 10 }
        },
        {
            id: "score_points",
            name: "Score Points",
            description: "Score 1000 points",
            objective: "total_score",
            targetValue: 1000,
            rewards: { xp: 150, tokens: 15 }
        }
    ]
};

/**
 * Get mission configurations for a game
 * @param {string} gameId - Game ID (UUID)
 * @returns {Array} Mission configurations
 */
function getMissionConfig(gameId) {
    return MISSION_CONFIGS[gameId] || MISSION_CONFIGS["default"];
}

/**
 * Get or create daily mission progress for user
 * @param {object} nk - Nakama runtime
 * @param {object} logger - Logger instance
 * @param {string} userId - User ID
 * @param {string} gameId - Game ID (UUID)
 * @returns {object} Mission progress data
 */
function getMissionProgress(nk, logger, userId, gameId) {
    var collection = "daily_missions";
    var key = utils.makeGameStorageKey("mission_progress", userId, gameId);
    
    var data = utils.readStorage(nk, logger, collection, key, userId);
    
    if (!data || !isToday(data.resetDate)) {
        // Initialize new daily missions
        var missions = getMissionConfig(gameId);
        var progress = {};
        
        for (var i = 0; i < missions.length; i++) {
            progress[missions[i].id] = {
                currentValue: 0,
                targetValue: missions[i].targetValue,
                completed: false,
                claimed: false
            };
        }
        
        data = {
            userId: userId,
            gameId: gameId,
            resetDate: utils.getStartOfDay(),
            progress: progress,
            updatedAt: utils.getCurrentTimestamp()
        };
    }
    
    return data;
}

/**
 * Check if a timestamp is from today
 * @param {number} timestamp - Unix timestamp (seconds)
 * @returns {boolean} True if timestamp is from today
 */
function isToday(timestamp) {
    if (!timestamp) return false;
    var todayStart = utils.getStartOfDay();
    var tomorrowStart = todayStart + 86400; // +24 hours
    return timestamp >= todayStart && timestamp < tomorrowStart;
}

/**
 * Save mission progress
 * @param {object} nk - Nakama runtime
 * @param {object} logger - Logger instance
 * @param {string} userId - User ID
 * @param {string} gameId - Game ID (UUID)
 * @param {object} data - Mission progress data
 * @returns {boolean} Success status
 */
function saveMissionProgress(nk, logger, userId, gameId, data) {
    var collection = "daily_missions";
    var key = utils.makeGameStorageKey("mission_progress", userId, gameId);
    data.updatedAt = utils.getCurrentTimestamp();
    return utils.writeStorage(nk, logger, collection, key, userId, data);
}

/**
 * RPC: Get daily missions
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON payload with { gameId: "uuid" }
 * @returns {string} JSON response
 */
function rpcGetDailyMissions(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC get_daily_missions called");
    
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    var validation = utils.validatePayload(data, ['gameId']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }
    
    var gameId = data.gameId;
    if (!utils.isValidUUID(gameId)) {
        return utils.handleError(ctx, null, "Invalid gameId UUID format");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    // Get mission progress
    var progressData = getMissionProgress(nk, logger, userId, gameId);
    
    // Get mission configs
    var missions = getMissionConfig(gameId);
    
    // Build response with mission details and progress
    var missionsList = [];
    for (var i = 0; i < missions.length; i++) {
        var mission = missions[i];
        var progress = progressData.progress[mission.id] || {
            currentValue: 0,
            targetValue: mission.targetValue,
            completed: false,
            claimed: false
        };
        
        missionsList.push({
            id: mission.id,
            name: mission.name,
            description: mission.description,
            objective: mission.objective,
            currentValue: progress.currentValue,
            targetValue: progress.targetValue,
            completed: progress.completed,
            claimed: progress.claimed,
            rewards: mission.rewards
        });
    }
    
    return JSON.stringify({
        success: true,
        userId: userId,
        gameId: gameId,
        resetDate: progressData.resetDate,
        missions: missionsList,
        timestamp: utils.getCurrentTimestamp()
    });
}

/**
 * RPC: Submit mission progress
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON payload with { gameId: "uuid", missionId: "string", value: number }
 * @returns {string} JSON response
 */
function rpcSubmitMissionProgress(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC submit_mission_progress called");
    
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    var validation = utils.validatePayload(data, ['gameId', 'missionId', 'value']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }
    
    var gameId = data.gameId;
    if (!utils.isValidUUID(gameId)) {
        return utils.handleError(ctx, null, "Invalid gameId UUID format");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    var missionId = data.missionId;
    var value = data.value;
    
    // Get current progress
    var progressData = getMissionProgress(nk, logger, userId, gameId);
    
    // Check if mission exists
    if (!progressData.progress[missionId]) {
        return utils.handleError(ctx, null, "Mission not found: " + missionId);
    }
    
    var missionProgress = progressData.progress[missionId];
    
    // Update progress
    missionProgress.currentValue += value;
    
    // Check if completed
    if (missionProgress.currentValue >= missionProgress.targetValue && !missionProgress.completed) {
        missionProgress.completed = true;
        utils.logInfo(logger, "Mission " + missionId + " completed for user " + userId);
    }
    
    // Save progress
    if (!saveMissionProgress(nk, logger, userId, gameId, progressData)) {
        return utils.handleError(ctx, null, "Failed to save mission progress");
    }
    
    return JSON.stringify({
        success: true,
        userId: userId,
        gameId: gameId,
        missionId: missionId,
        currentValue: missionProgress.currentValue,
        targetValue: missionProgress.targetValue,
        completed: missionProgress.completed,
        claimed: missionProgress.claimed,
        timestamp: utils.getCurrentTimestamp()
    });
}

/**
 * RPC: Claim mission reward
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON payload with { gameId: "uuid", missionId: "string" }
 * @returns {string} JSON response
 */
function rpcClaimMissionReward(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC claim_mission_reward called");
    
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    var validation = utils.validatePayload(data, ['gameId', 'missionId']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }
    
    var gameId = data.gameId;
    if (!utils.isValidUUID(gameId)) {
        return utils.handleError(ctx, null, "Invalid gameId UUID format");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    var missionId = data.missionId;
    
    // Get current progress
    var progressData = getMissionProgress(nk, logger, userId, gameId);
    
    // Check if mission exists
    if (!progressData.progress[missionId]) {
        return utils.handleError(ctx, null, "Mission not found: " + missionId);
    }
    
    var missionProgress = progressData.progress[missionId];
    
    // Check if completed
    if (!missionProgress.completed) {
        return JSON.stringify({
            success: false,
            error: "Mission not completed yet"
        });
    }
    
    // Check if already claimed
    if (missionProgress.claimed) {
        return JSON.stringify({
            success: false,
            error: "Reward already claimed"
        });
    }
    
    // Mark as claimed
    missionProgress.claimed = true;
    
    // Get mission config to retrieve rewards
    var missions = getMissionConfig(gameId);
    var missionConfig = null;
    for (var i = 0; i < missions.length; i++) {
        if (missions[i].id === missionId) {
            missionConfig = missions[i];
            break;
        }
    }
    
    if (!missionConfig) {
        return utils.handleError(ctx, null, "Mission configuration not found");
    }
    
    // Save progress
    if (!saveMissionProgress(nk, logger, userId, gameId, progressData)) {
        return utils.handleError(ctx, null, "Failed to save mission progress");
    }
    
    // Log reward claim for transaction history
    var transactionKey = "transaction_log_" + userId + "_" + utils.getUnixTimestamp();
    var transactionData = {
        userId: userId,
        gameId: gameId,
        type: "mission_reward_claim",
        missionId: missionId,
        rewards: missionConfig.rewards,
        timestamp: utils.getCurrentTimestamp()
    };
    utils.writeStorage(nk, logger, "transaction_logs", transactionKey, userId, transactionData);
    
    utils.logInfo(logger, "User " + userId + " claimed mission reward for " + missionId);
    
    // Grant rewards to wallet (tokens mapped to coins)
    var walletChanges = {};
    if (missionConfig.rewards.tokens) walletChanges.coins = missionConfig.rewards.tokens;
    if (missionConfig.rewards.xp) walletChanges.xp = missionConfig.rewards.xp;
    if (Object.keys(walletChanges).length > 0) {
        try {
            nk.walletUpdate(userId, walletChanges, { source: "daily_mission", missionId: missionId, gameId: gameId }, true);
            logger.info("[DailyMissions] Granted wallet: " + JSON.stringify(walletChanges) + " to " + userId);
        } catch (walletErr) {
            logger.error("[DailyMissions] Wallet grant failed: " + walletErr.message);
        }
    }
    
    return JSON.stringify({
        success: true,
        userId: userId,
        gameId: gameId,
        missionId: missionId,
        rewards: missionConfig.rewards,
        walletGranted: walletChanges,
        claimedAt: utils.getCurrentTimestamp()
    });
}


// --- Module: daily_rewards\daily_progress.js ---
// daily_progress.js — DAILY PROGRESSION PLATFORM (consolidated surface)
//
// This module is the OFFICIAL client-facing surface for daily login rewards,
// login streaks (advanced on app open / daily_progress_check), the streak
// dashboard, calendar, shield/freeze state, and any future daily-progression
// feature. It exposes exactly TWO production RPCs:
//
//   1. daily_progress_check — advances login streak once per UTC day, then
//      returns EVERYTHING the client needs: streak, claim eligibility,
//      countdown/next reset, next reward, 7-day reward table, 30-day calendar
//      + milestones, claim history, shield state, server UTC time, payload version.
//
//   2. daily_progress_claim — validates, performs the ATOMIC/IDEMPOTENT claim
//      (delegating to performDailyClaim in daily_rewards.js — the single claim
//      core; does NOT bump login streak), and returns the SAME full state as
//      check so the client never needs a follow-up refresh RPC.
//
// SINGLE SOURCE OF TRUTH RULES:
//   - Login streak:        currentStreak / lastOpenTimestamp via performAppOpenStreak
//   - Claim cycle:         totalClaims / lastClaimTimestamp / claimHistory
//   - Streak storage:      daily_streaks / user_daily_streak (daily_rewards.js)
//   - Claim core:          performDailyClaim (daily_rewards.js) — OCC versioned
//   - Eligibility:         canClaimToday (daily_rewards.js) — UTC day window
//   - Reward table:        REWARD_CONFIGS (daily_rewards.js)
//   - Calendar config:     CALENDAR_REWARD_CONFIGS (daily_reward_calendar.js)
//   - Shield storage:      streak_shield / shield (legacy_runtime.js retention)
//
// The legacy RPCs (daily_rewards_get_status/claim/get_history,
// daily_reward_get_calendar, quizverse_claim_daily_reward) remain registered
// ONLY for already-shipped clients and all delegate to the same core functions.
// Do not add new callers to them.

var DAILY_PROGRESS_VERSION = 1;
var DP_QUIZVERSE_GAME_ID = "126bf539-dae2-4bcf-964d-316c0fa1f92b";

/**
 * Accepts gameId under any historical alias (gameId / gameID / game_id) and
 * normalizes non-UUID slugs to the QuizVerse UUID so legacy Arcade payloads
 * ("quizverse") resolve to the SAME streak record as the main game.
 */
function dpResolveGameId(data) {
    var raw = (data && (data.gameId || data.gameID || data.game_id)) || "";
    if (raw && utils.isValidUUID(raw)) return raw;
    return DP_QUIZVERSE_GAME_ID;
}

/** Next UTC midnight (the daily reset) as ISO string + seconds remaining. */
function dpNextReset() {
    var d = new Date();
    d.setUTCHours(24, 0, 0, 0);
    var resetUnix = Math.floor(d.getTime() / 1000);
    return {
        nextResetUtc: d.toISOString(),
        countdownSeconds: Math.max(0, resetUnix - Math.floor(Date.now() / 1000))
    };
}

/**
 * Read streak shield state (retention system, legacy_runtime.js storage:
 * collection "streak_shield", key "shield", ms-epoch expiryTime).
 * Fail-open to "no shield" — shield display must never break the check RPC.
 */
function dpReadShield(nk, logger, userId) {
    try {
        var rows = nk.storageRead([{ collection: "streak_shield", key: "shield", userId: userId }]);
        if (rows && rows.length > 0 && rows[0].value) {
            var s = rows[0].value;
            var nowMs = Date.now();
            var active = !!s.isActive && (s.expiryTime || 0) > nowMs;
            return {
                isActive: active,
                expiryUnix: active ? Math.floor(s.expiryTime / 1000) : 0,
                hoursRemaining: active ? Math.ceil((s.expiryTime - nowMs) / 3600000) : 0
            };
        }
    } catch (e) {
        utils.logWarn(logger, "[DailyProgress] Shield read skipped: " + e.message);
    }
    return { isActive: false, expiryUnix: 0, hoursRemaining: 0 };
}

/**
 * Build the 30-day calendar view + milestones from ALREADY-RESOLVED streak
 * state. Extracted from rpcDailyRewardGetCalendar so the legacy calendar RPC
 * and daily_progress_check share ONE implementation (the legacy copy also had
 * a local-timezone eligibility bug and hand-rolled storage keys — both gone:
 * callers now resolve state via the canonical getStreakData/canClaimToday).
 */
function buildDailyRewardCalendarView(gameId, claimCycleDay, canClaim) {
    var config = getCalendarConfig(gameId);
    var calendar = [];
    var milestones = [];
    var totalTokens = 0;
    var totalXp = 0;

    for (var day = 1; day <= 30; day++) {
        var dayConfig = null;
        for (var c = 0; c < config.length; c++) {
            if (config[c].day === day) { dayConfig = config[c]; break; }
        }
        if (!dayConfig) {
            var weekDay = ((day - 1) % 7);
            var base = config[weekDay] || config[0];
            var weekNum = Math.floor((day - 1) / 7) + 1;
            dayConfig = {
                day: day,
                xp: Math.round(base.xp * (1 + (weekNum - 1) * 0.15)),
                tokens: Math.round(base.tokens * (1 + (weekNum - 1) * 0.15)),
                name: base.name,
                tier: base.tier,
                icon: base.icon
            };
        }

        totalTokens += dayConfig.tokens || 0;
        totalXp += dayConfig.xp || 0;

        // Claim calendar uses totalClaims cycle — not login currentStreak.
        var status = 'locked';
        if (day <= claimCycleDay) {
            status = 'claimed';
        } else if (day === claimCycleDay + 1 && canClaim) {
            status = 'available';
        } else if (day === claimCycleDay + 1 && !canClaim) {
            status = 'claimed_today';
        }

        calendar.push({
            day: day,
            name: dayConfig.name,
            tier: dayConfig.tier || 'common',
            icon: dayConfig.icon || 'coin_stack',
            rewards: {
                xp: dayConfig.xp || 0,
                tokens: dayConfig.tokens || 0,
                multiplier: dayConfig.multiplier || null,
                bonus: dayConfig.bonus || null
            },
            status: status
        });
    }

    for (var m = 0; m < config.length; m++) {
        if (config[m].tier === 'rare' || config[m].tier === 'epic' || config[m].tier === 'legendary') {
            milestones.push({
                day: config[m].day,
                name: config[m].name,
                tier: config[m].tier,
                reached: config[m].day <= claimCycleDay
            });
        }
    }

    return { calendar: calendar, milestones: milestones, totalTokens30: totalTokens, totalXp30: totalXp };
}

/**
 * Assemble the FULL daily-progression state — the single response body used by
 * both production RPCs. Flat legacy aliases (streak / currentStreak / canClaim
 * / canClaimToday / lastClaimTimestamp / totalClaims / nextReward /
 * claimHistory / bestStreak) are preserved so every shipped C# model
 * deserializes this payload without change.
 */
function buildDailyProgressState(nk, logger, userId, gameId) {
    // App open advances login streak once per UTC day (server-authoritative).
    var streakData = performAppOpenStreak(nk, logger, userId, gameId);

    var claimCheck = canClaimToday(streakData);
    var claimCycle = streakData.totalClaims || 0;
    var nextReward = getRewardForDay(gameId, claimCycle + 1);
    var rewardTable = REWARD_CONFIGS[gameId] || REWARD_CONFIGS["default"];
    var cal = buildDailyRewardCalendarView(gameId, claimCycle, claimCheck.canClaim);
    var shield = dpReadShield(nk, logger, userId);
    var reset = dpNextReset();

    return {
        // ── envelope ──
        v: DAILY_PROGRESS_VERSION,
        serverTimeUtc: new Date().toISOString(),
        serverUnix: Math.floor(Date.now() / 1000),
        userId: userId,
        gameId: gameId,

        // ── login streak (app open) ──
        streak: streakData.currentStreak,
        currentStreak: streakData.currentStreak,
        bestStreak: streakData.bestStreak || 0,
        totalClaims: claimCycle,
        lastClaimTimestamp: streakData.lastClaimTimestamp || 0,
        lastOpenTimestamp: streakData.lastOpenTimestamp || 0,

        // ── claim eligibility ──
        canClaim: claimCheck.canClaim,
        canClaimToday: claimCheck.canClaim,
        claimReason: claimCheck.reason,
        nextResetUtc: reset.nextResetUtc,
        countdownSeconds: reset.countdownSeconds,

        // ── rewards (claim cycle) ──
        nextReward: nextReward,
        rewardTable: rewardTable,

        // ── calendar / history ──
        calendar: cal.calendar,
        milestones: cal.milestones,
        claimHistory: streakData.claimHistory || [],

        // ── shield / freeze ──
        shield: shield
    };
}

/** Shared payload validation for both production RPCs. */
function dpValidate(ctx, payload) {
    var parsed = utils.safeJsonParse(payload || "{}");
    if (!parsed.success) return { error: "Invalid JSON payload" };
    if (!ctx.userId) return { error: "User not authenticated" };
    return { data: parsed.data || {}, userId: ctx.userId };
}

/**
 * RPC 1: daily_progress_check
 * One request → everything the client UI needs.
 * Payload: { gameId?: "uuid" } (defaults to QuizVerse)
 */
function rpcDailyProgressCheck(ctx, logger, nk, payload) {
    var v = dpValidate(ctx, payload);
    if (v.error) return JSON.stringify({ success: false, error: v.error });

    var gameId = dpResolveGameId(v.data);
    var state = buildDailyProgressState(nk, logger, v.userId, gameId);
    state.success = true;
    return JSON.stringify(state);
}

/**
 * RPC 2: daily_progress_claim
 * Atomic + idempotent claim (OCC versioned write via performDailyClaim), then
 * returns the FULL refreshed state — no follow-up RPC required. On rejection
 * the CURRENT full state is still included so the client can resync instantly.
 * Payload: { gameId?: "uuid" }
 */
function rpcDailyProgressClaim(ctx, logger, nk, payload) {
    var v = dpValidate(ctx, payload);
    if (v.error) return JSON.stringify({ success: false, error: v.error });

    var gameId = dpResolveGameId(v.data);
    var result = performDailyClaim(nk, logger, v.userId, gameId);

    var state = buildDailyProgressState(nk, logger, v.userId, gameId);

    if (!result.ok) {
        // Idempotent double-tap / concurrent claim: streak already advanced for
        // today's UTC day. Returning success:false here made Unity show
        // "Claim failed" even though the first writer landed the claim.
        if (result.reason === "already_claimed_today" &&
            state.lastClaimTimestamp > 0 &&
            !state.canClaim) {
            var todayUtc = (typeof getTodayUtcDateString === "function")
                ? getTodayUtcDateString()
                : new Date().toISOString().slice(0, 10);
            var lastDate = (typeof getUtcDateStringFromUnix === "function")
                ? getUtcDateStringFromUnix(state.lastClaimTimestamp)
                : "";
            if (lastDate === todayUtc) {
                state.success = true;
                state.error = null;
                state.idempotentReplay = true;
                state.reward = state.reward || getRewardForDay(gameId, state.totalClaims || 1);
                state.walletGranted = state.walletGranted || {
                    game: (state.reward && (state.reward.game || state.reward.tokens)) || 0,
                    xp: (state.reward && state.reward.xp) || 0
                };
                state.newStreak = state.currentStreak;
                state.claimedAt = utils.getCurrentTimestamp();
                return JSON.stringify(state);
            }
        }
        state.success = false;
        state.error = result.error;
        state.claimRejectedReason = result.reason;
        return JSON.stringify(state);
    }

    state.success = true;
    // Claim result block + flat legacy aliases used by the shipped
    // C# DailyRewardClaim model ([JsonProperty("streak")] → newStreak, reward).
    state.reward = result.reward;
    state.walletGranted = result.walletGranted;
    state.newStreak = result.streakData.currentStreak;
    state.claimedAt = utils.getCurrentTimestamp();
    return JSON.stringify(state);
}

// ============================================================================
// Registration — postbuild.js renames InitModule → __ModuleInit_N and wires the
// literal registerRpc calls into the master InitModule (see daily_rewards.js).
// ============================================================================
function __ModuleInit_49(ctx, logger, nk, initializer) {
    __rpc_daily_progress_check = __rpc_daily_progress_check || (rpcDailyProgressCheck);
    __rpc_daily_progress_claim = __rpc_daily_progress_claim || (rpcDailyProgressClaim);
    logger.info("[DailyProgress] Platform registered: 2 RPCs (check, claim)");
}


