// ─── 1. Flash Event Create ──────────────────────────────────────────────────

var rpcFlashEventCreate = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var gameId = input.game_id;
  var eventName = input.event_name;
  var eventType = input.event_type;
  var multiplier = input.multiplier || 2;
  var durationMinutes = input.duration_minutes || 60;
  var description = input.description || "";

  var validTypes = ["double_xp", "bonus_coins", "special_category", "tournament_blitz", "happy_hour"];
  if (validTypes.indexOf(eventType) === -1) {
    throw Error("invalid event_type: " + eventType);
  }

  var now = nowSeconds();
  var eventId = uuid();

  var eventData = {
    event_id: eventId,
    game_id: gameId,
    event_name: eventName,
    event_type: eventType,
    multiplier: multiplier,
    duration_minutes: durationMinutes,
    description: description,
    start_time: now,
    end_time: now + (durationMinutes * 60),
    created_by: ctx.userId,
    created_at: now
  };

  nk.storageWrite([{
    collection: "flash_events",
    key: eventId,
    userId: "00000000-0000-0000-0000-000000000000",
    value: eventData,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Flash event created: %s (%s) for game %s", eventName, eventType, gameId);
  return JSON.stringify({ success: true, event: eventData });
};

// ─── 2. Flash Event List Active ─────────────────────────────────────────────

var rpcFlashEventListActive = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var gameId = input.game_id;
  var now = nowSeconds();

  var query = "+collection:flash_events +value.game_id:" + gameId;
  var results = nk.storageIndexList("flash_events_idx", query, 100);

  var active = [];
  if (results && results.objects) {
    for (var i = 0; i < results.objects.length; i++) {
      var obj = results.objects[i];
      var val = obj.value;
      if (val.start_time <= now && val.end_time > now) {
        val.time_remaining_seconds = val.end_time - now;
        active.push(val);
      }
    }
  }

  // Fallback: list via storageList if index not available
  if (active.length === 0) {
    var cursor = "";
    var systemId = "00000000-0000-0000-0000-000000000000";
    var listed = nk.storageList(systemId, "flash_events", 100, cursor);
    if (listed && listed.objects) {
      for (var j = 0; j < listed.objects.length; j++) {
        var item = listed.objects[j];
        var v = item.value;
        if (v.game_id === gameId && v.start_time <= now && v.end_time > now) {
          v.time_remaining_seconds = v.end_time - now;
          active.push(v);
        }
      }
    }
  }

  return JSON.stringify({ active_events: active, count: active.length });
};

// ─── 3. Mystery Box Grant ───────────────────────────────────────────────────

var rpcMysteryBoxGrant = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var userId = input.user_id;
  var gameId = input.game_id;
  var boxType = input.box_type || "common";
  var source = input.source || "unknown";

  var validBoxTypes = ["common", "rare", "epic", "legendary"];
  if (validBoxTypes.indexOf(boxType) === -1) {
    throw Error("invalid box_type: " + boxType);
  }

  var boxId = uuid();
  var now = nowSeconds();

  var boxData = {
    box_id: boxId,
    game_id: gameId,
    box_type: boxType,
    source: source,
    granted_to: userId,
    granted_at: now,
    opened: false,
    opened_at: null,
    reward: null
  };

  nk.storageWrite([{
    collection: "mystery_boxes",
    key: boxId,
    userId: userId,
    value: boxData,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Mystery box (%s) granted to %s from %s", boxType, userId, source);
  return JSON.stringify({ success: true, box: boxData });
};

// ─── 4. Mystery Box Open ────────────────────────────────────────────────────

var rpcMysteryBoxOpen = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var boxId = input.box_id;
  var gameId = input.game_id;
  var userId = ctx.userId;

  var records = nk.storageRead([{
    collection: "mystery_boxes",
    key: boxId,
    userId: userId
  }]);

  if (!records || records.length === 0) {
    throw Error("mystery box not found: " + boxId);
  }

  var box = records[0].value;

  if (box.opened) {
    throw Error("mystery box already opened: " + boxId);
  }

  if (box.game_id !== gameId) {
    throw Error("box does not belong to game: " + gameId);
  }

  var table = MYSTERY_BOX_TABLES[box.box_type];
  if (!table) {
    throw Error("unknown box_type on stored box: " + box.box_type);
  }

  var pick = weightedPick(table);
  var walletChangeset = {};
  if (pick.reward.coins) { walletChangeset.coins = pick.reward.coins; }
  if (pick.reward.gems)  { walletChangeset.gems = pick.reward.gems; }

  if (walletChangeset.coins || walletChangeset.gems) {
    nk.walletUpdate(userId, walletChangeset, { source: "mystery_box", box_type: box.box_type, box_id: boxId }, true);
  }

  var now = nowSeconds();
  box.opened = true;
  box.opened_at = now;
  box.reward = {
    label: pick.label,
    coins: pick.reward.coins || 0,
    gems: pick.reward.gems || 0,
    badge: pick.reward.badge || null,
    avatar: pick.reward.avatar || null
  };

  nk.storageWrite([{
    collection: "mystery_boxes",
    key: boxId,
    userId: userId,
    value: box,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Mystery box %s opened by %s: %s", boxId, userId, pick.label);
  return JSON.stringify({ success: true, reward: box.reward, box_type: box.box_type });
};

// ─── 5. Daily Spotlight ─────────────────────────────────────────────────────

var SPOTLIGHT_CATEGORIES = [
  "Science", "History", "Geography", "Entertainment",
  "Sports", "Technology", "Art", "Music", "Literature", "Nature"
];

var rpcDailySpotlight = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var gameId = input.game_id;
  var today = todayKey();
  var spotlightKey = gameId + "_" + today;

  var records = nk.storageRead([{
    collection: "daily_spotlight",
    key: spotlightKey,
    userId: "00000000-0000-0000-0000-000000000000"
  }]);

  if (records && records.length > 0) {
    return JSON.stringify({ spotlight: records[0].value, cached: true });
  }

  // Generate today's spotlight
  var featuredCategoryIdx = Math.floor(Math.random() * SPOTLIGHT_CATEGORIES.length);
  var bonusCategoryIdx = (featuredCategoryIdx + 1 + Math.floor(Math.random() * (SPOTLIGHT_CATEGORIES.length - 1))) % SPOTLIGHT_CATEGORIES.length;

  var spotlight = {
    game_id: gameId,
    date: today,
    featured_category: SPOTLIGHT_CATEGORIES[featuredCategoryIdx],
    bonus_category: SPOTLIGHT_CATEGORIES[bonusCategoryIdx],
    bonus_multiplier: 2,
    featured_player: null,
    featured_group: null,
    tip_of_the_day: "Challenge a friend today for bonus rewards!",
    created_at: nowSeconds()
  };

  // Try to find top scorer via leaderboard
  try {
    var leaderboardId = gameId + "_daily";
    var topRecords = nk.leaderboardRecordsList(leaderboardId, null, 1, null, 0);
    if (topRecords && topRecords.records && topRecords.records.length > 0) {
      var topRecord = topRecords.records[0];
      spotlight.featured_player = {
        user_id: topRecord.ownerId,
        username: topRecord.username || "Anonymous",
        score: topRecord.score
      };
    }
  } catch (e) {
    logger.warn("Could not fetch leaderboard for spotlight: %s", e.message);
  }

  // Try to find most active group
  try {
    var groups = nk.groupsList(null, null, null, null, 1, null);
    if (groups && groups.groups && groups.groups.length > 0) {
      var g = groups.groups[0];
      spotlight.featured_group = {
        group_id: g.id,
        name: g.name,
        member_count: g.edgeCount
      };
    }
  } catch (e) {
    logger.warn("Could not fetch groups for spotlight: %s", e.message);
  }

  nk.storageWrite([{
    collection: "daily_spotlight",
    key: spotlightKey,
    userId: "00000000-0000-0000-0000-000000000000",
    value: spotlight,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  return JSON.stringify({ spotlight: spotlight, cached: false });
};

// ─── 6. Streak Milestone Celebrate ──────────────────────────────────────────

var rpcStreakMilestoneCelebrate = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var deviceId = input.device_id;
  var gameId = input.game_id;
  var streakCount = input.streak_count;
  var userId = ctx.userId;

  var milestoneReward = STREAK_MILESTONES[streakCount];
  if (!milestoneReward) {
    return JSON.stringify({
      milestone_reached: false,
      streak_count: streakCount,
      message: "No milestone at streak " + streakCount + ". Keep going!"
    });
  }

  var milestoneKey = gameId + "_" + userId + "_streak_" + streakCount;

  var existing = nk.storageRead([{
    collection: "streak_milestones",
    key: milestoneKey,
    userId: userId
  }]);

  if (existing && existing.length > 0) {
    return JSON.stringify({
      milestone_reached: true,
      already_claimed: true,
      streak_count: streakCount,
      reward: existing[0].value.reward
    });
  }

  var walletChangeset = {};
  if (milestoneReward.coins) { walletChangeset.coins = milestoneReward.coins; }
  if (milestoneReward.gems)  { walletChangeset.gems = milestoneReward.gems; }

  nk.walletUpdate(userId, walletChangeset, {
    source: "streak_milestone",
    streak_count: streakCount,
    game_id: gameId
  }, true);

  var milestoneData = {
    game_id: gameId,
    device_id: deviceId,
    streak_count: streakCount,
    reward: {
      coins: milestoneReward.coins || 0,
      gems: milestoneReward.gems || 0,
      badge: milestoneReward.badge || null
    },
    claimed_at: nowSeconds()
  };

  nk.storageWrite([{
    collection: "streak_milestones",
    key: milestoneKey,
    userId: userId,
    value: milestoneData,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Streak milestone %d claimed by %s: %d coins, %d gems, badge=%s",
    streakCount, userId, milestoneReward.coins, milestoneReward.gems, milestoneReward.badge);

  return JSON.stringify({
    milestone_reached: true,
    already_claimed: false,
    streak_count: streakCount,
    reward: milestoneData.reward,
    celebration: "Congratulations on your " + streakCount + "-day streak!"
  });
};

// ─── 7. Comeback Surprise ───────────────────────────────────────────────────

var rpcComebackSurprise = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var deviceId = input.device_id;
  var gameId = input.game_id;
  var daysAway = input.days_away || 1;
  var userId = ctx.userId;

  var coins = 0;
  var gems = 0;
  var message = "";
  var tier = "";

  if (daysAway >= 90) {
    tier = "legendary_comeback";
    coins = 25000;
    gems = 500;
    message = "A LEGEND RETURNS! We've missed you incredibly. Here's a legendary welcome-back package!";
  } else if (daysAway >= 30) {
    tier = "epic_comeback";
    coins = 10000;
    gems = 200;
    message = "Welcome back, champion! It's been a while. Here's an epic care package just for you!";
  } else if (daysAway >= 14) {
    tier = "rare_comeback";
    coins = 5000;
    gems = 75;
    message = "Great to see you again! We saved some special rewards for your return!";
  } else if (daysAway >= 7) {
    tier = "uncommon_comeback";
    coins = 2000;
    gems = 30;
    message = "Hey, welcome back! Here's a little something to get you going again!";
  } else if (daysAway >= 3) {
    tier = "common_comeback";
    coins = 500;
    gems = 10;
    message = "Good to see you! Here are some comeback goodies!";
  } else {
    tier = "quick_return";
    coins = 100;
    gems = 0;
    message = "Welcome back! Here's a small token of appreciation.";
  }

  var walletChangeset = { coins: coins };
  if (gems > 0) { walletChangeset.gems = gems; }

  nk.walletUpdate(userId, walletChangeset, {
    source: "comeback_surprise",
    days_away: daysAway,
    tier: tier,
    game_id: gameId
  }, true);

  var comebackData = {
    game_id: gameId,
    device_id: deviceId,
    days_away: daysAway,
    tier: tier,
    coins: coins,
    gems: gems,
    message: message,
    claimed_at: nowSeconds()
  };

  nk.storageWrite([{
    collection: "comeback_surprises",
    key: gameId + "_" + userId + "_" + todayKey(),
    userId: userId,
    value: comebackData,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Comeback surprise (%s) granted to %s: %d coins, %d gems", tier, userId, coins, gems);

  return JSON.stringify({
    success: true,
    tier: tier,
    reward: { coins: coins, gems: gems },
    message: message,
    days_away: daysAway
  });
};

// ─── 8. Lucky Draw Enter ────────────────────────────────────────────────────

var rpcLuckyDrawEnter = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var gameId = input.game_id;
  var userId = ctx.userId;
  var today = todayKey();
  var entryKey = gameId + "_" + today + "_" + userId;

  var existing = nk.storageRead([{
    collection: "lucky_draw",
    key: entryKey,
    userId: userId
  }]);

  if (existing && existing.length > 0) {
    return JSON.stringify({
      entered: false,
      already_entered: true,
      draw_date: today,
      message: "You've already entered today's lucky draw. Come back tomorrow!"
    });
  }

  var entryData = {
    game_id: gameId,
    user_id: userId,
    draw_date: today,
    entry_time: nowSeconds(),
    status: "pending"
  };

  nk.storageWrite([{
    collection: "lucky_draw",
    key: entryKey,
    userId: userId,
    value: entryData,
    permissionRead: 1,
    permissionWrite: 0
  }]);

  logger.info("Lucky draw entry for %s on %s (game: %s)", userId, today, gameId);

  return JSON.stringify({
    entered: true,
    already_entered: false,
    draw_date: today,
    message: "You're in! Good luck in today's draw!"
  });
};

// ─── 9. Happy Hour Status ───────────────────────────────────────────────────

var rpcHappyHourStatus = function (ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var gameId = input.game_id;
  var now = nowSeconds();

  var active = false;
  var multiplier = 1;
  var timeRemaining = 0;
  var eventName = "";

  // Scan flash_events for happy_hour type
  var systemId = "00000000-0000-0000-0000-000000000000";
  try {
    var listed = nk.storageList(systemId, "flash_events", 100, "");
    if (listed && listed.objects) {
      for (var i = 0; i < listed.objects.length; i++) {
        var val = listed.objects[i].value;
        if (val.game_id === gameId && val.event_type === "happy_hour" &&
            val.start_time <= now && val.end_time > now) {
          active = true;
          multiplier = val.multiplier || 2;
          timeRemaining = val.end_time - now;
          eventName = val.event_name || "Happy Hour";
          break;
        }
      }
    }
  } catch (e) {
    logger.warn("Could not list flash events for happy hour: %s", e.message);
  }

  return JSON.stringify({
    active: active,
    multiplier: multiplier,
    time_remaining_seconds: timeRemaining,
    event_name: eventName,
    game_id: gameId
  });
};


// --- Module: manifest\manifest.js ---
// manifest.js - Asset Manifest Version Check for QuizVerse v3.0
// RPC: manifest_get_version

/**
 * Asset Manifest System — Production-Ready
 *
 * Provides CDN asset manifest version to clients at startup.
 * Lightweight single-read RPC — no writes on normal requests.
 *
 * Storage: collection="game_config", key="manifest_{gameId}"
 */

// ─── CONSTANTS ──────────────────────────────────────────────────────────────

var MANIFEST_STORAGE_COLLECTION = 'game_config';

// ─── HELPERS ────────────────────────────────────────────────────────────────

function manifestErrorResponse(msg) {
    return JSON.stringify({ success: false, error: msg });
}

function manifestValidatePayload(payload) {
    if (!payload || payload === '') return {};
    try {
        return JSON.parse(payload);
    } catch (err) {
        return null;
    }
}

// ─── RPC: manifest_get_version ──────────────────────────────────────────────

function rpcManifestGetVersion(ctx, logger, nk, payload) {
    // No auth required for manifest check (can be called pre-login)
    var data = manifestValidatePayload(payload);
    if (data === null) return manifestErrorResponse('Invalid JSON payload');

    var gameId = data.gameId || 'quizverse';
    var manifestKey = 'manifest_' + gameId;

    try {
        // System-owned storage (userId = null for system reads, but Nakama requires
        // a userId for storageRead, so we use a well-known system user or empty string)
        var records = nk.storageRead([{
            collection: MANIFEST_STORAGE_COLLECTION,
            key: manifestKey,
            userId: '00000000-0000-0000-0000-000000000000'
        }]);

        if (records && records.length > 0 && records[0].value) {
            var manifest = records[0].value;

            return JSON.stringify({
                success: true,
                gameId: gameId,
                version: manifest.version || '1.0.0',
                cdnBaseUrl: manifest.cdnBaseUrl || '',
                manifestUrl: manifest.manifestUrl || '',
                minAppVersion: manifest.minAppVersion || '1.0.0',
                forceUpdate: manifest.forceUpdate || false,
                maintenanceMode: manifest.maintenanceMode || false,
                maintenanceMessage: manifest.maintenanceMessage || '',
                lastUpdatedAt: manifest.lastUpdatedAt || null,
                features: manifest.features || {},
                timestamp: new Date().toISOString()
            });
        }

        // No manifest found — return defaults (don't block the client)
        logger.warn('[Manifest] No manifest found for ' + gameId + ', returning defaults');

        return JSON.stringify({
            success: true,
            gameId: gameId,
            version: '1.0.0',
            cdnBaseUrl: '',
            manifestUrl: '',
            minAppVersion: '1.0.0',
            forceUpdate: false,
            maintenanceMode: false,
            maintenanceMessage: '',
            lastUpdatedAt: null,
            features: {},
            isDefault: true,
            timestamp: new Date().toISOString()
        });

    } catch (err) {
        logger.error('[Manifest] Storage read failed: ' + err.message);
        // Never block client on manifest failure
        return JSON.stringify({
            success: true,
            gameId: gameId,
            version: '1.0.0',
            cdnBaseUrl: '',
            manifestUrl: '',
            minAppVersion: '1.0.0',
            forceUpdate: false,
            maintenanceMode: false,
            maintenanceMessage: '',
            lastUpdatedAt: null,
            features: {},
            isDefault: true,
            fallback: true,
            timestamp: new Date().toISOString()
        });
    }
}


// --- Module: matchmaking\matchmaking.js ---
/**
 * Matchmaking System for Multi-Game Platform
 * Supports skill-based matching, party queues, and game modes
 * 
 * Collections:
 * - matchmaking_tickets: Stores active matchmaking tickets
 * - matchmaking_history: Stores match history for analytics
 */

var MATCHMAKING_TICKETS_COLLECTION = "matchmaking_tickets";
var MATCHMAKING_HISTORY_COLLECTION = "matchmaking_history";

/**
 * RPC: matchmaking_find_match
 * Create matchmaking ticket and find match
 */
var rpcMatchmakingFindMatch = function(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        
        if (!data.game_id || !data.mode) {
            throw Error("game_id and mode are required");
        }
        
        var userId = ctx.userId;
        var gameId = data.game_id;
        var mode = data.mode;
        var skillLevel = data.skill_level || 1000;
        var partyMembers = data.party_members || [];
        var properties = data.properties || {};
        
        logger.info("[Matchmaking] Finding match for user: " + userId + ", mode: " + mode);
        
        // Calculate skill range (widen over time in production)
        var minSkill = skillLevel - 100;
        var maxSkill = skillLevel + 100;
        
        // Party size
        var partySize = partyMembers.length + 1;
        
        // Create matchmaking query
        var query = "+properties.game_id:" + gameId + " +properties.mode:" + mode;
        
        // Add matchmaking ticket
        var ticket = nk.matchmakerAdd(
            query,
            minSkill,
            maxSkill,
            query,
            {
                skill: skillLevel,
                party_size: partySize
            },
            Object.assign({
                game_id: gameId,
                mode: mode,
                user_id: userId
            }, properties)
        );
        
        // Store ticket info
        var ticketKey = "ticket_" + userId + "_" + gameId;
        var ticketData = {
            ticket_id: ticket,
            user_id: userId,
            game_id: gameId,
            mode: mode,
            skill_level: skillLevel,
            party_members: partyMembers,
            created_at: new Date().toISOString(),
            status: "searching"
        };
        
        nk.storageWrite([{
            collection: MATCHMAKING_TICKETS_COLLECTION,
            key: ticketKey,
            userId: userId,
            value: ticketData,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        
        logger.info("[Matchmaking] Ticket created: " + ticket);
        
        return JSON.stringify({
            success: true,
            ticket_id: ticket,
            estimated_wait_seconds: 30,
            mode: mode,
            skill_level: skillLevel
        });
        
    } catch (err) {
        logger.error("[Matchmaking] Find match error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
};

/**
 * RPC: matchmaking_cancel
 * Cancel matchmaking ticket
 */
var rpcMatchmakingCancel = function(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        
        if (!data.ticket_id) {
            throw Error("ticket_id is required");
        }
        
        var ticketId = data.ticket_id;
        
        // Remove from matchmaker
        nk.matchmakerRemove(ticketId);
        
        logger.info("[Matchmaking] Ticket cancelled: " + ticketId);
        
        return JSON.stringify({
            success: true,
            ticket_id: ticketId
        });
        
    } catch (err) {
        logger.error("[Matchmaking] Cancel error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
};

/**
 * RPC: matchmaking_get_status
 * Check matchmaking status
 */
var rpcMatchmakingGetStatus = function(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        
        if (!data.game_id) {
            throw Error("game_id is required");
        }
        
        var userId = ctx.userId;
        var gameId = data.game_id;
        
        // Get ticket info
        var ticketKey = "ticket_" + userId + "_" + gameId;
        
        var records = nk.storageRead([{
            collection: MATCHMAKING_TICKETS_COLLECTION,
            key: ticketKey,
            userId: userId
        }]);
        
        if (!records || records.length === 0 || !records[0].value) {
            return JSON.stringify({
                success: true,
                status: "idle",
                message: "No active matchmaking"
            });
        }
        
        var ticketData = records[0].value;
        
        return JSON.stringify({
            success: true,
            status: ticketData.status,
            ticket_id: ticketData.ticket_id,
            mode: ticketData.mode,
            created_at: ticketData.created_at
        });
        
    } catch (err) {
        logger.error("[Matchmaking] Get status error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
};

/**
 * RPC: matchmaking_create_party
 * Create a party for group matchmaking
 */
var rpcMatchmakingCreateParty = function(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        
        if (!data.game_id) {
            throw Error("game_id is required");
        }
        
        var userId = ctx.userId;
        var gameId = data.game_id;
        var maxMembers = data.max_members || 4;
        
        // Create party (simplified - use Nakama parties in production)
        var partyId = "party_" + userId + "_" + Date.now();
        
        var party = {
            party_id: partyId,
            leader_id: userId,
            game_id: gameId,
            members: [userId],
            max_members: maxMembers,
            created_at: new Date().toISOString(),
            status: "open"
        };
        
        nk.storageWrite([{
            collection: "parties",
            key: partyId,
            userId: userId,
            value: party,
            permissionRead: 2,
            permissionWrite: 0
        }]);
        
        logger.info("[Matchmaking] Party created: " + partyId);
        
        return JSON.stringify({
            success: true,
            party: party
        });
        
    } catch (err) {
        logger.error("[Matchmaking] Create party error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
};

/**
 * RPC: matchmaking_join_party
 * Join an existing party
 */
var rpcMatchmakingJoinParty = function(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        
        if (!data.party_id) {
            throw Error("party_id is required");
        }
        
        var userId = ctx.userId;
        var partyId = data.party_id;
        
        // Get party
        var records = nk.storageRead([{
            collection: "parties",
            key: partyId,
            userId: null
        }]);
        
        if (!records || records.length === 0 || !records[0].value) {
            throw Error("Party not found");
        }
        
        var party = records[0].value;
        
        // Check if party is full
        if (party.members.length >= party.max_members) {
            throw Error("Party is full");
        }
        
        // Check if already in party
        if (party.members.indexOf(userId) !== -1) {
            throw Error("Already in this party");
        }
        
        // Add member
        party.members.push(userId);
        
        nk.storageWrite([{
            collection: "parties",
            key: partyId,
            userId: party.leader_id,
            value: party,
            permissionRead: 2,
            permissionWrite: 0
        }]);
        
        logger.info("[Matchmaking] User " + userId + " joined party: " + partyId);
        
        return JSON.stringify({
            success: true,
            party: party
        });
        
    } catch (err) {
        logger.error("[Matchmaking] Join party error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
};


// --- Module: multigame_rpcs.js ---
// multigame_rpcs.js - Multi-Game RPCs for QuizVerse, LastToLive, and Custom Games
// Pure JavaScript - No TypeScript
// Compatible with Nakama V8 JavaScript runtime (No ES Modules)
//
// IMPORTANT TERMINOLOGY:
// - gameID: Legacy identifier for built-in games ("quizverse", "lasttolive")
// - gameUUID: Unique identifier (UUID) from external game registry API
// - gameTitle: Human-readable game name from external API
//
// This module supports both:
// 1. Legacy built-in games using gameID (backward compatibility)
// 2. New games using gameUUID from external registry

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Parse and validate payload with gameID or gameUUID
 * Supports both legacy gameID ("quizverse", "lasttolive") and new gameUUID (UUID)
 */
function parseAndValidateGamePayload(payload, requiredFields) {
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (e) {
        throw Error("Invalid JSON payload");
    }

    // Support both gameID (legacy) and gameUUID (new)
    var gameIdentifier = data.gameID || data.gameUUID;
    
    if (!gameIdentifier) {
        throw Error("Missing game identifier: provide either 'gameID' (for built-in games) or 'gameUUID' (for custom games)");
    }
    
    // Normalize to gameID field for backward compatibility
    if (!data.gameID && data.gameUUID) {
        data.gameID = data.gameUUID;
    }
    
    // Legacy validation for built-in games
    var isLegacyGame = ["quizverse", "lasttolive"].includes(data.gameID);
    var isUUID = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(data.gameID);
    
    if (!isLegacyGame && !isUUID) {
        throw Error("Invalid game identifier. Must be 'quizverse', 'lasttolive', or a valid UUID");
    }

    // Validate required fields
    for (var i = 0; i < requiredFields.length; i++) {
        var field = requiredFields[i];
        if (!data.hasOwnProperty(field) || data[field] === null || data[field] === undefined) {
            throw Error("Missing required field: " + field);
        }
    }

    return data;
}

/**
 * Get user ID from data or context
 */
function getUserId(data, ctx) {
    return data.userID || ctx.userId;
}

/**
 * Create namespaced collection name
 */
function getCollection(gameID, type) {
    return gameID + "_" + type;
}

/**
 * Get leaderboard ID for game
 */
function getLeaderboardId(gameID, type) {
    if (type === "weekly" || !type) {
        return gameID + "_weekly";
    }
    return gameID + "_" + type;
}

// ============================================================================
// AUTHENTICATION & PROFILE
// ============================================================================

/**
 * RPC: quizverse_update_user_profile
 * Updates user profile for QuizVerse
 */
function quizverseUpdateUserProfile(context, logger, nk, payload) {
    try {
        var data = parseAndValidateGamePayload(payload, ["gameID"]);
        var userId = getUserId(data, context);
        
        var collection = getCollection(data.gameID, "profiles");
        var key = "profile_" + userId;
        
        // Read existing profile or create new
        var profile = {};
        try {
            var records = nk.storageRead([{
                collection: collection,
                key: key,
                userId: userId
            }]);
            if (records && records.length > 0 && records[0].value) {
                profile = records[0].value;
            }
        } catch (err) {
            logger.debug("No existing profile found, creating new");
        }
        
        // Update profile fields
        if (data.displayName) profile.displayName = data.displayName;
        if (data.avatar) profile.avatar = data.avatar;
        if (data.level !== undefined) profile.level = data.level;
        if (data.xp !== undefined) profile.xp = data.xp;
        if (data.metadata) profile.metadata = data.metadata;
        
        profile.updatedAt = new Date().toISOString();
        if (!profile.createdAt) {
            profile.createdAt = profile.updatedAt;
        }
        
        // Write profile
        nk.storageWrite([{
            collection: collection,
            key: key,
            userId: userId,
            value: profile,
            permissionRead: 2,
            permissionWrite: 1
        }]);
        
        logger.info("[" + data.gameID + "] Profile updated for user: " + userId);
        
        return JSON.stringify({
            success: true,
            data: profile
        });
        
    } catch (err) {
        logger.error("quizverse_update_user_profile error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: lasttolive_update_user_profile
 * Updates user profile for LastToLive
 */
function lasttoliveUpdateUserProfile(context, logger, nk, payload) {
    // Reuse the same logic as QuizVerse
    return quizverseUpdateUserProfile(context, logger, nk, payload);
}

// ============================================================================
// WALLET OPERATIONS
// ============================================================================

/**
 * RPC: quizverse_grant_currency
 * Grant currency to user wallet
 */
function quizverseGrantCurrency(context, logger, nk, payload) {
    try {
        var data = parseAndValidateGamePayload(payload, ["gameID", "amount"]);
        var userId = getUserId(data, context);
        var amount = parseInt(data.amount);
        
        if (isNaN(amount) || amount <= 0) {
            throw Error("Amount must be a positive number");
        }
        
        var collection = getCollection(data.gameID, "wallets");
        var key = "wallet_" + userId;
        
        // Read existing wallet
        var wallet = { balance: 0, currency: "coins" };
        try {
            var records = nk.storageRead([{
                collection: collection,
                key: key,
                userId: userId
            }]);
            if (records && records.length > 0 && records[0].value) {
                wallet = records[0].value;
            }
        } catch (err) {
            logger.debug("No existing wallet found, creating new");
        }
        
        // Grant currency
        wallet.balance = (wallet.balance || 0) + amount;
        wallet.updatedAt = new Date().toISOString();
        
        // Write wallet
        nk.storageWrite([{
            collection: collection,
            key: key,
            userId: userId,
            value: wallet,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        
        logger.info("[" + data.gameID + "] Granted " + amount + " currency to user: " + userId);
        
        return JSON.stringify({
            success: true,
            data: {
                balance: wallet.balance,
                amount: amount
            }
        });
        
    } catch (err) {
        logger.error("quizverse_grant_currency error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: lasttolive_grant_currency
 */
function lasttoliveGrantCurrency(context, logger, nk, payload) {
    return quizverseGrantCurrency(context, logger, nk, payload);
}

/**
 * RPC: quizverse_spend_currency
 * Spend currency from user wallet
 */
function quizverseSpendCurrency(context, logger, nk, payload) {
    try {
        var data = parseAndValidateGamePayload(payload, ["gameID", "amount"]);
        var userId = getUserId(data, context);
        var amount = parseInt(data.amount);
        
        if (isNaN(amount) || amount <= 0) {
            throw Error("Amount must be a positive number");
        }
        
        var collection = getCollection(data.gameID, "wallets");
        var key = "wallet_" + userId;
        
        // Read existing wallet
        var wallet = null;
        try {
            var records = nk.storageRead([{
                collection: collection,
                key: key,
                userId: userId
            }]);
            if (records && records.length > 0 && records[0].value) {
                wallet = records[0].value;
            }
        } catch (err) {
            throw Error("Wallet not found");
        }
        
        if (!wallet || wallet.balance < amount) {
            throw Error("Insufficient balance");
        }
        
        // Spend currency
        wallet.balance -= amount;
        wallet.updatedAt = new Date().toISOString();
        
        // Write wallet
        nk.storageWrite([{
            collection: collection,
            key: key,
            userId: userId,
            value: wallet,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        
        logger.info("[" + data.gameID + "] User " + userId + " spent " + amount + " currency");
        
        return JSON.stringify({
            success: true,
            data: {
                balance: wallet.balance,
                amount: amount
            }
        });
        
    } catch (err) {
        logger.error("quizverse_spend_currency error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: lasttolive_spend_currency
 */
function lasttoliveSpendCurrency(context, logger, nk, payload) {
    return quizverseSpendCurrency(context, logger, nk, payload);
}

/**
 * RPC: quizverse_validate_purchase
 * Validate and process purchase
 */
function quizverseValidatePurchase(context, logger, nk, payload) {
    try {
        var data = parseAndValidateGamePayload(payload, ["gameID", "itemId", "price"]);
        var userId = getUserId(data, context);
        var price = parseInt(data.price);
        
        if (isNaN(price) || price < 0) {
            throw Error("Invalid price");
        }
        
        var collection = getCollection(data.gameID, "wallets");
        var key = "wallet_" + userId;
        
        // Read wallet
        var wallet = null;
        try {
            var records = nk.storageRead([{
                collection: collection,
                key: key,
                userId: userId
            }]);
            if (records && records.length > 0 && records[0].value) {
                wallet = records[0].value;
            }
        } catch (err) {
            throw Error("Wallet not found");
        }
        
        if (!wallet || wallet.balance < price) {
            return JSON.stringify({
                success: false,
                error: "Insufficient balance",
                data: { canPurchase: false }
            });
        }
        
        return JSON.stringify({
            success: true,
            data: {
                canPurchase: true,
                itemId: data.itemId,
                price: price,
                balance: wallet.balance
            }
        });
        
    } catch (err) {
        logger.error("quizverse_validate_purchase error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: lasttolive_validate_purchase
 */
function lasttoliveValidatePurchase(context, logger, nk, payload) {
    return quizverseValidatePurchase(context, logger, nk, payload);
}

