// --- Module: notifications\notification_gate.js ---
// notification_gate.js - Notification Budget Gate for QuizVerse v3.0
// RPC: notification_gate_get_state

/**
 * Notification Gate — Production-Ready
 *
 * Controls client-side notification budget to prevent spam.
 * Max 3 notifications/day, 3-hour cooldown between each.
 * Priority queue ensures most important notifications fire first.
 *
 * Storage: collection="notification_state", key="{userId}_{gameId}"
 */

// ─── CONSTANTS ──────────────────────────────────────────────────────────────

var DAILY_NOTIFICATION_BUDGET = 3;
var COOLDOWN_HOURS = 3;
var NOTIF_STORAGE_COLLECTION = 'notification_state';

// ─── HELPERS ────────────────────────────────────────────────────────────────

function notifStorageKey(userId, gameId) {
    return userId + '_' + gameId;
}

function readNotifState(nk, logger, userId, gameId) {
    try {
        var records = nk.storageRead([{
            collection: NOTIF_STORAGE_COLLECTION,
            key: notifStorageKey(userId, gameId),
            userId: userId
        }]);
        if (records && records.length > 0 && records[0].value) {
            return records[0].value;
        }
    } catch (err) {
        logger.warn('[NotifGate] Storage read failed: ' + err.message);
    }
    return null;
}

function writeNotifState(nk, logger, userId, gameId, data) {
    try {
        nk.storageWrite([{
            collection: NOTIF_STORAGE_COLLECTION,
            key: notifStorageKey(userId, gameId),
            userId: userId,
            value: data,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return true;
    } catch (err) {
        logger.error('[NotifGate] Storage write failed: ' + err.message);
        return false;
    }
}

function getTodayKey() {
    var now = new Date();
    return now.getUTCFullYear() + '-' +
           (now.getUTCMonth() + 1 < 10 ? '0' : '') + (now.getUTCMonth() + 1) + '-' +
           (now.getUTCDate() < 10 ? '0' : '') + now.getUTCDate();
}

function initNotifState() {
    var now = new Date().toISOString();
    return {
        dailyBudget: DAILY_NOTIFICATION_BUDGET,
        usedToday: 0,
        todayKey: getTodayKey(),
        lastNotificationAt: null,
        cooldownEndsAt: null,
        pendingQueue: [],
        history: [],
        totalSent: 0,
        createdAt: now,
        updatedAt: now
    };
}

function notifErrorResponse(msg) {
    return JSON.stringify({ success: false, error: msg });
}

function notifValidatePayload(payload) {
    if (!payload || payload === '') return {};
    try {
        return JSON.parse(payload);
    } catch (err) {
        return null;
    }
}

// ─── RPC: notification_gate_get_state ───────────────────────────────────────

function rpcNotifGateGetState(ctx, logger, nk, payload) {
    if (!ctx.userId) return notifErrorResponse('User not authenticated');

    var data = notifValidatePayload(payload);
    if (data === null) return notifErrorResponse('Invalid JSON payload');

    var gameId = data.gameId || 'quizverse';
    var state = readNotifState(nk, logger, ctx.userId, gameId);
    var isNew = false;

    if (!state) {
        state = initNotifState();
        writeNotifState(nk, logger, ctx.userId, gameId, state);
        isNew = true;
    }

    // Reset daily counter if new day
    var todayKey = getTodayKey();
    if (state.todayKey !== todayKey) {
        state.usedToday = 0;
        state.todayKey = todayKey;
        state.pendingQueue = [];  // Clear stale queue
        state.updatedAt = new Date().toISOString();
        writeNotifState(nk, logger, ctx.userId, gameId, state);
    }

    var remaining = Math.max(0, DAILY_NOTIFICATION_BUDGET - state.usedToday);
    var now = new Date();
    var inCooldown = false;
    var cooldownEndsAt = null;

    if (state.lastNotificationAt) {
        var lastNotif = new Date(state.lastNotificationAt);
        var cooldownEnd = new Date(lastNotif.getTime() + COOLDOWN_HOURS * 3600000);
        if (now.getTime() < cooldownEnd.getTime()) {
            inCooldown = true;
            cooldownEndsAt = cooldownEnd.toISOString();
        }
    }

    // Sort pending queue by priority (higher priority = more important)
    var sortedQueue = (state.pendingQueue || []).slice();
    sortedQueue.sort(function(a, b) { return (b.priority || 0) - (a.priority || 0); });

    return JSON.stringify({
        success: true,
        isNew: isNew,
        userId: ctx.userId,
        gameId: gameId,
        dailyBudget: DAILY_NOTIFICATION_BUDGET,
        used: state.usedToday,
        remaining: remaining,
        inCooldown: inCooldown,
        cooldownEndsAt: cooldownEndsAt,
        cooldownHours: COOLDOWN_HOURS,
        lastNotificationAt: state.lastNotificationAt,
        pendingQueue: sortedQueue.slice(0, 10),  // Return max 10
        totalSent: state.totalSent || 0,
        timestamp: now.toISOString()
    });
}


// --- Module: notifications\notification_inbox.js ---
// notification_inbox.js - Notification Inbox System for QuizVerse v3.0
// RPCs: list_notification_inbox, mark_notifications_read
// Nakama is the source of truth for all notification state.

/**
 * Notification Inbox — Production-Ready
 *
 * Bridges Nakama built-in notifications (from nk.notificationSend across all modules)
 * with custom scheduled/inbox entries stored in "notification_inbox" collection.
 *
 * Storage: collection="notification_inbox", key="{notificationId}"
 *
 * Nakama built-in notifications come from:
 *   - social_v2.js (friend invites, friend challenges)
 *   - quizverse_depth.js (duel results)
 *   - player_gifts.js (gifts sent/claimed)
 *   - friends.js (friend challenges)
 *   - chat.js (chat notifications)
 *   - copilot/social_features.js (friend requests/accepts)
 */

// ─── CONSTANTS ──────────────────────────────────────────────────────────────

var INBOX_COLLECTION = 'notification_inbox';
var MAX_INBOX_LIMIT = 100;

// Map Nakama built-in notification codes to event types (align with
// data/modules/friends/notification_codes.js — friend invite lifecycle 1-6).
var NOTIFICATION_CODE_MAP = {
    1: 'friend_request',
    2: 'friend_request_accepted',
    3: 'friend_request_declined',
    4: 'friend_request_cancelled',
    5: 'friend_removed',
    6: 'friend_blocked',
    100: 'friend_challenge',
    101: 'friend_challenge_accepted',
    102: 'friend_challenge_declined',
    103: 'friend_challenge_cancelled',
    104: 'friend_challenge_expired',
    105: 'friend_spectate_request',
    0: 'system'
};

// ─── HELPERS ────────────────────────────────────────────────────────────────

function inboxErrorResponse(msg) {
    return JSON.stringify({ success: false, error: msg });
}

function inboxParsePayload(payload) {
    if (!payload || payload === '') return {};
    try {
        return JSON.parse(payload);
    } catch (err) {
        return null;
    }
}

/**
 * Convert a Nakama built-in notification to the unified ServerNotificationEntry format
 * that the Unity client expects.
 *
 * Nakama built-in notification shape:
 *   { id, subject, content (object), code (int), senderId, createTime (RFC3339 string) }
 */
/**
 * Collapse duplicate rows (nakama_builtin + notification_inbox mirror) that share
 * the same friend lifecycle key so Unity badge counts stay accurate.
 */
function dedupeInboxNotifications(list) {
    var seen = {};
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var n = list[i];
        if (!n) continue;
        var data = n.data || {};
        var inviteId = data.inviteId || data.invite_id || '';
        var fromId = data.fromUserId || data.from_user_id || '';
        var key = (n.event_type || 'system') + '|' + inviteId + '|' + fromId;
        if (inviteId || fromId) {
            if (seen[key]) continue;
            seen[key] = true;
        }
        out.push(n);
    }
    return out;
}

/**
 * True when `code` is a friend-lifecycle Nakama code (1-6 / 100-105).
 * Code 0 / 7001 / 9001 must NOT force event_type via NOTIFICATION_CODE_MAP.
 */
function isFriendNotificationCode(code) {
    return (code >= 1 && code <= 6) || (code >= 100 && code <= 105);
}

/**
 * Subject looks like a machine id (snake_case event type), not a display name.
 */
function isMachineIdSubject(subject) {
    if (!subject || typeof subject !== 'string') return false;
    var s = subject.trim();
    if (!s) return false;
    // Underscore snake ids: direct_message, daily_quiz, streak_warning, …
    if (s.indexOf('_') >= 0) return true;
    // Known single-token machine ids (no underscore)
    var known = {
        motivation: true,
        challenge: true,
        promotion: true,
        system: true,
        general: true
    };
    return !!known[s.toLowerCase()];
}

/**
 * Flatten content into a string map for Unity deep-link extras.
 * Merges nested content.data object keys; never iterates a string as an object.
 */
function flattenNotificationContentData(content) {
    var data = {};
    if (!content || typeof content !== 'object') return data;

    for (var key in content) {
        if (!content.hasOwnProperty(key)) continue;
        if (key === 'data') continue; // merged below
        var val = content[key];
        if (val === null || val === undefined) continue;
        if (typeof val === 'object') continue; // skip nested objects (avoid "[object Object]")
        data[key] = String(val);
    }

    var nested = content.data;
    if (nested && typeof nested === 'object' && !Array.isArray(nested)) {
        for (var nk in nested) {
            if (!nested.hasOwnProperty(nk)) continue;
            var nv = nested[nk];
            if (nv === null || nv === undefined) continue;
            if (typeof nv === 'object') continue;
            data[nk] = String(nv);
        }
    }

    return data;
}

/**
 * Resolve machine-id event_type for a Nakama built-in notification.
 * Order: content.type → eventType → event_type → friend code map → machine subject → system
 */
function resolveBuiltinEventType(content, code, subject) {
    if (content) {
        if (content.type) return String(content.type);
        if (content.eventType) return String(content.eventType);
        if (content.event_type) return String(content.event_type);
    }
    if (isFriendNotificationCode(code) && NOTIFICATION_CODE_MAP[code]) {
        return NOTIFICATION_CODE_MAP[code];
    }
    if (isMachineIdSubject(subject)) {
        return String(subject).trim();
    }
    return 'system';
}

function mapBuiltinNotification(n, logger) {
    var code = n.code || 0;
    var subject = n.subject || '';
    var content = n.content || {};

    // content may arrive as a JSON string (some send paths / storage round-trips)
    if (typeof content === 'string') {
        try {
            content = JSON.parse(content);
        } catch (parseErr) {
            content = {};
        }
    }
    if (!content || typeof content !== 'object') {
        content = {};
    }

    var eventType = resolveBuiltinEventType(content, code, subject);
    var data = flattenNotificationContentData(content);

    // Unity NotificationUI resolves inviteId — alias snake_case keys
    if (data.inviteId && !data.invite_id) data.invite_id = data.inviteId;
    if (data.fromUserId && !data.from_user_id) data.from_user_id = data.fromUserId;

    // Prefer human-readable title from content; never force raw machine id when title exists
    var title = content.title || subject || 'Notification';
    var body = content.body || content.message || '';

    // Parse createTime — Nakama returns RFC3339 string (e.g. "2024-01-15T10:30:00Z")
    var sentAtMs = Date.now();
    if (n.createTime) {
        try {
            sentAtMs = new Date(n.createTime).getTime();
            if (isNaN(sentAtMs)) sentAtMs = Date.now();
        } catch (e) {
            sentAtMs = Date.now();
        }
    }

    if (logger && typeof logger.debug === 'function') {
        logger.debug('[NotifInbox] mapBuiltin id=%s code=%s subject=%s → event_type=%s',
            n.id || '', code, subject, eventType);
    }

    return {
        notification_id: n.id || ('builtin_' + Date.now() + '_' + Math.random()),
        title: title,
        body: body,
        event_type: eventType,
        data: data,
        template_id: '',
        priority: code <= 5 ? (10 - code) : 5,   // Lower codes = higher priority
        channel: 'in_app',
        is_read: false,    // Nakama built-ins are unread until deleted
        sent_at: sentAtMs,
        created_at: sentAtMs,
        source: 'nakama_builtin'
    };
}

/**
 * Convert a custom inbox storage entry to the ServerNotificationEntry format.
 */
function mapCustomInboxEntry(record) {
    var v = record.value || {};
    return {
        notification_id: v.notification_id || record.key,
        title: v.title || 'Notification',
        body: v.body || '',
        event_type: v.event_type || 'general',
        data: v.data || {},
        template_id: v.template_id || '',
        priority: v.priority || 5,
        channel: v.channel || 'both',
        is_read: v.is_read || false,
        sent_at: v.sent_at || v.created_at || Date.now(),
        created_at: v.created_at || Date.now(),
        source: 'custom'
    };
}

/**
 * Read custom inbox entries from notification_inbox collection.
 * nk.storageList returns { objects: [...], cursor: "..." }
 */
function readCustomInbox(nk, logger, userId, limit) {
    var entries = [];
    try {
        var result = nk.storageList(userId, INBOX_COLLECTION, limit, '');
        if (result && result.objects && result.objects.length > 0) {
            for (var i = 0; i < result.objects.length; i++) {
                entries.push(mapCustomInboxEntry(result.objects[i]));
            }
        }
    } catch (err) {
        logger.warn('[NotifInbox] Failed to read custom inbox: ' + err.message);
    }
    return entries;
}

/**
 * Write a notification to the custom inbox
 */
function writeInboxEntry(nk, logger, userId, entry) {
    try {
        var notifId = entry.notification_id || ('notif_' + Date.now() + '_' + Math.floor(Math.random() * 10000));
        nk.storageWrite([{
            collection: INBOX_COLLECTION,
            key: notifId,
            userId: userId,
            value: {
                notification_id: notifId,
                title: entry.title || 'Notification',
                body: entry.body || '',
                event_type: entry.event_type || 'general',
                data: entry.data || {},
                template_id: entry.template_id || '',
                priority: entry.priority || 5,
                channel: entry.channel || 'both',
                is_read: false,
                sent_at: entry.sent_at || Date.now(),
                created_at: Date.now()
            },
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return notifId;
    } catch (err) {
        logger.error('[NotifInbox] Failed to write inbox entry: ' + err.message);
        return null;
    }
}

// ─── RPC: list_notification_inbox ───────────────────────────────────────────

/**
 * Fetch the user's unified notification inbox.
 * Merges Nakama built-in notifications + custom inbox entries.
 *
 * Payload: { limit: 50, include_read: true, event_type: null }
 * Response: { success, notifications[], count, unread_count }
 */
function rpcListNotificationInbox(ctx, logger, nk, payload) {
    if (!ctx.userId) return inboxErrorResponse('User not authenticated');

    var data = inboxParsePayload(payload);
    if (data === null) return inboxErrorResponse('Invalid JSON payload');

    var userId = ctx.userId;
    var limit = Math.min(data.limit || 50, MAX_INBOX_LIMIT);
    var includeRead = data.include_read !== false; // Default true
    var eventTypeFilter = data.event_type || null;

    var allNotifications = [];

    // ── Source 1: Nakama built-in notifications ──
    // nk.notificationsList returns { notifications: [...], cacheableCursor: "..." }
    try {
        var builtinResult = nk.notificationsList(userId, limit, null);
        if (builtinResult && builtinResult.notifications) {
            for (var i = 0; i < builtinResult.notifications.length; i++) {
                var mapped = mapBuiltinNotification(builtinResult.notifications[i], logger);
                allNotifications.push(mapped);
            }
            logger.debug('[NotifInbox] Loaded ' + builtinResult.notifications.length + ' built-in notifications');
        }
    } catch (err) {
        logger.warn('[NotifInbox] Failed to read built-in notifications: ' + err.message);
    }

    // ── Source 2: Custom inbox entries ──
    var customEntries = readCustomInbox(nk, logger, userId, limit);
    for (var j = 0; j < customEntries.length; j++) {
        allNotifications.push(customEntries[j]);
    }
    logger.debug('[NotifInbox] Loaded ' + customEntries.length + ' custom inbox entries');

    // ── Dedup: builtin + mirrored inbox rows for the same friend event ──
    allNotifications = dedupeInboxNotifications(allNotifications);

    // ── Filter ──
    var filtered = [];
    var unreadCount = 0;

    for (var k = 0; k < allNotifications.length; k++) {
        var n = allNotifications[k];

        // Filter by read status
        if (!includeRead && n.is_read) continue;

        // Filter by event type
        if (eventTypeFilter && n.event_type !== eventTypeFilter) continue;

        filtered.push(n);

        if (!n.is_read) unreadCount++;
    }

    // ── Sort by sent_at descending (newest first) ──
    filtered.sort(function(a, b) {
        return (b.sent_at || 0) - (a.sent_at || 0);
    });

    // ── Trim to limit ──
    if (filtered.length > limit) {
        filtered = filtered.slice(0, limit);
    }

    logger.info('[NotifInbox] User ' + userId + ': ' + filtered.length + ' notifications (' + unreadCount + ' unread)');

    return JSON.stringify({
        success: true,
        notifications: filtered,
        count: filtered.length,
        unread_count: unreadCount
    });
}

// ─── RPC: mark_notifications_read ───────────────────────────────────────────

/**
 * Mark notifications as read.
 *
 * Payload: { notification_ids: ["id1", "id2"], mark_all: false }
 *   OR:    { mark_all: true }
 *
 * Response: { success, marked_count }
 *
 * For Nakama built-in notifications: deletes them (Nakama's canonical "mark read").
 * For custom inbox entries: sets is_read = true in storage.
 */
function rpcMarkNotificationsRead(ctx, logger, nk, payload) {
    if (!ctx.userId) return inboxErrorResponse('User not authenticated');

    var data = inboxParsePayload(payload);
    if (data === null) return inboxErrorResponse('Invalid JSON payload');

    var userId = ctx.userId;
    var markAll = data.mark_all === true;
    var notificationIds = data.notification_ids || [];
    var markedCount = 0;

    if (markAll) {
        // ── Mark ALL: Delete all built-in notifications ──
        try {
            var builtinResult = nk.notificationsList(userId, MAX_INBOX_LIMIT, null);
            if (builtinResult && builtinResult.notifications && builtinResult.notifications.length > 0) {
                var builtinIds = [];
                for (var i = 0; i < builtinResult.notifications.length; i++) {
                    builtinIds.push(builtinResult.notifications[i].id);
                }
                if (builtinIds.length > 0) {
                    nk.notificationsDelete(userId, builtinIds);
                    markedCount += builtinIds.length;
                    logger.info('[NotifInbox] Deleted ' + builtinIds.length + ' built-in notifications for mark-all-read');
                }
            }
        } catch (err) {
            logger.warn('[NotifInbox] Failed to clear built-in notifications: ' + err.message);
        }

        // ── Mark ALL: Update all custom inbox entries ──
        // nk.storageList returns { objects: [...], cursor: "..." }
        try {
            var customResult = nk.storageList(userId, INBOX_COLLECTION, MAX_INBOX_LIMIT, '');
            if (customResult && customResult.objects && customResult.objects.length > 0) {
                var writes = [];
                for (var ci = 0; ci < customResult.objects.length; ci++) {
                    var rec = customResult.objects[ci];
                    var val = rec.value || {};
                    if (!val.is_read) {
                        val.is_read = true;
                        val.read_at = Date.now();
                        writes.push({
                            collection: INBOX_COLLECTION,
                            key: rec.key,
                            userId: userId,
                            value: val,
                            permissionRead: 1,
                            permissionWrite: 0
                        });
                        markedCount++;
                    }
                }
                if (writes.length > 0) {
                    nk.storageWrite(writes);
                    logger.info('[NotifInbox] Marked ' + writes.length + ' custom inbox entries as read');
                }
            }
        } catch (err) {
            logger.warn('[NotifInbox] Failed to mark custom entries as read: ' + err.message);
        }

    } else if (notificationIds.length > 0) {
        // ── Mark specific IDs ──
        var builtinIdsToDelete = [];
        var customKeysToUpdate = [];

        // Separate built-in vs custom (try to read each from custom first)
        for (var ni = 0; ni < notificationIds.length; ni++) {
            var nid = notificationIds[ni];

            // Try to read from custom inbox
            try {
                var customCheck = nk.storageRead([{
                    collection: INBOX_COLLECTION,
                    key: nid,
                    userId: userId
                }]);
                if (customCheck && customCheck.length > 0) {
                    customKeysToUpdate.push({ key: nid, record: customCheck[0] });
                    continue;
                }
            } catch (readErr) {
                // Not in custom inbox — must be a built-in notification
            }

            // Assume it's a built-in notification ID
            builtinIdsToDelete.push(nid);
        }

        // Delete built-in notifications
        if (builtinIdsToDelete.length > 0) {
            try {
                nk.notificationsDelete(userId, builtinIdsToDelete);
                markedCount += builtinIdsToDelete.length;
                logger.info('[NotifInbox] Deleted ' + builtinIdsToDelete.length + ' built-in notifications');
            } catch (err) {
                logger.warn('[NotifInbox] Failed to delete built-in: ' + err.message);
            }
        }

        // Update custom inbox entries
        if (customKeysToUpdate.length > 0) {
            var updateWrites = [];
            for (var ui = 0; ui < customKeysToUpdate.length; ui++) {
                var item = customKeysToUpdate[ui];
                var value = item.record.value || {};
                value.is_read = true;
                value.read_at = Date.now();
                updateWrites.push({
                    collection: INBOX_COLLECTION,
                    key: item.key,
                    userId: userId,
                    value: value,
                    permissionRead: 1,
                    permissionWrite: 0
                });
                markedCount++;
            }
            if (updateWrites.length > 0) {
                try {
                    nk.storageWrite(updateWrites);
                    logger.info('[NotifInbox] Marked ' + updateWrites.length + ' custom entries as read');
                } catch (err) {
                    logger.warn('[NotifInbox] Failed to update custom entries: ' + err.message);
                }
            }
        }
    } else {
        return inboxErrorResponse('No notification_ids provided and mark_all is false');
    }

    return JSON.stringify({
        success: true,
        marked_count: markedCount
    });
}


// --- Module: offer_engine\offer_engine.js ---
// offer_engine.js — Phase 6 (2026-05) Personalized Offer Engine.
//
// Goal: deliver measurable offers without over-targeting players.
//
// ─── Design principles ───────────────────────────────────────────────────────
//
//   1. Analytics as truth  — eligibility is always derived from the GPA doc
//      (game_player_analytics) and the Phase 5 identity traits computed by
//      analytics_satori_identity.js. The offer engine never reaches into raw
//      event scans at request time.
//
//   2. Natural moments only — offers are surfaced only at five trigger types:
//      quiz_complete / streak_risk / repeated_wrong / rewarded_ad_result /
//      usual_active_hour. Unity passes the trigger when calling
//      offer_get_eligible so the engine returns only contextually relevant
//      offers.
//
//   3. Cooldowns by default — after a player dismisses an offer it cannot
//      appear again for `cooldown_hours` (default: 24 h). After purchase the
//      offer is suppressed for `purchased_cooldown_hours` (default: 168 h = 7 d).
//      The engine enforces both without any client-side state.
//
//   4. Holdout groups — each offer can define a `holdout_pct` (0–100).
//      Players are hashed deterministically into holdout/treatment using
//      FNV-32 so the assignment is stable and reproducible. A player in
//      holdout never sees the offer but their events are still counted so
//      the dashboard can produce a lift comparison.
//
//   5. Max shows per day — `max_shows_per_day` guards against showing the
//      same offer to the same player more than N times in a 24 h window.
//
// ─── Storage layout ──────────────────────────────────────────────────────────
//
//   offer_catalog / <offer_id>          (system user)
//     The offer definition: metadata, eligibility rules, cooldowns, holdout.
//
//   offer_player_state / <userId>_<offerId>   (system user)
//     Per-player per-offer state: last_viewed_utc, last_dismissed_utc,
//     last_purchased_utc, views_today, assigned, holdout.
//
//   offer_engine_meta / last_status     (system user)
//     Last batch-assign run summary.
//
// ─── Registered RPCs ─────────────────────────────────────────────────────────
//
// Player-facing (require live session, only access own data):
//   offer_get_eligible     { game_id?, trigger?, limit? }
//   offer_record_view      { offer_id, game_id? }
//   offer_record_click     { offer_id, game_id? }
//   offer_record_dismiss   { offer_id, game_id? }
//   offer_record_purchase  { offer_id, game_id?, product_id?, price_usd? }
//
// Admin-gated:
//   offer_upsert           { offer: { offer_id, ... } }      create or update offer
//   offer_list             { game_id?, active_only?: bool }  list offers + stats
//   offer_status           {}                                engine health summary
//
// ─── Offer catalog schema ─────────────────────────────────────────────────────
//
//   {
//     offer_id:              string   (slug, e.g. "starter_pack_50pct")
//     game_id:               string   (filters to this game; "all" = any game)
//     title:                 string   (display name for debugging)
//     product_id:            string   (IAP product ID to unlock)
//     price_usd:             number   (display price)
//     active:                bool     (false = soft-delete)
//     triggers:              string[] (quiz_complete, streak_risk, repeated_wrong,
//                                      rewarded_ad_result, usual_active_hour, any)
//     eligible_spend_tiers:  string[] (non_spender, low, mid, high — from trait)
//     eligible_churn_risks:  string[] (low, medium, high)
//     eligible_skill_bands:  string[] (beginner, intermediate, expert)
//     min_install_age_days:  number   (0 = no minimum)
//     max_install_age_days:  number   (9999 = no maximum)
//     min_quiz_plays:        number
//     cooldown_hours:        number   (default 24)
//     purchased_cooldown_hours: number (default 168)
//     max_shows_per_day:     number   (default 3)
//     holdout_pct:           number   (0–100; default 0 = no holdout)
//     priority:              number   (higher = shown first when multiple match)
//     created_at:            string   (ISO-8601)
//     updated_at:            string   (ISO-8601)
//   }

var OE_SYSTEM_USER      = "00000000-0000-0000-0000-000000000000";
var OE_ADMIN_COLLECTION = "admin_users";
var OE_CATALOG_COLLECTION   = "offer_catalog";
var OE_STATE_COLLECTION     = "offer_player_state";
var OE_META_COLLECTION      = "offer_engine_meta";
var OE_GPA_COLLECTION       = "game_player_analytics";
var OE_SATORI_ID_COLLECTION = "analytics_satori_id_state";

var OE_DEFAULT_COOLDOWN_HOURS           = 24;
var OE_DEFAULT_PURCHASED_COOLDOWN_HOURS = 168;
var OE_DEFAULT_MAX_SHOWS_PER_DAY        = 3;
var OE_MAX_OFFERS_PER_REQUEST           = 10;
var OE_CATALOG_PAGE_SIZE                = 200;

// Valid trigger names (also accepted: "any" = match any trigger).
var OE_VALID_TRIGGERS = {
    "quiz_complete": 1, "streak_risk": 1, "repeated_wrong": 1,
    "rewarded_ad_result": 1, "usual_active_hour": 1, "any": 1
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

function oeParse(payload) {
    try { return JSON.parse(payload || "{}"); } catch (e) { return {}; }
}

function oeOk(data) {
    var out = { success: true };
    if (data) for (var k in data) if (Object.prototype.hasOwnProperty.call(data, k)) out[k] = data[k];
    return JSON.stringify(out);
}

function oeErr(msg, code) {
    return JSON.stringify({ success: false, error: msg || "error", code: code || 400 });
}

function oeEnv(ctx, key) {
    if (key === "DASHBOARD_SECRET" && typeof AA_FALLBACK_DASHBOARD_SECRET === "string") {
        return AA_FALLBACK_DASHBOARD_SECRET;
    }
    try {
        if (ctx && ctx.env && ctx.env[key]) {
            var v = String(ctx.env[key]).trim();
            if (v.length > 0) return v;
        }
    } catch (e) { /* */ }
    return "";
}

function oeIsAdmin(ctx, nk) {
    if (!ctx.userId) return false;
    if (ctx.userId === OE_SYSTEM_USER) return true;
    if (!ctx.username || ctx.username.indexOf("admin:") !== 0) return false;
    try {
        var recs = nk.storageRead([{ collection: OE_ADMIN_COLLECTION, key: "profile", userId: ctx.userId }]);
        if (!recs || recs.length === 0) return false;
        var r = recs[0].value || {};
        if (!r.isAdmin) return false;
        if (r.expiresAt && r.expiresAt < Math.floor(Date.now() / 1000)) return false;
        return true;
    } catch (e) { return false; }
}

function oeRequireAdmin(ctx, nk, data) {
    var secret = oeEnv(ctx, "DASHBOARD_SECRET");
    if (secret && data && data.dashboard_secret === secret) return { ok: true, bypass: "secret" };
    if (oeIsAdmin(ctx, nk)) return { ok: true, bypass: "session" };
    return { ok: false, reason: "admin authentication required" };
}

function oeResolveGameId(g) {
    if (!g) return g;
    try { if (typeof resolveGameIdAlias === "function") return resolveGameIdAlias(g); } catch (e) { /* */ }
    return g;
}

function oeReadOne(nk, collection, key, userId) {
    try {
        var r = nk.storageRead([{ collection: collection, key: key, userId: userId || OE_SYSTEM_USER }]);
        return (r && r.length > 0) ? (r[0].value || null) : null;
    } catch (e) { return null; }
}

function oeWriteOne(nk, collection, key, userId, value) {
    try {
        nk.storageWrite([{
            collection: collection, key: key, userId: userId || OE_SYSTEM_USER,
            value: value, permissionRead: 0, permissionWrite: 0
        }]);
    } catch (e) { /* best-effort */ }
}

function oeNowSec() { return Math.floor(Date.now() / 1000); }

function oeIsoNow() { return new Date().toISOString(); }

// Deterministic FNV-32a hash for holdout assignment.
// userId + offerId → stable 0–99 bucket, consistent across all server nodes.
function oeHoldoutBucket(userId, offerId) {
    var s = userId + ":" + offerId;
    var h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = ((h * 0x01000193) >>> 0); // FNV prime, keep in 32-bit unsigned
    }
    return h % 100;
}

// Fire analytics event via the global analytics log path.
// Falls back gracefully if the analytics module symbols aren't yet available.
function oeFireEvent(ctx, nk, logger, userId, gameId, eventName, eventData) {
    try {
        if (typeof rpcAnalyticsLogEvent === "function") {
            rpcAnalyticsLogEvent(ctx, logger, nk, JSON.stringify({
                event_name: eventName,
                user_id:    userId,
                game_id:    gameId,
                schema_version: 2,
                client_event_id: "oe_" + userId + "_" + eventName + "_" + oeNowSec(),
                event_time: new Date().toISOString(),
                event_data: eventData || {}
            }));
        } else if (typeof sdEventsPublish === "function") {
            // Fallback: push directly to Satori (best-effort)
            sdEventsPublish(ctx, nk, logger, userId, [{
                name: eventName,
                id:   "oe_" + userId + "_" + eventName + "_" + oeNowSec(),
                timestamp: oeNowSec(),
                metadata: eventData || {}
            }]);
        }
    } catch (e) {
        if (logger) logger.warn("[offer_engine] fireEvent error " + eventName + ": " + e.message);
    }
}

// ─── Offer catalog helpers ────────────────────────────────────────────────────

function oeDefaultOffer() {
    return {
        offer_id: "",
        game_id: "all",
        title: "",
        product_id: "",
        price_usd: 0,
        active: true,
        triggers: ["any"],
        eligible_spend_tiers:  [],   // empty = all tiers
        eligible_churn_risks:  [],   // empty = all
        eligible_skill_bands:  [],   // empty = all
        min_install_age_days:  0,
        max_install_age_days:  9999,
        min_quiz_plays:        0,
        cooldown_hours:            OE_DEFAULT_COOLDOWN_HOURS,
        purchased_cooldown_hours:  OE_DEFAULT_PURCHASED_COOLDOWN_HOURS,
        max_shows_per_day:         OE_DEFAULT_MAX_SHOWS_PER_DAY,
        holdout_pct: 0,
        priority: 0,
        created_at: "",
        updated_at: ""
    };
}

function oeValidateOffer(offer) {
    if (!offer) return "offer object required";
    if (!offer.offer_id || typeof offer.offer_id !== "string" || offer.offer_id.trim().length === 0) {
        return "offer_id (non-empty string) required";
    }
    if (!/^[a-z0-9_\-]{1,64}$/.test(offer.offer_id)) {
        return "offer_id must match /^[a-z0-9_\\-]{1,64}$/";
    }
    if (offer.holdout_pct !== undefined) {
        var hp = parseInt(offer.holdout_pct, 10);
        if (isNaN(hp) || hp < 0 || hp > 100) return "holdout_pct must be 0–100";
    }
    return null; // valid
}

function oeReadCatalog(nk) {
    var offers = [];
    var cursor = "";
    var iter   = 0;
    try {
        do {
            var r = nk.storageList(OE_SYSTEM_USER, OE_CATALOG_COLLECTION, OE_CATALOG_PAGE_SIZE, cursor);
            if (!r || !r.objects || r.objects.length === 0) break;
            for (var i = 0; i < r.objects.length; i++) {
                var v = r.objects[i].value;
                if (v) offers.push(v);
            }
            cursor = r.cursor || "";
            iter++;
        } while (cursor && iter < 10);
    } catch (e) { /* ignore */ }
    return offers;
}

// ─── Eligibility engine ──────────────────────────────────────────────────────

/**
 * Read player's GPA doc and Satori identity state to assemble their traits.
 * Returns a lightweight trait snapshot for eligibility checks.
 */
function oeGetPlayerTraits(nk, userId, gameId) {
    gameId = oeResolveGameId(gameId || "default");
    var gpaKey = gameId + ":" + userId;
    var gpa = null;
    try {
        var recs = nk.storageRead([{ collection: OE_GPA_COLLECTION, key: gpaKey, userId: userId }]);
        if (recs && recs.length > 0) gpa = recs[0].value || null;
    } catch (e) { /* not found */ }

    if (!gpa) return null; // no profile = no offers (player too new)

    var nowSec = oeNowSec();
    var money  = gpa.money  || {};
    var eng    = gpa.eng    || {};

    // Re-compute traits inline (mirrors siComputeTraits from analytics_satori_identity.js)
    // so the offer engine works even if the Satori sync hasn't run yet.
    var iapCount  = money.iap_count || 0;
    var spendUsd  = money.spend_usd || 0;
    var spendTier;
    if (iapCount === 0)                      spendTier = "non_spender";
    else if (iapCount <= 2 || spendUsd < 10) spendTier = "low";
    else if (iapCount <= 5 || spendUsd < 50) spendTier = "mid";
    else                                     spendTier = "high";

    var lastActiveSec   = gpa.last_active_utc || 0;
    var daysSinceActive = lastActiveSec > 0 ? Math.floor((nowSec - lastActiveSec) / 86400) : null;
    var churnRisk;
    if (daysSinceActive === null)      churnRisk = "unknown";
    else if (daysSinceActive <= 3)     churnRisk = "low";
    else if (daysSinceActive <= 14)    churnRisk = "medium";
    else                               churnRisk = "high";

    var avgAcc = (typeof eng.avg_accuracy === "number") ? eng.avg_accuracy : -1;
    var totalAnswered = (typeof eng.total_answered === "number") ? eng.total_answered : 0;
    var skillBand;
    if (totalAnswered < 10 || avgAcc < 0) skillBand = "beginner";
    else if (avgAcc >= 70)                skillBand = "expert";
    else if (avgAcc >= 40)                skillBand = "intermediate";
    else                                  skillBand = "beginner";

    var firstSeen    = gpa.first_seen_utc || 0;
    var installAgeDays = firstSeen > 0 ? Math.floor((nowSec - firstSeen) / 86400) : 0;

    var ltQuizPlays  = gpa.lt_quiz_plays || 0;

    // Best play hour from sessions
    var bestPlayHour = null;
    try {
        var sessions = gpa.sessions || [];
        if (sessions.length > 0) {
            var hc = {};
            for (var si = 0; si < sessions.length; si++) {
                var ts = parseInt(sessions[si].start || sessions[si].startUtc || sessions[si].ts || 0, 10);
                if (ts > 0) {
                    var h = new Date(ts > 1e12 ? ts : ts * 1000).getUTCHours();
                    hc[h] = (hc[h] || 0) + 1;
                }
            }
            var bestH = -1, bestHN = 0;
            for (var hk in hc) {
                if (Object.prototype.hasOwnProperty.call(hc, hk) && hc[hk] > bestHN) {
                    bestHN = hc[hk]; bestH = parseInt(hk, 10);
                }
            }
            if (bestH >= 0) bestPlayHour = bestH;
        }
    } catch (e) { /* */ }

    var currentHour = new Date().getUTCHours();

    return {
        user_id:          userId,
        game_id:          gameId,
        spend_tier:       spendTier,
        churn_risk:       churnRisk,
        skill_band:       skillBand,
        install_age_days: installAgeDays,
        lt_quiz_plays:    ltQuizPlays,
        best_play_hour:   bestPlayHour,
        current_hour:     currentHour,
        is_best_play_hour: (bestPlayHour !== null && Math.abs(bestPlayHour - currentHour) <= 1)
    };
}

/**
 * Check whether a player is eligible for a specific offer.
 * Returns { eligible: bool, reason: string }.
 */
function oeCheckEligibility(offer, traits, trigger, playerState, nowSec) {
    if (!offer.active) return { eligible: false, reason: "offer_inactive" };

    // ── Trigger match ────────────────────────────────
    if (trigger && trigger !== "any") {
        var offerTriggers = offer.triggers || ["any"];
        var hasAny = false;
        for (var ti = 0; ti < offerTriggers.length; ti++) {
            if (offerTriggers[ti] === "any" || offerTriggers[ti] === trigger) { hasAny = true; break; }
        }
        if (!hasAny) return { eligible: false, reason: "trigger_mismatch" };
    }

    // ── Segment filters (empty array = no restriction) ──
    if (offer.eligible_spend_tiers && offer.eligible_spend_tiers.length > 0) {
        var foundTier = false;
        for (var si = 0; si < offer.eligible_spend_tiers.length; si++) {
            if (offer.eligible_spend_tiers[si] === traits.spend_tier) { foundTier = true; break; }
        }
        if (!foundTier) return { eligible: false, reason: "spend_tier_mismatch" };
    }

    if (offer.eligible_churn_risks && offer.eligible_churn_risks.length > 0) {
        var foundChurn = false;
        for (var ci = 0; ci < offer.eligible_churn_risks.length; ci++) {
            if (offer.eligible_churn_risks[ci] === traits.churn_risk) { foundChurn = true; break; }
        }
        if (!foundChurn) return { eligible: false, reason: "churn_risk_mismatch" };
    }

    if (offer.eligible_skill_bands && offer.eligible_skill_bands.length > 0) {
        var foundSkill = false;
        for (var ki = 0; ki < offer.eligible_skill_bands.length; ki++) {
            if (offer.eligible_skill_bands[ki] === traits.skill_band) { foundSkill = true; break; }
        }
        if (!foundSkill) return { eligible: false, reason: "skill_band_mismatch" };
    }

    // ── Install age ──────────────────────────────────
    var minAge = offer.min_install_age_days || 0;
    var maxAge = offer.max_install_age_days !== undefined ? offer.max_install_age_days : 9999;
    if (traits.install_age_days < minAge) return { eligible: false, reason: "too_new" };
    if (traits.install_age_days > maxAge) return { eligible: false, reason: "too_old" };

    // ── Min quiz plays ───────────────────────────────
    var minPlays = offer.min_quiz_plays || 0;
    if (traits.lt_quiz_plays < minPlays) return { eligible: false, reason: "not_enough_plays" };

    // ── Usual active hour ────────────────────────────
    if (trigger === "usual_active_hour" && !traits.is_best_play_hour) {
        return { eligible: false, reason: "not_active_hour" };
    }

    // ── Holdout group ────────────────────────────────
    var holdoutPct = offer.holdout_pct || 0;
    if (holdoutPct > 0) {
        var bucket = oeHoldoutBucket(traits.user_id, offer.offer_id);
        if (bucket < holdoutPct) {
            return { eligible: false, reason: "holdout_group", holdout: true };
        }
    }

    // ── Cooldowns ────────────────────────────────────
    if (playerState) {
        var cooldownHours = offer.cooldown_hours !== undefined
            ? offer.cooldown_hours : OE_DEFAULT_COOLDOWN_HOURS;
        if (playerState.last_dismissed_utc && cooldownHours > 0) {
            var cooldownSec = cooldownHours * 3600;
            if ((nowSec - playerState.last_dismissed_utc) < cooldownSec) {
                return { eligible: false, reason: "on_dismiss_cooldown" };
            }
        }

        var purchasedCooldownHours = offer.purchased_cooldown_hours !== undefined
            ? offer.purchased_cooldown_hours : OE_DEFAULT_PURCHASED_COOLDOWN_HOURS;
        if (playerState.last_purchased_utc && purchasedCooldownHours > 0) {
            var purchasedCooldownSec = purchasedCooldownHours * 3600;
            if ((nowSec - playerState.last_purchased_utc) < purchasedCooldownSec) {
                return { eligible: false, reason: "on_purchase_cooldown" };
            }
        }

        // ── Max shows per day ────────────────────────
        var maxShows = offer.max_shows_per_day !== undefined
            ? offer.max_shows_per_day : OE_DEFAULT_MAX_SHOWS_PER_DAY;
        if (maxShows > 0 && playerState.views_today >= maxShows) {
            var today = new Date().toISOString().slice(0, 10);
            if (playerState.views_today_date === today) {
                return { eligible: false, reason: "max_shows_reached" };
            }
        }
    }

    return { eligible: true, reason: "ok" };
}

// ─── RPC: offer_get_eligible ──────────────────────────────────────────────────

/**
 * Returns offers the calling player can see right now.
 *
 * Payload:
 *   game_id   : optional
 *   trigger   : optional — one of quiz_complete | streak_risk | repeated_wrong |
 *               rewarded_ad_result | usual_active_hour | any (default: any)
 *   limit     : 1–10, default 3
 *
 * For each returned offer, also emits:
 *   - offer_eligible  (always, so the funnel denominator is always counted)
 *   - offer_assigned  (if the player is in treatment, not holdout)
 */
function rpcOfferGetEligible(ctx, logger, nk, payload) {
    var data   = oeParse(payload);
    var userId = ctx.userId;
    if (!userId) return oeErr("session required", 401);

    var gameId  = oeResolveGameId(data.game_id || data.gameId || "default");
    var trigger = (data.trigger || "any").toLowerCase();
    var limit   = Math.min(OE_MAX_OFFERS_PER_REQUEST, Math.max(1, parseInt(data.limit, 10) || 3));

    // Load traits.
    var traits = oeGetPlayerTraits(nk, userId, gameId);
    if (!traits) {
        return oeOk({ offers: [], reason: "no_player_profile", trigger: trigger });
    }

    // Load catalog.
    var catalog = oeReadCatalog(nk);
    if (!catalog.length) {
        return oeOk({ offers: [], reason: "empty_catalog", trigger: trigger });
    }

    var nowSec = oeNowSec();
    var eligible = [];

    for (var ci = 0; ci < catalog.length; ci++) {
        var offer = catalog[ci];
        if (!offer || !offer.offer_id) continue;

        // Filter by game_id if the offer specifies one.
        if (offer.game_id && offer.game_id !== "all" && offer.game_id !== gameId) continue;

        // Load per-player state for this offer.
        var stateKey    = userId + "_" + offer.offer_id;
        var playerState = oeReadOne(nk, OE_STATE_COLLECTION, stateKey, OE_SYSTEM_USER);

        // Always fire offer_eligible so the funnel denominator is counted.
        oeFireEvent(ctx, nk, logger, userId, gameId, "offer_eligible", {
            offer_id:   offer.offer_id,
            product_id: offer.product_id || null,
            trigger:    trigger
        });

        var check = oeCheckEligibility(offer, traits, trigger, playerState, nowSec);

        if (!check.eligible) {
            // If the player is in holdout, fire offer_cooldown_blocked so the
            // holdout/treatment split is visible in the offer funnel dashboard.
            if (check.holdout) {
                oeFireEvent(ctx, nk, logger, userId, gameId, "offer_cooldown_blocked", {
                    offer_id: offer.offer_id,
                    reason:   "holdout_group"
                });
            }
            continue;
        }

        // Assign the offer.
        var assigned = (playerState && playerState.assigned) ? playerState.assigned : false;
        if (!assigned) {
            // First time this player was assigned this offer.
            var newState = playerState || { offer_id: offer.offer_id, user_id: userId };
            newState.assigned    = true;
            newState.assigned_at = nowSec;
            oeWriteOne(nk, OE_STATE_COLLECTION, stateKey, OE_SYSTEM_USER, newState);

            oeFireEvent(ctx, nk, logger, userId, gameId, "offer_assigned", {
                offer_id:   offer.offer_id,
                product_id: offer.product_id || null,
                trigger:    trigger
            });
        }

        eligible.push({
            offer_id:     offer.offer_id,
            title:        offer.title        || "",
            product_id:   offer.product_id   || "",
            price_usd:    offer.price_usd    || 0,
            trigger:      trigger,
            priority:     offer.priority     || 0
        });

        if (eligible.length >= limit) break;
    }

    // Sort by priority descending.
    eligible.sort(function (a, b) { return b.priority - a.priority; });

    return oeOk({
        offers:       eligible,
        offer_count:  eligible.length,
        trigger:      trigger,
        game_id:      gameId,
        traits: {
            spend_tier:       traits.spend_tier,
            churn_risk:       traits.churn_risk,
            skill_band:       traits.skill_band,
            install_age_days: traits.install_age_days,
            lt_quiz_plays:    traits.lt_quiz_plays
        }
    });
}

// ─── RPC helpers: per-offer lifecycle recording ──────────────────────────────

function oeRecordLifecycle(ctx, nk, logger, userId, gameId, offerId, eventName, extra) {
    if (!userId || !offerId) return oeErr("session + offer_id required", 400);
    var nowSec  = oeNowSec();
    var stateKey = userId + "_" + offerId;
    var state    = oeReadOne(nk, OE_STATE_COLLECTION, stateKey, OE_SYSTEM_USER) || {};
    var today    = new Date().toISOString().slice(0, 10);

    // Ensure the offer exists in catalog (best-effort — don't block the lifecycle
    // call if the catalog read fails, since client may have a valid offer
    // from a previous get_eligible call).
    var offer = oeReadOne(nk, OE_CATALOG_COLLECTION, offerId, OE_SYSTEM_USER) || {};

    switch (eventName) {
        case "offer_viewed":
            state.last_viewed_utc = nowSec;
            // Daily view counter (resets when date changes).
            if (state.views_today_date !== today) {
                state.views_today      = 0;
                state.views_today_date = today;
            }
            state.views_today = (state.views_today || 0) + 1;
            state.total_views = (state.total_views  || 0) + 1;
            break;

        case "offer_clicked":
            state.last_clicked_utc = nowSec;
            state.total_clicks     = (state.total_clicks || 0) + 1;
            break;

        case "offer_dismissed":
            state.last_dismissed_utc = nowSec;
            state.total_dismissals   = (state.total_dismissals || 0) + 1;
            break;

        case "offer_purchased":
            state.last_purchased_utc = nowSec;
            state.total_purchases    = (state.total_purchases || 0) + 1;
            state.last_product_id    = extra.product_id || offer.product_id || null;
            state.last_price_usd     = extra.price_usd  || offer.price_usd  || 0;
            break;
    }

    state.offer_id = offerId;
    state.user_id  = userId;
    oeWriteOne(nk, OE_STATE_COLLECTION, stateKey, OE_SYSTEM_USER, state);

    // Fire analytics event.
    oeFireEvent(ctx, nk, logger, userId, gameId, eventName, Object.assign({
        offer_id:   offerId,
        product_id: offer.product_id || extra.product_id || null,
        price_usd:  offer.price_usd  || extra.price_usd  || 0
    }, extra || {}));

    return null; // success
}

// ─── RPC: offer_record_view ──────────────────────────────────────────────────

function rpcOfferRecordView(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    if (!ctx.userId) return oeErr("session required", 401);
    var gameId  = oeResolveGameId(data.game_id || data.gameId || "default");
    var offerId = data.offer_id || data.offerId;
    if (!offerId) return oeErr("offer_id required", 400);
    var err = oeRecordLifecycle(ctx, nk, logger, ctx.userId, gameId, offerId, "offer_viewed", {});
    return err || oeOk({ offer_id: offerId, recorded: "viewed" });
}

// ─── RPC: offer_record_click ─────────────────────────────────────────────────

function rpcOfferRecordClick(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    if (!ctx.userId) return oeErr("session required", 401);
    var gameId  = oeResolveGameId(data.game_id || data.gameId || "default");
    var offerId = data.offer_id || data.offerId;
    if (!offerId) return oeErr("offer_id required", 400);
    var err = oeRecordLifecycle(ctx, nk, logger, ctx.userId, gameId, offerId, "offer_clicked", {});
    return err || oeOk({ offer_id: offerId, recorded: "clicked" });
}

// ─── RPC: offer_record_dismiss ───────────────────────────────────────────────

function rpcOfferRecordDismiss(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    if (!ctx.userId) return oeErr("session required", 401);
    var gameId  = oeResolveGameId(data.game_id || data.gameId || "default");
    var offerId = data.offer_id || data.offerId;
    if (!offerId) return oeErr("offer_id required", 400);
    var err = oeRecordLifecycle(ctx, nk, logger, ctx.userId, gameId, offerId, "offer_dismissed", {});
    return err || oeOk({ offer_id: offerId, recorded: "dismissed" });
}

// ─── RPC: offer_record_purchase ──────────────────────────────────────────────

function rpcOfferRecordPurchase(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    if (!ctx.userId) return oeErr("session required", 401);
    var gameId  = oeResolveGameId(data.game_id || data.gameId || "default");
    var offerId = data.offer_id || data.offerId;
    if (!offerId) return oeErr("offer_id required", 400);
    var extra = {
        product_id: data.product_id || null,
        price_usd:  parseFloat(data.price_usd || 0)
    };
    var err = oeRecordLifecycle(ctx, nk, logger, ctx.userId, gameId, offerId, "offer_purchased", extra);
    return err || oeOk({ offer_id: offerId, recorded: "purchased" });
}

// ─── RPC: offer_upsert (admin) ───────────────────────────────────────────────

/**
 * Create or update an offer in the catalog.
 *
 * Payload: { offer: { offer_id, ...fields }, dashboard_secret? }
 *
 * Merges into existing doc (fields not provided keep their old values).
 */
function rpcOfferUpsert(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    var gate = oeRequireAdmin(ctx, nk, data);
    if (!gate.ok) return oeErr(gate.reason, 401);

    var incoming = data.offer || data;
    var err = oeValidateOffer(incoming);
    if (err) return oeErr(err, 400);

    var offerId  = incoming.offer_id.trim().toLowerCase();
    var existing = oeReadOne(nk, OE_CATALOG_COLLECTION, offerId, OE_SYSTEM_USER) || oeDefaultOffer();

    // Merge incoming fields into the existing doc.
    var fields = [
        "game_id","title","product_id","price_usd","active","triggers",
        "eligible_spend_tiers","eligible_churn_risks","eligible_skill_bands",
        "min_install_age_days","max_install_age_days","min_quiz_plays",
        "cooldown_hours","purchased_cooldown_hours","max_shows_per_day",
        "holdout_pct","priority"
    ];
    for (var fi = 0; fi < fields.length; fi++) {
        var f = fields[fi];
        if (Object.prototype.hasOwnProperty.call(incoming, f)) existing[f] = incoming[f];
    }
    existing.offer_id   = offerId;
    existing.updated_at = oeIsoNow();
    if (!existing.created_at) existing.created_at = oeIsoNow();

    oeWriteOne(nk, OE_CATALOG_COLLECTION, offerId, OE_SYSTEM_USER, existing);
    logger.info("[offer_engine] upserted offer " + offerId);

    return oeOk({ offer: existing });
}

// ─── RPC: offer_list (admin) ─────────────────────────────────────────────────

/**
 * List all offers in the catalog with optional filtering.
 *
 * Payload: { game_id?, active_only?: bool }
 */
function rpcOfferList(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    var gate = oeRequireAdmin(ctx, nk, data);
    if (!gate.ok) return oeErr(gate.reason, 401);

    var gameId     = data.game_id ? oeResolveGameId(data.game_id) : null;
    var activeOnly = (data.active_only === true || data.active_only === "true");

    var catalog = oeReadCatalog(nk);
    var results = [];
    for (var i = 0; i < catalog.length; i++) {
        var o = catalog[i];
        if (activeOnly && !o.active) continue;
        if (gameId && o.game_id && o.game_id !== "all" && o.game_id !== gameId) continue;
        results.push(o);
    }
    results.sort(function (a, b) { return (b.priority || 0) - (a.priority || 0); });

    return oeOk({ offers: results, count: results.length });
}

// ─── RPC: offer_status (admin) ───────────────────────────────────────────────

/**
 * Engine health summary: catalog size, active offers, recent funnel snapshot.
 */
function rpcOfferStatus(ctx, logger, nk, payload) {
    var data = oeParse(payload);
    var gate = oeRequireAdmin(ctx, nk, data);
    if (!gate.ok) return oeErr(gate.reason, 401);

    var catalog = oeReadCatalog(nk);
    var total   = catalog.length;
    var active  = 0;
    var withHoldout = 0;
    for (var i = 0; i < catalog.length; i++) {
        if (catalog[i].active) active++;
        if ((catalog[i].holdout_pct || 0) > 0) withHoldout++;
    }

    return oeOk({
        catalog_size:     total,
        active_offers:    active,
        inactive_offers:  total - active,
        offers_with_holdout: withHoldout,
        valid_triggers:   Object.keys(OE_VALID_TRIGGERS),
        default_cooldown_hours: OE_DEFAULT_COOLDOWN_HOURS,
        default_purchased_cooldown_hours: OE_DEFAULT_PURCHASED_COOLDOWN_HOURS,
        default_max_shows_per_day: OE_DEFAULT_MAX_SHOWS_PER_DAY,
        checked_at: oeIsoNow()
    });
}

// ─── Registration ─────────────────────────────────────────────────────────────

// ─── Default offer catalog seed ──────────────────────────────────────────────
//
// Three "starter offers" written on first boot (skipped if an offer with the
// same offer_id already exists in the catalog). These are intentionally
// conservative targeting ranges so they never fire in error. Live-ops can
// adjust them via offer_upsert at any time.
//
// Offer design rationale:
//   quiz_bundle_starter  — shown after first 3 quiz plays to brand-new
//                          non-spenders. Low-friction entry-level SKU.
//   premium_week_trial   — shown on paywall_shown trigger to mid-skill players
//                          who have seen the paywall twice (price-sensitive
//                          explorers likely to trial before committing).
//   coin_booster_churn   — shown at quiz_complete to players with high
//                          churn_risk (haven't played in 5-10 days).
//                          20% holdout by default for lift measurement.

var OE_DEFAULT_SEED_OFFERS = [
    {
        offer_id:    "quiz_bundle_starter",
        game_id:     "all",
        title:       "Starter Bundle — 5 Quiz Packs",
        product_id:  "com.intelliversex.quizverse.starter_bundle",
        price_usd:   1.99,
        active:      true,
        triggers:    ["quiz_complete"],
        eligible_spend_tiers:  ["non_spender"],
        eligible_churn_risks:  [],
        eligible_skill_bands:  [],
        min_install_age_days:  0,
        max_install_age_days:  30,
        min_quiz_plays:        3,
        cooldown_hours:        48,
        purchased_cooldown_hours: 720,
        max_shows_per_day:     2,
        holdout_pct:           10,
        priority:              10
    },
    {
        offer_id:    "premium_week_trial",
        game_id:     "all",
        title:       "1-Week Premium Trial",
        product_id:  "com.intelliversex.quizverse.premium_trial_7d",
        price_usd:   0.99,
        active:      true,
        triggers:    ["quiz_complete", "any"],
        eligible_spend_tiers:  ["non_spender", "low"],
        eligible_churn_risks:  ["low", "medium"],
        eligible_skill_bands:  ["intermediate", "expert"],
        min_install_age_days:  3,
        max_install_age_days:  60,
        min_quiz_plays:        5,
        cooldown_hours:        72,
        purchased_cooldown_hours: 720,
        max_shows_per_day:     1,
        holdout_pct:           15,
        priority:              20
    },
    {
        offer_id:    "coin_booster_churn",
        game_id:     "all",
        title:       "500 Coins — Welcome Back Deal",
        product_id:  "com.intelliversex.quizverse.coins_500",
        price_usd:   0.99,
        active:      true,
        triggers:    ["quiz_complete"],
        eligible_spend_tiers:  [],
        eligible_churn_risks:  ["high"],
        eligible_skill_bands:  [],
        min_install_age_days:  7,
        max_install_age_days:  9999,
        min_quiz_plays:        3,
        cooldown_hours:        24,
        purchased_cooldown_hours: 168,
        max_shows_per_day:     2,
        holdout_pct:           20,
        priority:              30
    }
];

function oeSeedDefaultOffers(nk, logger) {
    var now = new Date().toISOString();
    var seeded = 0;
    for (var i = 0; i < OE_DEFAULT_SEED_OFFERS.length; i++) {
        var offer = OE_DEFAULT_SEED_OFFERS[i];
        // Only write if not already present — never overwrite live-ops edits.
        var existing = oeReadOne(nk, OE_CATALOG_COLLECTION, offer.offer_id, OE_SYSTEM_USER);
        if (existing && existing.offer_id) continue;
        var full = {};
        for (var k in offer) if (Object.prototype.hasOwnProperty.call(offer, k)) full[k] = offer[k];
        full.created_at = now;
        full.updated_at = now;
        oeWriteOne(nk, OE_CATALOG_COLLECTION, offer.offer_id, OE_SYSTEM_USER, full);
        seeded++;
    }
    if (seeded > 0) logger.info("[offer_engine] Seeded " + seeded + " default offer(s) into catalog.");
}

function __ModuleInit_90(ctx, logger, nk, initializer) {
    // Player-facing
    __rpc_offer_get_eligible = __rpc_offer_get_eligible || (rpcOfferGetEligible);
    __rpc_offer_record_view = __rpc_offer_record_view || (rpcOfferRecordView);
    __rpc_offer_record_click = __rpc_offer_record_click || (rpcOfferRecordClick);
    __rpc_offer_record_dismiss = __rpc_offer_record_dismiss || (rpcOfferRecordDismiss);
    __rpc_offer_record_purchase = __rpc_offer_record_purchase || (rpcOfferRecordPurchase);
    // Admin
    __rpc_offer_upsert = __rpc_offer_upsert || (rpcOfferUpsert);
    __rpc_offer_list = __rpc_offer_list || (rpcOfferList);
    __rpc_offer_status = __rpc_offer_status || (rpcOfferStatus);
    logger.info("[offer_engine] Registered 8 RPCs: offer_get_eligible, " +
                "offer_record_view/click/dismiss/purchase, offer_upsert/list/status. " +
                "Triggers: " + Object.keys(OE_VALID_TRIGGERS).join(", "));
    // Seed starter offers if catalog is empty.
    try { oeSeedDefaultOffers(nk, logger); } catch (e) { /* never fail startup */ }
}


// --- Module: onboarding\ob_analytics_emit.js ---
/**
 * Server-side ob_* analytics for Unity onboarding hooks (D1/D7, welcome bonus, streak shield).
 * Writes to qv_onboarding_events — same lake as web onboarding_events_batch.
 */
function obAnalyticsEmitEvent(nk, nakamaUserId, eventName, data) {
    if (!nk || !nakamaUserId || !eventName) return;
    var SYSTEM_USER_ID = "00000000-0000-0000-0000-000000000000";
    var COL = "qv_onboarding_events";
    var ts = Date.now();
    var inv = "" + (100000000000000 - ts);
    while (inv.length < 14) inv = "0" + inv;
    var safe = (eventName || "x").replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 40);
    var key = "ev_0" + inv + "_" + safe;
    var record = {
        identityId: nakamaUserId,
        userId: nakamaUserId,
        nakamaUserId: nakamaUserId,
        name: eventName,
        timestamp: ts,
        screen: "",
        sessionId: "server",
        dwellMs: 0,
        data: data || {},
        userSnapshot: {},
        date: new Date(ts).toISOString().slice(0, 10)
    };
    try {
        nk.storageWrite([
            {
                collection: COL,
                key: key,
                userId: SYSTEM_USER_ID,
                value: record,
                permissionRead: 0,
                permissionWrite: 0
            },
            {
                collection: COL,
                key: key,
                userId: nakamaUserId,
                value: record,
                permissionRead: 2,
                permissionWrite: 0
            }
        ]);
    } catch (e) {
        /* non-fatal */
    }
}


// --- Module: onboarding\onboarding.js ---
﻿/**
 * Nakama Onboarding Module
 * Handles user onboarding state, preferences, and first-session hooks
 * 
 * Storage Collections:
 * - onboarding_state: User's onboarding progress
 * - user_preferences: User interests and personalization
 * - first_session: First session hooks and rewards
 * - retention_data: D1-D7 retention tracking
 */

// Collection names
var COLLECTION_ONBOARDING = "onboarding_state";
var COLLECTION_PREFERENCES = "user_preferences";
var COLLECTION_FIRST_SESSION = "first_session";
var COLLECTION_RETENTION = "retention_data";

// Keys
var KEY_ONBOARDING = "state";
var KEY_PREFERENCES = "prefs";
var KEY_SESSION = "session";
var KEY_RETENTION = "retention";

// ============================================================================
// DEFAULT AVATAR SYSTEM
// ============================================================================
var DEFAULT_AVATARS = [
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/indian-f.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/indian-m.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/chinese-f.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/chinese-m.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/african-f.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/african-m.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/european-f.png",
    "https://intelli-verse-x-media.s3.us-east-1.amazonaws.com/quiz-verse/quizverse-social-zone-profiles/european-m.png"
];

/**
 * Deterministically pick a default avatar from the pool.
 * Same userId always gets the same avatar (hash-based, not random).
 */
function getDefaultAvatarUrl(userId) {
    var hash = 0;
    for (var i = 0; i < userId.length; i++) {
        hash = ((hash << 5) - hash) + userId.charCodeAt(i);
        hash |= 0; // Convert to 32-bit integer
    }
    return DEFAULT_AVATARS[Math.abs(hash) % DEFAULT_AVATARS.length];
}

/**
 * True when the avatar is an old /DefaultAvatar/ preset that should be replaced.
 */
function isLegacyDefaultAvatar(url) {
    return !!(url && url.indexOf("/quiz-verse/DefaultAvatar/") !== -1);
}

/**
 * Ensure a user has an avatar URL. If missing or still on a legacy DefaultAvatar
 * preset, assign a deterministic social-zone profile.
 * Non-fatal — wrapped in try-catch to never block authentication.
 */
function ensureUserHasAvatar(nk, logger, userId) {
    try {
        var accounts = nk.accountsGetId([userId]);
        if (accounts && accounts.length > 0) {
            var account = accounts[0];
            var current = account.user.avatarUrl || "";
            if (!current || isLegacyDefaultAvatar(current)) {
                var defaultAvatar = getDefaultAvatarUrl(userId);
                nk.accountUpdateId(userId, null, null, null, null, null, defaultAvatar, null);
                logger.info("[Onboarding] Assigned default avatar to user " + userId + ": " + defaultAvatar);
                return true;
            }
        }
    } catch (avatarErr) {
        logger.warn("[Onboarding] Failed to assign default avatar for " + userId + ": " + avatarErr.message);
    }
    return false;
}

/**
 * Initialize onboarding module
 */
function _OnboardingInit(ctx, logger, nk, initializer) {
    logger.info("[Onboarding] Initializing onboarding module...");

    // Register RPCs
    __rpc_onboarding_get_state = __rpc_onboarding_get_state || (rpcGetOnboardingState);
    __rpc_onboarding_update_state = __rpc_onboarding_update_state || (rpcUpdateOnboardingState);
    __rpc_onboarding_complete_step = __rpc_onboarding_complete_step || (rpcCompleteStep);
    __rpc_onboarding_set_interests = __rpc_onboarding_set_interests || (rpcSetInterests);
    __rpc_onboarding_get_interests = __rpc_onboarding_get_interests || (rpcGetInterests);
    __rpc_onboarding_claim_welcome_bonus = __rpc_onboarding_claim_welcome_bonus || (rpcClaimWelcomeBonus);
    __rpc_onboarding_first_quiz_complete = __rpc_onboarding_first_quiz_complete || (rpcFirstQuizComplete);
    __rpc_onboarding_get_tomorrow_preview = __rpc_onboarding_get_tomorrow_preview || (rpcGetTomorrowPreview);
    __rpc_onboarding_track_session = __rpc_onboarding_track_session || (rpcTrackSession);
    __rpc_onboarding_get_retention_data = __rpc_onboarding_get_retention_data || (rpcGetRetentionData);
    __rpc_onboarding_grant_streak_shield = __rpc_onboarding_grant_streak_shield || (rpcGrantStreakShield);

    // Register hooks
    initializer.registerAfterAuthenticateDevice(afterAuthHook);
    initializer.registerAfterAuthenticateEmail(afterAuthHook);
    initializer.registerAfterAuthenticateApple(afterAuthHook);
    initializer.registerAfterAuthenticateGoogle(afterAuthHook);

    logger.info("[Onboarding] Module initialized successfully");
}

/**
 * After authentication hook - Initialize new users
 */
function afterAuthHook(ctx, logger, nk, data, request) {
    var userId = ctx.userId;
    
    try {
        // Check if user has onboarding state
        var existing = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        var isNewUser = existing.length === 0;

        if (isNewUser) {
            // New user - initialize onboarding state
            logger.info(`[Onboarding] New user detected: ${userId}`);
            initializeNewUser(nk, logger, userId);
            // Assign default avatar for new user
            ensureUserHasAvatar(nk, logger, userId);
        } else {
            // Returning user - track session
            trackUserSession(nk, logger, userId);
            // Backfill avatar for returning users who don't have one
            ensureUserHasAvatar(nk, logger, userId);
        }

        // Track DAU on every authentication (new + returning)
        try {
            trackDAUOnAuth(nk, logger, userId, isNewUser);
        } catch (dauErr) {
            logger.warn(`[Onboarding] DAU tracking failed (non-fatal): ${dauErr.message}`);
        }
    } catch (e) {
        logger.error(`[Onboarding] Auth hook error: ${e.message}`);
    }
}

/**
 * Track DAU on every authentication - writes both game-level and platform-level keys.
 * Uses the dashboard-compatible schema: { uniqueUsers, count, newUsers, date }
 */
function trackDAUOnAuth(nk, logger, userId, isNewUser) {
    var SYSTEM_USER = "00000000-0000-0000-0000-000000000000";
    var today = new Date().toISOString().split("T")[0];
    var gameId = typeof DEFAULT_GAME_ID !== "undefined" ? DEFAULT_GAME_ID : "126bf539-dae2-4bcf-964d-316c0fa1f92b"; // QuizVerse
    var collection = "analytics_dau";

    // Write both game-specific and platform-level DAU
    var keys = [
        "dau_" + gameId + "_" + today,
        "dau_platform_" + today
    ];

    for (var k = 0; k < keys.length; k++) {
        var key = keys[k];
        var dauData = null;
        try {
            var recs = nk.storageRead([{ collection: collection, key: key, userId: SYSTEM_USER }]);
            if (recs && recs.length > 0 && recs[0].value) {
                dauData = recs[0].value;
            }
        } catch (_) {}

        if (!dauData) {
            dauData = {
                date: today,
                uniqueUsers: [],
                count: 0,
                newUsers: 0
            };
        }

        // Ensure uniqueUsers is an array (migrate from old "users" field)
        if (!Array.isArray(dauData.uniqueUsers)) {
            dauData.uniqueUsers = Array.isArray(dauData.users) ? dauData.users : [];
        }

        // Add user if not already tracked today
        if (dauData.uniqueUsers.indexOf(userId) === -1) {
            dauData.uniqueUsers.push(userId);
            dauData.count = dauData.uniqueUsers.length;
            if (isNewUser) {
                dauData.newUsers = (dauData.newUsers || 0) + 1;
            }

            nk.storageWrite([{
                collection: collection,
                key: key,
                userId: SYSTEM_USER,
                value: dauData,
                permissionRead: 0,
                permissionWrite: 0
            }]);
        }
    }
}

/**
 * Initialize new user with default onboarding state
 */
function initializeNewUser(nk, logger, userId) {
    var now = Date.now();
    
    // Default onboarding state
    var onboardingState = {
        userId: userId,
        createdAt: now,
        currentStep: 1,
        totalSteps: 5,  // V2 Onboarding has 5 steps
        completedSteps: [],
        welcomeBonusClaimed: false,
        firstQuizCompleted: false,
        onboardingComplete: false,
        streakShieldExpiry: 0,
        lastUpdated: now
    };

    // Default preferences
    var preferences = {
        userId: userId,
        interests: [],
        preferredDifficulty: "easy",
        dailyReminderEnabled: true,
        reminderTime: "09:00",
        language: "en",
        createdAt: now,
        lastUpdated: now
    };

    // Session data
    var sessionData = {
        userId: userId,
        firstSessionAt: now,
        totalSessions: 1,
        lastSessionAt: now,
        totalQuizzesPlayed: 0,
        totalCoinsEarned: 0,
        currentStreak: 0,
        longestStreak: 0,
        d1Returned: false,
        d7Returned: false
    };

    // Write all initial data
    nk.storageWrite([
        {
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: onboardingState,
            permissionRead: 1, // Owner read
            permissionWrite: 0 // Server write only
        },
        {
            collection: COLLECTION_PREFERENCES,
            key: KEY_PREFERENCES,
            userId: userId,
            value: preferences,
            permissionRead: 1,
            permissionWrite: 0
        },
        {
            collection: COLLECTION_FIRST_SESSION,
            key: KEY_SESSION,
            userId: userId,
            value: sessionData,
            permissionRead: 1,
            permissionWrite: 0
        }
    ]);

    logger.info(`[Onboarding] Initialized new user: ${userId}`);
}

/**
 * #QVVBS54 FIX: Check if user has any game activity
 * Used to detect returning users whose onboarding state was lost
 */
function checkUserHasGameActivity(nk, logger, userId) {
    try {
        // Check wallet - if user has coins/gems, they've played before
        var walletResult = nk.storageRead([{
            collection: "wallet",
            key: "balance",
            userId: userId
        }]);
        
        if (walletResult.length > 0) {
            var wallet = walletResult[0].value;
            if (wallet.coins > 1000 || wallet.gems > 0) {
                logger.info(`[Onboarding] #QVVBS54: User ${userId} has wallet balance (coins: ${wallet.coins}, gems: ${wallet.gems})`);
                return true;
            }
        }
        
        // Check leaderboard entries - if user has any scores, they've played
        try {
            var leaderboardRecords = nk.leaderboardRecordsList("weekly_leaderboard", [userId], 1, null, 0);
            if (leaderboardRecords && leaderboardRecords.records && leaderboardRecords.records.length > 0) {
                logger.info(`[Onboarding] #QVVBS54: User ${userId} has leaderboard entries`);
                return true;
            }
        } catch (e) {
            // Leaderboard might not exist yet, that's ok
        }
        
        // Check daily completion history
        var dailyResult = nk.storageRead([{
            collection: "daily_completion",
            key: "history",
            userId: userId
        }]);
        
        if (dailyResult.length > 0) {
            logger.info(`[Onboarding] #QVVBS54: User ${userId} has daily completion history`);
            return true;
        }
        
        // Check quiz stats
        var statsResult = nk.storageRead([{
            collection: "quiz_stats",
            key: "stats",
            userId: userId
        }]);
        
        if (statsResult.length > 0) {
            var stats = statsResult[0].value;
            if (stats.totalGamesPlayed > 0 || stats.totalQuizzesCompleted > 0) {
                logger.info(`[Onboarding] #QVVBS54: User ${userId} has quiz stats`);
                return true;
            }
        }
        
        // Check first session data - if they've had multiple sessions, they're returning
        var sessionResult = nk.storageRead([{
            collection: COLLECTION_FIRST_SESSION,
            key: KEY_SESSION,
            userId: userId
        }]);
        
        if (sessionResult.length > 0) {
            var session = sessionResult[0].value;
            if (session.totalSessions > 1 || session.totalQuizzesPlayed > 0) {
                logger.info(`[Onboarding] #QVVBS54: User ${userId} has session history`);
                return true;
            }
        }
        
        return false;
    } catch (e) {
        logger.error(`[Onboarding] #QVVBS54: Error checking game activity: ${e.message}`);
        return false;
    }
}

/**
 * Track returning user session
 */
function trackUserSession(nk, logger, userId) {
    try {
        var result = nk.storageRead([{
            collection: COLLECTION_FIRST_SESSION,
            key: KEY_SESSION,
            userId: userId
        }]);

        if (result.length > 0) {
            var sessionData = result[0].value;
            var now = Date.now();
            var firstSession = sessionData.firstSessionAt;
            var hoursSinceFirst = (now - firstSession) / (1000 * 60 * 60);

            sessionData.totalSessions++;
            sessionData.lastSessionAt = now;

            if (!sessionData.d1Returned && hoursSinceFirst >= 20 && hoursSinceFirst <= 48) {
                sessionData.d1Returned = true;
                logger.info(`[Onboarding] User ${userId} returned on D1!`);
                obAnalyticsEmitEvent(nk, userId, "ob_d1_return", { hoursSinceFirst: Math.round(hoursSinceFirst) });
            }

            // Track D7 return
            if (!sessionData.d7Returned && hoursSinceFirst >= 144 && hoursSinceFirst <= 192) {
                sessionData.d7Returned = true;
                logger.info(`[Onboarding] User ${userId} returned on D7!`);
                obAnalyticsEmitEvent(nk, userId, "ob_d7_return", { hoursSinceFirst: Math.round(hoursSinceFirst) });
            }

            nk.storageWrite([{
                collection: COLLECTION_FIRST_SESSION,
                key: KEY_SESSION,
                userId: userId,
                value: sessionData,
                permissionRead: 1,
                permissionWrite: 0
            }]);
        }
    } catch (e) {
        logger.error(`[Onboarding] Track session error: ${e.message}`);
    }
}

// ==================== RPC HANDLERS ====================

/**
 * RPC: Get user's onboarding state
 * #QVVBS54 FIX: Check for returning user evidence before declaring new user
 */
function rpcGetOnboardingState(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    
    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        if (result.length === 0) {
            // #QVVBS54 FIX: Before creating new user state, check if user has game activity
            // This catches users whose onboarding state was lost but have played before
            var hasGameActivity = checkUserHasGameActivity(nk, logger, userId);
            
            if (hasGameActivity) {
                logger.info(`[Onboarding] User ${userId} has game activity but no onboarding state - marking complete`);
                var completedState = {
                    userId: userId,
                    createdAt: Date.now(),
                    currentStep: 6,
                    totalSteps: 5,
                    completedSteps: [1, 2, 3, 4, 5],
                    welcomeBonusClaimed: true,
                    firstQuizCompleted: true,
                    onboardingComplete: true,
                    recoveredFromActivity: true, // Flag for debugging
                    lastUpdated: Date.now()
                };
                nk.storageWrite([{
                    collection: COLLECTION_ONBOARDING,
                    key: KEY_ONBOARDING,
                    userId: userId,
                    value: completedState,
                    permissionRead: 1,
                    permissionWrite: 0
                }]);
                return JSON.stringify({
                    success: true,
                    isNewUser: false,
                    wasRecovered: true,
                    state: completedState
                });
            }
            
            // Truly new user - initialize
            initializeNewUser(nk, logger, userId);
            return JSON.stringify({
                success: true,
                isNewUser: true,
                state: {
                    currentStep: 1,
                    totalSteps: 5,  // V2 Onboarding has 5 steps
                    completedSteps: [],
                    welcomeBonusClaimed: false,
                    firstQuizCompleted: false,
                    onboardingComplete: false
                }
            });
        }

        // #QVVBS52 FIX: Stored row exists but flagged as incomplete. This is the
        // #1 source of "onboarding replays for returning users" because the
        // afterAuthHook writes this row on very first auth with
        // onboardingComplete=false, and never self-heals once the user has
        // actually played. Extend the activity-inference used in the "no row"
        // branch so any user with wallet / leaderboard / quiz / session history
        // auto-heals their row to complete on next login.
        var storedState = result[0].value;
        if (storedState && storedState.onboardingComplete !== true) {
            try {
                if (checkUserHasGameActivity(nk, logger, userId)) {
                    logger.info(`[Onboarding] #QVVBS52: User ${userId} has row with onboardingComplete=false but verified game activity - auto-healing to complete`);
                    storedState.onboardingComplete = true;
                    storedState.currentStep = Math.max(storedState.currentStep || 0, (storedState.totalSteps || 5) + 1);
                    storedState.completedSteps = [1, 2, 3, 4, 5];
                    storedState.welcomeBonusClaimed = true;
                    storedState.firstQuizCompleted = true;
                    storedState.recoveredFromActivity = true;
                    storedState.lastUpdated = Date.now();
                    nk.storageWrite([{
                        collection: COLLECTION_ONBOARDING,
                        key: KEY_ONBOARDING,
                        userId: userId,
                        value: storedState,
                        permissionRead: 1,
                        permissionWrite: 0
                    }]);
                    return JSON.stringify({
                        success: true,
                        isNewUser: false,
                        wasRecovered: true,
                        state: storedState
                    });
                }
            } catch (healErr) {
                logger.warn(`[Onboarding] #QVVBS52: auto-heal activity check failed (non-fatal): ${healErr.message}`);
            }
        }

        return JSON.stringify({
            success: true,
            isNewUser: false,
            state: storedState
        });
    } catch (e) {
        logger.error(`[Onboarding] Get state error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Update onboarding state
 */
function rpcUpdateOnboardingState(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ success: false, error: "No onboarding state found" });
        }

        var state = result[0].value;
        
        // Update fields
        if (input.currentStep !== undefined) state.currentStep = input.currentStep;
        if (input.completedSteps !== undefined) state.completedSteps = input.completedSteps;
        if (input.onboardingComplete !== undefined) state.onboardingComplete = input.onboardingComplete;
        state.lastUpdated = Date.now();

        nk.storageWrite([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: state,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        return JSON.stringify({ success: true, state: state });
    } catch (e) {
        logger.error(`[Onboarding] Update state error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Complete a specific onboarding step
 * V2 Onboarding has 5 steps; marks complete when stepId >= 5
 */
function rpcCompleteStep(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);
    var stepId = input.stepId;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        // #QVVBS54 FIX: If no state exists, create it and mark complete
        // This handles edge case where user completed onboarding but state was lost
        if (result.length === 0) {
            if (stepId >= 5) {
                // User is trying to complete final step - they've done onboarding
                logger.info(`[Onboarding] Creating completed state for user ${userId} (step ${stepId})`);
                var completedState = {
                    userId: userId,
                    createdAt: Date.now(),
                    currentStep: 6,
                    totalSteps: 5,
                    completedSteps: [1, 2, 3, 4, 5],
                    welcomeBonusClaimed: true,
                    firstQuizCompleted: true,
                    onboardingComplete: true,
                    lastUpdated: Date.now()
                };
                nk.storageWrite([{
                    collection: COLLECTION_ONBOARDING,
                    key: KEY_ONBOARDING,
                    userId: userId,
                    value: completedState,
                    permissionRead: 1,
                    permissionWrite: 0
                }]);
                return JSON.stringify({ success: true, state: completedState, rewards: getStepRewards(9) });
            }
            return JSON.stringify({ success: false, error: "No onboarding state" });
        }

        var state = result[0].value;
        
        // Add step to completed if not already
        if (!state.completedSteps.includes(stepId)) {
            state.completedSteps.push(stepId);
        }

        // Auto-advance to next step
        if (stepId >= state.currentStep) {
            state.currentStep = stepId + 1;
        }

        // #QVVBS54 FIX: Mark complete if step 9 is completed OR if all steps are done
        if (stepId >= 5 || state.completedSteps.length >= state.totalSteps) {
            state.onboardingComplete = true;
            logger.info(`[Onboarding] User ${userId} completed onboarding!`);
        }

        state.lastUpdated = Date.now();

        nk.storageWrite([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: state,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Return rewards for completing step
        var rewards = getStepRewards(stepId);

        return JSON.stringify({ 
            success: true, 
            state: state,
            rewards: rewards
        });
    } catch (e) {
        logger.error(`[Onboarding] Complete step error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Set user interests/preferences
 */
function rpcSetInterests(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_PREFERENCES,
            key: KEY_PREFERENCES,
            userId: userId
        }]);

        var prefs;
        if (result.length === 0) {
            prefs = {
                userId: userId,
                interests: input.interests || [],
                preferredDifficulty: input.difficulty || "easy",
                dailyReminderEnabled: true,
                reminderTime: "09:00",
                language: input.language || "en",
                createdAt: Date.now(),
                lastUpdated: Date.now()
            };
        } else {
            prefs = result[0].value;
            if (input.interests) prefs.interests = input.interests;
            if (input.difficulty) prefs.preferredDifficulty = input.difficulty;
            if (input.language) prefs.language = input.language;
            if (input.reminderEnabled !== undefined) prefs.dailyReminderEnabled = input.reminderEnabled;
            if (input.reminderTime) prefs.reminderTime = input.reminderTime;
            prefs.lastUpdated = Date.now();
        }

        nk.storageWrite([{
            collection: COLLECTION_PREFERENCES,
            key: KEY_PREFERENCES,
            userId: userId,
            value: prefs,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        logger.info(`[Onboarding] User ${userId} set interests: ${prefs.interests.join(", ")}`);

        return JSON.stringify({ success: true, preferences: prefs });
    } catch (e) {
        logger.error(`[Onboarding] Set interests error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Get user interests
 */
function rpcGetInterests(ctx, logger, nk, payload) {
    var userId = ctx.userId;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_PREFERENCES,
            key: KEY_PREFERENCES,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ 
                success: true, 
                preferences: {
                    interests: [],
                    preferredDifficulty: "easy"
                }
            });
        }

        return JSON.stringify({ success: true, preferences: result[0].value });
    } catch (e) {
        logger.error(`[Onboarding] Get interests error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Claim welcome bonus (50 coins for new users)
 */
function rpcClaimWelcomeBonus(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var WELCOME_BONUS = 50;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ success: false, error: "No onboarding state" });
        }

        var state = result[0].value;

        if (state.welcomeBonusClaimed) {
            // #QVVBS52 FIX: Return success=true with coinsAwarded=0 so the client's
            // "success && coins>0" guard no-ops instead of falling to the
            // offline-fallback branch and duplicate-granting 50 coins locally.
            return JSON.stringify({
                success: true,
                alreadyClaimed: true,
                coinsAwarded: 0,
                message: "Welcome bonus already granted"
            });
        }

        // Grant coins via wallet
        var changeset = { coins: WELCOME_BONUS };
        var metadata = { source: "welcome_bonus" };
        nk.walletUpdate(userId, changeset, metadata, true);

        // Update state
        state.welcomeBonusClaimed = true;
        state.lastUpdated = Date.now();

        nk.storageWrite([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: state,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        logger.info(`[Onboarding] User ${userId} claimed welcome bonus: ${WELCOME_BONUS} coins`);
        obAnalyticsEmitEvent(nk, userId, "ob_welcome_bonus_claimed", { coinsAwarded: WELCOME_BONUS });

        return JSON.stringify({
            success: true, 
            coinsAwarded: WELCOME_BONUS,
            message: "Welcome! Here's 50 free coins! 🎉"
        });
    } catch (e) {
        logger.error(`[Onboarding] Claim welcome bonus error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: First quiz completed - award bonus
 */
function rpcFirstQuizComplete(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);
    var FIRST_QUIZ_BONUS = 200;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ success: false, error: "No onboarding state" });
        }

        var state = result[0].value;

        if (state.firstQuizCompleted) {
            return JSON.stringify({ 
                success: false, 
                error: "First quiz bonus already claimed",
                alreadyClaimed: true
            });
        }

        // Grant bonus
        var changeset = { coins: FIRST_QUIZ_BONUS };
        var metadata = { 
            source: "first_quiz_bonus",
            score: input.score || 0,
            correctAnswers: input.correctAnswers || 0
        };
        nk.walletUpdate(userId, changeset, metadata, true);

        // Update state
        state.firstQuizCompleted = true;
        state.lastUpdated = Date.now();

        // Also grant streak shield (48 hours)
        state.streakShieldExpiry = Date.now() + (48 * 60 * 60 * 1000);

        nk.storageWrite([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: state,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Update session data
        updateSessionStats(nk, logger, userId, {
            quizzesPlayed: 1,
            coinsEarned: FIRST_QUIZ_BONUS
        });

        logger.info(`[Onboarding] User ${userId} completed first quiz: ${FIRST_QUIZ_BONUS} coins + streak shield`);
        obAnalyticsEmitEvent(nk, userId, "ob_streak_shield_activated", {
            streakShieldHours: 48,
            source: "first_quiz_bonus",
            coinsAwarded: FIRST_QUIZ_BONUS
        });

        return JSON.stringify({
            success: true, 
            coinsAwarded: FIRST_QUIZ_BONUS,
            streakShieldHours: 48,
            message: "Amazing! First Quiz Bonus: +200 Coins! 🎉\n🛡️ Streak Shield activated for 48 hours!"
        });
    } catch (e) {
        logger.error(`[Onboarding] First quiz complete error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Get tomorrow's preview (personalized hook)
 */
function rpcGetTomorrowPreview(ctx, logger, nk, payload) {
    var userId = ctx.userId;

    try {
        // Get user preferences
        var prefsResult = nk.storageRead([{
            collection: COLLECTION_PREFERENCES,
            key: KEY_PREFERENCES,
            userId: userId
        }]);

        var interests = ["General Knowledge"];
        if (prefsResult.length > 0 && prefsResult[0].value.interests.length > 0) {
            interests = prefsResult[0].value.interests;
        }

        // Pick a random interest for tomorrow's quiz
        var tomorrowCategory = interests[Math.floor(Math.random() * interests.length)];

        // Generate preview
        var preview = {
            category: tomorrowCategory,
            xpMultiplier: 2,
            bonusCoins: 100,
            specialReward: "Mystery Box",
            message: `Tomorrow: ${tomorrowCategory} Quiz with 2x XP! 🔥`,
            notificationText: `Your ${tomorrowCategory} quiz is ready! Don't miss the 2x XP bonus!`
        };

        return JSON.stringify({ success: true, preview: preview });
    } catch (e) {
        logger.error(`[Onboarding] Get tomorrow preview error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Track session for retention analytics
 */
function rpcTrackSession(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);

    try {
        trackUserSession(nk, logger, userId);

        if (input.quizzesPlayed || input.coinsEarned) {
            updateSessionStats(nk, logger, userId, input);
        }

        return JSON.stringify({ success: true });
    } catch (e) {
        logger.error(`[Onboarding] Track session error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Get retention data for analytics
 */
function rpcGetRetentionData(ctx, logger, nk, payload) {
    var userId = ctx.userId;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_FIRST_SESSION,
            key: KEY_SESSION,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ success: false, error: "No session data" });
        }

        var sessionData = result[0].value;
        var now = Date.now();
        var daysSinceFirst = Math.floor((now - sessionData.firstSessionAt) / (1000 * 60 * 60 * 24));

        var data = {};
        for (var k in sessionData) { data[k] = sessionData[k]; }
        data.daysSinceFirstSession = daysSinceFirst;
        data.isD1 = daysSinceFirst === 1;
        data.isD7 = daysSinceFirst === 7;

        return JSON.stringify({
            success: true,
            data: data
        });
    } catch (e) {
        logger.error(`[Onboarding] Get retention data error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

/**
 * RPC: Grant streak shield to user
 */
function rpcGrantStreakShield(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    var input = JSON.parse(payload);
    var hours = input.hours || 48;

    try {
        var result = nk.storageRead([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId
        }]);

        if (result.length === 0) {
            return JSON.stringify({ success: false, error: "No onboarding state" });
        }

        var state = result[0].value;
        state.streakShieldExpiry = Date.now() + (hours * 60 * 60 * 1000);
        state.lastUpdated = Date.now();

        nk.storageWrite([{
            collection: COLLECTION_ONBOARDING,
            key: KEY_ONBOARDING,
            userId: userId,
            value: state,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        return JSON.stringify({ 
            success: true, 
            streakShieldExpiry: state.streakShieldExpiry,
            hoursRemaining: hours
        });
    } catch (e) {
        logger.error(`[Onboarding] Grant streak shield error: ${e.message}`);
        return JSON.stringify({ success: false, error: e.message });
    }
}

// ==================== HELPER FUNCTIONS ====================

/**
 * Get rewards for completing a specific step
 */
function getStepRewards(stepId) {
    var stepRewards = {
        1: { coins: 0, message: "Welcome to QuizVerse!" },
        2: { coins: 50, message: "Interests saved! +50 coins" },
        3: { coins: 200, message: "First quiz done! +200 coins + Streak Shield!" },
        4: { coins: 50, message: "Daily rewards unlocked! +50 coins" },
        5: { coins: 100, message: "Onboarding complete! +100 bonus coins!" }
    };
    return stepRewards[stepId] || { coins: 0, message: "" };
}

/**
 * Update session statistics
 */
function updateSessionStats(nk, logger, userId, stats) {
    try {
        var result = nk.storageRead([{
            collection: COLLECTION_FIRST_SESSION,
            key: KEY_SESSION,
            userId: userId
        }]);

        if (result.length > 0) {
            var sessionData = result[0].value;
            
            if (stats.quizzesPlayed) {
                sessionData.totalQuizzesPlayed += stats.quizzesPlayed;
            }
            if (stats.coinsEarned) {
                sessionData.totalCoinsEarned += stats.coinsEarned;
            }
            if (stats.streak !== undefined) {
                sessionData.currentStreak = stats.streak;
                if (stats.streak > sessionData.longestStreak) {
                    sessionData.longestStreak = stats.streak;
                }
            }

            nk.storageWrite([{
                collection: COLLECTION_FIRST_SESSION,
                key: KEY_SESSION,
                userId: userId,
                value: sessionData,
                permissionRead: 1,
                permissionWrite: 0
            }]);
        }
    } catch (e) {
        logger.error(`[Onboarding] Update session stats error: ${e.message}`);
    }
}

