// --- Module: progression\mastery_system.js ---
/**
 * Prestige & Category Mastery System
 * Rewards deep engagement with specific categories and long-term progression
 * 
 * Impact: D30 +10% retention, increases session duration
 */

// ============================================================================
// MASTERY CONFIGURATION
// ============================================================================

var MASTERY_CONFIG = {
    // XP needed for each level in a category
    levels: [
        0,      // Level 0
        100,    // Level 1
        250,    // Level 2
        500,    // Level 3 (Bronze Badge)
        1000,   // Level 4
        2000,   // Level 5 (Silver Badge)
        4000,   // Level 6
        8000,   // Level 7 (Gold Badge)
        15000,  // Level 8
        30000   // Level 9 (Platinum Badge)
    ],
    
    // Rewards for reaching levels
    rewards: {
        3: { coins: 500, badge: "bronze" },
        5: { coins: 1500, gems: 20, badge: "silver" },
        7: { coins: 5000, gems: 100, badge: "gold" },
        9: { coins: 15000, gems: 500, badge: "platinum" }
    },
    
    // Prestige configuration
    prestige: {
        maxMasteryLevel: 9,
        prestigeLevels: [
            { id: 1, name: "Novice", xpBoost: 1.1, coinBoost: 1.05, requirements: { totalMastery: 5 } },
            { id: 2, name: "Scholar", xpBoost: 1.2, coinBoost: 1.1, requirements: { totalMastery: 15 } },
            { id: 3, name: "Sage", xpBoost: 1.5, coinBoost: 1.2, requirements: { totalMastery: 40 } },
            { id: 4, name: "Master", xpBoost: 2.0, coinBoost: 1.5, requirements: { totalMastery: 80 } },
            { id: 5, name: "Legend", xpBoost: 3.0, coinBoost: 2.0, requirements: { totalMastery: 150 } }
        ]
    }
};

// ============================================================================
// STORAGE KEYS
// ============================================================================

var STORAGE_COLLECTION = "progression";
var STORAGE_KEY_MASTERY = "category_mastery";
var STORAGE_KEY_PRESTIGE = "prestige_data";

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function getMasteryData(nk, userId) {
    try {
        var objects = nk.storageRead([{
            collection: STORAGE_COLLECTION,
            key: STORAGE_KEY_MASTERY,
            userId: userId
        }]);
        
        if (objects && objects.length > 0) {
            return objects[0].value;
        }
    } catch (e) {
        // No data yet
    }
    
    return {
        categories: {}, // categoryId -> { xp, level, badges: [] }
        totalMasteryLevel: 0,
        lastUpdated: Date.now()
    };
}

function getPrestigeData(nk, userId) {
    try {
        var objects = nk.storageRead([{
            collection: STORAGE_COLLECTION,
            key: STORAGE_KEY_PRESTIGE,
            userId: userId
        }]);
        
        if (objects && objects.length > 0) {
            return objects[0].value;
        }
    } catch (e) {
        // No data yet
    }
    
    return {
        prestigeLevel: 0,
        unlockedPrestigeNames: [],
        currentXpBoost: 1.0,
        currentCoinBoost: 1.0,
        lastUpdated: Date.now()
    };
}

function saveMasteryData(nk, userId, data) {
    data.lastUpdated = Date.now();
    nk.storageWrite([{
        collection: STORAGE_COLLECTION,
        key: STORAGE_KEY_MASTERY,
        userId: userId,
        value: data,
        permissionRead: 1,
        permissionWrite: 0
    }]);
}

function savePrestigeData(nk, userId, data) {
    data.lastUpdated = Date.now();
    nk.storageWrite([{
        collection: STORAGE_COLLECTION,
        key: STORAGE_KEY_PRESTIGE,
        userId: userId,
        value: data,
        permissionRead: 1,
        permissionWrite: 0
    }]);
}

function calculateLevel(xp) {
    var level = 0;
    for (var i = 0; i < MASTERY_CONFIG.levels.length; i++) {
        if (xp >= MASTERY_CONFIG.levels[i]) {
            level = i;
        } else {
            break;
        }
    }
    return level;
}

// ============================================================================
// RPC FUNCTIONS
// ============================================================================

/**
 * Add XP to a category after a quiz
 * Payload: { categoryId: string, xp: number }
 */
function rpcAddMasteryXp(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var request = {};
    try {
        request = JSON.parse(payload || "{}");
    } catch (e) {
        return JSON.stringify({ success: false, error: "Invalid payload" });
    }
    
    var categoryId = request.categoryId;
    var xpToAdd = request.xp || 0;
    
    if (!categoryId) {
        return JSON.stringify({ success: false, error: "Category ID required" });
    }
    
    var masteryData = getMasteryData(nk, ctx.userId);
    var prestigeData = getPrestigeData(nk, ctx.userId);
    
    // Apply prestige boost
    var boostedXp = Math.floor(xpToAdd * (prestigeData.currentXpBoost || 1.0));
    
    if (!masteryData.categories[categoryId]) {
        masteryData.categories[categoryId] = { xp: 0, level: 0, badges: [] };
    }
    
    var oldLevel = masteryData.categories[categoryId].level;
    masteryData.categories[categoryId].xp += boostedXp;
    var newLevel = calculateLevel(masteryData.categories[categoryId].xp);
    
    var levelUps = [];
    if (newLevel > oldLevel) {
        masteryData.categories[categoryId].level = newLevel;
        
        // Grant rewards for each level up
        for (var l = oldLevel + 1; l <= newLevel; l++) {
            var reward = MASTERY_CONFIG.rewards[l];
            if (reward) {
                // Grant rewards to wallet
                var walletChanges = {};
                if (reward.coins) walletChanges.coins = reward.coins;
                if (reward.gems) walletChanges.gems = reward.gems;
                
                if (Object.keys(walletChanges).length > 0) {
                    nk.walletUpdate(ctx.userId, walletChanges, {}, true);
                }
                
                if (reward.badge) {
                    masteryData.categories[categoryId].badges.push(reward.badge);
                }
                
                levelUps.push({ level: l, reward: reward });
            } else {
                levelUps.push({ level: l });
            }
        }
        
        // Update total mastery level
        var total = 0;
        for (var cat in masteryData.categories) {
            total += masteryData.categories[cat].level;
        }
        masteryData.totalMasteryLevel = total;
    }
    
    saveMasteryData(nk, ctx.userId, masteryData);
    
    return JSON.stringify({
        success: true,
        data: {
            categoryId: categoryId,
            addedXp: boostedXp,
            totalXp: masteryData.categories[categoryId].xp,
            level: newLevel,
            levelUps: levelUps,
            totalMasteryLevel: masteryData.totalMasteryLevel
        }
    });
}

/**
 * Get current mastery and prestige state
 */
function rpcGetProgressionState(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var masteryData = getMasteryData(nk, ctx.userId);
    var prestigeData = getPrestigeData(nk, ctx.userId);
    
    // Check if new prestige levels are available
    var nextPrestige = null;
    for (var i = 0; i < MASTERY_CONFIG.prestige.prestigeLevels.length; i++) {
        var p = MASTERY_CONFIG.prestige.prestigeLevels[i];
        if (p.id > prestigeData.prestigeLevel) {
            var met = masteryData.totalMasteryLevel >= p.requirements.totalMastery;
            nextPrestige = {
                id: p.id,
                name: p.name,
                requirements: p.requirements,
                met: met,
                xpBoost: p.xpBoost,
                coinBoost: p.coinBoost
            };
            break;
        }
    }
    
    return JSON.stringify({
        success: true,
        data: {
            mastery: masteryData,
            prestige: prestigeData,
            nextPrestige: nextPrestige,
            levelConfig: MASTERY_CONFIG.levels
        }
    });
}

/**
 * Claim a prestige level if requirements are met
 */
function rpcClaimPrestige(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var masteryData = getMasteryData(nk, ctx.userId);
    var prestigeData = getPrestigeData(nk, ctx.userId);
    
    var nextLevelId = prestigeData.prestigeLevel + 1;
    var nextLevelConfig = null;
    
    for (var i = 0; i < MASTERY_CONFIG.prestige.prestigeLevels.length; i++) {
        if (MASTERY_CONFIG.prestige.prestigeLevels[i].id === nextLevelId) {
            nextLevelConfig = MASTERY_CONFIG.prestige.prestigeLevels[i];
            break;
        }
    }
    
    if (!nextLevelConfig) {
        return JSON.stringify({ success: false, error: "No more prestige levels" });
    }
    
    if (masteryData.totalMasteryLevel < nextLevelConfig.requirements.totalMastery) {
        return JSON.stringify({ success: false, error: "Requirements not met" });
    }
    
    // Update prestige
    prestigeData.prestigeLevel = nextLevelConfig.id;
    prestigeData.unlockedPrestigeNames.push(nextLevelConfig.name);
    prestigeData.currentXpBoost = nextLevelConfig.xpBoost;
    prestigeData.currentCoinBoost = nextLevelConfig.coinBoost;
    
    savePrestigeData(nk, ctx.userId, prestigeData);
    
    logger.info("User " + ctx.userId + " reached prestige level " + nextLevelConfig.id + " (" + nextLevelConfig.name + ")");
    
    return JSON.stringify({
        success: true,
        data: {
            prestigeLevel: prestigeData.prestigeLevel,
            name: nextLevelConfig.name,
            xpBoost: prestigeData.currentXpBoost,
            coinBoost: prestigeData.currentCoinBoost
        }
    });
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = {
    rpcAddMasteryXp: rpcAddMasteryXp,
    rpcGetProgressionState: rpcGetProgressionState,
    rpcClaimPrestige: rpcClaimPrestige
};




// --- Module: progression\progressive_unlocks.js ---
/**
 * Progressive Content Unlocks Module
 * Unlocks game features over the first 7 days to maintain engagement
 * 
 * Impact: D7 +5% retention
 */

// ============================================================================
// UNLOCK CONFIGURATION
// ============================================================================

var UNLOCK_CONFIG = {
    // Day 1: Basic features (default)
    day1: {
        features: ["basic_quiz", "championship", "daily_quiz"],
        rewards: { coins: 50 },
        message: "Welcome! Start your trivia journey!"
    },
    // Day 2: Engagement features
    day2: {
        features: ["lucky_wheel", "daily_streak", "power_ups"],
        rewards: { coins: 100, energy: 3 },
        message: "🎡 Lucky Wheel unlocked! Spin for rewards!",
        requirement: { type: "login", day: 2 }
    },
    // Day 3: Social features
    day3: {
        features: ["multiplayer", "friends_list", "chat"],
        rewards: { coins: 150, gems: 10 },
        message: "⚔️ Multiplayer unlocked! Battle friends!",
        requirement: { type: "quizzes_won", count: 3 }
    },
    // Day 4: Content creation
    day4: {
        features: ["link_and_play", "custom_quizzes", "share_quiz"],
        rewards: { coins: 200, gems: 15 },
        message: "📚 Link & Play unlocked! Create your own quizzes!",
        requirement: { type: "login", day: 4 }
    },
    // Day 5: Advanced modes
    day5: {
        features: ["survival_mode", "timed_challenge", "hard_mode"],
        rewards: { coins: 250, gems: 20, mystery_box: 1 },
        message: "💀 Survival Mode unlocked! How long can you last?",
        requirement: { type: "quizzes_completed", count: 10 }
    },
    // Day 6: Competitive features
    day6: {
        features: ["weekly_tournament", "global_leaderboard", "rankings"],
        rewards: { coins: 300, gems: 25 },
        message: "🏆 Weekly Tournament unlocked! Compete globally!",
        requirement: { type: "login", day: 6 }
    },
    // Day 7: Premium trial
    day7: {
        features: ["premium_trial", "all_categories", "ad_free_trial"],
        rewards: { coins: 500, gems: 50, premium_days: 3 },
        message: "👑 VIP Trial unlocked! 3 days of Premium FREE!",
        requirement: { type: "login", day: 7 }
    }
};

// All possible features
var ALL_FEATURES = [
    "basic_quiz", "championship", "daily_quiz",
    "lucky_wheel", "daily_streak", "power_ups",
    "multiplayer", "friends_list", "chat",
    "link_and_play", "custom_quizzes", "share_quiz",
    "survival_mode", "timed_challenge", "hard_mode",
    "weekly_tournament", "global_leaderboard", "rankings",
    "premium_trial", "all_categories", "ad_free_trial"
];

// ============================================================================
// STORAGE KEYS
// ============================================================================

var STORAGE_COLLECTION = "progression";
var STORAGE_KEY_UNLOCKS = "progressive_unlocks";

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function getUnlockData(nk, userId) {
    try {
        var objects = nk.storageRead([{
            collection: STORAGE_COLLECTION,
            key: STORAGE_KEY_UNLOCKS,
            userId: userId
        }]);
        
        if (objects && objects.length > 0) {
            return objects[0].value;
        }
    } catch (e) {
        // No data yet
    }
    
    // Initialize default data
    return {
        firstLoginDate: Date.now(),
        currentDay: 1,
        unlockedFeatures: UNLOCK_CONFIG.day1.features.slice(),
        claimedDays: [1],
        totalQuizzesCompleted: 0,
        totalQuizzesWon: 0,
        lastCheckDate: Date.now()
    };
}

function saveUnlockData(nk, userId, data) {
    data.lastUpdated = Date.now();
    
    nk.storageWrite([{
        collection: STORAGE_COLLECTION,
        key: STORAGE_KEY_UNLOCKS,
        userId: userId,
        value: data,
        permissionRead: 1,
        permissionWrite: 0
    }]);
}

function calculateCurrentDay(firstLoginDate) {
    var now = Date.now();
    var daysSinceFirst = Math.floor((now - firstLoginDate) / (24 * 60 * 60 * 1000));
    return Math.min(daysSinceFirst + 1, 7); // Cap at day 7
}

function checkRequirement(data, requirement) {
    if (!requirement) return true;
    
    switch (requirement.type) {
        case "login":
            return data.currentDay >= requirement.day;
        case "quizzes_won":
            return data.totalQuizzesWon >= requirement.count;
        case "quizzes_completed":
            return data.totalQuizzesCompleted >= requirement.count;
        default:
            return true;
    }
}

function grantRewards(nk, userId, rewards, logger) {
    if (!rewards) return;
    
    try {
        // Grant coins
        if (rewards.coins) {
            nk.walletUpdate(userId, { coins: rewards.coins }, {}, true);
            logger.info("Granted " + rewards.coins + " coins to " + userId);
        }
        
        // Grant gems
        if (rewards.gems) {
            nk.walletUpdate(userId, { gems: rewards.gems }, {}, true);
            logger.info("Granted " + rewards.gems + " gems to " + userId);
        }
        
        // Grant energy
        if (rewards.energy) {
            nk.walletUpdate(userId, { energy: rewards.energy }, {}, true);
        }
        
        // Grant premium days
        if (rewards.premium_days) {
            var premiumExpiry = Date.now() + (rewards.premium_days * 24 * 60 * 60 * 1000);
            nk.storageWrite([{
                collection: "premium",
                key: "trial",
                userId: userId,
                value: { expiresAt: premiumExpiry, type: "trial" },
                permissionRead: 1,
                permissionWrite: 0
            }]);
        }
        
        // Grant mystery box
        if (rewards.mystery_box) {
            var inventoryData = { mystery_boxes: rewards.mystery_box };
            nk.walletUpdate(userId, inventoryData, {}, true);
        }
    } catch (e) {
        logger.error("Error granting rewards: " + e.message);
    }
}

// ============================================================================
// RPC FUNCTIONS
// ============================================================================

/**
 * Get current unlock state
 * Returns: unlockedFeatures, currentDay, nextUnlock, progress
 */
function rpcGetUnlockState(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var data = getUnlockData(nk, ctx.userId);
    
    // Update current day
    data.currentDay = calculateCurrentDay(data.firstLoginDate);
    saveUnlockData(nk, ctx.userId, data);
    
    // Calculate next unlock info
    var nextDay = null;
    var nextUnlock = null;
    
    for (var day = 1; day <= 7; day++) {
        var dayKey = "day" + day;
        var config = UNLOCK_CONFIG[dayKey];
        
        if (config && data.claimedDays.indexOf(day) === -1) {
            nextDay = day;
            nextUnlock = {
                day: day,
                features: config.features,
                rewards: config.rewards,
                message: config.message,
                canClaim: checkRequirement(data, config.requirement),
                requirement: config.requirement
            };
            break;
        }
    }
    
    // Build locked features list
    var lockedFeatures = [];
    ALL_FEATURES.forEach(function(feature) {
        if (data.unlockedFeatures.indexOf(feature) === -1) {
            lockedFeatures.push(feature);
        }
    });
    
    return JSON.stringify({
        success: true,
        data: {
            currentDay: data.currentDay,
            firstLoginDate: data.firstLoginDate,
            unlockedFeatures: data.unlockedFeatures,
            lockedFeatures: lockedFeatures,
            claimedDays: data.claimedDays,
            nextUnlock: nextUnlock,
            totalQuizzesCompleted: data.totalQuizzesCompleted,
            totalQuizzesWon: data.totalQuizzesWon,
            allUnlocked: data.claimedDays.length >= 7
        }
    });
}

/**
 * Claim unlock for a specific day
 * Payload: { day: number }
 */
function rpcClaimUnlock(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var request = {};
    try {
        request = JSON.parse(payload || "{}");
    } catch (e) {
        return JSON.stringify({ success: false, error: "Invalid payload" });
    }
    
    var day = request.day;
    if (!day || day < 1 || day > 7) {
        return JSON.stringify({ success: false, error: "Invalid day" });
    }
    
    var data = getUnlockData(nk, ctx.userId);
    data.currentDay = calculateCurrentDay(data.firstLoginDate);
    
    // Check if already claimed
    if (data.claimedDays.indexOf(day) !== -1) {
        return JSON.stringify({ success: false, error: "Already claimed" });
    }
    
    // Check if day is reachable
    if (day > data.currentDay) {
        return JSON.stringify({ success: false, error: "Day not yet available" });
    }
    
    // Check requirements
    var dayKey = "day" + day;
    var config = UNLOCK_CONFIG[dayKey];
    
    if (!config) {
        return JSON.stringify({ success: false, error: "Invalid day config" });
    }
    
    if (!checkRequirement(data, config.requirement)) {
        return JSON.stringify({ 
            success: false, 
            error: "Requirement not met",
            requirement: config.requirement
        });
    }
    
    // Claim the unlock
    data.claimedDays.push(day);
    config.features.forEach(function(feature) {
        if (data.unlockedFeatures.indexOf(feature) === -1) {
            data.unlockedFeatures.push(feature);
        }
    });
    
    // Grant rewards
    grantRewards(nk, ctx.userId, config.rewards, logger);
    
    // Save
    saveUnlockData(nk, ctx.userId, data);
    
    logger.info("User " + ctx.userId + " claimed Day " + day + " unlock");
    
    return JSON.stringify({
        success: true,
        data: {
            day: day,
            unlockedFeatures: config.features,
            rewards: config.rewards,
            message: config.message,
            allUnlockedFeatures: data.unlockedFeatures
        }
    });
}

/**
 * Check if a specific feature is unlocked
 */
function rpcCheckFeatureUnlocked(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var request = {};
    try {
        request = JSON.parse(payload || "{}");
    } catch (e) {
        return JSON.stringify({ success: false, error: "Invalid payload" });
    }
    
    var feature = request.feature;
    if (!feature) {
        return JSON.stringify({ success: false, error: "Feature required" });
    }
    
    var data = getUnlockData(nk, ctx.userId);
    var isUnlocked = data.unlockedFeatures.indexOf(feature) !== -1;
    
    // Find which day unlocks this feature
    var unlockDay = null;
    for (var day = 1; day <= 7; day++) {
        var config = UNLOCK_CONFIG["day" + day];
        if (config && config.features.indexOf(feature) !== -1) {
            unlockDay = day;
            break;
        }
    }
    
    return JSON.stringify({
        success: true,
        data: {
            feature: feature,
            isUnlocked: isUnlocked,
            unlockDay: unlockDay,
            currentDay: calculateCurrentDay(data.firstLoginDate)
        }
    });
}

/**
 * Update progress (quizzes completed/won)
 */
function rpcUpdateProgress(ctx, logger, nk, payload) {
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "Not authenticated" });
    }
    
    var request = {};
    try {
        request = JSON.parse(payload || "{}");
    } catch (e) {
        return JSON.stringify({ success: false, error: "Invalid payload" });
    }
    
    var data = getUnlockData(nk, ctx.userId);
    
    if (request.quizCompleted) {
        data.totalQuizzesCompleted++;
    }
    if (request.quizWon) {
        data.totalQuizzesWon++;
    }
    
    data.currentDay = calculateCurrentDay(data.firstLoginDate);
    saveUnlockData(nk, ctx.userId, data);
    
    // Check if any new unlocks are available
    var newUnlocksAvailable = [];
    for (var day = 1; day <= data.currentDay; day++) {
        if (data.claimedDays.indexOf(day) === -1) {
            var config = UNLOCK_CONFIG["day" + day];
            if (config && checkRequirement(data, config.requirement)) {
                newUnlocksAvailable.push({
                    day: day,
                    features: config.features,
                    message: config.message
                });
            }
        }
    }
    
    return JSON.stringify({
        success: true,
        data: {
            totalQuizzesCompleted: data.totalQuizzesCompleted,
            totalQuizzesWon: data.totalQuizzesWon,
            newUnlocksAvailable: newUnlocksAvailable
        }
    });
}

// ============================================================================
// EXPORTS
// ============================================================================

module.exports = {
    rpcGetUnlockState: rpcGetUnlockState,
    rpcClaimUnlock: rpcClaimUnlock,
    rpcCheckFeatureUnlocked: rpcCheckFeatureUnlocked,
    rpcUpdateProgress: rpcUpdateProgress
};




// --- Module: quests_analytics_bridge.js ---
/**
 * quests_analytics_bridge.js
 *
 * Nakama RPCs that expose analytics and player-profile data for the
 * quests-economy NestJS API.  This replaces the direct SQL queries that
 * the NestJS side was running against Nakama's storage / users tables
 * through the wrong DataSource.
 *
 * RPCs registered:
 *   qe_player_full_profile  – single-user profile aggregate
 *   qe_stale_sessions       – batch: sessions inactive > N days
 *   qe_cohort_export        – batch: active sessions + events
 *   qe_user_event_summary   – single-user event ring-buffer
 */

// ─── helpers ─────────────────────────────────────────────────────

function _qeParseMaybeJson(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch (e) { return v; }
}

// nk.sqlQuery() returns the storage `value` column (JSON content) as a UTF-8
// BYTE ARRAY in the Goja runtime, not a string or parsed object. _qeParseMaybeJson
// would pass that array straight through, leaving callers with {0:123,1:34,...}
// instead of the event. _qeDecodeJson handles all three shapes: already-parsed
// object, JSON string, or UTF-8 byte array (decoded via the escape/decodeURIComponent
// trick so multi-byte content — e.g. non-Latin quiz text — survives intact).
function _qeDecodeJson(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  if (typeof v === 'object') {
    var looksLikeBytes = (typeof v.length === 'number') &&
      (v.length === 0 || typeof v[0] === 'number');
    if (!looksLikeBytes) return v;
    var bin = '';
    for (var i = 0; i < v.length; i++) bin += String.fromCharCode(v[i] & 0xff);
    var str;
    try { str = decodeURIComponent(escape(bin)); } catch (e) { str = bin; }
    try { return JSON.parse(str); } catch (e2) { return null; }
  }
  return null;
}

/**
 * Attach consent markers IVX-AI analytics-knowledge expects on cohort rows.
 * Reads user_metadata/analytics and scans recent events for consent_state.
 */
function _qeBuildConsentContext(nk, userId, session, events) {
  var out = session && typeof session === 'object' ? Object.assign({}, session) : {};

  try {
    var recs = nk.storageRead([
      { collection: 'user_metadata', key: 'analytics', userId: userId },
      { collection: 'user_metadata', key: 'profile', userId: userId }
    ]);
    for (var ri = 0; ri < recs.length; ri++) {
      var val = recs[ri].value || {};
      if (val.personalization_consent === true || val.analytics_consent === true) {
        out.personalization_consent = true;
        out.analytics_consent = true;
      }
      if (val.personalization_consent === false) out.personalization_consent = false;
      if (val.analytics_consent === false) out.analytics_consent = false;
      if (val.consent_state) out.consent_state = val.consent_state;
    }
  } catch (e) { /* non-fatal */ }

  var evList = Array.isArray(events) ? events : [];
  for (var i = 0; i < evList.length; i++) {
    var ev = evList[i] || {};
    var ed = ev.eventData || ev.data || ev;
    if (ed.consent_state) out.consent_state = ed.consent_state;
    if (ed.personalization_consent === true) out.personalization_consent = true;
    if (ed.personalization_consent === false) out.personalization_consent = false;
    if (ed.analytics_consent) out.analytics_consent = ed.analytics_consent;
  }

  if (out.consent_state === 'granted' || out.personalization_consent === true) {
    out.consent = {
      personalization_consent: true,
      analytics_consent: out.analytics_consent !== false
    };
  } else if (out.consent_state === 'denied' || out.personalization_consent === false) {
    out.consent = {
      personalization_consent: false,
      analytics_consent: false
    };
  }

  return out;
}

var _QE_SYSTEM_USER_ID = "00000000-0000-0000-0000-000000000000";
var _QE_GPA_COLLECTION = "game_player_analytics";

/** Expand a GPA ring-buffer tuple {n,t,d} into a normalized analytics event. */
function _qeExpandGpaEvent(doc, ev) {
  var unixSec = parseInt(ev.t, 10) || 0;
  var ed = ev.d || {};
  return {
    eventName: String(ev.n || "unknown"),
    eventData: ed,
    userId: doc.user_id || "",
    gameId: doc.game_id || "",
    platform: doc.platform || "unknown",
    unixTimestamp: unixSec,
    timestamp: unixSec,
    sessionId: ed.session_id ? String(ed.session_id) : ""
  };
}

/**
 * O(1) read from game_player_analytics (per-player docs). Returns [] when
 * the user has no GPA doc; null when storage read failed (caller may SQL-fallback).
 */
function _qeLoadEventsFromGpa(nk, userId, activeSinceDays, maxEvents, gameId) {
  var cutoffSec = activeSinceDays > 0
    ? Math.floor(Date.now() / 1000) - (activeSinceDays * 86400)
    : 0;
  var docs = [];
  try {
    if (gameId) {
      var keyed = nk.storageRead([{
        collection: _QE_GPA_COLLECTION,
        key: gameId + ":" + userId,
        userId: userId
      }]);
      if (keyed && keyed.length > 0 && keyed[0].value) docs.push(keyed[0].value);
    } else {
      var cursor = "";
      var pages = 0;
      do {
        var page = nk.storageList(userId, _QE_GPA_COLLECTION, 25, cursor);
        if (!page || !page.objects || page.objects.length === 0) break;
        for (var pi = 0; pi < page.objects.length; pi++) {
          if (page.objects[pi].value) docs.push(page.objects[pi].value);
        }
        cursor = page.cursor || "";
        pages++;
      } while (cursor && pages < 20);
    }
  } catch (e) {
    return null;
  }

  var out = [];
  for (var di = 0; di < docs.length; di++) {
    var doc = docs[di] || {};
    var buf = doc.events || [];
    for (var ei = 0; ei < buf.length; ei++) {
      var expanded = _qeExpandGpaEvent(doc, buf[ei]);
      if (cutoffSec > 0 && expanded.unixTimestamp < cutoffSec) continue;
      out.push(expanded);
    }
  }
  out.sort(function (a, b) {
    return (b.unixTimestamp || 0) - (a.unixTimestamp || 0);
  });
  if (out.length > maxEvents) out = out.slice(0, maxEvents);
  return out;
}

/** Slow fallback: full-table scan on analytics_events JSON userId. */
function _qeLoadEventsFromAnalyticsSql(nk, userId, activeSinceDays, maxEvents) {
  var sql =
    "SELECT value FROM storage " +
    "WHERE collection = 'analytics_events' " +
    "AND value->>'userId' = $1 ";
  var params;
  if (activeSinceDays > 0) {
    sql += "AND update_time >= (CURRENT_TIMESTAMP - ($2::int * interval '1 day')) " +
           "ORDER BY update_time DESC LIMIT $3::int";
    params = [userId, activeSinceDays, maxEvents];
  } else {
    sql += "ORDER BY update_time DESC LIMIT $2::int";
    params = [userId, maxEvents];
  }
  var rows = nk.sqlQuery(sql, params);
  var events = [];
  for (var i = 0; i < rows.length; i++) {
    var parsed = _qeDecodeJson(rows[i].value);
    if (parsed) events.push(parsed);
  }
  return events;
}

/** Prefer GPA ring buffer; SQL-scan only when GPA is empty or unreadable. */
function _qeLoadEventsForUser(nk, logger, userId, activeSinceDays, maxEvents, gameId) {
  var fromGpa = _qeLoadEventsFromGpa(nk, userId, activeSinceDays, maxEvents, gameId);
  if (fromGpa !== null && fromGpa.length > 0) return fromGpa;
  try {
    return _qeLoadEventsFromAnalyticsSql(nk, userId, activeSinceDays, maxEvents);
  } catch (e) {
    if (logger && logger.warn) {
      logger.warn("[QeAnalytics] analytics_events SQL fallback failed for " +
        userId + ": " + (e.message || e));
    }
    return fromGpa || [];
  }
}

/** Active cohort from GPA (indexed user_id); falls back to analytics_events JSON scan. */
function _qeLoadActiveCohortUserIds(nk, logger, activeSinceDays, limit) {
  try {
    var gpaRows = nk.sqlQuery(
      "SELECT user_id::text AS uid, MAX(update_time) AS last_seen " +
      "FROM storage " +
      "WHERE collection = $1 " +
      "AND update_time >= (CURRENT_TIMESTAMP - ($2::int * interval '1 day')) " +
      "AND user_id IS NOT NULL " +
      "AND user_id <> $3 " +
      "GROUP BY user_id " +
      "ORDER BY last_seen DESC LIMIT $4::int",
      [_QE_GPA_COLLECTION, activeSinceDays, _QE_SYSTEM_USER_ID, limit]
    );
    if (gpaRows && gpaRows.length > 0) return gpaRows;
  } catch (eGpa) {
    if (logger && logger.warn) {
      logger.warn("[QeAnalytics] GPA cohort query failed, falling back: " +
        (eGpa.message || eGpa));
    }
  }
  return nk.sqlQuery(
    "SELECT value->>'userId' AS uid, MAX(update_time) AS last_seen " +
    "FROM storage " +
    "WHERE collection = 'analytics_events' " +
    "AND update_time >= (CURRENT_TIMESTAMP - ($1::int * interval '1 day')) " +
    "AND value->>'userId' IS NOT NULL " +
    "AND value->>'userId' <> '' " +
    "AND value->>'userId' <> $2 " +
    "GROUP BY value->>'userId' " +
    "ORDER BY last_seen DESC LIMIT $3::int",
    [activeSinceDays, _QE_SYSTEM_USER_ID, limit]
  );
}

// 2026-04 polish — return HTTP 400 (not generic 500) when callers send a
// malformed payload or omit a required field. Nakama's JS runtime expects
// the thrown `code` field to be a **gRPC status code** (0-16), NOT an HTTP
// status — anything outside the valid gRPC range falls through to UNKNOWN
// which the HTTP layer surfaces as 500. The other places in the bundle
// that throw `{code: 400, ...}` (e.g. quizverse_get_item_catalog) actually
// produce HTTP 500 too — they just happen to ship a "400" inside the JSON
// body, which is misleading. We use gRPC code 3 (INVALID_ARGUMENT) so the
// HTTP layer correctly returns 400 for missing/malformed input.
//
//   gRPC 3  = INVALID_ARGUMENT → HTTP 400  (this function)
//   gRPC 16 = UNAUTHENTICATED  → HTTP 401
//   gRPC 7  = PERMISSION_DENIED→ HTTP 403
//   gRPC 5  = NOT_FOUND        → HTTP 404
function _qeBadRequest(message) {
  return {
    code: 3, // gRPC INVALID_ARGUMENT → HTTP 400
    message: String(message || 'invalid request'),
    data: {}
  };
}

function _qeSafeParsePayload(payload) {
  // Empty / null payload is treated as `{}` so missing-field validation
  // below is the *only* thing that can trip the 400 — keeps behaviour
  // predictable for callers that omit the body entirely.
  if (payload === null || payload === undefined || payload === '') return {};
  try {
    var parsed = JSON.parse(payload);
    if (parsed && typeof parsed === 'object') return parsed;
    throw _qeBadRequest('payload must be a JSON object');
  } catch (e) {
    // Re-throw structured 400s as-is; wrap only raw SyntaxError from JSON.parse.
    if (e && typeof e === 'object' && e.code === 3) throw e;
    throw _qeBadRequest('payload is not valid JSON: ' + (e && e.message ? e.message : e));
  }
}

// ─── RPC: qe_player_full_profile ─────────────────────────────────

function rpcQePlayerFullProfile(ctx, logger, nk, payload) {
  var input = _qeSafeParsePayload(payload);
  var userId = input.user_id || '';
  if (!userId) {
    throw _qeBadRequest('user_id is required');
  }
  var gameId = input.game_id || input.gameId || '126bf539-dae2-4bcf-964d-316c0fa1f92b';

  var profile = {};
  var gameStats = {};
  var analytics = {};
  var questAnalytics = null;

  try {
    var records = nk.storageRead([
      { collection: 'user_metadata', key: 'profile',    userId: userId },
      { collection: 'user_metadata', key: 'game_stats', userId: userId },
      { collection: 'user_metadata', key: 'analytics',  userId: userId },
      { collection: 'quest_analytics', key: 'summary',  userId: userId }
    ]);

    for (var i = 0; i < records.length; i++) {
      var rec = records[i];
      if (rec.collection === 'user_metadata') {
        if (rec.key === 'profile')    profile    = rec.value || {};
        if (rec.key === 'game_stats') gameStats  = rec.value || {};
        if (rec.key === 'analytics')  analytics  = rec.value || {};
      }
      if (rec.collection === 'quest_analytics' && rec.key === 'summary') {
        questAnalytics = rec.value || null;
      }
    }
  } catch (e) {
    logger.warn('[QeAnalytics] storageRead failed for ' + userId + ': ' + e);
  }

  // GPA doc — primary source of truth for all live player KPIs.
  // Canonical key is {gameId}:{userId}; stored under the player's userId.
  var gpaDoc = null;
  try {
    var gpaKey = gameId + ':' + userId;
    var gpaRecs = nk.storageRead([{
      collection: _QE_GPA_COLLECTION, key: gpaKey, userId: userId
    }]);
    if (gpaRecs && gpaRecs.length > 0 && gpaRecs[0].value) {
      gpaDoc = gpaRecs[0].value;
    }
  } catch (eGpa) {
    logger.warn('[QeAnalytics] GPA read failed for ' + userId + ': ' + eGpa);
  }

  // When legacy user_metadata is empty, backfill from the GPA doc so callers
  // that key off profile.display_name / analytics.last_active_utc etc. still
  // get real data without needing a separate code change on their end.
  if (gpaDoc) {
    if (!profile.display_name && gpaDoc.display_name) profile.display_name = gpaDoc.display_name;
    if (!profile.avatar_url   && gpaDoc.avatar_url)   profile.avatar_url   = gpaDoc.avatar_url;
    if (!profile.platform     && gpaDoc.platform)     profile.platform     = gpaDoc.platform;
    if (!profile.country      && gpaDoc.country)      profile.country      = gpaDoc.country;
    if (!analytics.last_active_utc && gpaDoc.last_active_utc) analytics.last_active_utc = gpaDoc.last_active_utc;
    if (!analytics.first_seen_utc  && gpaDoc.first_seen_utc)  analytics.first_seen_utc  = gpaDoc.first_seen_utc;
    if (!analytics.lt_events       && gpaDoc.lt_events)       analytics.lt_events       = gpaDoc.lt_events;
    if (!analytics.lt_sessions     && gpaDoc.lt_sessions)     analytics.lt_sessions     = gpaDoc.lt_sessions;
    if (!analytics.lt_quiz_plays   && gpaDoc.lt_quiz_plays)   analytics.lt_quiz_plays   = gpaDoc.lt_quiz_plays;
    if (!gameStats.fav_mode        && gpaDoc.fav_mode)        gameStats.fav_mode        = gpaDoc.fav_mode;
    if (gameStats.fav_mode_n === undefined && gpaDoc.fav_mode_n) gameStats.fav_mode_n   = gpaDoc.fav_mode_n;
  }

  var userRow = null;
  try {
    var userRows = nk.sqlQuery(
      'SELECT id, username, display_name, lang_tag, location, timezone, ' +
      'metadata, wallet, create_time, update_time, edge_count ' +
      'FROM users WHERE id = $1 LIMIT 1',
      [userId]
    );
    if (userRows && userRows.length > 0) {
      userRow = userRows[0];
      if (userRow.metadata && typeof userRow.metadata === 'string') {
        try { userRow.metadata = JSON.parse(userRow.metadata); } catch (e2) { /* keep raw */ }
      }
    }
  } catch (e) {
    logger.warn('[QeAnalytics] users query failed: ' + e);
  }

  var leaderboardCount = 0;
  try {
    var lbRows = nk.sqlQuery(
      'SELECT COUNT(*)::int AS cnt FROM leaderboard_record WHERE owner_id = $1',
      [userId]
    );
    if (lbRows && lbRows.length > 0) {
      leaderboardCount = Number(lbRows[0].cnt) || 0;
    }
  } catch (e) {
    logger.warn('[QeAnalytics] leaderboard count query failed: ' + e);
  }

  return JSON.stringify({
    profile:           profile,
    game_stats:        gameStats,
    analytics:         analytics,
    quest_analytics:   questAnalytics,
    gpa:               gpaDoc,
    user:              userRow,
    leaderboard_count: leaderboardCount
  });
}

// ─── RPC: qe_stale_sessions ─────────────────────────────────────

function rpcQeStaleSessions(ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var inactiveDays = Number(input.inactive_days) || 3;
  var limit = Math.min(Number(input.limit) || 5000, 10000);

  try {
    var rows = nk.sqlQuery(
      "SELECT user_id, value FROM storage " +
      "WHERE collection = 'user_sessions' AND key = 'current' " +
      "AND update_time < (CURRENT_TIMESTAMP - ($1::int * interval '1 day')) " +
      "ORDER BY update_time ASC LIMIT $2::int",
      [inactiveDays, limit]
    );

    var results = [];
    for (var i = 0; i < rows.length; i++) {
      results.push({
        user_id: rows[i].user_id,
        session: _qeParseMaybeJson(rows[i].value)
      });
    }

    return JSON.stringify({ sessions: results, count: results.length });
  } catch (e) {
    logger.error('[QeAnalytics] qe_stale_sessions failed: ' + e);
    return JSON.stringify({ sessions: [], count: 0, error: String(e) });
  }
}

// ─── RPC: qe_cohort_export ──────────────────────────────────────

function rpcQeCohortExport(ctx, logger, nk, payload) {
  var input = JSON.parse(payload);
  var activeSinceDays = Number(input.active_since_days) || 30;
  var limit = Math.min(Number(input.limit) || 500, 2000);
  var maxEventsPerUser = Math.min(Number(input.max_events_per_user) || 500, 1000);
  var gameId = input.game_id || input.gameId || null;

  try {
    // Step 1 — active learners (GPA fast path uses indexed storage.user_id).
    var userRows = _qeLoadActiveCohortUserIds(nk, logger, activeSinceDays, limit);

    var cohort = [];
    for (var k = 0; k < userRows.length; k++) {
      var uid = userRows[k].uid;
      if (!uid) continue;

      var events = [];
      try {
        events = _qeLoadEventsForUser(
          nk, logger, uid, activeSinceDays, maxEventsPerUser, gameId
        );
      } catch (eEv) {
        logger.warn('[QeAnalytics] event fetch failed for ' + uid + ': ' + eEv);
      }

      // Best-effort session doc — usually absent in prod, but surface it when
      // present so any consent metadata stored on the session is honoured.
      var session = null;
      try {
        var sRec = nk.storageRead([{ collection: 'user_sessions', key: 'current', userId: uid }]);
        if (sRec && sRec.length > 0 && sRec[0].value) session = sRec[0].value;
      } catch (eS) { /* session optional */ }

      var eventsOut = events.length ? events : null;
      cohort.push({
        user_id: uid,
        session: _qeBuildConsentContext(nk, uid, session, eventsOut),
        events:  eventsOut
      });
    }

    return JSON.stringify({ cohort: cohort, count: cohort.length });
  } catch (e) {
    logger.error('[QeAnalytics] qe_cohort_export failed: ' + e);
    return JSON.stringify({ cohort: [], count: 0, error: String(e) });
  }
}

// ─── RPC: qe_user_event_summary ─────────────────────────────────

function rpcQeUserEventSummary(ctx, logger, nk, payload) {
  var input = _qeSafeParsePayload(payload);
  var userId = input.user_id || '';
  if (!userId) {
    throw _qeBadRequest('user_id is required');
  }
  // Optional window (days); 0/absent = all-time. Bounded event cap.
  var activeSinceDays = Number(input.active_since_days) || 0;
  var maxEvents = Math.min(Number(input.limit) || 500, 1000);
  var gameId = input.game_id || input.gameId || null;

  try {
    var events = _qeLoadEventsForUser(
      nk, logger, userId, activeSinceDays, maxEvents, gameId
    );
    if (events.length) {
      return JSON.stringify({
        events: events,
        found: true,
        session: _qeBuildConsentContext(nk, userId, null, events)
      });
    }
  } catch (e) {
    logger.warn('[QeAnalytics] qe_user_event_summary failed for ' + userId + ': ' + e);
  }

  return JSON.stringify({ events: null, found: false });
}

// ─── Registration (postbuild picks up initializer.registerRpc) ──

function _QeAnalyticsBridgeInit(ctx, logger, nk, initializer) {
  logger.info('[QeAnalyticsBridge] Registering RPCs');
  __rpc_qe_player_full_profile = __rpc_qe_player_full_profile || (rpcQePlayerFullProfile);
  __rpc_qe_stale_sessions = __rpc_qe_stale_sessions || (rpcQeStaleSessions);
  __rpc_qe_cohort_export = __rpc_qe_cohort_export || (rpcQeCohortExport);
  __rpc_qe_user_event_summary = __rpc_qe_user_event_summary || (rpcQeUserEventSummary);
  logger.info('[QeAnalyticsBridge] 4 RPCs registered');
}


// --- Module: quests_economy_bridge.js ---
/**
 * Quests Economy Bridge — Nakama is the single source of truth for XUT wallet.
 *
 * All balance reads and mutations use Nakama's NATIVE wallet system:
 *   - nk.walletUpdate(userId, changeset, metadata, updateLedger)
 *   - nk.walletLedgerList(userId, limit, cursor)
 *   - nk.accountGetId(userId) → account.wallet
 *
 * No HTTP callbacks to Postgres. The quests-economy API consumes these RPCs
 * via REST and treats Nakama as the authoritative store.
 *
 * Environment variables:
 *   QUESTS_ECONOMY_API_URL  — still used for IntelliDraws / non-wallet RPCs
 *   NAKAMA_WEBHOOK_SECRET   — shared HMAC secret for S2S auth
 *   DEFAULT_GAME_ID         — default game_id if not provided
 */

var QUESTS_API_URL = '';
var WEBHOOK_SECRET = '';
var DEFAULT_GAME_ID = '126bf539-dae2-4bcf-964d-316c0fa1f92b'; // QuizVerse
var _bridgeEnvInitialized = false;

var GAME_CONVERSION_RATIOS = {};

function _ensureBridgeEnv(ctx) {
    if (_bridgeEnvInitialized) return;
    if (ctx && ctx.env) {
        QUESTS_API_URL = QUESTS_API_URL
            || (ctx.env['QUESTS_ECONOMY_API_URL'] || 'http://quests-api.quests-economy.svc.cluster.local:3001').replace(/\/$/, '');
        WEBHOOK_SECRET = WEBHOOK_SECRET || ctx.env['NAKAMA_WEBHOOK_SECRET'] || '';
        DEFAULT_GAME_ID = ctx.env['DEFAULT_GAME_ID'] || DEFAULT_GAME_ID;
        _bridgeEnvInitialized = true;
    }
}

function _QuestsBridgeInit(ctx, logger, nk, initializer) {
    QUESTS_API_URL = (ctx.env['QUESTS_ECONOMY_API_URL'] || 'http://localhost:3001').replace(/\/$/, '');
    WEBHOOK_SECRET = ctx.env['NAKAMA_WEBHOOK_SECRET'] || '';
    DEFAULT_GAME_ID = ctx.env['DEFAULT_GAME_ID'] || DEFAULT_GAME_ID;

    loadConversionRatios(nk, logger);

    logger.info('[QuestsBridge] Initializing — Nakama native wallet as single source of truth');

    // Wallet RPCs — Nakama native (no Postgres proxy)
    __rpc_quests_wallet_balance = __rpc_quests_wallet_balance || (rpcQuestsWalletBalance);
    __rpc_quests_wallet_earn = __rpc_quests_wallet_earn || (rpcQuestsWalletEarn);
    __rpc_quests_wallet_spend = __rpc_quests_wallet_spend || (rpcQuestsWalletSpend);
    __rpc_quests_wallet_history = __rpc_quests_wallet_history || (rpcQuestsWalletHistory);

    // Keep old names as aliases for backward compatibility (games may call them)
    __rpc_global_wallet_balance = __rpc_global_wallet_balance || (rpcQuestsWalletBalance);
    __rpc_global_wallet_earn = __rpc_global_wallet_earn || (rpcQuestsWalletEarn);
    __rpc_global_wallet_spend = __rpc_global_wallet_spend || (rpcQuestsWalletSpend);
    __rpc_global_wallet_history = __rpc_global_wallet_history || (rpcQuestsWalletHistory);

    // One-time migration RPC (admin use only)
    __rpc_quests_wallet_migrate_from_postgres = __rpc_quests_wallet_migrate_from_postgres || (rpcMigrateFromPostgres);

    // Conversion RPCs
    __rpc_game_to_global_convert = __rpc_game_to_global_convert || (rpcGameToGlobalConvert);
    __rpc_game_to_global_preview = __rpc_game_to_global_preview || (rpcGameToGlobalPreview);
    __rpc_conversion_ratio_set = __rpc_conversion_ratio_set || (rpcConversionRatioSet);
    __rpc_conversion_ratio_get = __rpc_conversion_ratio_get || (rpcConversionRatioGet);

    // IntelliDraws RPCs
    __rpc_intellidraws_list = __rpc_intellidraws_list || (rpcIntelliDrawsList);
    __rpc_intellidraws_winners = __rpc_intellidraws_winners || (rpcIntelliDrawsWinners);
    __rpc_intellidraws_enter = __rpc_intellidraws_enter || (rpcIntelliDrawsEnter);
    __rpc_intellidraws_past = __rpc_intellidraws_past || (rpcIntelliDrawsPast);

    logger.info('[QuestsBridge] RPCs registered (native wallet + conversion + intellidraws + migration)');
}

function signRequest(nk, body) {
    if (!WEBHOOK_SECRET) return '';
    return nk.hmacSha256Hash(WEBHOOK_SECRET, body);
}

// ═══════════════════════════════════════════════════════════════════
//  NATIVE WALLET RPCs (Nakama single source of truth)
// ═══════════════════════════════════════════════════════════════════

/**
 * RPC: quests_wallet_balance
 * Returns all currency balances from Nakama's native wallet.
 * No HTTP callback — reads directly from nk.accountGetId().
 */
function rpcQuestsWalletBalance(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    try {
        var account = nk.accountGetId(userId);
        var wallet = {};
        if (account.wallet) {
            wallet = typeof account.wallet === 'string'
                ? JSON.parse(account.wallet)
                : account.wallet;
        }

        return JSON.stringify({
            success: true,
            data: {
                userId: userId,
                xut: wallet.xut || 0,
                ivx: wallet.ivx || 0,
                spark: wallet.spark || 0,
                nova: wallet.nova || 0,
                nexus: wallet.nexus || 0,
            },
        });
    } catch (err) {
        logger.error('[QuestsBridge] quests_wallet_balance failed: ' + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * RPC: quests_wallet_earn
 * Credits currency to the user's Nakama native wallet.
 * Payload: { amount, currency?, sourceType?, sourceId?, description? }
 */
function rpcQuestsWalletEarn(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    var amount = parsed.amount;
    if (!amount || amount <= 0) {
        return JSON.stringify({ success: false, error: 'amount must be > 0' });
    }

    var currency = parsed.currency || 'xut';
    var changeset = {};
    changeset[currency] = amount;

    var metadata = {
        type: 'earn',
        source: parsed.sourceType || 'quests_reward',
        sourceId: parsed.sourceId || '',
        description: parsed.description || ('Earned ' + amount + ' ' + currency),
    };

    try {
        var result = nk.walletUpdate(userId, changeset, metadata, true);
        var updated = result.updated || {};

        // Auto-credit 1 NOVA per XUT earned (loyalty program)
        if (currency === 'xut' && amount > 0) {
            try {
                nk.walletUpdate(userId, { nova: amount }, {
                    type: 'earn',
                    source: 'nova_auto_credit',
                    description: 'Auto NOVA: 1 per XUT earned',
                }, true);
            } catch (novaErr) {
                logger.warn('[QuestsBridge] NOVA auto-credit failed: ' + novaErr.message);
            }
        }

        logger.info('[QuestsBridge] Earned ' + amount + ' ' + currency + ' for user ' + userId);

        return JSON.stringify({
            success: true,
            data: {
                userId: userId,
                amountEarned: amount,
                currency: currency,
                newBalance: updated[currency] || 0,
                wallet: updated,
            },
        });
    } catch (err) {
        logger.error('[QuestsBridge] quests_wallet_earn failed: ' + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * RPC: quests_wallet_spend
 * Debits currency from the user's Nakama native wallet.
 * Nakama natively rejects negative balances.
 * Payload: { amount, currency?, sourceType?, sourceId?, description? }
 */
function rpcQuestsWalletSpend(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    var amount = parsed.amount;
    if (!amount || amount <= 0) {
        return JSON.stringify({ success: false, error: 'amount must be > 0' });
    }

    var currency = parsed.currency || 'xut';

    // Pre-check balance to give a clear error message
    try {
        var account = nk.accountGetId(userId);
        var wallet = {};
        if (account.wallet) {
            wallet = typeof account.wallet === 'string'
                ? JSON.parse(account.wallet)
                : account.wallet;
        }
        var currentBalance = wallet[currency] || 0;
        if (currentBalance < amount) {
            return JSON.stringify({
                success: false,
                error: 'Insufficient ' + currency + ' balance. Available: ' + currentBalance + ', Required: ' + amount,
            });
        }
    } catch (err) {
        logger.error('[QuestsBridge] Balance pre-check failed: ' + err.message);
        return JSON.stringify({ success: false, error: 'Failed to check balance' });
    }

    var changeset = {};
    changeset[currency] = -amount;

    var metadata = {
        type: 'spend',
        source: parsed.sourceType || 'redemption',
        sourceId: parsed.sourceId || '',
        description: parsed.description || ('Spent ' + amount + ' ' + currency),
    };

    try {
        var result = nk.walletUpdate(userId, changeset, metadata, true);
        var updated = result.updated || {};

        logger.info('[QuestsBridge] Spent ' + amount + ' ' + currency + ' for user ' + userId);

        return JSON.stringify({
            success: true,
            data: {
                userId: userId,
                amountSpent: amount,
                currency: currency,
                newBalance: updated[currency] || 0,
                wallet: updated,
            },
        });
    } catch (err) {
        logger.error('[QuestsBridge] quests_wallet_spend failed: ' + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * RPC: quests_wallet_history
 * Returns wallet ledger entries from Nakama's built-in wallet ledger.
 * Payload: { limit?, cursor? }
 */
function rpcQuestsWalletHistory(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    var limit = parsed.limit || 50;
    var cursor = parsed.cursor || '';

    try {
        var result = nk.walletLedgerList(userId, limit, cursor);
        var items = result.items || [];

        var entries = [];
        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            entries.push({
                id: item.id,
                changeset: item.changeset,
                metadata: item.metadata,
                create_time: item.createTime
                    ? Math.floor(new Date(item.createTime).getTime() / 1000)
                    : 0,
            });
        }

        return JSON.stringify({
            success: true,
            data: {
                userId: userId,
                entries: entries,
                count: entries.length,
                cursor: result.cursor || '',
            },
        });
    } catch (err) {
        logger.error('[QuestsBridge] quests_wallet_history failed: ' + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ═══════════════════════════════════════════════════════════════════
//  ONE-TIME MIGRATION: Postgres → Nakama native wallet
// ═══════════════════════════════════════════════════════════════════

/**
 * RPC: quests_wallet_migrate_from_postgres
 * Seeds user balances into Nakama's native wallet via nk.walletUpdate.
 *
 * Payload: { dryRun?: boolean, balances: [{ user_id: string, balance: number }] }
 *
 * If balances are provided in the payload, uses them directly.
 * Otherwise attempts to fetch from the quests-economy API.
 * Should be called once by an admin after deploying native wallet RPCs.
 */
function rpcMigrateFromPostgres(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var parsed = JSON.parse(payload || '{}');
    var dryRun = parsed.dryRun === true;
    var balances = parsed.balances || [];

    if (balances.length === 0) {
        var apiUrl = QUESTS_API_URL || 'http://quests-api.quests-economy.svc.cluster.local:3001';
        logger.info('[QuestsBridge] No balances in payload, fetching from API: ' + apiUrl);

        var bodyStr = JSON.stringify({});
        var sig = WEBHOOK_SECRET ? nk.hmacSha256Hash(WEBHOOK_SECRET, bodyStr) : '';
        var url = apiUrl + '/api/game-bridge/s2s/wallet/all-balances';
        var headers = {};
        headers['Content-Type'] = 'application/json';
        headers['X-Source'] = 'nakama-rpc';
        if (sig) headers['X-Webhook-Signature'] = sig;

        try {
            var response = nk.httpRequest(url, 'POST', headers, bodyStr);
            if (response.code >= 200 && response.code < 300) {
                var data = JSON.parse(response.body);
                balances = data.balances || data.data || [];
            } else {
                logger.error('[QuestsBridge] API returned ' + response.code);
                return JSON.stringify({ success: false, error: 'API returned ' + response.code });
            }
        } catch (err) {
            logger.error('[QuestsBridge] HTTP call failed: ' + err.message);
            return JSON.stringify({ success: false, error: 'HTTP failed: ' + err.message + '. Pass balances directly in the payload instead.' });
        }
    }

    logger.info('[QuestsBridge] Starting migration (dryRun=' + dryRun + ', users=' + balances.length + ')');
    var migrated = 0;
    var skipped = 0;
    var errors = 0;

    for (var i = 0; i < balances.length; i++) {
        var entry = balances[i];
        var userId = entry.user_id || entry.userId;
        var xut = entry.balance || entry.xut || 0;

        if (!userId || xut <= 0) {
            skipped++;
            continue;
        }

        if (dryRun) {
            logger.info('[QuestsBridge] DRY RUN: would migrate user=' + userId + ' xut=' + xut);
            migrated++;
            continue;
        }

        try {
            // Resolve Cognito ID → Nakama ID (creates account if needed)
            var nakamaId = userId;
            try {
                var authResult = nk.authenticateCustom(userId, '', true);
                nakamaId = authResult.userId || userId;
                logger.info('[QuestsBridge] Resolved cognito=' + userId + ' → nakama=' + nakamaId);
            } catch (authErr) {
                logger.warn('[QuestsBridge] authenticateCustom failed for ' + userId + ': ' + authErr.message + ' — trying direct');
            }

            var account = nk.accountGetId(nakamaId);
            var wallet = {};
            if (account.wallet) {
                wallet = typeof account.wallet === 'string'
                    ? JSON.parse(account.wallet)
                    : account.wallet;
            }

            if ((wallet.xut || 0) > 0) {
                logger.info('[QuestsBridge] Skip user=' + nakamaId + ' — already has ' + wallet.xut + ' XUT in Nakama');
                skipped++;
                continue;
            }

            nk.walletUpdate(nakamaId, { xut: xut }, {
                type: 'migration',
                source: 'postgres_migration',
                description: 'One-time migration from Postgres points_ledger (cognito=' + userId + ')',
            }, true);

            migrated++;
            logger.info('[QuestsBridge] Migrated cognito=' + userId + ' nakama=' + nakamaId + ' xut=' + xut);
        } catch (err) {
            errors++;
            logger.error('[QuestsBridge] Failed to migrate user=' + userId + ': ' + err.message);
        }
    }

    var summary = 'Migration complete: ' + migrated + ' migrated, ' + skipped + ' skipped, ' + errors + ' errors (total ' + balances.length + ')';
    logger.info('[QuestsBridge] ' + summary);

    return JSON.stringify({
        success: true,
        dryRun: dryRun,
        migrated: migrated,
        skipped: skipped,
        errors: errors,
        total: balances.length,
        summary: summary,
    });
}

// ═══════════════════════════════════════════════════════════════════
//  GAME WALLET HELPERS (Nakama storage-based — unchanged)
// ═══════════════════════════════════════════════════════════════════

function bridgeGetGameWallet(nk, logger, userId, gameId) {
    var key = 'wallet_' + userId + '_' + gameId;
    try {
        var records = nk.storageRead([{
            collection: 'wallets',
            key: key,
            userId: userId,
        }]);
        if (records && records.length > 0 && records[0].value) {
            var wallet = records[0].value;
            if (wallet.currencies) {
                if (wallet.currencies.game === undefined) wallet.currencies.game = wallet.currencies.tokens || 0;
                if (wallet.currencies.tokens === undefined) wallet.currencies.tokens = wallet.currencies.game || 0;
            }
            return wallet;
        }
    } catch (err) {
        logger.warn('[QuestsBridge] Failed to read game wallet: ' + err.message);
    }
    return {
        userId: userId,
        gameId: gameId,
        currencies: { game: 0, tokens: 0, xp: 0 },
        items: {},
    };
}

function bridgeSaveGameWallet(nk, logger, userId, gameId, wallet) {
    var key = 'wallet_' + userId + '_' + gameId;
    try {
        nk.storageWrite([{
            collection: 'wallets',
            key: key,
            userId: userId,
            value: wallet,
            permissionRead: 1,
            permissionWrite: 0,
        }]);
        return true;
    } catch (err) {
        logger.error('[QuestsBridge] Failed to save game wallet: ' + err.message);
        return false;
    }
}

function bridgeLogTransaction(nk, logger, userId, data) {
    try {
        var key = 'txn_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
        nk.storageWrite([{
            collection: 'transaction_logs',
            key: key,
            userId: userId,
            value: data,
            permissionRead: 1,
            permissionWrite: 0,
        }]);
    } catch (err) {
        logger.warn('[QuestsBridge] Failed to log transaction: ' + err.message);
    }
}

// ═══════════════════════════════════════════════════════════════════
//  CONVERSION RATIO STORAGE
// ═══════════════════════════════════════════════════════════════════

var CONVERSION_STORAGE_COLLECTION = 'economy_config';
var CONVERSION_STORAGE_KEY = 'game_conversion_ratios';
var SYSTEM_USER_ID = '00000000-0000-0000-0000-000000000000';

function loadConversionRatios(nk, logger) {
    try {
        var records = nk.storageRead([{
            collection: CONVERSION_STORAGE_COLLECTION,
            key: CONVERSION_STORAGE_KEY,
            userId: SYSTEM_USER_ID,
        }]);
        if (records && records.length > 0 && records[0].value) {
            GAME_CONVERSION_RATIOS = records[0].value.ratios || {};
        }
    } catch (err) {
        logger.warn('[QuestsBridge] No saved conversion ratios found, using defaults');
    }

    if (!GAME_CONVERSION_RATIOS['126bf539-dae2-4bcf-964d-316c0fa1f92b']) {
        GAME_CONVERSION_RATIOS['126bf539-dae2-4bcf-964d-316c0fa1f92b'] = 1000;
    }

    logger.info('[QuestsBridge] Conversion ratios loaded: ' + JSON.stringify(GAME_CONVERSION_RATIOS));
}

function saveConversionRatios(nk, logger) {
    try {
        nk.storageWrite([{
            collection: CONVERSION_STORAGE_COLLECTION,
            key: CONVERSION_STORAGE_KEY,
            userId: SYSTEM_USER_ID,
            value: { ratios: GAME_CONVERSION_RATIOS, updatedAt: Date.now() },
            permissionRead: 2,
            permissionWrite: 0,
        }]);
        return true;
    } catch (err) {
        logger.error('[QuestsBridge] Failed to save conversion ratios: ' + err.message);
        return false;
    }
}

function getConversionRatio(gameId) {
    return GAME_CONVERSION_RATIOS[gameId] || 0;
}

// ═══════════════════════════════════════════════════════════════════
//  CONVERSION RPCs (game coins → global XUT via Nakama native wallet)
// ═══════════════════════════════════════════════════════════════════

function rpcGameToGlobalPreview(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    var gameId = parsed.gameId;
    if (!gameId) {
        return JSON.stringify({ success: false, error: 'gameId is required' });
    }

    var ratio = getConversionRatio(gameId);
    if (ratio <= 0) {
        return JSON.stringify({ success: false, error: 'No conversion ratio configured for game ' + gameId });
    }

    var gameWallet = bridgeGetGameWallet(nk, logger, userId, gameId);
    var gameBalance = (gameWallet.currencies && (gameWallet.currencies.game || gameWallet.currencies.tokens)) || 0;

    var gameCoinAmount = parsed.gameCoinAmount || gameBalance;
    if (gameCoinAmount <= 0) {
        return JSON.stringify({ success: false, error: 'No game coins to convert' });
    }

    var globalPointsYield = Math.floor(gameCoinAmount / ratio);

    // Read global balance from Nakama native wallet
    var currentGlobalBalance = 0;
    try {
        var account = nk.accountGetId(userId);
        var wallet = {};
        if (account.wallet) {
            wallet = typeof account.wallet === 'string'
                ? JSON.parse(account.wallet)
                : account.wallet;
        }
        currentGlobalBalance = wallet.xut || 0;
    } catch (err) {
        logger.warn('[QuestsBridge] Failed to read global balance for preview: ' + err.message);
    }

    return JSON.stringify({
        success: true,
        gameId: gameId,
        gameCoinAmount: gameCoinAmount,
        globalPointsYield: globalPointsYield,
        ratio: ratio,
        gameBalance: gameBalance,
        currentGlobalBalance: currentGlobalBalance,
        projectedGlobalBalance: currentGlobalBalance + globalPointsYield,
    });
}

function rpcGameToGlobalConvert(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    var gameId = parsed.gameId;
    if (!gameId) {
        return JSON.stringify({ success: false, error: 'gameId is required' });
    }

    var ratio = getConversionRatio(gameId);
    if (ratio <= 0) {
        return JSON.stringify({ success: false, error: 'No conversion ratio configured for game ' + gameId });
    }

    var gameCoinAmount = parsed.gameCoinAmount;
    if (!gameCoinAmount || gameCoinAmount <= 0) {
        return JSON.stringify({ success: false, error: 'gameCoinAmount must be > 0' });
    }

    if (gameCoinAmount < ratio) {
        return JSON.stringify({
            success: false,
            error: 'Minimum conversion is ' + ratio + ' game coins (= 1 global point)',
        });
    }

    var gameWallet = bridgeGetGameWallet(nk, logger, userId, gameId);
    var gameBalance = (gameWallet.currencies && (gameWallet.currencies.game || gameWallet.currencies.tokens)) || 0;

    if (gameBalance < gameCoinAmount) {
        return JSON.stringify({
            success: false,
            error: 'Insufficient game balance. Have ' + gameBalance + ', need ' + gameCoinAmount,
        });
    }

    var globalPointsEarned = Math.floor(gameCoinAmount / ratio);
    var actualCoinsBurned = globalPointsEarned * ratio;

    // Step 1: Deduct from game wallet (Nakama storage)
    var currenciesToUpdate = ['game', 'tokens'];
    for (var i = 0; i < currenciesToUpdate.length; i++) {
        var curr = currenciesToUpdate[i];
        if (gameWallet.currencies[curr] !== undefined) {
            gameWallet.currencies[curr] -= actualCoinsBurned;
            if (gameWallet.currencies[curr] < 0) gameWallet.currencies[curr] = 0;
        }
    }
    if (!bridgeSaveGameWallet(nk, logger, userId, gameId, gameWallet)) {
        return JSON.stringify({ success: false, error: 'Failed to deduct game coins' });
    }

    // Step 2: Credit to Nakama native wallet (NOT Postgres)
    try {
        var walletResult = nk.walletUpdate(userId, { xut: globalPointsEarned }, {
            type: 'earn',
            source: 'game_to_global_conversion',
        sourceId: gameId,
            description: 'Converted ' + actualCoinsBurned + ' game coins → ' + globalPointsEarned + ' XUT (ratio ' + ratio + ':1)',
        }, true);

        // Also auto-credit NOVA
        try {
            nk.walletUpdate(userId, { nova: globalPointsEarned }, {
                type: 'earn',
                source: 'nova_auto_credit',
                description: 'Auto NOVA from game conversion',
            }, true);
        } catch (novaErr) {
            logger.warn('[QuestsBridge] NOVA auto-credit failed during conversion: ' + novaErr.message);
        }

        var newGlobalBalance = (walletResult.updated && walletResult.updated.xut) || 0;

    bridgeLogTransaction(nk, logger, userId, {
        type: 'game_to_global_conversion',
        gameId: gameId,
        gameCoinsBurned: actualCoinsBurned,
        globalPointsEarned: globalPointsEarned,
        ratio: ratio,
    });

    var newGameBalance = (gameWallet.currencies.game || gameWallet.currencies.tokens || 0);

    logger.info('[QuestsBridge] User ' + userId + ' converted ' + actualCoinsBurned + ' game coins → ' +
            globalPointsEarned + ' XUT (game ' + gameId + ')');

    return JSON.stringify({
        success: true,
        gameId: gameId,
        gameCoinsBurned: actualCoinsBurned,
        globalPointsEarned: globalPointsEarned,
        ratio: ratio,
        newGameBalance: newGameBalance,
            newGlobalBalance: newGlobalBalance,
        });
    } catch (err) {
        // Rollback: re-add game coins
        for (var i = 0; i < currenciesToUpdate.length; i++) {
            var curr = currenciesToUpdate[i];
            if (gameWallet.currencies[curr] !== undefined) {
                gameWallet.currencies[curr] += actualCoinsBurned;
            }
        }
        bridgeSaveGameWallet(nk, logger, userId, gameId, gameWallet);
        logger.error('[QuestsBridge] Conversion rolled back for user ' + userId + ': ' + err.message);
        return JSON.stringify({ success: false, error: 'Failed to credit global wallet, game coins restored' });
    }
}

function rpcConversionRatioSet(ctx, logger, nk, payload) {
    var parsed = JSON.parse(payload || '{}');
    var gameId = parsed.gameId;
    var ratio = parsed.ratio;

    if (!gameId || !ratio || ratio <= 0) {
        return JSON.stringify({ success: false, error: 'gameId and ratio (> 0) are required' });
    }

    GAME_CONVERSION_RATIOS[gameId] = ratio;
    saveConversionRatios(nk, logger);

    logger.info('[QuestsBridge] Conversion ratio set: game ' + gameId + ' = ' + ratio + ':1');

    return JSON.stringify({
        success: true,
        gameId: gameId,
        ratio: ratio,
        allRatios: GAME_CONVERSION_RATIOS,
    });
}

function rpcConversionRatioGet(ctx, logger, nk, payload) {
    var parsed = JSON.parse(payload || '{}');

    if (parsed.gameId) {
        var ratio = getConversionRatio(parsed.gameId);
        return JSON.stringify({
            success: true,
            gameId: parsed.gameId,
            ratio: ratio,
            configured: ratio > 0,
        });
    }

    return JSON.stringify({
        success: true,
        ratios: GAME_CONVERSION_RATIOS,
    });
}

// ═══════════════════════════════════════════════════════════════════
//  INTELLIDRAWS (LOTTERY) RPCs — still proxy to quests-economy API
// ═══════════════════════════════════════════════════════════════════

function questsApiGet(nk, logger, path) {
    var url = QUESTS_API_URL + path;
    try {
        var response = nk.httpRequest(url, 'get', { 'Content-Type': 'application/json' }, '');
        if (response.code >= 200 && response.code < 300) {
            return JSON.parse(response.body);
        }
        logger.error('[QuestsBridge] GET ' + path + ' returned ' + response.code);
        return { error: 'API returned ' + response.code };
    } catch (err) {
        logger.error('[QuestsBridge] GET ' + path + ' failed: ' + err.message);
        return { error: err.message };
    }
}

function questsApiPost(nk, logger, userId, path, body) {
    var bodyStr = JSON.stringify(body || {});
    var signature = signRequest(nk, bodyStr);
    var url = QUESTS_API_URL + path;
    var headers = {
        'Content-Type': 'application/json',
        'X-Source': 'nakama-rpc',
        'X-Webhook-Signature': signature,
        'X-User-Id': userId,
    };
    try {
        var response = nk.httpRequest(url, 'post', headers, bodyStr);
        if (response.code >= 200 && response.code < 300) {
            return JSON.parse(response.body);
        }
        logger.error('[QuestsBridge] POST ' + path + ' returned ' + response.code + ': ' + response.body);
        return { error: 'API returned ' + response.code, details: response.body };
    } catch (err) {
        logger.error('[QuestsBridge] POST ' + path + ' failed: ' + err.message);
        return { error: err.message };
    }
}

function rpcIntelliDrawsList(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var result = questsApiGet(nk, logger, '/consumer/intellidraws');
    if (result.error) {
        return JSON.stringify({ success: false, error: result.error });
    }
    return JSON.stringify({ success: true, sweepstakes: result });
}

function rpcIntelliDrawsWinners(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var result = questsApiGet(nk, logger, '/consumer/intellidraws/winners');
    if (result.error) {
        return JSON.stringify({ success: false, error: result.error });
    }
    return JSON.stringify({ success: true, winners: result });
}

function rpcIntelliDrawsEnter(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ error: 'User not authenticated' });
    }

    var parsed = JSON.parse(payload || '{}');
    if (!parsed.sweepstakeId) {
        return JSON.stringify({ success: false, error: 'sweepstakeId is required' });
    }

    var result = questsApiPost(nk, logger, userId, '/consumer/intellidraws/enter', {
        sweepstakeId: parsed.sweepstakeId,
        entries: parsed.entries || 1,
    });

    if (result.error) {
        return JSON.stringify({ success: false, error: result.error, details: result.details });
    }

    logger.info('[QuestsBridge] User ' + userId + ' entered IntelliDraws ' + parsed.sweepstakeId);
    return JSON.stringify({ success: true, result: result });
}

function rpcIntelliDrawsPast(ctx, logger, nk, payload) {
    _ensureBridgeEnv(ctx);
    var result = questsApiGet(nk, logger, '/consumer/intellidraws/past');
    if (result.error) {
        return JSON.stringify({ success: false, error: result.error });
    }
    return JSON.stringify({ success: true, pastDraws: result });
}


// --- Module: quiz_results\quiz_results.js ---
// quiz_results.js - Quiz Results Tracking & Analytics System
// Stores ALL quiz results from ALL game modes for analytics, history, and leaderboards
//
// Seen-question merging is delegated to globalThis.__qvsSeen (quizverse_seen.js)
// so that OCC, scope/topic slugification, and the safety cap are applied consistently.

// ─────────────────────────────────────────────────────────────────────────────
// KNOWLEDGE MAP HISTORY — constants
// ─────────────────────────────────────────────────────────────────────────────
// Maximum number of per-question history entries kept per user in the knowledge
// map rolling window. Older entries are dropped when this cap is exceeded so the
// storageRead payload stays bounded regardless of play-session count.
var KM_HISTORY_MAX_ENTRIES = 2000;

// Canonical UUID → slug map. Mirrors the entry in analytics.js so both systems
// resolve to the same slug-based collection name without a shared dependency.
var KM_UUID_TO_SLUG = {
    "126bf539-dae2-4bcf-964d-316c0fa1f92b": "quiz-verse"
};

/**
 * Resolve a gameId (UUID or slug) to its short slug, which is used as the
 * prefix for the knowledge-map history collection.
 * Returns the input unchanged if no mapping is found (graceful no-op).
 */
function kmResolveSlug(gameId) {
    if (!gameId) return "quiz-verse";
    var mapped = KM_UUID_TO_SLUG[gameId];
    return mapped || gameId;
}

/**
 * Append per-question knowledge-map history entries for a completed quiz and
 * persist them as a rolling window in Nakama storage.
 *
 * Called as a non-critical side-effect of quiz_submit_result. Any failure is
 * caught and logged so it never blocks the main result submission.
 *
 * Entry sources (in priority order):
 *  1. data.questionHistory   — [{category, correct, time_ms}] (AsyncChallenge / ScoreCalculationEngine)
 *  1b. data.questionDetails  — [{category, isCorrect, timeTakenSeconds}] (IVXQuizResultsManager SDK)
 *  2. data.categoryName + result aggregate — one synthesized entry per quiz
 *
 * The synthesized fallback maps:
 *   category  = data.categoryName || data.categoryId || "general"
 *   correct   = accuracy >= 60 %  (i.e. the player knew most of this category)
 *   time_ms   = round(timeTakenSeconds / totalQuestions * 1000)  per-question avg
 *
 * Rolling window: after appending, entries are trimmed to KM_HISTORY_MAX_ENTRIES
 * keeping the most recent ones so the document stays bounded forever.
 */
function appendKnowledgeMapHistory(nk, logger, userId, data, result, metrics) {
    try {
        var slug = kmResolveSlug(data.gameId);
        var collection = slug + "_quiz_history";
        var storageKey  = "history";

        // Read current history document (may not exist yet for a new player).
        var existing = null;
        try {
            var records = nk.storageRead([{ collection: collection, key: storageKey, userId: userId }]);
            if (records && records.length > 0 && records[0].value) {
                existing = records[0].value;
            }
        } catch (readErr) {
            // Missing document is fine — we will create it below.
            logger.debug("[KMHistory] No existing history for user " + userId + " — creating new document.");
        }

        var entries = (existing && Array.isArray(existing.entries)) ? existing.entries : [];

        // ── Build new entries to append ───────────────────────────────────────
        var newEntries = [];

        // Priority 1: explicit per-question breakdown — QuestionHistoryEntry schema
        // (from AsyncChallengeManager / ScoreCalculationEngine).
        // Expected shape: [{category, correct, time_ms}]
        // Also accepts alternate field names for forward/backward compat.
        if (data.questionHistory && Array.isArray(data.questionHistory) && data.questionHistory.length > 0) {
            for (var qi = 0; qi < data.questionHistory.length; qi++) {
                var q = data.questionHistory[qi];
                if (!q || typeof q !== "object") continue;
                var cat     = q.category  || q.categoryName || q.categoryId || "general";
                var correct = (q.correct !== undefined) ? !!q.correct
                            : (q.was_correct !== undefined) ? !!q.was_correct
                            : false;
                var timeMs  = parseInt(q.time_ms || q.timeMs || 0, 10);
                newEntries.push({ category: cat, correct: correct, time_ms: timeMs });
            }
        }

        // Priority 1b: IVXQuizResultsManager.QuizResultData uses "questionDetails"
        // (QuestionAnswerDetail[] schema from the SDK).  Fields: category, isCorrect,
        // timeTakenSeconds (seconds, not ms).  This is the path used by
        // DailyQuizManager and any mode submitting through QuizContainer.
        if (newEntries.length === 0 &&
            data.questionDetails && Array.isArray(data.questionDetails) && data.questionDetails.length > 0) {
            for (var qd = 0; qd < data.questionDetails.length; qd++) {
                var d = data.questionDetails[qd];
                if (!d || typeof d !== "object") continue;
                var cat     = d.category || d.concept || "general";
                var correct = (d.isCorrect !== undefined) ? !!d.isCorrect : false;
                var timeMs  = Math.round((parseFloat(d.timeTakenSeconds) || 0) * 1000);
                newEntries.push({ category: cat, correct: correct, time_ms: timeMs });
            }
        }

        // Priority 2: synthesize one aggregate entry from the quiz-level result.
        // Used when Unity does not send a per-question breakdown (older clients,
        // multiplayer modes, etc.).
        if (newEntries.length === 0) {
            var cat     = data.categoryName || data.categoryId || "general";
            var correct = (typeof metrics.accuracy === "number") ? metrics.accuracy >= 60 : false;
            var perQMs  = (result.totalQuestions > 0)
                        ? Math.round((result.timeTakenSeconds * 1000) / result.totalQuestions)
                        : 0;
            newEntries.push({ category: cat, correct: correct, time_ms: perQMs });
        }

        // ── Append + enforce rolling cap ──────────────────────────────────────
        var combined = entries.concat(newEntries);
        if (combined.length > KM_HISTORY_MAX_ENTRIES) {
            combined = combined.slice(combined.length - KM_HISTORY_MAX_ENTRIES);
        }

        nk.storageWrite([{
            collection:      collection,
            key:             storageKey,
            userId:          userId,
            value:           { entries: combined },
            permissionRead:  1,
            permissionWrite: 0
        }]);

        logger.info("[KMHistory] Appended " + newEntries.length + " entries for user " + userId +
            " (total=" + combined.length + ", slug=" + slug + ")");

    } catch (err) {
        // Non-critical: never let a history write failure block the main submit.
        logger.warn("[KMHistory] appendKnowledgeMapHistory failed (non-critical): " + err.message);
    }
}

/**
 * Quiz Result Schema
 * Captures comprehensive data about each quiz attempt
 */
var QUIZ_RESULT_SCHEMA = {
    // Required fields
    gameId: "string",           // Game UUID
    gameMode: "string",         // QuickPlay, DailyChallenge, Championship, etc.
    
    // Score data
    score: "number",            // Final score
    correctAnswers: "number",   // Number of correct answers
    totalQuestions: "number",   // Total questions in quiz
    
    // Timing
    timeTakenSeconds: "number", // Total time taken
    
    // Win/Loss
    won: "boolean",             // Did user win?
    
    // Optional fields
    difficulty: "string",       // easy, medium, hard
    categoryId: "string",       // Category/topic ID
    categoryName: "string",     // Category/topic name
    opponentId: "string",       // For multiplayer
    opponentName: "string",     // Opponent display name
    tournamentId: "string",     // If part of tournament
    matchId: "string",          // Match ID for multiplayer
    hintsUsed: "number",        // Power-ups used
    skipsUsed: "number",
    extraTimeUsed: "number",
    extraLivesUsed: "number",
    coinsSpent: "number",       // Coins spent on power-ups
    coinsEarned: "number",      // Coins earned from this quiz
    xpEarned: "number",         // XP earned
    streakDay: "number",        // Daily streak day
    perfectScore: "boolean",    // 100% accuracy
    metadata: "object"          // Any additional game-specific data
};

/**
 * Get collection name for quiz results
 */
function getResultsCollection(gameId) {
    return "quiz_results_" + gameId;
}

/**
 * Get user stats collection
 */
function getUserStatsCollection(gameId) {
    return "quiz_user_stats_" + gameId;
}

/**
 * Generate unique result key
 */
function generateResultKey(userId, timestamp) {
    return "result_" + userId + "_" + timestamp;
}

/**
 * Calculate performance metrics
 */
function calculateMetrics(result) {
    var accuracy = result.totalQuestions > 0 
        ? (result.correctAnswers / result.totalQuestions) * 100 
        : 0;
    
    var avgTimePerQuestion = result.totalQuestions > 0 
        ? result.timeTakenSeconds / result.totalQuestions 
        : 0;
    
    var isPerfect = result.correctAnswers === result.totalQuestions && result.totalQuestions > 0;
    
    return {
        accuracy: Math.round(accuracy * 100) / 100,
        avgTimePerQuestion: Math.round(avgTimePerQuestion * 100) / 100,
        isPerfect: isPerfect,
        performanceRating: calculatePerformanceRating(accuracy, avgTimePerQuestion, result.won)
    };
}

/**
 * Calculate performance rating (1-5 stars)
 */
function calculatePerformanceRating(accuracy, avgTime, won) {
    var rating = 0;
    
    // Accuracy contribution (0-2.5 stars)
    if (accuracy >= 90) rating += 2.5;
    else if (accuracy >= 70) rating += 2.0;
    else if (accuracy >= 50) rating += 1.5;
    else if (accuracy >= 30) rating += 1.0;
    else rating += 0.5;
    
    // Speed contribution (0-1.5 stars)
    if (avgTime <= 5) rating += 1.5;
    else if (avgTime <= 10) rating += 1.0;
    else if (avgTime <= 15) rating += 0.5;
    
    // Win bonus (0-1 star)
    if (won) rating += 1.0;
    
    return Math.min(5, Math.round(rating * 10) / 10);
}

// ─────────────────────────────────────────────────────────────────────────────
// MANAGER PLAYER SUMMARY — helpers (QVBF player-tracking)
// ─────────────────────────────────────────────────────────────────────────────
// A single clean, human-readable per-player document that the manager can read
// straight off the Nakama Console → Storage tab. Collection: "qv_player_stats",
// Key: "summary" (owner = userId, server-write only). Holds exactly the 5 asked
// metrics: Accuracy, Quizzes Taken, Quiz Scores, Consistency, Participation.

/** UTC calendar date string (YYYY-MM-DD). */
function qvDateStr(d) {
    return d.getUTCFullYear() + "-" +
        String(d.getUTCMonth() + 1).padStart(2, "0") + "-" +
        String(d.getUTCDate()).padStart(2, "0");
}

/** Whole days between two YYYY-MM-DD strings (b - a). */
function qvDaysBetween(a, b) {
    var ms = Date.parse(b + "T00:00:00Z") - Date.parse(a + "T00:00:00Z");
    return Math.round(ms / 86400000);
}

/**
 * Build the compact, manager-facing player summary from the aggregate stats.
 * Pure function (no I/O) so it can be reused by both the write path
 * (updateUserStats) and the read path (quizverse_get_player_summary).
 *
 * Holds exactly the manager-requested metrics — Accuracy, Quizzes Taken,
 * Quiz Scores, Consistency, Participation — plus the raw counts behind them
 * for full transparency in the Nakama Console Storage tab.
 */
function buildPlayerSummary(stats) {
    stats = stats || {};

    var totalGames    = stats.totalGames || 0;
    var totalQuestions = stats.totalQuestions || 0;
    var totalCorrect  = stats.totalCorrect || 0;
    var totalScore    = stats.totalScore || 0;
    var totalTime     = stats.totalTimePlayed || 0;

    var accuracyPct = totalQuestions > 0
        ? Math.round((totalCorrect / totalQuestions) * 1000) / 10 : 0;
    var avgScore = totalGames > 0 ? Math.round(totalScore / totalGames) : 0;
    var winRatePct = totalGames > 0
        ? Math.round((stats.totalWins || 0) / totalGames * 100) : 0;
    var avgSecondsPerQuestion = totalQuestions > 0
        ? Math.round((totalTime / totalQuestions) * 10) / 10 : 0;

    // Consistency = how regularly they play: active days vs days since first play.
    var windowDays = (stats.firstPlayedDate && stats.lastPlayedDate)
        ? qvDaysBetween(stats.firstPlayedDate, stats.lastPlayedDate) + 1 : 1;
    if (windowDays < 1) windowDays = 1;
    var consistencyPct = Math.min(100, Math.round(((stats.activeDays || 0) / windowDays) * 100));

    return {
        // ── Quizzes Taken ──
        quizzesTaken: totalGames,
        // ── Accuracy ──
        accuracyPct: accuracyPct,
        correctAnswers: totalCorrect,
        totalQuestions: totalQuestions,
        // ── Quiz Scores ──
        totalScore: totalScore,
        avgScore: avgScore,
        highestScore: stats.highestScore || 0,
        // ── Performance ──
        wins: stats.totalWins || 0,
        winRatePct: winRatePct,
        perfectQuizzes: stats.perfectGames || 0,
        timePlayedSeconds: totalTime,
        avgSecondsPerQuestion: avgSecondsPerQuestion,
        // ── Consistency ──
        consistency: {
            consistencyPct: consistencyPct,
            currentStreakDays: stats.currentStreakDays || 0,
            longestStreakDays: stats.longestStreakDays || 0,
            activeDays: stats.activeDays || 0,
            firstPlayedDate: stats.firstPlayedDate || null,
            lastPlayedDate: stats.lastPlayedDate || null
        },
        // ── Participation (per game mode) ──
        participationByMode: stats.modeStats || {},
        updatedAt: utils.getCurrentTimestamp()
    };
}

/**
 * Build a compact, flat snapshot for the Nakama Console **Account tab**
 * (account.metadata). Kept small + string-friendly so it reads cleanly in the
 * metadata box. Full structured data still lives in the Storage tab.
 */
function buildAccountStatsSnapshot(summary) {
    return {
        quizzesTaken: summary.quizzesTaken,
        accuracyPct: summary.accuracyPct,
        avgScore: summary.avgScore,
        highestScore: summary.highestScore,
        totalScore: summary.totalScore,
        wins: summary.wins,
        winRatePct: summary.winRatePct,
        consistencyPct: summary.consistency.consistencyPct,
        currentStreakDays: summary.consistency.currentStreakDays,
        longestStreakDays: summary.consistency.longestStreakDays,
        activeDays: summary.consistency.activeDays,
        lastPlayedDate: summary.consistency.lastPlayedDate,
        updatedAt: summary.updatedAt
    };
}

/**
 * Merge the quiz-stats snapshot into the player's account.metadata so it shows
 * on the Console **Account tab**. Reads existing metadata first and merges,
 * so pre-existing keys (e.g. country) are preserved. Non-critical.
 */
function writeAccountStatsMeta(nk, logger, userId, summary) {
    try {
        var meta = {};
        var user = null;
        try {
            var acct = nk.accountGetId(userId);
            user = (acct && acct.user) || null;
            if (user && user.metadata) {
                meta = user.metadata;
            }
        } catch (readErr) {
            // user may not exist yet / no account — skip silently
            return;
        }

        meta.quizStats = buildAccountStatsSnapshot(summary);

        // Backfill native Account-tab fields ONLY when empty — never clobber
        // real values the user/profile-sync already set.
        //   • Display name → fall back to username
        //   • Location     → fall back to the country already in metadata (e.g. "IN")
        var displayName = null;
        if (user && (!user.displayName || user.displayName === "") && user.username) {
            displayName = user.username;
        }
        var location = null;
        if (user && (!user.location || user.location === "") && meta && meta.country) {
            location = String(meta.country);
        }

        // Signature: accountUpdateId(userId, username, displayName, timezone, location, langTag, avatarUrl, metadata)
        nk.accountUpdateId(userId, null, displayName, null, location, null, null, meta);
    } catch (err) {
        utils.logWarning(logger, "[PlayerSummary] account metadata update failed (non-critical): " + err.message);
    }
}

/**
 * Write the compact manager-facing summary from the aggregate stats to BOTH:
 *   1. Storage tab  → qv_player_stats/summary  (full structured doc)
 *   2. Account tab  → account.metadata.quizStats (compact snapshot)
 * Non-critical: never blocks result submission.
 */
function writePlayerSummary(nk, logger, userId, stats) {
    var summary = buildPlayerSummary(stats);
    try {
        nk.storageWrite([{
            collection: "qv_player_stats",
            key: "summary",
            userId: userId,
            value: summary,
            permissionRead: 1,
            permissionWrite: 0
        }]);
    } catch (err) {
        utils.logWarning(logger, "[PlayerSummary] storage write failed (non-critical): " + err.message);
    }
    writeAccountStatsMeta(nk, logger, userId, summary);
}

/**
 * Update user's aggregate statistics
 */
function updateUserStats(nk, logger, userId, gameId, result, metrics) {
    var collection = getUserStatsCollection(gameId);
    var key = "stats_" + userId;
    
    // Get existing stats
    var stats = utils.readStorage(nk, logger, collection, key, userId);
    
    if (!stats) {
        stats = {
            userId: userId,
            gameId: gameId,
            totalGames: 0,
            totalWins: 0,
            totalScore: 0,
            totalCorrect: 0,
            totalQuestions: 0,
            totalTimePlayed: 0,
            perfectGames: 0,
            highestScore: 0,
            longestStreak: 0,
            currentStreak: 0,
            // Day-based consistency (distinct calendar days played)
            firstPlayedDate: null,
            lastPlayedDate: null,
            activeDays: 0,
            currentStreakDays: 0,
            longestStreakDays: 0,
            lastPlayedAt: null,
            modeStats: {},
            createdAt: utils.getCurrentTimestamp()
        };
    }
    
    // Update totals
    stats.totalGames++;
    stats.totalScore += result.score || 0;
    stats.totalCorrect += result.correctAnswers || 0;
    stats.totalQuestions += result.totalQuestions || 0;
    stats.totalTimePlayed += result.timeTakenSeconds || 0;
    
    if (result.won) {
        stats.totalWins++;
        stats.currentStreak++;
        stats.longestStreak = Math.max(stats.longestStreak, stats.currentStreak);
    } else {
        stats.currentStreak = 0;
    }
    
    if (metrics.isPerfect) {
        stats.perfectGames++;
    }
    
    stats.highestScore = Math.max(stats.highestScore, result.score || 0);
    stats.lastPlayedAt = utils.getCurrentTimestamp();

    // ── Day-based consistency tracking (distinct calendar days + day streak) ──
    var todayStr = qvDateStr(new Date());
    if (!stats.firstPlayedDate) stats.firstPlayedDate = todayStr;
    if (stats.lastPlayedDate !== todayStr) {
        // New distinct day played.
        stats.activeDays = (stats.activeDays || 0) + 1;
        if (stats.lastPlayedDate && qvDaysBetween(stats.lastPlayedDate, todayStr) === 1) {
            stats.currentStreakDays = (stats.currentStreakDays || 0) + 1; // consecutive day
        } else {
            stats.currentStreakDays = 1; // first day or a gap → reset
        }
        stats.longestStreakDays = Math.max(stats.longestStreakDays || 0, stats.currentStreakDays);
        stats.lastPlayedDate = todayStr;
    }
    
    // Update per-mode stats
    var mode = result.gameMode || "unknown";
    if (!stats.modeStats[mode]) {
        stats.modeStats[mode] = {
            games: 0,
            wins: 0,
            totalScore: 0,
            highestScore: 0
        };
    }
    stats.modeStats[mode].games++;
    if (result.won) stats.modeStats[mode].wins++;
    stats.modeStats[mode].totalScore += result.score || 0;
    stats.modeStats[mode].highestScore = Math.max(
        stats.modeStats[mode].highestScore, 
        result.score || 0
    );
    
    stats.updatedAt = utils.getCurrentTimestamp();
    
    // Save stats
    utils.writeStorage(nk, logger, collection, key, userId, stats);

    // Write the compact manager-facing summary (qv_player_stats/summary).
    writePlayerSummary(nk, logger, userId, stats);

    return stats;
}

/**
 * RPC: quiz_submit_result
 * Submit quiz result from any game mode
 * 
 * Required payload:
 * {
 *   gameId: "uuid",
 *   gameMode: "QuickPlay",
 *   score: 850,
 *   correctAnswers: 8,
 *   totalQuestions: 10,
 *   timeTakenSeconds: 120,
 *   won: true
 * }
 * 
 * Optional fields: difficulty, categoryId, categoryName, opponentId,
 *   tournamentId, matchId, hintsUsed, skipsUsed, coinsSpent, coinsEarned, etc.
 */
function rpcQuizSubmitResult(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC quiz_submit_result called");
    
    // Parse payload
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    
    // Validate required fields
    var required = ['gameId', 'gameMode', 'score', 'correctAnswers', 'totalQuestions', 'timeTakenSeconds'];
    var validation = utils.validatePayload(data, required);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }
    
    // Validate gameId UUID
    if (!utils.isValidUUID(data.gameId)) {
        return utils.handleError(ctx, null, "Invalid gameId UUID format");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    var username = ctx.username || "unknown";
    var timestamp = utils.getUnixTimestamp();
    
    // Build result object
    var result = {
        id: generateResultKey(userId, timestamp),
        userId: userId,
        username: username,
        gameId: data.gameId,
        gameMode: data.gameMode,
        score: parseInt(data.score) || 0,
        correctAnswers: parseInt(data.correctAnswers) || 0,
        totalQuestions: parseInt(data.totalQuestions) || 0,
        timeTakenSeconds: parseFloat(data.timeTakenSeconds) || 0,
        won: data.won === true || data.won === "true",
        
        // Optional fields
        difficulty: data.difficulty || "normal",
        categoryId: data.categoryId || null,
        categoryName: data.categoryName || null,
        opponentId: data.opponentId || null,
        opponentName: data.opponentName || null,
        tournamentId: data.tournamentId || null,
        matchId: data.matchId || null,
        hintsUsed: parseInt(data.hintsUsed) || 0,
        skipsUsed: parseInt(data.skipsUsed) || 0,
        extraTimeUsed: parseInt(data.extraTimeUsed) || 0,
        extraLivesUsed: parseInt(data.extraLivesUsed) || 0,
        coinsSpent: parseInt(data.coinsSpent) || 0,
        coinsEarned: parseInt(data.coinsEarned) || 0,
        xpEarned: parseInt(data.xpEarned) || 0,
        streakDay: parseInt(data.streakDay) || 0,
        metadata: data.metadata || {},
        
        // Server-generated
        timestamp: timestamp,
        submittedAt: utils.getCurrentTimestamp()
    };
    
    // Calculate metrics
    var metrics = calculateMetrics(result);
    result.metrics = metrics;
    result.perfectScore = metrics.isPerfect;
    
    try {
        // 1. Store the result
        var collection = getResultsCollection(data.gameId);
        var resultKey = result.id;
        utils.writeStorage(nk, logger, collection, resultKey, userId, result);
        utils.logInfo(logger, "Stored quiz result: " + resultKey);
        
        // 2. Update user stats
        var updatedStats = updateUserStats(nk, logger, userId, data.gameId, result, metrics);
        
        // 3. Update leaderboard if score > 0
        if (result.score > 0) {
            try {
                var leaderboardId = "leaderboard_" + data.gameId;
                var leaderboardMetadata = {
                    gameMode: result.gameMode,
                    accuracy: metrics.accuracy,
                    submittedAt: result.submittedAt
                };
                
                nk.leaderboardRecordWrite(
                    leaderboardId,
                    userId,
                    username,
                    result.score,
                    0, // subscore
                    JSON.stringify(leaderboardMetadata),
                    null // operator - use default (best)
                );
                utils.logInfo(logger, "Updated leaderboard: " + leaderboardId);
            } catch (lbErr) {
                utils.logWarning(logger, "Leaderboard update failed (non-critical): " + lbErr.message);
            }
        }
        
        // 4. Store in transaction log for analytics
        var transactionKey = "quiz_result_" + userId + "_" + timestamp;
        utils.writeStorage(nk, logger, "transaction_logs", transactionKey, userId, {
            type: "quiz_result",
            resultId: result.id,
            gameMode: result.gameMode,
            score: result.score,
            won: result.won,
            timestamp: result.submittedAt
        });
        
        // 5. Merge seen question IDs into the qv_seen ledger (if provided)
        // Delegates to globalThis.__qvsSeen (quizverse_seen.js) for OCC-safe,
        // correctly slugified writes. Supports both top-level and nested metadata
        // layouts from the Unity SDK.
        var seenIds = null;
        var seenScopeRaw = null;
        var seenTopicRaw = null;
        if (data.seenQuestionIds && Array.isArray(data.seenQuestionIds) && data.seenQuestionIds.length > 0) {
            seenIds = data.seenQuestionIds;
            seenScopeRaw = data.seenScope;
            seenTopicRaw = data.seenTopic;
        } else if (data.metadata && data.metadata.seenQuestionIds &&
                   Array.isArray(data.metadata.seenQuestionIds) && data.metadata.seenQuestionIds.length > 0) {
            seenIds = data.metadata.seenQuestionIds;
            seenScopeRaw = data.metadata.seenScope;
            seenTopicRaw = data.metadata.seenTopic;
        }
        if (seenIds && seenIds.length > 0) {
            try {
                var seenScope = seenScopeRaw || "global";
                var seenTopic = seenTopicRaw || data.categoryName || "general";
                globalThis.__qvsSeen.merge(nk, userId, seenScope, seenTopic, seenIds);
                utils.logInfo(logger, "Merged " + seenIds.length +
                    " seen IDs into qv_seen/" + globalThis.__qvsSeen.buildKey(seenScope, seenTopic) +
                    " for user " + userId);
            } catch (seenErr) {
                utils.logWarning(logger, "Seen ledger merge failed (non-critical): " + seenErr.message);
            }
        }

        // 6. Append per-question entries to the knowledge-map history document.
        // Non-critical: wrapped internally so failures never block the response.
        appendKnowledgeMapHistory(nk, logger, userId, data, result, metrics);

        utils.logInfo(logger, "Quiz result submitted: User " + userId + ", Mode: " + result.gameMode + ", Score: " + result.score);
        
        return JSON.stringify({
            success: true,
            resultId: result.id,
            metrics: metrics,
            stats: {
                totalGames: updatedStats.totalGames,
                totalWins: updatedStats.totalWins,
                currentStreak: updatedStats.currentStreak,
                highestScore: updatedStats.highestScore
            }
        });
        
    } catch (err) {
        utils.logError(logger, "Failed to submit quiz result: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Failed to submit result: " + err.message
        });
    }
}

/**
 * RPC: quiz_get_history
 * Get quiz history for a user
 * 
 * Payload:
 * {
 *   gameId: "uuid",
 *   gameMode: "QuickPlay" (optional, filter by mode),
 *   limit: 20,
 *   cursor: "..." (for pagination)
 * }
 */
function rpcQuizGetHistory(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC quiz_get_history called");
    
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    var validation = utils.validatePayload(data, ['gameId']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing gameId");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    var collection = getResultsCollection(data.gameId);
    var limit = Math.min(parseInt(data.limit) || 20, 100);
    
    try {
        // List storage objects for this user
        var objects = nk.storageList(userId, collection, limit, data.cursor || "");
        
        var results = [];
        for (var obj of objects.objects || []) {
            var result = JSON.parse(obj.value);
            
            // Filter by gameMode if specified
            if (data.gameMode && result.gameMode !== data.gameMode) {
                continue;
            }
            
            results.push({
                id: result.id,
                gameMode: result.gameMode,
                score: result.score,
                correctAnswers: result.correctAnswers,
                totalQuestions: result.totalQuestions,
                won: result.won,
                metrics: result.metrics,
                categoryName: result.categoryName,
                submittedAt: result.submittedAt
            });
        }
        
        return JSON.stringify({
            success: true,
            results: results,
            cursor: objects.cursor || null,
            count: results.length
        });
        
    } catch (err) {
        utils.logError(logger, "Failed to get quiz history: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Failed to get history: " + err.message
        });
    }
}

/**
 * RPC: quiz_get_stats
 * Get user's aggregate quiz statistics
 */
function rpcQuizGetStats(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC quiz_get_stats called");
    
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    var validation = utils.validatePayload(data, ['gameId']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing gameId");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    var collection = getUserStatsCollection(data.gameId);
    var key = "stats_" + userId;
    
    var stats = utils.readStorage(nk, logger, collection, key, userId);
    
    if (!stats) {
        return JSON.stringify({
            success: true,
            stats: {
                totalGames: 0,
                totalWins: 0,
                winRate: 0,
                totalScore: 0,
                averageScore: 0,
                accuracy: 0,
                highestScore: 0,
                currentStreak: 0,
                longestStreak: 0,
                perfectGames: 0,
                modeStats: {}
            }
        });
    }
    
    // Calculate derived stats
    var winRate = stats.totalGames > 0 
        ? Math.round((stats.totalWins / stats.totalGames) * 100) 
        : 0;
    
    var averageScore = stats.totalGames > 0 
        ? Math.round(stats.totalScore / stats.totalGames) 
        : 0;
    
    var accuracy = stats.totalQuestions > 0 
        ? Math.round((stats.totalCorrect / stats.totalQuestions) * 100) 
        : 0;
    
    return JSON.stringify({
        success: true,
        stats: {
            totalGames: stats.totalGames,
            totalWins: stats.totalWins,
            winRate: winRate,
            totalScore: stats.totalScore,
            averageScore: averageScore,
            accuracy: accuracy,
            highestScore: stats.highestScore,
            currentStreak: stats.currentStreak,
            longestStreak: stats.longestStreak,
            perfectGames: stats.perfectGames,
            totalTimePlayed: stats.totalTimePlayed,
            modeStats: stats.modeStats,
            lastPlayedAt: stats.lastPlayedAt
        }
    });
}

/**
 * RPC: quiz_check_daily_completion
 * Check if user has completed a quiz for a specific game mode today
 * Based on user UUID - queries across all quiz result collections for the user
 * 
 * Payload:
 * {
 *   gameMode: "DailyChallenge" | "DailyPremiumQuiz"
 *   gameId: "uuid" (optional - if provided, only checks that specific game)
 * }
 * 
 * Returns:
 * {
 *   success: true,
 *   completed: boolean,
 *   gameMode: "DailyChallenge",
 *   date: "2025-01-15" (YYYY-MM-DD format)
 * }
 */
function rpcQuizCheckDailyCompletion(ctx, logger, nk, payload) {
    utils.logInfo(logger, "RPC quiz_check_daily_completion called");
    
    // Parse payload
    var parsed = utils.safeJsonParse(payload);
    if (!parsed.success) {
        return utils.handleError(ctx, null, "Invalid JSON payload");
    }
    
    var data = parsed.data;
    
    // Validate required fields (only gameMode is required now)
    var validation = utils.validatePayload(data, ['gameMode']);
    if (!validation.valid) {
        return utils.handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }
    
    // Validate gameMode
    var validModes = ['DailyChallenge', 'DailyPremiumQuiz'];
    if (validModes.indexOf(data.gameMode) === -1) {
        return utils.handleError(ctx, null, "Invalid gameMode. Must be 'DailyChallenge' or 'DailyPremiumQuiz'");
    }
    
    // Validate gameId if provided (optional)
    if (data.gameId && !utils.isValidUUID(data.gameId)) {
        return utils.handleError(ctx, null, "Invalid gameId UUID format");
    }
    
    var userId = ctx.userId;
    if (!userId) {
        return utils.handleError(ctx, null, "User not authenticated");
    }
    
    try {
        // Get today's start timestamp (00:00:00 UTC)
        var todayStart = utils.getStartOfDay();
        var todayEnd = todayStart + 86400; // End of day (24 hours later)
        
        // Get current date string for response (YYYY-MM-DD)
        var today = new Date();
        var dateString = today.getUTCFullYear() + "-" + 
                          String(today.getUTCMonth() + 1).padStart(2, '0') + "-" + 
                          String(today.getUTCDate()).padStart(2, '0');
        
        var completed = false;
        
        // If gameId is provided, only check that specific collection
        if (data.gameId) {
            var collection = getResultsCollection(data.gameId);
            var limit = 100; // Check last 100 results (should be enough for daily check)
            
            var objects = nk.storageList(userId, collection, limit, "");
            
            // Check if any result matches gameMode and was submitted today
            for (var obj of objects.objects || []) {
                var result = JSON.parse(obj.value);
                
                // Check if gameMode matches
                if (result.gameMode !== data.gameMode) {
                    continue;
                }
                
                // Check if submitted today
                // result.timestamp is Unix timestamp in seconds
                if (result.timestamp >= todayStart && result.timestamp < todayEnd) {
                    completed = true;
                    utils.logInfo(logger, `User ${userId} completed ${data.gameMode} today (timestamp: ${result.timestamp})`);
                    break;
                }
            }
        } else {
            // No gameId provided - query transaction_logs which stores all quiz results
            var transactionCollection = "transaction_logs";
            var limit = 1000; // Higher limit to check more results
            var transactionObjects = nk.storageList(userId, transactionCollection, limit, "");
            
            // Check transaction logs for quiz results submitted today
            for (var obj of transactionObjects.objects || []) {
                var transaction = JSON.parse(obj.value);
                
                // Check if this is a quiz result transaction
                if (transaction.type === "quiz_result" && 
                    transaction.gameMode === data.gameMode) {
                    
                    // Parse timestamp from submittedAt (ISO string) or use timestamp if available
                    var transactionTimestamp = null;
                    if (transaction.timestamp) {
                        // If timestamp is a Unix timestamp (seconds)
                        if (typeof transaction.timestamp === 'number') {
                            transactionTimestamp = transaction.timestamp;
                        } else if (typeof transaction.timestamp === 'string') {
                            // If it's an ISO string, convert to Unix timestamp
                            var dateObj = new Date(transaction.timestamp);
                            if (!isNaN(dateObj.getTime())) {
                                transactionTimestamp = Math.floor(dateObj.getTime() / 1000);
                            }
                        }
                    } else if (transaction.submittedAt) {
                        // Fallback to submittedAt if timestamp not available
                        var dateObj = new Date(transaction.submittedAt);
                        if (!isNaN(dateObj.getTime())) {
                            transactionTimestamp = Math.floor(dateObj.getTime() / 1000);
                        }
                    }
                    
                    // Check if submitted today
                    if (transactionTimestamp && transactionTimestamp >= todayStart && transactionTimestamp < todayEnd) {
                        completed = true;
                        utils.logInfo(logger, `User ${userId} completed ${data.gameMode} today (from transaction log, timestamp: ${transactionTimestamp})`);
                        break;
                    }
                }
            }
        }
        
        return JSON.stringify({
            success: true,
            completed: completed,
            gameMode: data.gameMode,
            date: dateString
        });
        
    } catch (err) {
        utils.logError(logger, "Failed to check daily completion: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Failed to check completion: " + err.message,
            completed: false
        });
    }
}

/**
 * RPC: quizverse_get_player_summary
 * Returns the compact, manager-facing player summary (accuracy, quizzes taken,
 * scores, consistency, participation) for the authenticated user.
 *
 * Read order (world-class, never empty for an existing player):
 *   1. qv_player_stats/summary           — the canonical pre-built doc
 *   2. quiz_user_stats_<gameId>/stats_*  — fallback: build on the fly AND
 *                                          lazily backfill the summary doc
 *   3. zeroed summary                    — brand-new player (no quizzes yet)
 *
 * Optional payload: { "gameId": "<uuid>" } (defaults to the QuizVerse game id).
 */
var QV_DEFAULT_GAME_ID = "126bf539-dae2-4bcf-964d-316c0fa1f92b";

function rpcQuizverseGetPlayerSummary(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({ success: false, error: "User not authenticated" });
    }

    var gameId = QV_DEFAULT_GAME_ID;
    if (payload) {
        var parsed = utils.safeJsonParse(payload);
        if (parsed.success && parsed.data && parsed.data.gameId && utils.isValidUUID(parsed.data.gameId)) {
            gameId = parsed.data.gameId;
        }
    }

    try {
        // 1. Canonical pre-built summary.
        var existing = utils.readStorage(nk, logger, "qv_player_stats", "summary", userId);
        if (existing) {
            return JSON.stringify({ success: true, summary: existing, source: "summary" });
        }

        // 2. Fallback: build from aggregate stats + lazily backfill the summary doc.
        var stats = utils.readStorage(nk, logger, getUserStatsCollection(gameId), "stats_" + userId, userId);
        if (stats) {
            var built = buildPlayerSummary(stats);
            try { writePlayerSummary(nk, logger, userId, stats); } catch (e) { /* non-critical */ }
            return JSON.stringify({ success: true, summary: built, source: "backfill" });
        }

        // 3. Brand-new player — return a complete, zeroed summary (never null).
        return JSON.stringify({ success: true, summary: buildPlayerSummary({}), source: "empty" });

    } catch (err) {
        utils.logError(logger, "quizverse_get_player_summary failed: " + err.message);
        return JSON.stringify({ success: false, error: "Failed to load summary: " + err.message });
    }
}

/**
 * RPC: quizverse_backfill_player_summaries  (ADMIN / one-time)
 * Scans every existing `quiz_user_stats_<gameId>/stats_*` doc across ALL users
 * and writes their summary (Storage tab) + account snapshot (Account tab).
 * Use this once after deploy so players who already played show up immediately
 * instead of only after their next quiz.
 *
 * Security: runtime-only. Must be called WITHOUT a user session (Nakama Console
 * API Explorer "Run as the system" / server HTTP key). A logged-in user cannot
 * run it.
 *
 * Optional payload: { "gameId": "<uuid>" } (defaults to the QuizVerse game id).
 * Returns: { success, gameId, processed, errors }.
 */
function rpcQuizverseBackfillPlayerSummaries(ctx, logger, nk, payload) {
    // Admin gate: allow only runtime/system callers.
    //   • HTTP server-key call  → ctx.userId === ""        (empty)
    //   • Console "run as system" → ctx.userId === zero-UUID
    // A real logged-in player is rejected.
    var SYSTEM_USER_ID = "00000000-0000-0000-0000-000000000000";
    if (ctx.userId && ctx.userId !== SYSTEM_USER_ID) {
        return JSON.stringify({ success: false, error: "Admin only — run without a user session (server key) or as the system user." });
    }

    var gameId = QV_DEFAULT_GAME_ID;
    if (payload) {
        var parsed = utils.safeJsonParse(payload);
        if (parsed.success && parsed.data && parsed.data.gameId && utils.isValidUUID(parsed.data.gameId)) {
            gameId = parsed.data.gameId;
        }
    }

    var collection = getUserStatsCollection(gameId);
    var processed = 0;
    var errors = 0;
    var cursor = "";

    try {
        do {
            // userId = null → list this collection across ALL users (admin scan).
            var page = nk.storageList(null, collection, 100, cursor);
            var objects = (page && page.objects) || [];

            for (var i = 0; i < objects.length; i++) {
                var obj = objects[i];
                try {
                    var stats = obj.value;
                    if (typeof stats === "string") {
                        stats = JSON.parse(stats);
                    }
                    writePlayerSummary(nk, logger, obj.userId, stats);
                    processed++;
                } catch (rowErr) {
                    errors++;
                    utils.logWarning(logger, "[Backfill] failed for user " + (obj && obj.userId) + ": " + rowErr.message);
                }
            }

            cursor = (page && page.cursor) || "";
        } while (cursor);

        utils.logInfo(logger, "[Backfill] done — gameId=" + gameId + " processed=" + processed + " errors=" + errors);
        return JSON.stringify({ success: true, gameId: gameId, processed: processed, errors: errors });
    } catch (err) {
        utils.logError(logger, "quizverse_backfill_player_summaries failed: " + err.message);
        return JSON.stringify({ success: false, error: err.message, processed: processed, errors: errors });
    }
}

// ============================================================================
// MODULE INIT (postbuild AST hook)
// ----------------------------------------------------------------------------
// Registers the harmonized `rpcQuizSubmitResult` (with qv_seen ledger merge)
// over the legacy_runtime.js copy. postbuild's collision-rename pass renames
// the legacy declaration to `__legacy_rpcQuizSubmitResult`, so the modules
// version wins at the global scope when the guarded `||` assignments are
// replayed (modules first, legacy fallback second).
// ============================================================================
function __ModuleInit_101(ctx, logger, nk, initializer) {
    __rpc_quiz_submit_result = __rpc_quiz_submit_result || (rpcQuizSubmitResult);
    __rpc_quiz_get_history = __rpc_quiz_get_history || (rpcQuizGetHistory);
    __rpc_quiz_get_stats = __rpc_quiz_get_stats || (rpcQuizGetStats);
    __rpc_quiz_check_daily_completion = __rpc_quiz_check_daily_completion || (rpcQuizCheckDailyCompletion);
    __rpc_quizverse_get_player_summary = __rpc_quizverse_get_player_summary || (rpcQuizverseGetPlayerSummary);
    __rpc_quizverse_backfill_player_summaries = __rpc_quizverse_backfill_player_summaries || (rpcQuizverseBackfillPlayerSummaries);

    // ── Cross-module bridge ───────────────────────────────────────────────────
    // Expose appendKnowledgeMapHistory on globalThis so sibling modules
    // (legacy_runtime.js, async_challenge, etc.) can write knowledge-map history
    // entries without a hard module dependency.
    // Pattern mirrors globalThis.__qvsSeen used by the seen-question ledger.
    // Guarded with `||` so the first module to register wins (identical to the
    // postbuild collision-rename convention used throughout this codebase).
    globalThis.__kmAppendHistory = globalThis.__kmAppendHistory || appendKnowledgeMapHistory;

    logger.info("[QuizResults] Module InitModule registered: 4 RPCs + __kmAppendHistory bridge");
}


// --- Module: quizverse_depth\quizverse_depth.js ---
// quizverse_depth.js - Deep QuizVerse RPCs: Knowledge Maps, Streaks, Adaptive Difficulty, and more
// Nakama V8 JavaScript runtime (No ES Modules)

// ============================================================================
// CONSTANTS
// ============================================================================

// Rolling cap: the knowledge-map RPC only reads the newest N entries so that
// legacy documents written before the cap was enforced don't cause memory spikes.
// Must match KM_HISTORY_MAX_ENTRIES in quiz_results.js.
var QVD_HISTORY_READ_CAP = 2000;

// Slug ↔ UUID lookup — mirrors analytics.js so both modules resolve identically.
var QVD_SLUG_TO_UUID = {
    "quiz-verse": "126bf539-dae2-4bcf-964d-316c0fa1f92b"
};
var QVD_UUID_TO_SLUG = {
    "126bf539-dae2-4bcf-964d-316c0fa1f92b": "quiz-verse"
};

/**
 * Resolve a game_id that may be a UUID OR a slug to its canonical slug.
 * The history collection name is always slug-prefixed ("quiz-verse_quiz_history").
 */
function qvdResolveSlug(gameId) {
    if (!gameId) return "quiz-verse";
    // If it looks like a UUID, map to slug; otherwise assume it is already a slug.
    var fromUuid = QVD_UUID_TO_SLUG[gameId];
    return fromUuid || gameId;
}

// ============================================================================
// UTILITY HELPERS
// ============================================================================

function qvdParsePayload(payload, requiredFields) {
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (e) {
        throw Error("Invalid JSON payload");
    }
    for (var i = 0; i < requiredFields.length; i++) {
        if (data[requiredFields[i]] === undefined || data[requiredFields[i]] === null) {
            throw Error("Missing required field: " + requiredFields[i]);
        }
    }
    return data;
}

function qvdStorageRead(nk, collection, key, userId) {
    var records = nk.storageRead([{ collection: collection, key: key, userId: userId }]);
    if (records && records.length > 0 && records[0].value) {
        return records[0].value;
    }
    return null;
}

function qvdStorageWrite(nk, collection, key, userId, value) {
    nk.storageWrite([{
        collection: collection,
        key: key,
        userId: userId,
        value: value,
        permissionRead: 1,
        permissionWrite: 0
    }]);
}

function qvdTodayKey() {
    var now = new Date();
    var y = now.getUTCFullYear();
    var m = ("0" + (now.getUTCMonth() + 1)).slice(-2);
    var d = ("0" + now.getUTCDate()).slice(-2);
    return y + "-" + m + "-" + d;
}

// ============================================================================
// 1. KNOWLEDGE MAP
// ============================================================================

function rpcQuizverseKnowledgeMap(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id"]);
        var userId = ctx.userId;

        // Resolve UUID or slug → slug so the collection name is always consistent
        // with what quiz_results.js writes ("quiz-verse_quiz_history").
        var gameSlug   = qvdResolveSlug(data.game_id);
        var collection = gameSlug + "_quiz_history";

        logger.info("[KM-RPC] Start. userId=" + userId +
                    " game_id=" + data.game_id +
                    " resolved_slug=" + gameSlug +
                    " collection=" + collection);

        var history = qvdStorageRead(nk, collection, "history", userId);
        if (!history || !Array.isArray(history.entries) || history.entries.length === 0) {
            logger.info("[KM-RPC] No history found for userId=" + userId +
                        " collection=" + collection +
                        " — returning empty map (history=" + (history ? "exists_but_no_entries" : "missing") + ").");
            return JSON.stringify({
                success: true,
                categories: {},
                overall_coverage_pct: 0,
                strongest: null,
                weakest: null,
                total_quizzes: 0
            });
        }

        // Respect the rolling cap: only aggregate the newest QVD_HISTORY_READ_CAP
        // entries so legacy documents with no server-side cap don't spike memory.
        var entries = history.entries;
        var rawCount = entries.length;
        if (entries.length > QVD_HISTORY_READ_CAP) {
            entries = entries.slice(entries.length - QVD_HISTORY_READ_CAP);
        }

        logger.info("[KM-RPC] History found. userId=" + userId +
                    " rawEntries=" + rawCount +
                    " cappedEntries=" + entries.length +
                    " cap=" + QVD_HISTORY_READ_CAP);

        var cats = {};
        var totalQuizzes = entries.length;

        for (var i = 0; i < entries.length; i++) {
            var entry = entries[i];
            if (!entry || typeof entry !== "object") continue;

            // ── Category ─────────────────────────────────────────────────────
            // Accept both "category" (canonical) and legacy "categoryName" /
            // "categoryId" written by older client builds.
            var cat = entry.category || entry.categoryName || entry.categoryId || "general";

            // ── Correct flag ──────────────────────────────────────────────────
            // Accept bool "correct", bool "was_correct", and the synthesized
            // aggregate fallback that quiz_results.js writes.
            var isCorrect;
            if (entry.correct !== undefined) {
                isCorrect = !!entry.correct;
            } else if (entry.was_correct !== undefined) {
                isCorrect = !!entry.was_correct;
            } else {
                isCorrect = false;
            }

            // ── Time ─────────────────────────────────────────────────────────
            // Accept "time_ms" (canonical) and "timeMs" (camelCase alias).
            var timeMs = parseInt(entry.time_ms || entry.timeMs || 0, 10);
            if (isNaN(timeMs) || timeMs < 0) timeMs = 0;

            if (!cats[cat]) {
                cats[cat] = { total_questions: 0, correct: 0, total_time_ms: 0 };
            }
            cats[cat].total_questions += 1;
            if (isCorrect) cats[cat].correct += 1;
            cats[cat].total_time_ms += timeMs;
        }

        // ── Per-category metrics + strength classification ────────────────────
        var strongest = null;
        var weakest   = null;
        var highAcc   = -1;
        var lowAcc    = 101;
        var catKeys   = Object.keys(cats);

        for (var j = 0; j < catKeys.length; j++) {
            var k = catKeys[j];
            var c = cats[k];
            var acc     = c.total_questions > 0
                        ? Math.round((c.correct / c.total_questions) * 100) : 0;
            var avgTime = c.total_questions > 0
                        ? Math.round(c.total_time_ms / c.total_questions) : 0;

            var level = "weak";
            if      (acc >= 90) level = "expert";
            else if (acc >= 70) level = "strong";
            else if (acc >= 40) level = "moderate";

            cats[k] = {
                total_questions: c.total_questions,
                correct:         c.correct,
                accuracy_pct:    acc,
                avg_time_ms:     avgTime,
                strength_level:  level
            };

            if (acc > highAcc) { highAcc = acc; strongest = k; }
            if (acc < lowAcc)  { lowAcc  = acc; weakest   = k; }
        }

        // ── Coverage % ────────────────────────────────────────────────────────
        // Read the authoritative total-category count from a system-level storage
        // key ("quizverse_config / total_categories / system"). Falls back to a
        // conservative estimate (knownCategories × 2, clamped to ≥ 20) so new
        // players see a sensible non-100% figure before the config is set.
        var knownCategories = catKeys.length;
        var totalCategories = knownCategories; // fallback — set below
        try {
            var cfgRecords = nk.storageRead([{
                collection: "quizverse_config",
                key:        "total_categories",
                userId:     "00000000-0000-0000-0000-000000000000"
            }]);
            if (cfgRecords && cfgRecords.length > 0 && cfgRecords[0].value &&
                    typeof cfgRecords[0].value.total_categories === "number" &&
                    cfgRecords[0].value.total_categories > 0) {
                totalCategories = cfgRecords[0].value.total_categories;
            } else {
                // Conservative estimate: assume player has seen at most half the
                // available categories so far. Minimum floor of 20.
                totalCategories = Math.max(knownCategories * 2, 20);
            }
        } catch (cfgErr) {
            totalCategories = Math.max(knownCategories * 2, 20);
        }
        var coveragePct = Math.min(100, Math.round((knownCategories / totalCategories) * 100));

        var catKeys2 = Object.keys(cats);
        logger.info("[KM-RPC] Aggregation done. userId=" + userId +
                    " categories=" + catKeys2.length +
                    " coverage=" + coveragePct + "%" +
                    " totalEntries=" + totalQuizzes +
                    " strongest=" + (strongest || "null") +
                    " weakest="   + (weakest   || "null") +
                    " knownCats=" + knownCategories +
                    " totalCats=" + totalCategories);

        // Log any category that fell through to "general" as it may indicate
        // that quiz modes are not sending category fields in their submissions.
        if (cats["general"]) {
            logger.warn("[KM-RPC] 'general' category has " + cats["general"].total_questions +
                        " entries — quiz submissions may be missing category/categoryName fields.");
        }

        return JSON.stringify({
            success:              true,
            categories:           cats,
            overall_coverage_pct: coveragePct,
            strongest:            strongest,
            weakest:              weakest,
            total_quizzes:        totalQuizzes
        });

    } catch (err) {
        logger.error("[KM-RPC] Error: " + err.message + " stack=" + (err.stack || "N/A"));
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 2. STREAK QUIZ
// ============================================================================

function rpcQuizverseStreakQuiz(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var collection = gameId + "_streak_quizzes";

        var streak = qvdStorageRead(nk, collection, "current", userId) || {
            current_streak: 0,
            best_streak: 0,
            alive: false
        };

        var reward = null;

        if (data.action === "start") {
            streak.current_streak = 0;
            streak.alive = true;

        } else if (data.action === "answer") {
            if (!streak.alive) {
                return JSON.stringify({ success: false, error: "No active streak session" });
            }
            if (data.answer_correct) {
                streak.current_streak += 1;
            } else {
                streak.alive = false;
            }

        } else if (data.action === "end") {
            streak.alive = false;
            if (streak.current_streak > streak.best_streak) {
                streak.best_streak = streak.current_streak;
            }
            var coins = streak.current_streak * 10;
            if (coins > 0) {
                nk.walletUpdate(userId, { coins: coins }, { reason: "streak_reward", streak: streak.current_streak }, true);
                reward = { coins: coins };
            }

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use start, answer, or end" });
        }

        qvdStorageWrite(nk, collection, "current", userId, streak);

        return JSON.stringify({
            success: true,
            current_streak: streak.current_streak,
            best_streak: streak.best_streak,
            alive: streak.alive,
            reward: reward
        });

    } catch (err) {
        logger.error("rpcQuizverseStreakQuiz error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 3. ADAPTIVE DIFFICULTY
// ============================================================================

function rpcQuizverseAdaptiveDifficulty(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "category", "recent_accuracy"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var category = data.category;
        var recentAccuracy = data.recent_accuracy;
        var collection = gameId + "_adaptive_difficulty";

        var record = qvdStorageRead(nk, collection, category, userId) || {
            difficulty: 5,
            history: []
        };

        var currentDiff = record.difficulty;
        var newDiff = currentDiff;

        if (recentAccuracy < 40) {
            newDiff = Math.max(1, currentDiff - 1);
        } else if (recentAccuracy > 70) {
            newDiff = Math.min(10, currentDiff + 1);
        }

        record.difficulty = newDiff;
        record.history.push({ accuracy: recentAccuracy, difficulty: newDiff, timestamp: Date.now() });
        if (record.history.length > 50) {
            record.history = record.history.slice(-50);
        }

        qvdStorageWrite(nk, collection, category, userId, record);

        var playerLevel = "beginner";
        if (newDiff >= 8) {
            playerLevel = "expert";
        } else if (newDiff >= 5) {
            playerLevel = "intermediate";
        }

        return JSON.stringify({
            success: true,
            recommended_difficulty: newDiff,
            category: category,
            player_level: playerLevel
        });

    } catch (err) {
        logger.error("rpcQuizverseAdaptiveDifficulty error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 4. DAILY PUZZLE
// ============================================================================

function rpcQuizverseDailyPuzzle(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var today = qvdTodayKey();
        var collection = gameId + "_daily_puzzles";
        var leaderboardId = gameId + "_daily_puzzle_leaderboard";

        if (data.action === "get") {
            var puzzle = qvdStorageRead(nk, collection, today, userId);
            if (!puzzle) {
                var seed = 0;
                for (var i = 0; i < today.length; i++) {
                    seed += today.charCodeAt(i);
                }
                puzzle = {
                    date: today,
                    seed: seed,
                    puzzle_type: ["word_scramble", "logic", "trivia", "pattern"][seed % 4],
                    difficulty: (seed % 5) + 1,
                    completed: false,
                    created_at: Date.now()
                };
                qvdStorageWrite(nk, collection, today, userId, puzzle);
            }

            return JSON.stringify({
                success: true,
                puzzle: puzzle
            });

        } else if (data.action === "submit") {
            if (!data.solve_time_ms) {
                return JSON.stringify({ success: false, error: "solve_time_ms required for submit" });
            }

            var existing = qvdStorageRead(nk, collection, today, userId);
            if (existing && existing.completed) {
                return JSON.stringify({ success: false, error: "Already submitted today" });
            }

            var solveTime = data.solve_time_ms;
            var score = Math.max(0, 100000 - solveTime);

            try {
                nk.leaderboardRecordWrite(leaderboardId, userId, ctx.username || "", score, 0, { date: today, solve_time_ms: solveTime });
            } catch (lbErr) {
                logger.warn("Leaderboard write failed (may not exist): " + lbErr.message);
            }

            var result = {
                date: today,
                solve_time_ms: solveTime,
                score: score,
                completed: true,
                completed_at: Date.now()
            };
            qvdStorageWrite(nk, collection, today, userId, result);

            return JSON.stringify({
                success: true,
                result: result
            });

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use get or submit" });
        }

    } catch (err) {
        logger.error("rpcQuizverseDailyPuzzle error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 5. CATEGORY WAR
// ============================================================================

function rpcQuizverseCategoryWar(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var collection = gameId + "_category_wars";
        var today = qvdTodayKey();
        var warKey = "war_" + today;

        var war = qvdStorageRead(nk, collection, warKey, "00000000-0000-0000-0000-000000000000");
        if (!war) {
            var seed = 0;
            for (var s = 0; s < today.length; s++) {
                seed += today.charCodeAt(s);
            }
            var allCats = ["science", "history", "geography", "entertainment", "sports", "technology", "art", "literature"];
            var catA = allCats[seed % allCats.length];
            var catB = allCats[(seed + 3) % allCats.length];
            if (catA === catB) { catB = allCats[(seed + 5) % allCats.length]; }

            war = {
                war_id: warKey,
                categories: [catA, catB],
                scores: {},
                players: {},
                created_at: Date.now(),
                expires_at: Date.now() + 86400000
            };
            war.scores[catA] = 0;
            war.scores[catB] = 0;
        }

        if (data.action === "get_status") {
            var mySide = (war.players && war.players[userId]) ? war.players[userId] : null;
            return JSON.stringify({
                success: true,
                war_id: war.war_id,
                categories: war.categories,
                scores: war.scores,
                your_side: mySide,
                time_remaining: Math.max(0, war.expires_at - Date.now())
            });

        } else if (data.action === "join") {
            if (!data.category_choice) {
                return JSON.stringify({ success: false, error: "category_choice required" });
            }
            if (war.categories.indexOf(data.category_choice) === -1) {
                return JSON.stringify({ success: false, error: "Invalid category. Choose one of: " + war.categories.join(", ") });
            }
            if (!war.players) { war.players = {}; }
            war.players[userId] = data.category_choice;

            qvdStorageWrite(nk, collection, warKey, "00000000-0000-0000-0000-000000000000", war);

            return JSON.stringify({
                success: true,
                war_id: war.war_id,
                categories: war.categories,
                scores: war.scores,
                your_side: data.category_choice,
                time_remaining: Math.max(0, war.expires_at - Date.now())
            });

        } else if (data.action === "submit_score") {
            if (!data.score) {
                return JSON.stringify({ success: false, error: "score required" });
            }
            var playerSide = war.players ? war.players[userId] : null;
            if (!playerSide) {
                return JSON.stringify({ success: false, error: "Must join a side first" });
            }
            war.scores[playerSide] = (war.scores[playerSide] || 0) + data.score;

            qvdStorageWrite(nk, collection, warKey, "00000000-0000-0000-0000-000000000000", war);

            return JSON.stringify({
                success: true,
                war_id: war.war_id,
                categories: war.categories,
                scores: war.scores,
                your_side: playerSide,
                time_remaining: Math.max(0, war.expires_at - Date.now())
            });

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use get_status, join, or submit_score" });
        }

    } catch (err) {
        logger.error("rpcQuizverseCategoryWar error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 6. KNOWLEDGE DUEL
// ============================================================================

function rpcQuizverseKnowledgeDuel(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var collection = gameId + "_knowledge_duels";

        if (data.action === "create") {
            if (!data.opponent_id) {
                return JSON.stringify({ success: false, error: "opponent_id required" });
            }
            var duelId = gameId + "_duel_" + userId.substring(0, 8) + "_" + Date.now();
            var duel = {
                duel_id: duelId,
                creator: userId,
                opponent: data.opponent_id,
                status: "pending",
                scores: {},
                created_at: Date.now(),
                expires_at: Date.now() + 3600000
            };
            duel.scores[userId] = null;
            duel.scores[data.opponent_id] = null;

            qvdStorageWrite(nk, collection, duelId, userId, duel);

            try {
                // Signature: (userId, subject, content, code, senderId?, persistent?)
                // Code 7401 is outside friend lifecycle 1–6 / 100–105.
                nk.notificationSend(
                    data.opponent_id,
                    "Knowledge Duel Challenge",
                    {
                        type: "duel_challenge",
                        eventType: "duel_challenge",
                        duel_id: duelId,
                        challenger: userId,
                        challenger_name: ctx.username || "Unknown"
                    },
                    7401,
                    userId,
                    true
                );
            } catch (notifErr) {
                logger.warn("Could not send duel notification: " + notifErr.message);
            }

            return JSON.stringify({
                success: true,
                duel_id: duelId,
                status: "pending",
                your_score: null,
                opponent_score: null,
                winner: null
            });

        } else if (data.action === "join") {
            if (!data.duel_id) {
                return JSON.stringify({ success: false, error: "duel_id required" });
            }
            var records = nk.storageRead([{ collection: collection, key: data.duel_id, userId: "*" }]);
            var joinDuel = null;
            if (records && records.length > 0) {
                joinDuel = records[0].value;
            }
            if (!joinDuel) {
                return JSON.stringify({ success: false, error: "Duel not found" });
            }
            if (joinDuel.opponent !== userId) {
                return JSON.stringify({ success: false, error: "You are not the invited opponent" });
            }
            joinDuel.status = "active";
            qvdStorageWrite(nk, collection, data.duel_id, joinDuel.creator, joinDuel);

            return JSON.stringify({
                success: true,
                duel_id: joinDuel.duel_id,
                status: "active",
                your_score: null,
                opponent_score: null,
                winner: null
            });

        } else if (data.action === "submit") {
            if (!data.duel_id || data.score === undefined) {
                return JSON.stringify({ success: false, error: "duel_id and score required" });
            }
            var subRecords = nk.storageRead([{ collection: collection, key: data.duel_id, userId: "*" }]);
            var subDuel = null;
            var storageOwner = null;
            if (subRecords && subRecords.length > 0) {
                subDuel = subRecords[0].value;
                storageOwner = subRecords[0].userId;
            }
            if (!subDuel) {
                return JSON.stringify({ success: false, error: "Duel not found" });
            }
            subDuel.scores[userId] = data.score;

            var winner = null;
            if (subDuel.scores[subDuel.creator] !== null && subDuel.scores[subDuel.opponent] !== null) {
                subDuel.status = "completed";
                if (subDuel.scores[subDuel.creator] > subDuel.scores[subDuel.opponent]) {
                    winner = subDuel.creator;
                } else if (subDuel.scores[subDuel.opponent] > subDuel.scores[subDuel.creator]) {
                    winner = subDuel.opponent;
                } else {
                    winner = "draw";
                }
                subDuel.winner = winner;

                var loserId = winner === subDuel.creator ? subDuel.opponent : subDuel.creator;
                if (winner !== "draw") {
                    nk.walletUpdate(winner, { coins: 50 }, { reason: "duel_win", duel_id: subDuel.duel_id }, true);
                    try {
                        // Signature: (userId, subject, content, code, senderId?, persistent?)
                        // Code 7402 is outside friend lifecycle 1–6 / 100–105.
                        nk.notificationSend(loserId, "Duel Result", {
                            type: "duel_result",
                            eventType: "duel_result",
                            duel_id: subDuel.duel_id,
                            result: "lost"
                        }, 7402, winner, true);
                        nk.notificationSend(winner, "Duel Result", {
                            type: "duel_result",
                            eventType: "duel_result",
                            duel_id: subDuel.duel_id,
                            result: "won"
                        }, 7402, loserId, true);
                    } catch (nErr) {
                        logger.warn("Duel result notification failed: " + nErr.message);
                    }
                }
            }

            qvdStorageWrite(nk, collection, data.duel_id, storageOwner || subDuel.creator, subDuel);

            var myScore = subDuel.scores[userId];
            var oppId = userId === subDuel.creator ? subDuel.opponent : subDuel.creator;
            var oppScore = subDuel.scores[oppId];

            return JSON.stringify({
                success: true,
                duel_id: subDuel.duel_id,
                status: subDuel.status,
                your_score: myScore,
                opponent_score: oppScore,
                winner: winner
            });

        } else if (data.action === "result") {
            if (!data.duel_id) {
                return JSON.stringify({ success: false, error: "duel_id required" });
            }
            var resRecords = nk.storageRead([{ collection: collection, key: data.duel_id, userId: "*" }]);
            var resDuel = null;
            if (resRecords && resRecords.length > 0) {
                resDuel = resRecords[0].value;
            }
            if (!resDuel) {
                return JSON.stringify({ success: false, error: "Duel not found" });
            }
            var resOppId = userId === resDuel.creator ? resDuel.opponent : resDuel.creator;

            return JSON.stringify({
                success: true,
                duel_id: resDuel.duel_id,
                status: resDuel.status,
                your_score: resDuel.scores[userId],
                opponent_score: resDuel.scores[resOppId],
                winner: resDuel.winner || null
            });

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use create, join, submit, or result" });
        }

    } catch (err) {
        logger.error("rpcQuizverseKnowledgeDuel error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 7. STUDY MODE
// ============================================================================

function rpcQuizverseStudyMode(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var collection = gameId + "_study_progress";

        var progress = qvdStorageRead(nk, collection, "progress", userId) || {
            wrong_answers: [],
            attempts: {},
            started_at: Date.now()
        };

        if (data.action === "get_weak_areas") {
            var weakMap = {};
            for (var i = 0; i < progress.wrong_answers.length; i++) {
                var wa = progress.wrong_answers[i];
                var cat = wa.category || "general";
                if (!weakMap[cat]) {
                    weakMap[cat] = { wrong_count: 0, questions: [] };
                }
                weakMap[cat].wrong_count += 1;
                weakMap[cat].questions.push(wa.question_id);
            }

            var weakAreas = [];
            var wKeys = Object.keys(weakMap);
            for (var w = 0; w < wKeys.length; w++) {
                weakAreas.push({
                    category: wKeys[w],
                    wrong_count: weakMap[wKeys[w]].wrong_count,
                    question_ids: weakMap[wKeys[w]].questions
                });
            }
            weakAreas.sort(function(a, b) { return b.wrong_count - a.wrong_count; });

            return JSON.stringify({
                success: true,
                weak_areas: weakAreas,
                total_wrong: progress.wrong_answers.length
            });

        } else if (data.action === "record_attempt") {
            if (!data.question_id) {
                return JSON.stringify({ success: false, error: "question_id required" });
            }
            var qid = data.question_id;
            if (!progress.attempts[qid]) {
                progress.attempts[qid] = { total: 0, correct: 0 };
            }
            progress.attempts[qid].total += 1;

            if (data.was_correct) {
                progress.attempts[qid].correct += 1;
                progress.wrong_answers = progress.wrong_answers.filter(function(item) {
                    return item.question_id !== qid;
                });
            } else {
                var alreadyTracked = false;
                for (var a = 0; a < progress.wrong_answers.length; a++) {
                    if (progress.wrong_answers[a].question_id === qid) {
                        alreadyTracked = true;
                        break;
                    }
                }
                if (!alreadyTracked) {
                    progress.wrong_answers.push({
                        question_id: qid,
                        category: data.category || "general",
                        added_at: Date.now()
                    });
                }
            }

            qvdStorageWrite(nk, collection, "progress", userId, progress);

            return JSON.stringify({
                success: true,
                question_id: qid,
                attempts: progress.attempts[qid],
                remaining_weak: progress.wrong_answers.length
            });

        } else if (data.action === "get_improvement") {
            var totalAttempts = 0;
            var totalCorrect = 0;
            var attemptKeys = Object.keys(progress.attempts);
            for (var t = 0; t < attemptKeys.length; t++) {
                var att = progress.attempts[attemptKeys[t]];
                totalAttempts += att.total;
                totalCorrect += att.correct;
            }
            var improvementPct = totalAttempts > 0 ? Math.round((totalCorrect / totalAttempts) * 100) : 0;

            return JSON.stringify({
                success: true,
                total_questions_studied: attemptKeys.length,
                total_attempts: totalAttempts,
                total_correct: totalCorrect,
                accuracy_pct: improvementPct,
                remaining_weak: progress.wrong_answers.length,
                study_duration_ms: Date.now() - (progress.started_at || Date.now())
            });

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use get_weak_areas, record_attempt, or get_improvement" });
        }

    } catch (err) {
        logger.error("rpcQuizverseStudyMode error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

// ============================================================================
// 8. TRIVIA NIGHT
// ============================================================================

function rpcQuizverseTriviaNight(ctx, logger, nk, payload) {
    try {
        var data = qvdParsePayload(payload, ["game_id", "action"]);
        var userId = ctx.userId;
        var gameId = data.game_id;
        var collection = gameId + "_trivia_nights";
        var systemUser = "00000000-0000-0000-0000-000000000000";

        if (data.action === "schedule") {
            var eventId = gameId + "_trivia_" + Date.now();
            var scheduledAt = data.scheduled_at || (Date.now() + 3600000);
            var eventData = {
                event_id: eventId,
                title: data.title || "Trivia Night",
                scheduled_at: scheduledAt,
                status: "upcoming",
                registered_players: [],
                scores: {},
                category: data.category || "mixed",
                created_by: userId,
                created_at: Date.now()
            };

            qvdStorageWrite(nk, collection, eventId, systemUser, eventData);

            return JSON.stringify({
                success: true,
                event_id: eventId,
                scheduled_at: scheduledAt,
                status: "upcoming"
            });

        } else if (data.action === "get_upcoming") {
            var upcoming = qvdStorageRead(nk, collection, "upcoming_index", systemUser) || { events: [] };
            var now = Date.now();
            var active = [];
            for (var i = 0; i < upcoming.events.length; i++) {
                if (upcoming.events[i].scheduled_at > now || upcoming.events[i].status === "active") {
                    active.push(upcoming.events[i]);
                }
            }

            return JSON.stringify({
                success: true,
                events: active
            });

        } else if (data.action === "register") {
            if (!data.event_id) {
                return JSON.stringify({ success: false, error: "event_id required" });
            }
            var regEvent = qvdStorageRead(nk, collection, data.event_id, systemUser);
            if (!regEvent) {
                return JSON.stringify({ success: false, error: "Event not found" });
            }
            if (!regEvent.registered_players) {
                regEvent.registered_players = [];
            }
            var alreadyRegistered = false;
            for (var r = 0; r < regEvent.registered_players.length; r++) {
                if (regEvent.registered_players[r] === userId) {
                    alreadyRegistered = true;
                    break;
                }
            }
            if (!alreadyRegistered) {
                regEvent.registered_players.push(userId);
                qvdStorageWrite(nk, collection, data.event_id, systemUser, regEvent);
            }

            return JSON.stringify({
                success: true,
                event_id: data.event_id,
                registered: true,
                total_registered: regEvent.registered_players.length
            });

        } else if (data.action === "submit_score") {
            if (!data.event_id || data.score === undefined) {
                return JSON.stringify({ success: false, error: "event_id and score required" });
            }
            var scoreEvent = qvdStorageRead(nk, collection, data.event_id, systemUser);
            if (!scoreEvent) {
                return JSON.stringify({ success: false, error: "Event not found" });
            }
            if (!scoreEvent.scores) { scoreEvent.scores = {}; }
            scoreEvent.scores[userId] = data.score;

            qvdStorageWrite(nk, collection, data.event_id, systemUser, scoreEvent);

            var leaderboardId = gameId + "_trivia_" + data.event_id;
            try {
                nk.leaderboardRecordWrite(leaderboardId, userId, ctx.username || "", data.score, 0, { event_id: data.event_id });
            } catch (lbErr) {
                logger.warn("Trivia leaderboard write failed: " + lbErr.message);
            }

            return JSON.stringify({
                success: true,
                event_id: data.event_id,
                your_score: data.score,
                total_participants: Object.keys(scoreEvent.scores).length
            });

        } else {
            return JSON.stringify({ success: false, error: "Invalid action. Use schedule, get_upcoming, register, or submit_score" });
        }

    } catch (err) {
        logger.error("rpcQuizverseTriviaNight error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

