/**
 * Call AI API to generate personalized content
 */
function callAIService(nk, logger, endpoint, payload) {
    try {
        var response = nk.httpRequest(AI_API_BASE_URL + endpoint, "POST", {
            "Content-Type": "application/json",
            "Authorization": "Bearer " + AI_API_TOKEN
        }, JSON.stringify(payload));
        
        if (response.code === 200) {
            return JSON.parse(response.body);
        } else {
            logger.warn("[Winback] AI API call failed with code: " + response.code);
            return null;
        }
    } catch (err) {
        logger.warn("[Winback] AI API call error: " + err.message);
        return null;
    }
}

/**
 * Generate personalized welcome message using AI
 */
function generatePersonalizedWelcome(nk, logger, userId, daysAway, tier, language) {
    language = language || "en";
    
    var prompt = {
        prompt: "Generate a warm, personalized welcome back message for a trivia game user who has been away for " + 
                daysAway + " days. The message should be encouraging and mention the rewards they'll receive. " +
                "Tier: " + tier.name + ". Rewards include: " + JSON.stringify(tier.rewards) + 
                ". Make it friendly and exciting, around 2-3 sentences.",
        language: language,
        return_format: "Return only the welcome message text, no JSON formatting.",
        model: "gpt-4o-mini"
    };
    
    var result = callAIService(nk, logger, "/quiz/daily/motivational-message?langCode=" + language, {
        langCode: language
    });
    
    if (result && result.message) {
        return result.message;
    }
    
    // Fallback to tier's default message
    return tier.message;
}

/**
 * Get user's last session data
 */
function getLastSessionData(nk, logger, userId, gameId) {
    var collection = "user_sessions";
    var key = "last_session_" + userId + "_" + gameId;
    
    try {
        var records = nk.storageRead([{
            collection: collection,
            key: key,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            return records[0].value;
        }
    } catch (err) {
        logger.warn("[Winback] Failed to read session data: " + err.message);
    }
    
    return null;
}

/**
 * Save last session data
 */
function saveLastSessionData(nk, logger, userId, gameId, data) {
    var collection = "user_sessions";
    var key = "last_session_" + userId + "_" + gameId;
    
    try {
        nk.storageWrite([{
            collection: collection,
            key: key,
            userId: userId,
            value: data,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return true;
    } catch (err) {
        logger.error("[Winback] Failed to save session data: " + err.message);
        return false;
    }
}

/**
 * Get win-back data for user
 */
function getWinbackData(nk, logger, userId, gameId) {
    var collection = "winback";
    var key = "data_" + userId + "_" + gameId;
    
    try {
        var records = nk.storageRead([{
            collection: collection,
            key: key,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            return records[0].value;
        }
    } catch (err) {
        logger.warn("[Winback] Failed to read data: " + err.message);
    }
    
    return null;
}

/**
 * Save win-back data
 */
function saveWinbackData(nk, logger, userId, gameId, data) {
    var collection = "winback";
    var key = "data_" + userId + "_" + gameId;
    
    try {
        nk.storageWrite([{
            collection: collection,
            key: key,
            userId: userId,
            value: data,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return true;
    } catch (err) {
        logger.error("[Winback] Failed to save data: " + err.message);
        return false;
    }
}

/**
 * Calculate days since last session
 */
function getDaysSinceLastSession(lastSessionTimestamp) {
    if (!lastSessionTimestamp) return 0;
    
    var lastDate = new Date(lastSessionTimestamp);
    var now = new Date();
    var diffMs = now - lastDate;
    var diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    
    return diffDays;
}

/**
 * Get applicable comeback tier
 */
function getApplicableTier(daysAway) {
    for (var i = COMEBACK_TIERS.length - 1; i >= 0; i--) {
        var tier = COMEBACK_TIERS[i];
        if (daysAway >= tier.minDays && daysAway <= tier.maxDays) {
            return tier;
        }
    }
    return null;
}

/**
 * Get new features since date
 */
function getNewFeaturesSince(lastPlayDate) {
    var newFeatures = [];
    var lastDate = new Date(lastPlayDate);
    
    for (var i = 0; i < FEATURE_ANNOUNCEMENTS.length; i++) {
        var feature = FEATURE_ANNOUNCEMENTS[i];
        var featureDate = new Date(feature.addedDate);
        
        if (featureDate > lastDate) {
            newFeatures.push(feature);
        }
    }
    
    return newFeatures;
}

/**
 * RPC: winback_check_status
 * Check if user qualifies for comeback rewards
 */
function rpcWinbackCheckStatus(ctx, logger, nk, payload) {
    logger.info("[Winback] RPC winback_check_status called");
    
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "User not authenticated" });
    }
    
    var data;
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({ success: false, error: "Invalid JSON payload" });
    }
    
    var gameId = data.gameId;
    if (!gameId) {
        return JSON.stringify({ success: false, error: "Missing required field: gameId" });
    }
    
    // Get last session
    var sessionData = getLastSessionData(nk, logger, ctx.userId, gameId);
    
    if (!sessionData || !sessionData.lastSessionTime) {
        // First time user - no win-back needed
        return JSON.stringify({
            success: true,
            isReturningUser: false,
            daysAway: 0,
            hasRewards: false,
            timestamp: new Date().toISOString()
        });
    }
    
    var daysAway = getDaysSinceLastSession(sessionData.lastSessionTime);
    
    // Check if already claimed this comeback
    var winbackData = getWinbackData(nk, logger, ctx.userId, gameId);
    
    // Get applicable tier
    var tier = getApplicableTier(daysAway);
    
    if (!tier) {
        // Not away long enough for rewards
        return JSON.stringify({
            success: true,
            isReturningUser: daysAway > 0,
            daysAway: daysAway,
            hasRewards: false,
            message: daysAway > 0 ? "Welcome back!" : null,
            timestamp: new Date().toISOString()
        });
    }
    
    // Check if this tier was already claimed
    var alreadyClaimed = winbackData && winbackData.lastClaimedTier === tier.tier && 
                         getDaysSinceLastSession(winbackData.lastClaimTime) < 7;
    
    // Get new features
    var newFeatures = getNewFeaturesSince(sessionData.lastSessionTime);
    
    // Generate personalized welcome message using AI
    var language = data.language || "en";
    var personalizedMessage = tier.message; // Default
    
    if (!alreadyClaimed) {
        try {
            personalizedMessage = generatePersonalizedWelcome(nk, logger, ctx.userId, daysAway, tier, language);
        } catch (err) {
            logger.warn("[Winback] Failed to generate personalized message: " + err.message);
        }
    }
    
    return JSON.stringify({
        success: true,
        isReturningUser: true,
        daysAway: daysAway,
        hasRewards: !alreadyClaimed,
        tier: tier,
        personalizedMessage: personalizedMessage,
        alreadyClaimed: alreadyClaimed,
        newFeatures: newFeatures,
        timestamp: new Date().toISOString()
    });
}

/**
 * RPC: winback_claim_rewards
 * Claim comeback rewards
 */
function rpcWinbackClaimRewards(ctx, logger, nk, payload) {
    logger.info("[Winback] RPC winback_claim_rewards called");
    
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "User not authenticated" });
    }
    
    var data;
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({ success: false, error: "Invalid JSON payload" });
    }
    
    var gameId = data.gameId;
    if (!gameId) {
        return JSON.stringify({ success: false, error: "Missing required field: gameId" });
    }
    
    // Get last session
    var sessionData = getLastSessionData(nk, logger, ctx.userId, gameId);
    
    if (!sessionData || !sessionData.lastSessionTime) {
        return JSON.stringify({ success: false, error: "No previous session found" });
    }
    
    var daysAway = getDaysSinceLastSession(sessionData.lastSessionTime);
    var tier = getApplicableTier(daysAway);
    
    if (!tier) {
        return JSON.stringify({ success: false, error: "Not eligible for comeback rewards" });
    }
    
    // Check if already claimed
    var winbackData = getWinbackData(nk, logger, ctx.userId, gameId);
    
    if (winbackData && winbackData.lastClaimedTier === tier.tier &&
        getDaysSinceLastSession(winbackData.lastClaimTime) < 7) {
        return JSON.stringify({ success: false, error: "Rewards already claimed" });
    }
    
    // Mark as claimed
    var newWinbackData = {
        lastClaimedTier: tier.tier,
        lastClaimTime: new Date().toISOString(),
        daysAwayWhenClaimed: daysAway,
        claimHistory: winbackData && winbackData.claimHistory ? winbackData.claimHistory : []
    };
    
    newWinbackData.claimHistory.push({
        tier: tier.tier,
        daysAway: daysAway,
        claimedAt: new Date().toISOString(),
        rewards: tier.rewards
    });
    
    saveWinbackData(nk, logger, ctx.userId, gameId, newWinbackData);
    
    // Log transaction
    try {
        var transactionKey = "winback_reward_" + ctx.userId + "_" + Date.now();
        nk.storageWrite([{
            collection: "transaction_logs",
            key: transactionKey,
            userId: ctx.userId,
            value: {
                type: "winback_reward",
                tier: tier.tier,
                daysAway: daysAway,
                rewards: tier.rewards,
                timestamp: new Date().toISOString()
            },
            permissionRead: 1,
            permissionWrite: 0
        }]);
    } catch (err) {
        logger.warn("[Winback] Failed to log transaction: " + err.message);
    }
    
    // Grant rewards to wallet
    var walletChanges = {};
    if (tier.rewards.coins) walletChanges.coins = tier.rewards.coins;
    if (tier.rewards.gems) walletChanges.gems = tier.rewards.gems;
    if (Object.keys(walletChanges).length > 0) {
        try {
            nk.walletUpdate(ctx.userId, walletChanges, { source: "winback", tier: tier.tier, daysAway: daysAway }, true);
            logger.info("[Winback] Granted wallet: " + JSON.stringify(walletChanges) + " to " + ctx.userId);
        } catch (walletErr) {
            logger.error("[Winback] Wallet grant failed: " + walletErr.message);
        }
    }
    
    logger.info("[Winback] Rewards claimed by user " + ctx.userId + ", tier: " + tier.tier + ", days away: " + daysAway);
    
    return JSON.stringify({
        success: true,
        tier: tier.tier,
        tierName: tier.name,
        message: tier.message,
        rewards: tier.rewards,
        walletGranted: walletChanges,
        daysAway: daysAway,
        timestamp: new Date().toISOString()
    });
}

/**
 * RPC: winback_record_session
 * Record user's current session (call on app open)
 */
function rpcWinbackRecordSession(ctx, logger, nk, payload) {
    logger.info("[Winback] RPC winback_record_session called");
    
    if (!ctx.userId) {
        return JSON.stringify({ success: false, error: "User not authenticated" });
    }
    
    var data;
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({ success: false, error: "Invalid JSON payload" });
    }
    
    var gameId = data.gameId;
    if (!gameId) {
        return JSON.stringify({ success: false, error: "Missing required field: gameId" });
    }
    
    // Get existing session data
    var sessionData = getLastSessionData(nk, logger, ctx.userId, gameId);
    
    var previousSession = sessionData ? sessionData.lastSessionTime : null;
    var sessionCount = sessionData ? (sessionData.totalSessions || 0) + 1 : 1;
    
    // Update session data
    var newSessionData = {
        lastSessionTime: new Date().toISOString(),
        previousSessionTime: previousSession,
        totalSessions: sessionCount,
        firstSessionTime: sessionData ? sessionData.firstSessionTime : new Date().toISOString()
    };
    
    saveLastSessionData(nk, logger, ctx.userId, gameId, newSessionData);
    
    return JSON.stringify({
        success: true,
        sessionCount: sessionCount,
        daysSinceLastSession: previousSession ? getDaysSinceLastSession(previousSession) : 0,
        timestamp: new Date().toISOString()
    });
}

/**
 * RPC: winback_schedule_reengagement
 * Schedule re-engagement push notifications for at-risk users
 * (Called by server-side scheduled task)
 */
function rpcWinbackScheduleReengagement(ctx, logger, nk, payload) {
    logger.info("[Winback] RPC winback_schedule_reengagement called");
    
    // This would typically be called by a server-side scheduled task
    // to identify users who haven't played in X days and send them
    // push notifications
    
    var data;
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({ success: false, error: "Invalid JSON payload" });
    }
    
    var gameId = data.gameId;
    var targetDaysAway = data.targetDaysAway || 3; // Default: users 3+ days away
    
    // In production, this would query users with lastSessionTime older than targetDaysAway
    // and send them personalized push notifications
    
    return JSON.stringify({
        success: true,
        message: "Re-engagement notifications scheduled",
        targetDaysAway: targetDaysAway,
        timestamp: new Date().toISOString()
    });
}


// --- Module: rewarded_ads\rewarded_ads.js ---
// rewarded_ads.js - Server-validated Rewarded Ad System
// Enforces user-triggered rewarded ads via token-based validation
// Prevents auto-shown rewards, duplicate claims, and replay attacks
//
// PLAN-ADS-OPTIMIZATION-v2 §3/§4/§6:
//   - Tier-aware daily caps (T1=conservative, T2=balanced, T3=volume)
//   - 8 new placements (wager_boost_50, daily_bonus_2x, lucky_wheel_free_spin,
//     double_xp_levelup, leaderboard_rank_boost, topic_complete_preview,
//     friend_quest_progress, home_idle_powerup)
//   - Server-side cap enforcement in rewarded_ad_request_token

/**
 * REWARDED AD CLAIM FLOW:
 * 1. Client calls `rewarded_ad_request_token` BEFORE showing ad (user clicks button)
 * 2. Server generates a unique token with timestamp and placement info
 * 3. Client shows the ad to user
 * 4. After ad completes successfully, client calls `rewarded_ad_claim` with token
 * 5. Server validates token, ensures it's not expired/reused, grants wallet reward
 * 6. Server marks token as consumed to prevent replay attacks
 */

// Token configuration
var TOKEN_EXPIRY_SECONDS = 300; // 5 minutes - tokens expire if not claimed
var TOKEN_COLLECTION = "rewarded_ad_tokens";
var CLAIMS_COLLECTION = "rewarded_ad_claims";
var GEO_COLLECTION = "geo_tier";
var GEO_CACHE_KEY = "resolved";

// Reward configuration per placement
var REWARD_CONFIG = {
    "double_score": {
        rewardType: "score_multiplier",
        multiplier: 2,
        cooldownSeconds: 0, // No cooldown - once per session
        maxClaimsPerDay: 10
    },
    "extra_time": {
        rewardType: "currency",
        currency: "time_bonus",
        amount: 30, // 30 seconds
        cooldownSeconds: 60, // 1 minute between claims
        maxClaimsPerDay: 20
    },
    "free_hint": {
        rewardType: "currency",
        currency: "hints",
        amount: 1,
        cooldownSeconds: 30,
        maxClaimsPerDay: 30
    },
    "bonus_coins": {
        rewardType: "currency",
        currency: "coins",
        amount: 100,
        cooldownSeconds: 120,
        maxClaimsPerDay: 15
    },
    "default": {
        rewardType: "currency",
        currency: "coins",
        amount: 50,
        cooldownSeconds: 60,
        maxClaimsPerDay: 50
    },
    // ── NEW placements (PLAN-ADS-OPTIMIZATION-v2 §4) ──────────────────
    "wager_boost_50": {
        rewardType: "currency",
        currency: "coins",
        amount: 50,
        cooldownSeconds: 60,
        maxClaimsPerDay: 5,
        tierGate: ["t2", "t3"]  // T1 disabled — premium feel
    },
    "daily_bonus_2x": {
        rewardType: "score_multiplier",
        multiplier: 2,
        cooldownSeconds: 0,
        maxClaimsPerDay: 1,
        tierGate: null  // all tiers
    },
    "lucky_wheel_free_spin": {
        rewardType: "action",
        action: "fortune_wheel_spin",
        cooldownSeconds: 3600,  // 1 hour
        maxClaimsPerDay: 3,
        tierGate: ["t2", "t3"]  // T1 disabled — premium feel
    },
    "double_xp_levelup": {
        rewardType: "score_multiplier",
        multiplier: 2,
        cooldownSeconds: 0,
        maxClaimsPerDay: 5,
        tierGate: null  // all tiers — low intrusion
    },
    "leaderboard_rank_boost": {
        rewardType: "currency",
        currency: "coins",
        amount: 75,
        cooldownSeconds: 0,
        maxClaimsPerDay: 3,
        tierGate: ["t2", "t3"]  // T1 disabled
    },
    "topic_complete_preview": {
        rewardType: "action",
        action: "unlock_topic_preview",
        cooldownSeconds: 0,
        maxClaimsPerDay: 5,
        tierGate: ["t3"]  // T3 only — strong engagement signal
    },
    "friend_quest_progress": {
        rewardType: "action",
        action: "add_quest_progress",
        cooldownSeconds: 0,
        maxClaimsPerDay: 3,
        tierGate: ["t3"]  // T3 only
    },
    "home_idle_powerup": {
        rewardType: "currency",
        currency: "powerups",
        amount: 1,
        cooldownSeconds: 3600,  // 1 hour
        maxClaimsPerDay: 5,
        tierGate: ["t2", "t3"]  // T1 disabled — too intrusive
    }
};

// ── Tier cap scaling factors (PLAN-ADS-OPTIMIZATION-v2 §3) ──────────
// T1 users see fewer rewarded opportunities (push IAP instead).
// T3 users see more (maximize ad volume where IAP ARPU is low).
var TIER_CAP_FACTORS = {
    "t1": 0.5,
    "t2": 1.0,
    "t3": 2.0
};

/**
 * Read user's geo tier from GeoTier cache (written by geo-tier.ts).
 * Returns "t1", "t2", or "t3". Defaults to "t3" if no cache (safe for ad volume).
 */
function getUserTier(nk, logger, userId) {
    try {
        var records = nk.storageRead([{
            collection: GEO_COLLECTION,
            key: GEO_CACHE_KEY,
            userId: userId
        }]);
        if (records && records.length > 0 && records[0].value && records[0].value.tier) {
            var tier = records[0].value.tier.toLowerCase();
            if (tier === "t1" || tier === "t2" || tier === "t3") {
                return tier;
            }
        }
    } catch (err) {
        if (logger) logger.warn("[RewardedAds] Failed to read user tier: " + err.message);
    }
    return "t3"; // Default — maximize ad volume for unknown geos
}

/**
 * Get tier-aware config for a placement.
 * Scales maxClaimsPerDay by the tier factor and enforces tierGate.
 * Returns null if the placement is gated for this tier.
 */
function getTierAwareConfig(nk, logger, userId, placement) {
    var config = REWARD_CONFIG[placement] || REWARD_CONFIG["default"];
    var tier = getUserTier(nk, logger, userId);

    // Check tier gate — if placement is restricted to certain tiers
    if (config.tierGate && config.tierGate.length > 0) {
        var allowed = false;
        for (var i = 0; i < config.tierGate.length; i++) {
            if (config.tierGate[i] === tier) {
                allowed = true;
                break;
            }
        }
        if (!allowed) {
            return null; // This placement is not available for this tier
        }
    }

    // Scale maxClaimsPerDay by tier factor
    var factor = TIER_CAP_FACTORS[tier] || 1.0;
    var scaledMax = Math.max(1, Math.round(config.maxClaimsPerDay * factor));

    // Return a copy with scaled cap
    return {
        rewardType: config.rewardType,
        multiplier: config.multiplier,
        currency: config.currency,
        amount: config.amount,
        action: config.action,
        cooldownSeconds: config.cooldownSeconds,
        maxClaimsPerDay: scaledMax,
        tier: tier,
        originalMaxClaimsPerDay: config.maxClaimsPerDay
    };
}

/**
 * Generate a cryptographically secure token
 */
function generateToken() {
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    var token = "";
    for (var i = 0; i < 32; i++) {
        token += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    // Add timestamp component for uniqueness
    token += "_" + Date.now().toString(36);
    return token;
}

/**
 * Get start of day timestamp (UTC)
 */
function getStartOfDay() {
    var now = new Date();
    now.setUTCHours(0, 0, 0, 0);
    return Math.floor(now.getTime() / 1000);
}

/**
 * Get user's daily claim count for a placement
 */
function getDailyClaimCount(nk, logger, userId, placement) {
    var key = "daily_claims_" + getStartOfDay();
    
    try {
        var records = nk.storageRead([{
            collection: CLAIMS_COLLECTION,
            key: key,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            var claims = records[0].value;
            return claims[placement] || 0;
        }
    } catch (err) {
        logger.warn("[RewardedAds] Failed to read daily claims: " + err.message);
    }
    
    return 0;
}

/**
 * Increment user's daily claim count for a placement
 */
function incrementDailyClaimCount(nk, logger, userId, placement) {
    var key = "daily_claims_" + getStartOfDay();
    var claims = {};
    
    try {
        var records = nk.storageRead([{
            collection: CLAIMS_COLLECTION,
            key: key,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            claims = records[0].value;
        }
    } catch (err) {
        // Continue with empty claims
    }
    
    claims[placement] = (claims[placement] || 0) + 1;
    claims.updatedAt = new Date().toISOString();
    
    try {
        nk.storageWrite([{
            collection: CLAIMS_COLLECTION,
            key: key,
            userId: userId,
            value: claims,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return true;
    } catch (err) {
        logger.error("[RewardedAds] Failed to increment daily claims: " + err.message);
        return false;
    }
}

/**
 * Get user's last claim timestamp for a placement
 */
function getLastClaimTimestamp(nk, logger, userId, placement) {
    var key = "last_claim_" + placement;
    
    try {
        var records = nk.storageRead([{
            collection: CLAIMS_COLLECTION,
            key: key,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            return records[0].value.timestamp || 0;
        }
    } catch (err) {
        logger.warn("[RewardedAds] Failed to read last claim: " + err.message);
    }
    
    return 0;
}

/**
 * Update user's last claim timestamp for a placement
 */
function updateLastClaimTimestamp(nk, logger, userId, placement) {
    var key = "last_claim_" + placement;
    var now = Math.floor(Date.now() / 1000);
    
    try {
        nk.storageWrite([{
            collection: CLAIMS_COLLECTION,
            key: key,
            userId: userId,
            value: {
                timestamp: now,
                placement: placement,
                updatedAt: new Date().toISOString()
            },
            permissionRead: 1,
            permissionWrite: 0
        }]);
        return true;
    } catch (err) {
        logger.error("[RewardedAds] Failed to update last claim: " + err.message);
        return false;
    }
}

/**
 * RPC: Request a reward token before showing ad
 * This MUST be called when user clicks the ad button (not auto-triggered)
 * 
 * Payload: { placement: string, gameId: string, metadata?: object }
 * Returns: { success: bool, token: string, expiresIn: number }
 */
function rpcRewardedAdRequestToken(ctx, logger, nk, payload) {
    logger.info("[RewardedAds] Token request from user: " + ctx.userId);
    
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({
            success: false,
            error: "Authentication required"
        });
    }
    
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({
            success: false,
            error: "Invalid payload"
        });
    }
    
    var placement = data.placement || "default";
    var gameId = data.gameId || "unknown";
    var metadata = data.metadata || {};
    
    // PLAN-ADS-OPTIMIZATION-v2 §3+§6: Get TIER-AWARE reward config.
    // This checks the tier gate and scales maxClaimsPerDay by geo tier.
    var config = getTierAwareConfig(nk, logger, userId, placement);
    
    // Tier gate check — placement not available for this user's tier
    if (!config) {
        var userTier = getUserTier(nk, logger, userId);
        logger.info("[RewardedAds] Placement '" + placement + "' gated for tier " + userTier + ", user: " + userId);
        return JSON.stringify({
            success: false,
            error: "Placement not available for your region",
            errorCode: "TIER_GATED",
            tier: userTier,
            placement: placement
        });
    }
    
    // Check daily claim limit (now tier-scaled)
    var dailyClaims = getDailyClaimCount(nk, logger, userId, placement);
    if (dailyClaims >= config.maxClaimsPerDay) {
        logger.warn("[RewardedAds] Daily limit reached for user: " + userId + ", placement: " + placement + ", tier: " + config.tier + ", cap: " + config.maxClaimsPerDay);
        return JSON.stringify({
            success: false,
            error: "Daily limit reached",
            errorCode: "DAILY_CAP",
            dailyClaims: dailyClaims,
            maxClaimsPerDay: config.maxClaimsPerDay,
            tier: config.tier,
            resetAt: getStartOfDay() + 86400 // Next day UTC
        });
    }
    
    // Check cooldown
    var lastClaim = getLastClaimTimestamp(nk, logger, userId, placement);
    var now = Math.floor(Date.now() / 1000);
    var cooldownRemaining = (lastClaim + config.cooldownSeconds) - now;
    
    if (cooldownRemaining > 0) {
        logger.info("[RewardedAds] Cooldown active for user: " + userId + ", remaining: " + cooldownRemaining);
        return JSON.stringify({
            success: false,
            error: "Cooldown active",
            cooldownRemaining: cooldownRemaining,
            canClaimAt: lastClaim + config.cooldownSeconds
        });
    }
    
    // Generate unique token
    var token = generateToken();
    var expiresAt = now + TOKEN_EXPIRY_SECONDS;
    
    // Store token for later validation
    var tokenData = {
        token: token,
        userId: userId,
        placement: placement,
        gameId: gameId,
        metadata: metadata,
        createdAt: now,
        expiresAt: expiresAt,
        consumed: false,
        clientIp: ctx.clientIp || "unknown",
        sessionId: ctx.sessionId || "unknown"
    };
    
    try {
        nk.storageWrite([{
            collection: TOKEN_COLLECTION,
            key: token,
            userId: userId,
            value: tokenData,
            permissionRead: 1,
            permissionWrite: 0
        }]);
        
        logger.info("[RewardedAds] Token generated for user: " + userId + ", placement: " + placement + ", token: " + token.substring(0, 8) + "...");
        
        return JSON.stringify({
            success: true,
            token: token,
            expiresIn: TOKEN_EXPIRY_SECONDS,
            expiresAt: expiresAt,
            placement: placement,
            tier: config.tier,
            rewardConfig: {
                type: config.rewardType,
                currency: config.currency,
                amount: config.amount,
                multiplier: config.multiplier,
                action: config.action
            }
        });
        
    } catch (err) {
        logger.error("[RewardedAds] Failed to store token: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Failed to generate token"
        });
    }
}

/**
 * RPC: Claim reward after ad was watched
 * Token must be valid, not expired, and not already consumed
 * 
 * Payload: { token: string, adCompleted: bool, adNetwork?: string, metadata?: object }
 * Returns: { success: bool, reward: object, walletUpdate: object }
 */
function rpcRewardedAdClaim(ctx, logger, nk, payload) {
    logger.info("[RewardedAds] Claim request from user: " + ctx.userId);
    
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({
            success: false,
            error: "Authentication required"
        });
    }
    
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({
            success: false,
            error: "Invalid payload"
        });
    }
    
    var token = data.token;
    var adCompleted = data.adCompleted === true;
    var adNetwork = data.adNetwork || "unknown";
    var claimMetadata = data.metadata || {};
    
    if (!token) {
        logger.warn("[RewardedAds] Claim attempt without token from user: " + userId);
        return JSON.stringify({
            success: false,
            error: "Token required"
        });
    }
    
    if (!adCompleted) {
        logger.info("[RewardedAds] Ad not completed for user: " + userId);
        return JSON.stringify({
            success: false,
            error: "Ad was not completed"
        });
    }
    
    // Read and validate token
    var tokenData = null;
    try {
        var records = nk.storageRead([{
            collection: TOKEN_COLLECTION,
            key: token,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            tokenData = records[0].value;
        }
    } catch (err) {
        logger.error("[RewardedAds] Failed to read token: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Token validation failed"
        });
    }
    
    // Validate token exists
    if (!tokenData) {
        logger.warn("[RewardedAds] Invalid token from user: " + userId + ", token: " + token.substring(0, 8) + "...");
        return JSON.stringify({
            success: false,
            error: "Invalid or expired token"
        });
    }
    
    // Validate token ownership
    if (tokenData.userId !== userId) {
        logger.warn("[RewardedAds] Token ownership mismatch. Token user: " + tokenData.userId + ", Claim user: " + userId);
        return JSON.stringify({
            success: false,
            error: "Token does not belong to user"
        });
    }
    
    // Check if already consumed
    if (tokenData.consumed) {
        logger.warn("[RewardedAds] Token already consumed: " + token.substring(0, 8) + "...");
        return JSON.stringify({
            success: false,
            error: "Reward already claimed"
        });
    }
    
    // Check expiry
    var now = Math.floor(Date.now() / 1000);
    if (now > tokenData.expiresAt) {
        logger.warn("[RewardedAds] Token expired. Created: " + tokenData.createdAt + ", Expired: " + tokenData.expiresAt + ", Now: " + now);
        return JSON.stringify({
            success: false,
            error: "Token expired"
        });
    }
    
    // Get reward config
    var placement = tokenData.placement;
    var gameId = tokenData.gameId;
    var config = REWARD_CONFIG[placement] || REWARD_CONFIG["default"];
    
    // Mark token as consumed FIRST (prevent race conditions)
    tokenData.consumed = true;
    tokenData.consumedAt = now;
    tokenData.adNetwork = adNetwork;
    tokenData.claimMetadata = claimMetadata;
    
    try {
        nk.storageWrite([{
            collection: TOKEN_COLLECTION,
            key: token,
            userId: userId,
            value: tokenData,
            permissionRead: 1,
            permissionWrite: 0
        }]);
    } catch (err) {
        logger.error("[RewardedAds] Failed to mark token consumed: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Claim processing failed"
        });
    }
    
    // Process reward based on type
    var rewardResult = null;
    
    if (config.rewardType === "score_multiplier") {
        // For score multiplier, we return authorization to multiply
        // The actual score update is done by the client with server validation
        rewardResult = {
            type: "score_multiplier",
            multiplier: config.multiplier,
            authorized: true,
            authorizationToken: generateToken(), // One-time use token for score submission
            expiresIn: 60 // Must be used within 60 seconds
        };
        
        // Store the score multiplier authorization
        try {
            nk.storageWrite([{
                collection: "score_multiplier_auth",
                key: rewardResult.authorizationToken,
                userId: userId,
                value: {
                    multiplier: config.multiplier,
                    placement: placement,
                    gameId: gameId,
                    createdAt: now,
                    expiresAt: now + 60,
                    used: false
                },
                permissionRead: 1,
                permissionWrite: 0
            }]);
        } catch (err) {
            logger.error("[RewardedAds] Failed to store score auth: " + err.message);
        }
        
    } else if (config.rewardType === "currency") {
        // Grant currency to wallet
        var walletUpdate = grantWalletReward(nk, logger, userId, gameId, config.currency, config.amount, placement);
        rewardResult = {
            type: "currency",
            currency: config.currency,
            amount: config.amount,
            walletUpdate: walletUpdate
        };
    }
    
    // Update daily claims and last claim timestamp
    incrementDailyClaimCount(nk, logger, userId, placement);
    updateLastClaimTimestamp(nk, logger, userId, placement);
    
    // Log successful claim for analytics
    logger.info("[RewardedAds] Reward claimed successfully. User: " + userId + ", Placement: " + placement + ", Reward: " + JSON.stringify(rewardResult));
    
    // Include tier info in claim response for client-side analytics
    var claimTier = getUserTier(nk, logger, userId);
    return JSON.stringify({
        success: true,
        placement: placement,
        tier: claimTier,
        reward: rewardResult,
        dailyClaims: getDailyClaimCount(nk, logger, userId, placement),
        maxClaimsPerDay: config.maxClaimsPerDay
    });
}

/**
 * Grant wallet reward using Nakama's wallet system
 */
function grantWalletReward(nk, logger, userId, gameId, currency, amount, source) {
    var changeset = {};
    changeset[currency] = amount;
    
    var metadata = {
        source: "rewarded_ad",
        placement: source,
        gameId: gameId,
        grantedAt: new Date().toISOString()
    };
    
    try {
        var results = nk.walletUpdate(userId, changeset, metadata, true);
        logger.info("[RewardedAds] Wallet updated for user: " + userId + ", currency: " + currency + ", amount: " + amount);
        return {
            success: true,
            previousBalance: results.previous ? results.previous[currency] || 0 : 0,
            newBalance: results.updated ? results.updated[currency] || amount : amount,
            change: amount
        };
    } catch (err) {
        logger.error("[RewardedAds] Wallet update failed: " + err.message);
        return {
            success: false,
            error: err.message
        };
    }
}

/**
 * RPC: Validate score multiplier authorization
 * Called when submitting a doubled score to leaderboard
 * 
 * Payload: { authorizationToken: string, originalScore: number, multipliedScore: number }
 * Returns: { success: bool, authorized: bool }
 */
function rpcValidateScoreMultiplier(ctx, logger, nk, payload) {
    logger.info("[RewardedAds] Score multiplier validation from user: " + ctx.userId);
    
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({
            success: false,
            error: "Authentication required"
        });
    }
    
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        return JSON.stringify({
            success: false,
            error: "Invalid payload"
        });
    }
    
    var authToken = data.authorizationToken;
    var originalScore = data.originalScore;
    var multipliedScore = data.multipliedScore;
    
    if (!authToken) {
        return JSON.stringify({
            success: false,
            error: "Authorization token required"
        });
    }
    
    // Read authorization
    var authData = null;
    try {
        var records = nk.storageRead([{
            collection: "score_multiplier_auth",
            key: authToken,
            userId: userId
        }]);
        
        if (records && records.length > 0 && records[0].value) {
            authData = records[0].value;
        }
    } catch (err) {
        logger.error("[RewardedAds] Failed to read auth: " + err.message);
        return JSON.stringify({
            success: false,
            error: "Validation failed"
        });
    }
    
    if (!authData) {
        logger.warn("[RewardedAds] Invalid score auth token from user: " + userId);
        return JSON.stringify({
            success: false,
            error: "Invalid authorization"
        });
    }
    
    // Check if already used
    if (authData.used) {
        logger.warn("[RewardedAds] Score auth already used");
        return JSON.stringify({
            success: false,
            error: "Authorization already used"
        });
    }
    
    // Check expiry
    var now = Math.floor(Date.now() / 1000);
    if (now > authData.expiresAt) {
        logger.warn("[RewardedAds] Score auth expired");
        return JSON.stringify({
            success: false,
            error: "Authorization expired"
        });
    }
    
    // Validate the multiplied score matches expected calculation
    var expectedScore = originalScore * authData.multiplier;
    if (multipliedScore !== expectedScore) {
        logger.warn("[RewardedAds] Score mismatch. Expected: " + expectedScore + ", Got: " + multipliedScore);
        return JSON.stringify({
            success: false,
            error: "Score calculation mismatch"
        });
    }
    
    // Mark as used
    authData.used = true;
    authData.usedAt = now;
    authData.originalScore = originalScore;
    authData.multipliedScore = multipliedScore;
    
    try {
        nk.storageWrite([{
            collection: "score_multiplier_auth",
            key: authToken,
            userId: userId,
            value: authData,
            permissionRead: 1,
            permissionWrite: 0
        }]);
    } catch (err) {
        logger.error("[RewardedAds] Failed to mark auth used: " + err.message);
    }
    
    logger.info("[RewardedAds] Score multiplier validated. User: " + userId + ", Original: " + originalScore + ", Multiplied: " + multipliedScore);
    
    return JSON.stringify({
        success: true,
        authorized: true,
        originalScore: originalScore,
        multipliedScore: multipliedScore,
        multiplier: authData.multiplier
    });
}

/**
 * RPC: Get user's rewarded ad status (for UI display)
 * 
 * Payload: { placement?: string }
 * Returns: { placements: object[] }
 */
function rpcGetRewardedAdStatus(ctx, logger, nk, payload) {
    var userId = ctx.userId;
    if (!userId) {
        return JSON.stringify({
            success: false,
            error: "Authentication required"
        });
    }
    
    var data = {};
    try {
        data = JSON.parse(payload || "{}");
    } catch (err) {
        // Continue with empty data
    }
    
    var requestedPlacement = data.placement;
    var now = Math.floor(Date.now() / 1000);
    var statuses = [];
    
    var placements = requestedPlacement ? [requestedPlacement] : Object.keys(REWARD_CONFIG);
    
    for (var i = 0; i < placements.length; i++) {
        var placement = placements[i];
        if (placement === "default" && !requestedPlacement) continue;
        
        // Use tier-aware config so status reflects actual availability
        var config = getTierAwareConfig(nk, logger, userId, placement);
        if (!config) continue; // Tier-gated — skip entirely
        
        var dailyClaims = getDailyClaimCount(nk, logger, userId, placement);
        var lastClaim = getLastClaimTimestamp(nk, logger, userId, placement);
        var cooldownRemaining = Math.max(0, (lastClaim + config.cooldownSeconds) - now);
        
        statuses.push({
            placement: placement,
            tier: config.tier,
            available: dailyClaims < config.maxClaimsPerDay && cooldownRemaining === 0,
            dailyClaims: dailyClaims,
            maxClaimsPerDay: config.maxClaimsPerDay,
            originalMaxClaimsPerDay: config.originalMaxClaimsPerDay,
            cooldownRemaining: cooldownRemaining,
            canClaimAt: cooldownRemaining > 0 ? lastClaim + config.cooldownSeconds : now,
            rewardType: config.rewardType,
            rewardAmount: config.amount,
            rewardCurrency: config.currency,
            multiplier: config.multiplier,
            action: config.action
        });
    }
    
    return JSON.stringify({
        success: true,
        placements: statuses,
        resetAt: getStartOfDay() + 86400
    });
}

// Export functions for registration
var rewardedAdsModule = {
    rpcRewardedAdRequestToken: rpcRewardedAdRequestToken,
    rpcRewardedAdClaim: rpcRewardedAdClaim,
    rpcValidateScoreMultiplier: rpcValidateScoreMultiplier,
    rpcGetRewardedAdStatus: rpcGetRewardedAdStatus
};


// --- Module: s3_assets\s3_assets.js ---
﻿/**
 * s3_assets.js - AWS S3 Asset Management Module for Nakama
 * 
 * Provides secure asset delivery via pre-signed S3 URLs.
 * Assets remain private in S3; clients get temporary download links.
 * 
 * RPCs:
 *   - s3_asset_download: Get pre-signed URL for a single asset
 *   - s3_asset_list: List all assets in a category with download URLs
 *   - s3_asset_upload: Upload asset to S3 (admin only)
 *   - s3_asset_manifest: Get cached asset manifest (no S3 round-trip)
 * 
 * Environment Variables Required:
 *   - AWS_ACCESS_KEY_ID
 *   - AWS_SECRET_ACCESS_KEY
 *   - AWS_REGION (default: us-east-1)
 *   - AWS_S3_BUCKET
 *   - AWS_PRESIGNED_URL_EXPIRY (default: 3600 seconds)
 */

// AWS Signature Version 4 implementation for S3 pre-signed URLs
var ALGORITHM = 'AWS4-HMAC-SHA256';

/**
 * Get AWS configuration from environment
 */
function getAwsConfig(ctx) {
    const accessKeyId = ctx.env['AWS_ACCESS_KEY_ID'];
    const secretAccessKey = ctx.env['AWS_SECRET_ACCESS_KEY'];
    const region = ctx.env['AWS_REGION'] || 'us-east-1';
    const bucket = ctx.env['AWS_S3_BUCKET'];
    const expirySeconds = parseInt(ctx.env['AWS_PRESIGNED_URL_EXPIRY'] || '3600', 10);

    if (!accessKeyId || !secretAccessKey || !bucket) {
        return null;
    }

    return { accessKeyId, secretAccessKey, region, bucket, expirySeconds };
}

/**
 * HMAC-SHA256 using Nakama's built-in crypto
 */
function hmacSha256(key, message) {
    // Nakama's nk.hmacSha256Hash returns hex string
    // For AWS Sig v4, we need binary for chaining
    return nk.hmacSha256Hash(key, message);
}

/**
 * Create hex-encoded SHA256 hash
 */
function sha256Hex(str) {
    return nk.sha256Hash(str);
}

/**
 * Get AWS4 signing key
 */
function getSigningKey(secretKey, dateStamp, region, service) {
    const kDate = hmacSha256('AWS4' + secretKey, dateStamp);
    const kRegion = hmacSha256(hexToBytes(kDate), region);
    const kService = hmacSha256(hexToBytes(kRegion), service);
    const kSigning = hmacSha256(hexToBytes(kService), 'aws4_request');
    return kSigning;
}

/**
 * Convert hex string to byte array for HMAC chaining
 */
function hexToBytes(hex) {
    const bytes = [];
    for (let i = 0; i < hex.length; i += 2) {
        bytes.push(parseInt(hex.substr(i, 2), 16));
    }
    return String.fromCharCode.apply(null, bytes);
}

/**
 * URL encode per AWS requirements (RFC 3986)
 */
function awsUriEncode(str, encodeSlash) {
    if (!str) return '';
    let encoded = '';
    for (let i = 0; i < str.length; i++) {
        const ch = str.charAt(i);
        if ((ch >= 'A' && ch <= 'Z') ||
            (ch >= 'a' && ch <= 'z') ||
            (ch >= '0' && ch <= '9') ||
            ch === '_' || ch === '-' || ch === '~' || ch === '.') {
            encoded += ch;
        } else if (ch === '/') {
            encoded += encodeSlash ? '%2F' : ch;
        } else {
            encoded += '%' + ch.charCodeAt(0).toString(16).toUpperCase().padStart(2, '0');
        }
    }
    return encoded;
}

/**
 * Generate pre-signed S3 URL using AWS Signature Version 4
 */
function generatePresignedUrl(config, objectKey, expiresIn) {
    const now = new Date();
    const dateStamp = now.toISOString().replace(/[-:]/g, '').split('.')[0].replace('T', '').substring(0, 8);
    const amzDate = now.toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
    
    const host = config.bucket + '.s3.' + config.region + '.amazonaws.com';
    const canonicalUri = '/' + awsUriEncode(objectKey, false);
    const credentialScope = dateStamp + '/' + config.region + '/s3/aws4_request';
    
    // Query parameters for pre-signed URL
    const queryParams = {
        'X-Amz-Algorithm': ALGORITHM,
        'X-Amz-Credential': awsUriEncode(config.accessKeyId + '/' + credentialScope, true),
        'X-Amz-Date': amzDate,
        'X-Amz-Expires': expiresIn.toString(),
        'X-Amz-SignedHeaders': 'host'
    };
    
    // Build canonical query string (sorted)
    const sortedKeys = Object.keys(queryParams).sort();
    const canonicalQueryString = sortedKeys.map(k => k + '=' + queryParams[k]).join('&');
    
    // Canonical headers
    const canonicalHeaders = 'host:' + host + '\n';
    const signedHeaders = 'host';
    
    // Canonical request
    const canonicalRequest = [
        'GET',
        canonicalUri,
        canonicalQueryString,
        canonicalHeaders,
        signedHeaders,
        'UNSIGNED-PAYLOAD'
    ].join('\n');
    
    // String to sign
    const stringToSign = [
        ALGORITHM,
        amzDate,
        credentialScope,
        sha256Hex(canonicalRequest)
    ].join('\n');
    
    // Signing key and signature
    const signingKey = getSigningKey(config.secretAccessKey, dateStamp, config.region, 's3');
    const signature = hmacSha256(hexToBytes(signingKey), stringToSign);
    
    // Build final URL
    const presignedUrl = 'https://' + host + canonicalUri + '?' + 
        canonicalQueryString + '&X-Amz-Signature=' + signature;
    
    return presignedUrl;
}

/**
 * RPC: Download single asset - returns pre-signed URL
 * 
 * Request: { category: string, name: string }
 * Response: { name: string, downloadUrl: string, expiresAt: number }
 */
function rpcAssetDownload(ctx, logger, nk, payload) {
    const config = getAwsConfig(ctx);
    if (!config) {
        throw new Error('AWS S3 not configured. Set AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_S3_BUCKET.');
    }

    let request;
    try {
        request = JSON.parse(payload);
    } catch (e) {
        throw new Error('Invalid JSON payload');
    }

    if (!request.category || !request.name) {
        throw new Error('category and name are required');
    }

    const objectKey = request.category + '/' + request.name;
    const downloadUrl = generatePresignedUrl(config, objectKey, config.expirySeconds);
    const expiresAt = Math.floor(Date.now() / 1000) + config.expirySeconds;

    logger.info('Generated pre-signed URL for: %s', objectKey);

    return JSON.stringify({
        name: request.name,
        category: request.category,
        downloadUrl: downloadUrl,
        expiresAt: expiresAt
    });
}

/**
 * RPC: List assets in category - returns array of pre-signed URLs
 * 
 * This uses Nakama storage to cache the asset manifest, avoiding S3 ListObjects calls.
 * Upload script should update the manifest when assets change.
 * 
 * Request: { category: string }
 * Response: { assets: [{ name, downloadUrl, expiresAt }], count: number }
 */
function rpcAssetList(ctx, logger, nk, payload) {
    const config = getAwsConfig(ctx);
    if (!config) {
        throw new Error('AWS S3 not configured');
    }

    let request;
    try {
        request = JSON.parse(payload);
    } catch (e) {
        throw new Error('Invalid JSON payload');
    }

    if (!request.category) {
        throw new Error('category is required');
    }

    // Read manifest from Nakama storage
    const collection = 's3_asset_manifests';
    const key = request.category.replace(/\//g, '_');
    
    const objects = nk.storageRead([{
        collection: collection,
        key: key,
        userId: null // System owned
    }]);

    if (!objects || objects.length === 0) {
        return JSON.stringify({ assets: [], count: 0 });
    }

    const manifest = JSON.parse(objects[0].value);
    const assets = [];
    const expiresAt = Math.floor(Date.now() / 1000) + config.expirySeconds;

    for (const assetName of manifest.assets || []) {
        const objectKey = request.category + '/' + assetName;
        assets.push({
            name: assetName,
            downloadUrl: generatePresignedUrl(config, objectKey, config.expirySeconds),
            expiresAt: expiresAt
        });
    }

    logger.info('Listed %d assets in category: %s', assets.length, request.category);

    return JSON.stringify({
        category: request.category,
        assets: assets,
        count: assets.length
    });
}

/**
 * RPC: Update asset manifest (admin only)
 * 
 * Called by upload script to update the list of assets in a category.
 * 
 * Request: { category: string, assets: string[] }
 * Response: { success: true, count: number }
 */
function rpcAssetManifestUpdate(ctx, logger, nk, payload) {
    // Admin-only check: require server-to-server call or specific user
    if (ctx.userId && !isAdmin(ctx, nk)) {
        throw new Error('Unauthorized: admin access required');
    }

    let request;
    try {
        request = JSON.parse(payload);
    } catch (e) {
        throw new Error('Invalid JSON payload');
    }

    if (!request.category || !Array.isArray(request.assets)) {
        throw new Error('category and assets array required');
    }

    const collection = 's3_asset_manifests';
    const key = request.category.replace(/\//g, '_');

    const manifest = {
        category: request.category,
        assets: request.assets,
        updatedAt: Date.now()
    };

    nk.storageWrite([{
        collection: collection,
        key: key,
        userId: null, // System owned
        value: manifest,
        permissionRead: 2, // Public read
        permissionWrite: 0 // Server only
    }]);

    logger.info('Updated manifest for category %s with %d assets', request.category, request.assets.length);

    return JSON.stringify({
        success: true,
        category: request.category,
        count: request.assets.length
    });
}

/**
 * RPC: Get Star Wars character images specifically
 * 
 * Convenience RPC for the Star Wars quiz module.
 * 
 * Request: { characters?: string[] } - optional filter
 * Response: { characters: { [name]: downloadUrl } }
 */
function rpcStarWarsCharacterImages(ctx, logger, nk, payload) {
    const config = getAwsConfig(ctx);
    if (!config) {
        throw new Error('AWS S3 not configured');
    }

    let request = {};
    if (payload) {
        try {
            request = JSON.parse(payload);
        } catch (e) {
            // Empty payload is fine
        }
    }

    const category = 'starwars/characters';
    const collection = 's3_asset_manifests';
    const key = category.replace(/\//g, '_');

    const objects = nk.storageRead([{
        collection: collection,
        key: key,
        userId: null
    }]);

    const characters = {};
    const expiresAt = Math.floor(Date.now() / 1000) + config.expirySeconds;

    if (objects && objects.length > 0) {
        const manifest = JSON.parse(objects[0].value);
        
        for (const assetName of manifest.assets || []) {
            // Extract character name from filename (e.g., 'luke_skywalker.png' -> 'Luke Skywalker')
            const charName = assetName
                .replace(/\.[^.]+$/, '')
                .replace(/_/g, ' ')
                .replace(/\b\w/g, c => c.toUpperCase());
            
            // Filter if specific characters requested — normalise both sides so
            // "luke_skywalker" and "Luke Skywalker" both match.
            if (request.characters && request.characters.length > 0) {
                const charNameNorm = charName.toLowerCase().replace(/\s+/g, '_');
                const matched = request.characters.some(c =>
                    c === charName ||
                    c.toLowerCase() === charName.toLowerCase() ||
                    c.toLowerCase().replace(/\s+/g, '_') === charNameNorm ||
                    c.toLowerCase().replace(/_/g, ' ') === charName.toLowerCase()
                );
                if (!matched) continue;
            }

            const objectKey = category + '/' + assetName;
            characters[charName] = {
                downloadUrl: generatePresignedUrl(config, objectKey, config.expirySeconds),
                expiresAt: expiresAt
            };
        }
    }

    return JSON.stringify({
        characters: characters,
        count: Object.keys(characters).length
    });
}

/**
 * Check if user is admin
 */
function isAdmin(ctx, nk) {
    if (!ctx.userId) return true; // Server-to-server
    
    // Check for admin group membership or specific user ID
    // You can customize this logic
    try {
        const account = nk.accountGetId(ctx.userId);
        const metadata = JSON.parse(account.user.metadata || '{}');
        return metadata.isAdmin === true;
    } catch (e) {
        return false;
    }
}

// Register RPCs
function __ModuleInit_109(ctx, logger, nk, initializer) {
    logger.info('Initializing S3 Assets module...');

    const config = getAwsConfig(ctx);
    if (!config) {
        logger.warn('AWS S3 not configured - s3_assets RPCs will return errors. Set AWS_* env vars.');
    } else {
        logger.info('AWS S3 configured: bucket=%s, region=%s, urlExpiry=%ds', 
            config.bucket, config.region, config.expirySeconds);
    }

    __rpc_s3_asset_download = __rpc_s3_asset_download || (rpcAssetDownload);
    __rpc_s3_asset_list = __rpc_s3_asset_list || (rpcAssetList);
    __rpc_s3_asset_manifest_update = __rpc_s3_asset_manifest_update || (rpcAssetManifestUpdate);
    __rpc_s3_starwars_character_images = __rpc_s3_starwars_character_images || (rpcStarWarsCharacterImages);

    logger.info('S3 Assets module initialized with 4 RPCs');
}

