// cognito_wallet_mapper.js - Core RPC functions for Cognito â†” Wallet mapping


/**
 * RPC: get_user_wallet
 * Retrieves or creates a wallet for a Cognito user
 *
 * @param {object} ctx - Nakama context
 * @param {object} logger - Nakama logger
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON string with { "token": "<cognito_jwt>" }
 * @returns {string} JSON response with wallet info
 */
function __legacy_getUserWallet(ctx, logger, nk, payload) {
    try {
        __legacy_logWalletOperation(logger, 'get_user_wallet', { payload: payload });

        // Parse input
        var input = {};
        if (payload) {
            try {
                input = JSON.parse(payload);
            } catch (err) {
                return JSON.stringify({
                    success: false,
                    error: 'Invalid JSON payload'
                });
            }
        }

        var token = input.token;

        // If no token provided, try to use ctx.userId (for authenticated Nakama users)
        var userId;
        var username;

        if (token) {
            // Validate JWT structure
            if (!__legacy_validateJWTStructure(token)) {
                return JSON.stringify({
                    success: false,
                    error: 'Invalid JWT token format'
                });
            }

            // Extract user info from Cognito JWT
            var userInfo = __legacy_extractUserInfo(token);
            userId = userInfo.sub;
            username = userInfo.username;

            __legacy_logWalletOperation(logger, 'extracted_user_info', {
                userId: userId,
                username: username
            });
        } else if (ctx.userId) {
            // Fallback to Nakama context user
            userId = ctx.userId;
            username = ctx.username || userId;

            __legacy_logWalletOperation(logger, 'using_context_user', {
                userId: userId,
                username: username
            });
        } else {
            return JSON.stringify({
                success: false,
                error: 'No token provided and no authenticated user in context'
            });
        }

        // Query wallet registry
        var wallet = __legacy_getWalletByUserId(nk, logger, userId);

        // Create wallet if not found
        if (!wallet) {
            wallet = __legacy_createWalletRecord(nk, logger, userId, username);
            __legacy_logWalletOperation(logger, 'wallet_created', {
                walletId: wallet.walletId
            });
        } else {
            __legacy_logWalletOperation(logger, 'wallet_found', {
                walletId: wallet.walletId,
                gamesLinked: wallet.gamesLinked
            });
        }

        // Return wallet info
        return JSON.stringify({
            success: true,
            walletId: wallet.walletId,
            userId: wallet.userId,
            status: wallet.status,
            gamesLinked: wallet.gamesLinked || [],
            createdAt: wallet.createdAt
        });

    } catch (err) {
        return JSON.stringify(__legacy_handleWalletError(logger, 'get_user_wallet', err));
    }
}

/**
 * RPC: link_wallet_to_game
 * Links a wallet to a specific game
 *
 * @param {object} ctx - Nakama context
 * @param {object} logger - Nakama logger
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON string with { "token": "<cognito_jwt>", "gameId": "<game_id>" }
 * @returns {string} JSON response with updated wallet info
 */
function __legacy_linkWalletToGame(ctx, logger, nk, payload) {
    try {
        __legacy_logWalletOperation(logger, 'link_wallet_to_game', { payload: payload });

        // Parse input
        var input = {};
        if (payload) {
            try {
                input = JSON.parse(payload);
            } catch (err) {
                return JSON.stringify({
                    success: false,
                    error: 'Invalid JSON payload'
                });
            }
        }

        var token = input.token;
        var gameId = input.gameId;

        if (!gameId) {
            return JSON.stringify({
                success: false,
                error: 'gameId is required'
            });
        }

        // Get user ID from token or context
        var userId;
        var username;

        if (token) {
            if (!__legacy_validateJWTStructure(token)) {
                return JSON.stringify({
                    success: false,
                    error: 'Invalid JWT token format'
                });
            }

            var userInfo = __legacy_extractUserInfo(token);
            userId = userInfo.sub;
            username = userInfo.username;
        } else if (ctx.userId) {
            userId = ctx.userId;
            username = ctx.username || userId;
        } else {
            return JSON.stringify({
                success: false,
                error: 'No token provided and no authenticated user in context'
            });
        }

        // Ensure wallet exists
        var wallet = __legacy_getWalletByUserId(nk, logger, userId);
        if (!wallet) {
            wallet = __legacy_createWalletRecord(nk, logger, userId, username);
        }

        // Link game to wallet
        wallet = __legacy_updateWalletGames(nk, logger, wallet.walletId, gameId);

        __legacy_logWalletOperation(logger, 'game_linked', {
            walletId: wallet.walletId,
            gameId: gameId,
            totalGames: wallet.gamesLinked.length
        });

        return JSON.stringify({
            success: true,
            walletId: wallet.walletId,
            gameId: gameId,
            gamesLinked: wallet.gamesLinked,
            message: 'Game successfully linked to wallet'
        });

    } catch (err) {
        return JSON.stringify(__legacy_handleWalletError(logger, 'link_wallet_to_game', err));
    }
}

/**
 * RPC: get_wallet_registry
 * Returns all wallets in the registry (admin function)
 *
 * @param {object} ctx - Nakama context
 * @param {object} logger - Nakama logger
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON string with optional { "limit": 100 }
 * @returns {string} JSON response with wallet array
 */
function __legacy_getWalletRegistry(ctx, logger, nk, payload) {
    try {
        __legacy_logWalletOperation(logger, 'get_wallet_registry', { userId: ctx.userId });

        // Parse input
        var input = {};
        if (payload) {
            try {
                input = JSON.parse(payload);
            } catch (err) {
                // Ignore parse errors for optional payload
            }
        }

        var limit = input.limit || 100;

        // Get all wallets
        var wallets = __legacy_getAllWallets(nk, logger, limit);

        return JSON.stringify({
            success: true,
            wallets: wallets,
            count: wallets.length
        });

    } catch (err) {
        return JSON.stringify(__legacy_handleWalletError(logger, 'get_wallet_registry', err));
    }
}

// ============================================================================
// TUTORX AI COIN GATE - Daily Free Tier + Coin Gating for DeepTutor
// ============================================================================

var TUTORX_DEFAULT_CONFIG = {
    FREE_MESSAGES_PER_DAY: 5,
    COST_PER_MESSAGE: 20,
    COLLECTION: "tutorx_daily_usage"
};

/**
 * Get TutorX config from system storage (allows ops to change without redeploy)
 * Falls back to TUTORX_DEFAULT_CONFIG if not set
 */
function getTutorXConfig(nk, logger) {
    try {
        var records = nk.storageRead([{
            collection: "config",
            key: "tutorx_pricing",
            userId: "00000000-0000-0000-0000-000000000000"
        }]);
        if (records && records.length > 0 && records[0].value) {
            var cfg = records[0].value;
            return {
                FREE_MESSAGES_PER_DAY: cfg.free_daily !== undefined ? cfg.free_daily : TUTORX_DEFAULT_CONFIG.FREE_MESSAGES_PER_DAY,
                COST_PER_MESSAGE: cfg.cost_per_message !== undefined ? cfg.cost_per_message : TUTORX_DEFAULT_CONFIG.COST_PER_MESSAGE,
                COLLECTION: TUTORX_DEFAULT_CONFIG.COLLECTION
            };
        }
    } catch (err) {
        if (logger) logWarn(logger, "getTutorXConfig: " + err.message + " - using defaults");
    }
    return TUTORX_DEFAULT_CONFIG;
}

/**
 * RPC: tutorx_set_config (admin only)
 * Set TutorX pricing config: { "cost_per_message": 25, "free_daily": 3 }
 */
function rpcTutorXSetConfig(ctx, logger, nk, payload) {
    logInfo(logger, "RPC tutorx_set_config called");
    
    var parsed = safeJsonParse(payload || "{}");
    var data = parsed.data || {};
    
    var newConfig = {};
    if (data.cost_per_message !== undefined) {
        newConfig.cost_per_message = parseInt(data.cost_per_message);
        if (isNaN(newConfig.cost_per_message) || newConfig.cost_per_message < 0) {
            return handleError(ctx, null, "cost_per_message must be a non-negative integer");
        }
    }
    if (data.free_daily !== undefined) {
        newConfig.free_daily = parseInt(data.free_daily);
        if (isNaN(newConfig.free_daily) || newConfig.free_daily < 0) {
            return handleError(ctx, null, "free_daily must be a non-negative integer");
        }
    }
    
    if (Object.keys(newConfig).length === 0) {
        return handleError(ctx, null, "No valid config fields provided. Use: cost_per_message, free_daily");
    }
    
    var existingConfig = {};
    try {
        var records = nk.storageRead([{
            collection: "config",
            key: "tutorx_pricing",
            userId: "00000000-0000-0000-0000-000000000000"
        }]);
        if (records && records.length > 0 && records[0].value) {
            existingConfig = records[0].value;
        }
    } catch (err) {}
    
    var mergedConfig = {
        cost_per_message: newConfig.cost_per_message !== undefined ? newConfig.cost_per_message : (existingConfig.cost_per_message || TUTORX_DEFAULT_CONFIG.COST_PER_MESSAGE),
        free_daily: newConfig.free_daily !== undefined ? newConfig.free_daily : (existingConfig.free_daily || TUTORX_DEFAULT_CONFIG.FREE_MESSAGES_PER_DAY),
        updated_at: getCurrentTimestamp(),
        updated_by: ctx.userId
    };
    
    nk.storageWrite([{
        collection: "config",
        key: "tutorx_pricing",
        userId: "00000000-0000-0000-0000-000000000000",
        value: mergedConfig,
        permissionRead: 2,
        permissionWrite: 0
    }]);
    
    logInfo(logger, "TutorX config updated: cost_per_message=" + mergedConfig.cost_per_message + ", free_daily=" + mergedConfig.free_daily);
    
    return JSON.stringify({
        success: true,
        config: mergedConfig,
        timestamp: getCurrentTimestamp()
    });
}

/**
 * RPC: tutorx_get_config
 * Get current TutorX pricing config
 */
function rpcTutorXGetConfig(ctx, logger, nk, payload) {
    logInfo(logger, "RPC tutorx_get_config called");
    var config = getTutorXConfig(nk, logger);
    return JSON.stringify({
        success: true,
        config: {
            cost_per_message: config.COST_PER_MESSAGE,
            free_daily: config.FREE_MESSAGES_PER_DAY
        },
        timestamp: getCurrentTimestamp()
    });
}

/**
 * RPC: tutorx_check_allowance
 * Check if user can send an AI message (free tier or has coins)
 */
function __legacy_rpcTutorXCheckAllowance(ctx, logger, nk, payload) {
    logInfo(logger, "RPC tutorx_check_allowance called");

    var userId = ctx.userId;
    if (!userId) {
        return handleError(ctx, null, "User not authenticated");
    }

    var TUTORX_CONFIG = getTutorXConfig(nk, logger);

    var parsed = safeJsonParse(payload || "{}");
    var data = parsed.data || {};
    var gameId = data.gameId || "126bf539-dae2-4bcf-964d-316c0fa1f92b";
    var charge = tutorxResolveServiceCharge(data, TUTORX_CONFIG);
    var today = tutorxTodayKey();

    var usage = tutorxReadUsage(nk, TUTORX_CONFIG.COLLECTION, userId, today, TUTORX_CONFIG.FREE_MESSAGES_PER_DAY);
    var freeRemaining = tutorxFreeRemaining(usage, TUTORX_CONFIG.FREE_MESSAGES_PER_DAY);

    var coinBalance = 0;
    try {
        var wallet = __legacy_getGameWallet(nk, logger, userId, gameId);
        coinBalance = tutorxCoinBalance(wallet);
    } catch (err) {
        logWarn(logger, "tutorx_check_allowance: wallet read error: " + err.message);
    }

    var canUse = (charge.useFreeTier && freeRemaining > 0) || coinBalance >= charge.cost;

    return JSON.stringify({
        success: true,
        canUse: canUse,
        freeRemaining: freeRemaining,
        freeLimit: TUTORX_CONFIG.FREE_MESSAGES_PER_DAY,
        coinBalance: coinBalance,
        costPerMsg: charge.cost,
        service: charge.service,
        useFreeTier: charge.useFreeTier,
        usedToday: usage.usedToday,
        userId: userId,
        gameId: gameId,
        timestamp: getCurrentTimestamp()
    });
}

/**
 * RPC: tutorx_record_usage
 * Record that user sent an AI message. If free tier exhausted, deducts coins.
 * Returns success:false if user has no free messages AND insufficient coins.
 */
function __legacy_rpcTutorXRecordUsage(ctx, logger, nk, payload) {
    logInfo(logger, "RPC tutorx_record_usage called");

    var userId = ctx.userId;
    if (!userId) {
        return handleError(ctx, null, "User not authenticated");
    }

    var TUTORX_CONFIG = getTutorXConfig(nk, logger);

    var parsed = safeJsonParse(payload || "{}");
    var data = parsed.data || {};
    var gameId = data.gameId || "126bf539-dae2-4bcf-964d-316c0fa1f92b";
    var charge = tutorxResolveServiceCharge(data, TUTORX_CONFIG);
    var today = tutorxTodayKey();

    var usage = tutorxReadUsage(nk, TUTORX_CONFIG.COLLECTION, userId, today, TUTORX_CONFIG.FREE_MESSAGES_PER_DAY);
    var freeRemaining = tutorxFreeRemaining(usage, TUTORX_CONFIG.FREE_MESSAGES_PER_DAY);

    var coinsDeducted = 0;
    var coinBalance = 0;
    var usesFreeSlot = charge.useFreeTier && freeRemaining > 0;

    if (!usesFreeSlot) {
        try {
            var wallet = __legacy_getGameWallet(nk, logger, userId, gameId);
            coinBalance = tutorxCoinBalance(wallet);
        } catch (err) {
            logWarn(logger, "tutorx_record_usage: wallet read error: " + err.message);
        }

        if (coinBalance < charge.cost) {
            logWarn(logger, "tutorx_record_usage: BLOCKED user=" + userId + " service=" + charge.service + " cost=" + charge.cost + " coinBalance=" + coinBalance);
            return JSON.stringify({
                success: false,
                error: "INSUFFICIENT_COINS",
                message: "Insufficient coins for " + charge.service,
                freeRemaining: freeRemaining,
                coinBalance: coinBalance,
                costPerMsg: charge.cost,
                service: charge.service,
                usedToday: usage.usedToday,
                timestamp: getCurrentTimestamp()
            });
        }

        try {
            var deductResult = deductGameWallet(nk, logger, userId, gameId, charge.cost, "tutorx_" + charge.service);
            if (deductResult && deductResult.success) {
                coinsDeducted = charge.cost;
                coinBalance = deductResult.newBalance || (coinBalance - charge.cost);
                logInfo(logger, "tutorx_record_usage: deducted " + coinsDeducted + " coins user=" + userId + " service=" + charge.service);
            } else {
                logError(logger, "tutorx_record_usage: coin deduction failed for user=" + userId + " service=" + charge.service);
                return JSON.stringify({
                    success: false,
                    error: "DEDUCTION_FAILED",
                    message: "Failed to deduct coins",
                    freeRemaining: freeRemaining,
                    coinBalance: coinBalance,
                    costPerMsg: charge.cost,
                    service: charge.service,
                    usedToday: usage.usedToday,
                    timestamp: getCurrentTimestamp()
                });
            }
        } catch (err) {
            logError(logger, "tutorx_record_usage: coin deduction error: " + err.message);
            return JSON.stringify({
                success: false,
                error: "DEDUCTION_ERROR",
                message: err.message,
                freeRemaining: freeRemaining,
                coinBalance: coinBalance,
                costPerMsg: charge.cost,
                service: charge.service,
                usedToday: usage.usedToday,
                timestamp: getCurrentTimestamp()
            });
        }

        usage.paidToday = (usage.paidToday || 0) + 1;
    } else {
        try {
            var freeWallet = __legacy_getGameWallet(nk, logger, userId, gameId);
            coinBalance = tutorxCoinBalance(freeWallet);
        } catch (err) {
            logWarn(logger, "tutorx_record_usage: wallet read error: " + err.message);
        }
        usage.freeUsedToday = (usage.freeUsedToday || 0) + 1;
    }

    usage.usedToday = (usage.usedToday || 0) + 1;
    usage.date = today;

    try {
        tutorxWriteUsage(nk, TUTORX_CONFIG.COLLECTION, userId, today, usage);
    } catch (err) {
        logError(logger, "tutorx_record_usage: storage write failed: " + err.message);
        return handleError(ctx, null, "Failed to record usage");
    }

    freeRemaining = tutorxFreeRemaining(usage, TUTORX_CONFIG.FREE_MESSAGES_PER_DAY);

    logInfo(logger, "tutorx_record_usage: user=" + userId + " service=" + charge.service + " usedToday=" + usage.usedToday + " coinsDeducted=" + coinsDeducted);

    return JSON.stringify({
        success: true,
        usedToday: usage.usedToday,
        freeRemaining: freeRemaining,
        freeLimit: TUTORX_CONFIG.FREE_MESSAGES_PER_DAY,
        coinsDeducted: coinsDeducted,
        coinCharged: coinsDeducted,
        coinBalance: coinBalance,
        costPerMsg: charge.cost,
        service: charge.service,
        useFreeTier: charge.useFreeTier,
        timestamp: getCurrentTimestamp()
    });
}

/**
 * RPC: Get balances for a specific game wallet
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime
 * @param {string} payload - JSON payload with { gameId: "uuid" }
 * @returns {string} JSON response
 *
 * Response shape matches what your Unity client expects:
 * {
 *   "success": true,
 *   "game_balance":   <number>,
 *   "global_balance": <number>,
 *   "currencies": { ... },
 *   "gameId": "uuid",
 *   "userId": "uuid"
 * }
 */
function __legacy_rpcWalletGetBalances(ctx, logger, nk, payload) {
    logInfo(logger, "RPC wallet_get_balances called");

    var parsed = safeJsonParse(payload);
    if (!parsed.success) {
        return handleError(ctx, null, "Invalid JSON payload");
    }

    var data = parsed.data;
    var validation = __legacy_validatePayload(data, ['gameId']);
    if (!validation.valid) {
        return handleError(ctx, null, "Missing required fields: " + validation.missing.join(", "));
    }

    var gameId = data.gameId;
    if (!isValidUUID(gameId)) {
        return handleError(ctx, null, "Invalid gameId UUID format");
    }

    var userId = ctx.userId;
    if (!userId) {
        return handleError(ctx, null, "User not authenticated");
    }

    // Get game wallet
    var wallet = __legacy_getGameWallet(nk, logger, userId, gameId);
    var currencies = wallet.currencies || {};

    // Get global wallet too for global_balance
    var globalWallet = __legacy_getGlobalWallet(nk, logger, userId);
    var globalCurrencies = globalWallet.currencies || {};

    // Return BOTH key formats for maximum compatibility
    var gameBalance = currencies.game || currencies.tokens || 0;
    var globalBalance = globalCurrencies.global || globalCurrencies.xut || 0;

    logInfo(logger, "Returning balances - game: " + gameBalance + ", global: " + globalBalance);

    return JSON.stringify({
        success: true,
        userId: userId,
        gameId: gameId,
        game_balance: gameBalance,
        global_balance: globalBalance,
        currencies: currencies,
        timestamp: getCurrentTimestamp()
    });
}




