/**
 * RPC: quizverse_track_session_end
 * Track session end
 */
function quizverseTrackSessionEnd(context, logger, nk, payload) {
    try {
        var data = __legacy_parseAndValidateGamePayload(payload, ["gameID", "sessionKey"]);
        var userId = __legacy_getUserId(data, context);

        var collection = __legacy_getCollection(data.gameID, "sessions");

        // Read session
        var sessionData = null;
        try {
            var records = nk.storageRead([{
                collection: collection,
                key: data.sessionKey,
                userId: userId
            }]);
            if (records && records.length > 0 && records[0].value) {
                sessionData = records[0].value;
            }
        } catch (err) {
            throw new Error("Session not found");
        }

        if (sessionData) {
            sessionData.endTime = new Date().toISOString();
            sessionData.duration = data.duration || 0;

            nk.storageWrite([{
                collection: collection,
                key: data.sessionKey,
                userId: userId,
                value: sessionData,
                permissionRead: 1,
                permissionWrite: 0
            }]);
        }

        logger.info("[" + data.gameID + "] Session ended for user: " + userId);

        return JSON.stringify({
            success: true,
            data: { sessionKey: data.sessionKey }
        });

    } catch (err) {
        logger.error("quizverse_track_session_end error: " + err.message);
        throw {
            code: 400,
            message: err.message,
            data: {}
        };
    }
}

