/**
 * RPC: game_entry_validate
 * Validates and processes game entry - deducts coins or uses free play
 */
function rpcGameEntryValidate(ctx, logger, nk, payload) {
    logger.info('[GameEntry] Validating game entry');

    try {
        var data = JSON.parse(payload || '{}');
        var userId = ctx.userId;
        var gameId = data.gameId || "126bf539-dae2-4bcf-964d-316c0fa1f92b"; // QuizVerse default
        var gameMode = data.gameMode;
        var entryMethod = data.entryMethod || "coins"; // "coins", "free_play", "ad_entry"

        if (!gameMode) {
            return JSON.stringify({ success: false, error: "gameMode required" });
        }

        var config = GAME_MODE_COSTS[gameMode];
        if (!config) {
            return JSON.stringify({ success: false, error: "Unknown game mode: " + gameMode });
        }

        // Get user's wallet
        var walletKey = "wallet_" + userId + "_" + gameId;
        var walletRecords = nk.storageRead([{
            collection: "wallets",
            key: walletKey,
            userId: userId
        }]);

        var wallet = (walletRecords && walletRecords.length > 0) ? walletRecords[0].value : null;
        var currentBalance = wallet && wallet.currencies ? (wallet.currencies.game || wallet.currencies.tokens || 0) : 0;

        // Get daily tracking
        var today = new Date().toISOString().split('T')[0];
        var dailyKey = "game_entry_daily_" + userId + "_" + today;
        var dailyRecords = nk.storageRead([{
            collection: "game_entry_tracking",
            key: dailyKey,
            userId: userId
        }]);

        var dailyData = (dailyRecords && dailyRecords.length > 0) ? dailyRecords[0].value : {
            freePlaysUsed: {},
            adEntriesUsed: {},
            date: today
        };

        var freePlaysUsed = dailyData.freePlaysUsed[gameMode] || 0;
        var adEntriesUsed = dailyData.adEntriesUsed[gameMode] || 0;
        var MAX_AD_ENTRIES = 10;

        var entryGranted = false;
        var coinsDeducted = 0;
        var method = "";

        // Process entry based on method
        if (entryMethod === "free_play") {
            if (freePlaysUsed < config.freeDaily) {
                dailyData.freePlaysUsed[gameMode] = freePlaysUsed + 1;
                entryGranted = true;
                method = "free_play";
                logger.info("[GameEntry] Free play used for " + gameMode);
            } else {
                return JSON.stringify({
                    success: false,
                    error: "No free plays remaining",
                    freePlayesRemaining: 0
                });
            }
        } else if (entryMethod === "ad_entry") {
            if (adEntriesUsed < MAX_AD_ENTRIES) {
                dailyData.adEntriesUsed[gameMode] = adEntriesUsed + 1;
                entryGranted = true;
                method = "ad_entry";
                logger.info("[GameEntry] Ad entry used for " + gameMode);
            } else {
                return JSON.stringify({
                    success: false,
                    error: "Daily ad entry limit reached",
                    adEntriesRemaining: 0
                });
            }
        } else {
            // Coins entry
            if (currentBalance >= config.entryCost) {
                // Deduct coins
                if (wallet && wallet.currencies) {
                    wallet.currencies.game = (wallet.currencies.game || 0) - config.entryCost;
                    wallet.currencies.tokens = (wallet.currencies.tokens || 0) - config.entryCost;
                    wallet.updatedAt = new Date().toISOString();

                    nk.storageWrite([{
                        collection: "wallets",
                        key: walletKey,
                        userId: userId,
                        value: wallet,
                        permissionRead: 1,
                        permissionWrite: 0
                    }]);

                    coinsDeducted = config.entryCost;
                    entryGranted = true;
                    method = "coins";
                    logger.info("[GameEntry] Deducted " + config.entryCost + " coins for " + gameMode);
                }
            } else {
                return JSON.stringify({
                    success: false,
                    error: "Insufficient coins",
                    required: config.entryCost,
                    current: currentBalance,
                    shortfall: config.entryCost - currentBalance
                });
            }
        }

        if (!entryGranted) {
            return JSON.stringify({ success: false, error: "Entry not granted" });
        }

        // Save daily tracking
        nk.storageWrite([{
            collection: "game_entry_tracking",
            key: dailyKey,
            userId: userId,
            value: dailyData,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Generate entry token for game session validation
        var entryToken = generateEntryToken(userId, gameMode, Date.now());

        // Log the entry
        nk.storageWrite([{
            collection: "game_entry_logs",
            key: "entry_" + userId + "_" + Date.now(),
            userId: userId,
            value: {
                userId: userId,
                gameMode: gameMode,
                entryMethod: method,
                coinsDeducted: coinsDeducted,
                timestamp: new Date().toISOString(),
                entryToken: entryToken
            },
            permissionRead: 1,
            permissionWrite: 0
        }]);

        return JSON.stringify({
            success: true,
            entryGranted: true,
            entryMethod: method,
            coinsDeducted: coinsDeducted,
            newBalance: wallet ? (wallet.currencies.game || 0) : currentBalance - coinsDeducted,
            entryToken: entryToken,
            freePlayesRemaining: Math.max(0, config.freeDaily - (dailyData.freePlaysUsed[gameMode] || 0)),
            adEntriesRemaining: Math.max(0, MAX_AD_ENTRIES - (dailyData.adEntriesUsed[gameMode] || 0)),
            potentialRewards: {
                onComplete: config.rewardOnComplete,
                onWin: config.rewardOnWin
            }
        });

    } catch (err) {
        logger.error("[GameEntry] Error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * RPC: game_entry_complete
 * Awards coins when game is completed
 */
function rpcGameEntryComplete(ctx, logger, nk, payload) {
    logger.info('[GameEntry] Processing game completion');

    try {
        var data = JSON.parse(payload || '{}');
        var userId = ctx.userId;
        var gameId = data.gameId || "126bf539-dae2-4bcf-964d-316c0fa1f92b";
        var gameMode = data.gameMode;
        var won = data.won === true;
        var score = data.score || 0;
        var entryToken = data.entryToken;

        if (!gameMode) {
            return JSON.stringify({ success: false, error: "gameMode required" });
        }

        var config = GAME_MODE_COSTS[gameMode];
        if (!config) {
            return JSON.stringify({ success: false, error: "Unknown game mode" });
        }

        // Calculate rewards
        var reward = config.rewardOnComplete;
        if (won) {
            reward += config.rewardOnWin;
        }

        // Bonus for high scores (10% of score, capped at 50)
        var scoreBonus = Math.min(Math.floor(score / 10), 50);
        reward += scoreBonus;

        // Get and update wallet
        var walletKey = "wallet_" + userId + "_" + gameId;
        var walletRecords = nk.storageRead([{
            collection: "wallets",
            key: walletKey,
            userId: userId
        }]);

        var wallet = (walletRecords && walletRecords.length > 0) ? walletRecords[0].value : {
            userId: userId,
            currencies: { game: 0, tokens: 0 },
            createdAt: new Date().toISOString()
        };

        // Add reward
        wallet.currencies.game = (wallet.currencies.game || 0) + reward;
        wallet.currencies.tokens = (wallet.currencies.tokens || 0) + reward;
        wallet.updatedAt = new Date().toISOString();

        nk.storageWrite([{
            collection: "wallets",
            key: walletKey,
            userId: userId,
            value: wallet,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        logger.info("[GameEntry] Awarded " + reward + " coins for " + gameMode + " (won: " + won + ", score: " + score + ")");

        return JSON.stringify({
            success: true,
            reward: reward,
            breakdown: {
                completion: config.rewardOnComplete,
                winBonus: won ? config.rewardOnWin : 0,
                scoreBonus: scoreBonus
            },
            won: won,
            newBalance: wallet.currencies.game
        });

    } catch (err) {
        logger.error("[GameEntry] Complete error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * RPC: game_entry_get_status
 * Get entry status for all game modes
 */
function rpcGameEntryGetStatus(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        var userId = ctx.userId;
        var gameId = data.gameId || "126bf539-dae2-4bcf-964d-316c0fa1f92b";

        // Get wallet balance
        var walletKey = "wallet_" + userId + "_" + gameId;
        var walletRecords = nk.storageRead([{
            collection: "wallets",
            key: walletKey,
            userId: userId
        }]);
        var wallet = (walletRecords && walletRecords.length > 0) ? walletRecords[0].value : null;
        var currentBalance = wallet && wallet.currencies ? (wallet.currencies.game || 0) : 0;

        // Get daily tracking
        var today = new Date().toISOString().split('T')[0];
        var dailyKey = "game_entry_daily_" + userId + "_" + today;
        var dailyRecords = nk.storageRead([{
            collection: "game_entry_tracking",
            key: dailyKey,
            userId: userId
        }]);
        var dailyData = (dailyRecords && dailyRecords.length > 0) ? dailyRecords[0].value : {
            freePlaysUsed: {},
            adEntriesUsed: {}
        };

        var MAX_AD_ENTRIES = 10;
        var modeStatuses = [];

        for (var mode in GAME_MODE_COSTS) {
            var config = GAME_MODE_COSTS[mode];
            var freePlaysUsed = dailyData.freePlaysUsed[mode] || 0;
            var adEntriesUsed = dailyData.adEntriesUsed[mode] || 0;

            modeStatuses.push({
                mode: mode,
                entryCost: config.entryCost,
                canAfford: currentBalance >= config.entryCost,
                freePlayesRemaining: Math.max(0, config.freeDaily - freePlaysUsed),
                adEntriesRemaining: Math.max(0, MAX_AD_ENTRIES - adEntriesUsed),
                rewardOnComplete: config.rewardOnComplete,
                rewardOnWin: config.rewardOnWin,
                hasAnyEntry: (currentBalance >= config.entryCost) ||
                             (freePlaysUsed < config.freeDaily) ||
                             (adEntriesUsed < MAX_AD_ENTRIES)
            });
        }

        return JSON.stringify({
            success: true,
            currentBalance: currentBalance,
            modes: modeStatuses,
            resetAt: new Date(new Date().setHours(24, 0, 0, 0)).toISOString()
        });

    } catch (err) {
        logger.error("[GameEntry] GetStatus error: " + err.message);
        return JSON.stringify({ success: false, error: err.message });
    }
}

/**
 * Generate entry token for session validation
 */
function generateEntryToken(userId, gameMode, timestamp) {
    var data = userId + "_" + gameMode + "_" + timestamp;
    // Simple hash for validation
    var hash = 0;
    for (var i = 0; i < data.length; i++) {
        hash = ((hash << 5) - hash) + data.charCodeAt(i);
        hash = hash & hash;
    }
    return "entry_" + Math.abs(hash).toString(16) + "_" + timestamp.toString(36);
}

// ============================================================================
// COMPATIBILITY QUIZ SYSTEM - Valentine's Day Feature (QuizVerse)
// ============================================================================

var COLLECTION_COMPATIBILITY_SESSIONS = 'compatibility_sessions';

/**
 * Generate a unique 6-digit numeric share code for a compatibility session.
 * Matches the 6-field numeric input in the Unity UI (RoomCodeInput + CompatibilityQuizUIController).
 * Uses collision checking against existing code_* keys (same pattern as asyncChallengeGenerateShareCode).
 */
function compatibilityGenerateShareCode(nk) {
    for (var attempt = 0; attempt < 10; attempt++) {
        var code = String(100000 + Math.floor(Math.random() * 900000));
        try {
            var existing = nk.storageRead([{
                collection: COLLECTION_COMPATIBILITY_SESSIONS,
                key: 'code_' + code,
                userId: '00000000-0000-0000-0000-000000000000'
            }]);
            if (!existing || existing.length === 0) return code;
        } catch (e) {
            return code;
        }
    }
    return String(100000 + Math.floor(Math.random() * 900000));
}

/**
 * Send a push notification to a user for compatibility quiz
 */
/**
 * Compatibility inbox + device push (QVBF_421).
 * ES5-safe content merge (no object spread — Goja crashes on `...data`).
 * Optional ctx/logger enable LegacyPush FCM/APNs; without them, inbox-only.
 */
function compatibilitySendNotification(nk, userId, subject, content, data, ctx, logger) {
    try {
        var merged = { message: content };
        if (data && typeof data === 'object') {
            for (var k in data) {
                if (Object.prototype.hasOwnProperty.call(data, k)) {
                    merged[k] = data[k];
                }
            }
        }
        nk.notificationsSend([{
            userId: userId,
            subject: subject,
            content: merged,
            code: 100,
            persistent: true
        }]);
    } catch (e) {
        // inbox best-effort
    }

    try {
        if (ctx && typeof LegacyPush !== 'undefined' && LegacyPush.sendLocalizedPushToUser) {
            var eventType = (data && data.type) ? String(data.type) : 'compatibility';
            var titleKey = 'compatibility_generic_title';
            var bodyKey = 'compatibility_generic_body';
            if (eventType === 'partner_joined') {
                titleKey = 'compatibility_partner_joined_title';
                bodyKey = 'compatibility_partner_joined_body';
            } else if (eventType === 'creator_completed' || eventType === 'partner_completed') {
                titleKey = 'compatibility_partner_finished_title';
                bodyKey = 'compatibility_partner_finished_body';
            } else if (eventType === 'results_ready') {
                titleKey = 'compatibility_results_ready_title';
                bodyKey = 'compatibility_results_ready_body';
            }
            var vars = { name: 'Your partner', mode: 'Compatibility', subject: subject, message: content };
            LegacyPush.sendLocalizedPushToUser(
                ctx, logger || { warn: function () {}, info: function () {}, debug: function () {} },
                nk, userId, eventType, titleKey, bodyKey, vars,
                { skipQuietHours: true, data: merged }
            );
        }
    } catch (pushErr) {
        // device push best-effort
    }
}

/**
 * Convert internal session storage to Unity-compatible format
 * Status mapping: 0=WaitingForPartner, 1=PartnerJoined, 2=BothCompleted, 3=Expired, 4=Cancelled
 */
function compatibilitySessionToUnityFormat(session) {
    // Convert string status to numeric
    var statusMap = {
        'waiting_for_partner': 0,
        'partner_joined': 1,
        'creator_completed': 1,
        'partner_completed': 1,
        'both_completed': 2,
        'completed': 2,
        'expired': 3,
        'cancelled': 4
    };
    var numericStatus = typeof session.status === 'number' ? session.status : (statusMap[session.status] || 0);

    // Check expiry
    if (Date.now() > session.expiresAt && numericStatus < 2) {
        numericStatus = 3; // Expired
    }

    return {
        sessionId: session.sessionId || '',
        quizId: session.quizId || 'compatibility_quiz_v1',
        quizTitle: session.quizTitle || 'Compatibility Quiz',
        createdByUserId: session.creatorId || '',
        createdAt: session.createdAt,
        expiresAt: session.expiresAt,
        playerA: {
            userId: session.creatorId || '',
            displayName: session.creatorName || 'Player A',
            isComplete: session.creatorCompleted || false,
            answers: session.creatorAnswers || [],
            traitScores: session.creatorTraitScores || {},
            resultId: session.creatorResultId || '',
            personalityTitle: session.creatorPersonalityTitle || '',
            personalityEmoji: session.creatorPersonalityEmoji || '',
            completedAt: session.creatorCompletedAt || 0
        },
        playerB: session.partnerId ? {
            userId: session.partnerId || '',
            displayName: session.partnerName || 'Player B',
            isComplete: session.partnerCompleted || false,
            answers: session.partnerAnswers || [],
            traitScores: session.partnerTraitScores || {},
            resultId: session.partnerResultId || '',
            personalityTitle: session.partnerPersonalityTitle || '',
            personalityEmoji: session.partnerPersonalityEmoji || '',
            completedAt: session.partnerCompletedAt || 0
        } : null,
        compatibilityScore: session.compatibilityResult ? session.compatibilityResult.score : 0,
        compatibilityLevel: session.compatibilityResult ? (session.compatibilityResult.level || '') : '',
        matchingTraits: session.compatibilityResult ? (session.compatibilityResult.matchingTraits || []) : [],
        differentTraits: session.compatibilityResult ? (session.compatibilityResult.differentTraits || []) : [],
        compatibilityInsight: session.compatibilityResult ? (session.compatibilityResult.message || '') : '',
        status: numericStatus,
        shareCode: session.shareCode || ''
    };
}

/**
 * Calculate trait similarity between two trait score sets
 */
function compatibilityCalculateTraitSimilarity(traits1, traits2, relevantTraits) {
    var similarity = 0;
    var count = 0;

    for (var i = 0; i < relevantTraits.length; i++) {
        var trait = relevantTraits[i];
        var score1 = traits1[trait] || 0;
        var score2 = traits2[trait] || 0;

        var norm1 = Math.min(score1 / 5, 1);
        var norm2 = Math.min(score2 / 5, 1);

        var diff = Math.abs(norm1 - norm2);
        similarity += (1 - diff);
        count++;
    }

    return count > 0 ? similarity / count : 0.5;
}

/**
 * Count how many answers match between two players
 */
function compatibilityCountMatchingAnswers(answers1, answers2) {
    var matches = 0;
    var minLen = Math.min(answers1.length, answers2.length);

    for (var i = 0; i < minLen; i++) {
        var a1 = answers1[i];
        var a2 = answers2[i];

        if (a1 && a2 && a1.optionId === a2.optionId) {
            matches++;
        }
    }

    return matches;
}

/**
 * Compute compatibility score based on trait scores and answers
 */
function compatibilityComputeScore(creatorTraits, partnerTraits, creatorAnswers, partnerAnswers) {
    var totalScore = 0;
    var categoryCount = 0;
    var breakdown = {};

    // 1. Communication Style
    var commScore = compatibilityCalculateTraitSimilarity(
        creatorTraits,
        partnerTraits,
        ['mbti:E', 'mbti:I', 'mbti:J', 'mbti:P']
    );
    breakdown.communicationStyle = Math.round(commScore * 100);
    totalScore += commScore;
    categoryCount++;

    // 2. Emotional Connection
    var emotionalScore = compatibilityCalculateTraitSimilarity(
        creatorTraits,
        partnerTraits,
        ['mbti:F', 'mbti:T', 'big_five:high_agreeableness', 'big_five:high_openness']
    );
    breakdown.emotionalConnection = Math.round(emotionalScore * 100);
    totalScore += emotionalScore;
    categoryCount++;

    // 3. Shared Values
    var valuesScore = compatibilityCalculateTraitSimilarity(
        creatorTraits,
        partnerTraits,
        ['mbti:N', 'mbti:S', 'big_five:high_conscientiousness']
    );
    breakdown.sharedValues = Math.round(valuesScore * 100);
    totalScore += valuesScore;
    categoryCount++;

    // 4. Direct answer matching bonus
    var matchingAnswers = compatibilityCountMatchingAnswers(creatorAnswers, partnerAnswers);
    var maxLen = Math.max(creatorAnswers.length, partnerAnswers.length, 1);
    var matchRatio = matchingAnswers / maxLen;
    breakdown.answerAlignment = Math.round(matchRatio * 100);
    totalScore += matchRatio * 0.5;
    categoryCount += 0.5;

    var finalScore = (totalScore / categoryCount) * 100;

    var message;
    var emoji;
    if (finalScore >= 90) {
        message = "You're a perfect match! Your connection is extraordinary!";
        emoji = "heart";
    } else if (finalScore >= 75) {
        message = "Highly compatible! You complement each other wonderfully!";
        emoji = "hearts";
    } else if (finalScore >= 60) {
        message = "Good compatibility! You share many common values!";
        emoji = "heart_pink";
    } else if (finalScore >= 45) {
        message = "Moderate compatibility! Opposites can attract!";
        emoji = "heart_yellow";
    } else {
        message = "Different perspectives! Diversity makes life interesting!";
        emoji = "star";
    }

    // Determine compatibility level string
    var level;
    if (finalScore >= 90) {
        level = "Perfect Match";
    } else if (finalScore >= 75) {
        level = "Highly Compatible";
    } else if (finalScore >= 60) {
        level = "Good Match";
    } else if (finalScore >= 45) {
        level = "Moderate";
    } else {
        level = "Different Perspectives";
    }

    // Generate matching traits based on category scores
    var matchingTraits = [];
    var differentTraits = [];

    if (breakdown.communicationStyle >= 70) {
        matchingTraits.push("Communication Style");
    } else if (breakdown.communicationStyle < 40) {
        differentTraits.push("Communication Style");
    }

    if (breakdown.emotionalConnection >= 70) {
        matchingTraits.push("Emotional Connection");
    } else if (breakdown.emotionalConnection < 40) {
        differentTraits.push("Emotional Connection");
    }

    if (breakdown.sharedValues >= 70) {
        matchingTraits.push("Shared Values");
    } else if (breakdown.sharedValues < 40) {
        differentTraits.push("Shared Values");
    }

    if (breakdown.answerAlignment >= 60) {
        matchingTraits.push("Similar Thinking");
    } else if (breakdown.answerAlignment < 30) {
        differentTraits.push("Different Viewpoints");
    }

    // Add personality-based traits
    if (creatorTraits['mbti:E'] && partnerTraits['mbti:E'] &&
        creatorTraits['mbti:E'] > 2 && partnerTraits['mbti:E'] > 2) {
        matchingTraits.push("Both Outgoing");
    }
    if (creatorTraits['mbti:I'] && partnerTraits['mbti:I'] &&
        creatorTraits['mbti:I'] > 2 && partnerTraits['mbti:I'] > 2) {
        matchingTraits.push("Both Thoughtful");
    }
    if (creatorTraits['big_five:high_openness'] && partnerTraits['big_five:high_openness'] &&
        creatorTraits['big_five:high_openness'] > 2 && partnerTraits['big_five:high_openness'] > 2) {
        matchingTraits.push("Creative Minds");
    }
    if (creatorTraits['big_five:high_agreeableness'] && partnerTraits['big_five:high_agreeableness'] &&
        creatorTraits['big_five:high_agreeableness'] > 2 && partnerTraits['big_five:high_agreeableness'] > 2) {
        matchingTraits.push("Caring Hearts");
    }

    // Ensure we have at least one matching trait or different trait
    if (matchingTraits.length === 0 && finalScore >= 50) {
        matchingTraits.push("Open to Growth");
    }
    if (differentTraits.length === 0 && finalScore < 50) {
        differentTraits.push("Unique Perspectives");
    }

    // Format category scores for Unity frontend
    var categoryScores = {
        communication: breakdown.communicationStyle || 0,
        emotional: breakdown.emotionalConnection || 0,
        values: breakdown.sharedValues || 0,
        lifestyle: Math.round((breakdown.answerAlignment || 0) * 0.8), // Derive lifestyle from answer alignment
        interests: Math.round(finalScore * 0.9) // Derive interests from overall score
    };

    // Generate growth areas from low-scoring categories
    var growthAreas = [];
    if (categoryScores.communication < 50) growthAreas.push("Communication Skills");
    if (categoryScores.emotional < 50) growthAreas.push("Emotional Understanding");
    if (categoryScores.values < 50) growthAreas.push("Aligning Core Values");
    if (categoryScores.lifestyle < 50) growthAreas.push("Lifestyle Balance");
    if (categoryScores.interests < 50) growthAreas.push("Discovering Shared Interests");

    // Ensure at least one growth area
    if (growthAreas.length === 0) {
        growthAreas.push("Keep Growing Together");
    }

    // Generate relationship advice based on score
    var relationshipAdvice;
    if (finalScore >= 85) {
        relationshipAdvice = "Your connection is truly special! Keep nurturing this beautiful bond. ðŸ’•";
    } else if (finalScore >= 70) {
        relationshipAdvice = "You have great potential together. Communication is your superpower! ðŸ’–";
    } else if (finalScore >= 55) {
        relationshipAdvice = "Embrace your differences - they make your relationship unique! ðŸ’—";
    } else if (finalScore >= 40) {
        relationshipAdvice = "Every relationship is a journey of discovery. Keep exploring together! ðŸ’›";
    } else {
        relationshipAdvice = "Your different perspectives can lead to amazing growth. Stay curious! ðŸŒŸ";
    }

    return {
        score: finalScore,
        overallScore: finalScore, // Alias for Unity compatibility
        level: level,
        compatibilityLevel: level, // Alias for Unity compatibility
        breakdown: breakdown,
        categoryScores: categoryScores,
        message: message,
        relationshipAdvice: relationshipAdvice, // Explicit advice field for Unity
        compatibilityInsight: message, // Alias for backward compatibility
        emoji: emoji,
        matchingTraits: matchingTraits,
        differentTraits: differentTraits,
        growthAreas: growthAreas,
        matchingAnswers: matchingAnswers,
        totalQuestions: maxLen
    };
}

/**
 * RPC: Create a new compatibility quiz session
 * Payload: { quizId: string, userId?: string, playerDisplayName?: string }
 */
function rpcCompatibilityCreateSession(ctx, logger, nk, payload) {
    logger.debug('[CompatibilityQuiz] Creating session for user: ' + ctx.userId);

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var quizId = request.quizId || 'compatibility_quiz_v1';
        var quizTitle = request.quizTitle || 'Compatibility Quiz';
        var playerDisplayName = request.playerDisplayName || 'Unknown';
        var sessionId = nk.uuidv4();
        var shareCode = compatibilityGenerateShareCode(nk);
        var now = Date.now();
        var expiresAt = now + (48 * 60 * 60 * 1000);

        // Fetch user display name (with fallback)
        var displayName = playerDisplayName;
        try {
            var users = nk.usersGetId([userId]);
            if (users && users.length > 0) {
                displayName = users[0].displayName || users[0].username || playerDisplayName;
            }
        } catch (userErr) {
            logger.warn('[CompatibilityQuiz] Could not fetch user info: ' + userErr.message);
        }

        // Internal storage format
        var sessionStorage = {
            sessionId: sessionId,
            shareCode: shareCode,
            quizId: quizId,
            quizTitle: quizTitle,
            creatorId: userId,
            creatorName: displayName,
            partnerId: null,
            partnerName: null,
            status: 0, // WaitingForPartner
            createdAt: now,
            expiresAt: expiresAt,
            creatorCompleted: false,
            partnerCompleted: false,
            creatorAnswers: null,
            partnerAnswers: null,
            creatorTraitScores: null,
            partnerTraitScores: null,
            compatibilityResult: null
        };

        nk.storageWrite([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: userId,
            value: sessionStorage,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        // Store code mapping with system user ID for public lookup
        nk.storageWrite([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: 'code_' + shareCode,
            userId: '00000000-0000-0000-0000-000000000000',
            value: { sessionId: sessionId, creatorId: userId },
            permissionRead: 2,
            permissionWrite: 0
        }]);

        logger.info('[CompatibilityQuiz] Session created: ' + sessionId + ' with code: ' + shareCode);

        // Response format matching Unity client expectations
        return JSON.stringify({
            success: true,
            message: 'Session created successfully',
            data: {
                sessionId: sessionId,
                quizId: quizId,
                quizTitle: quizTitle,
                createdByUserId: ctx.userId,
                createdAt: now,
                expiresAt: expiresAt,
                playerA: {
                    userId: ctx.userId,
                    displayName: displayName,
                    isComplete: false,
                    answeredQuestions: [],
                    traitScores: {}
                },
                playerB: null,
                compatibilityScore: 0,
                compatibilityLevel: null,
                matchingTraits: [],
                differentTraits: [],
                compatibilityInsight: null,
                status: 0, // WaitingForPartner
                shareCode: shareCode
            }
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] Create session error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

/**
 * RPC: Join an existing compatibility quiz session
 * Payload: { shareCode: string, userId?: string, playerDisplayName?: string }
 */
function rpcCompatibilityJoinSession(ctx, logger, nk, payload) {
    logger.debug('[CompatibilityQuiz] User ' + ctx.userId + ' attempting to join session');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var shareCode = (request.shareCode || request.shareCodeOrSessionId || '').toUpperCase().trim();
        if (!shareCode || shareCode.length < 6) {
            return JSON.stringify({ success: false, message: 'Invalid share code', data: null });
        }

        // Note: We must read using the creator's ID, but we don't know it yet.
        // First, try to find the code record by listing storage with the code key pattern.
        // For now, we'll use a different approach - store the code mapping with system user.
        var codeResults = nk.storageRead([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: 'code_' + shareCode,
            userId: '00000000-0000-0000-0000-000000000000'
        }]);

        if (codeResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session not found', data: null });
        }

        var codeRecord = codeResults[0].value;
        var sessionId = codeRecord.sessionId;
        var creatorId = codeRecord.creatorId;

        var sessionResults = nk.storageRead([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: creatorId
        }]);

        if (sessionResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session data not found', data: null });
        }

        var session = sessionResults[0].value;

        if (session.status === 3 || session.status === 'expired' || Date.now() > session.expiresAt) {
            return JSON.stringify({ success: false, message: 'Session has expired', data: null });
        }

        if (session.partnerId !== null && session.partnerId !== userId) {
            return JSON.stringify({ success: false, message: 'Session already has a partner', data: null });
        }

        if (session.creatorId === userId) {
            return JSON.stringify({ success: false, message: 'Cannot join your own session', data: null });
        }

        // Fetch user display name (with fallback)
        var displayName = request.playerDisplayName || 'Unknown';
        try {
            var users = nk.usersGetId([userId]);
            if (users && users.length > 0) {
                displayName = users[0].displayName || users[0].username || displayName;
            }
        } catch (userErr) {
            logger.warn('[CompatibilityQuiz] Could not fetch user info: ' + userErr.message);
        }

        session.partnerId = userId;
        session.partnerName = displayName;
        session.status = 1; // PartnerJoined

        nk.storageWrite([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: creatorId,
            value: session,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        compatibilitySendNotification(nk, session.creatorId,
            'Partner Joined!',
            displayName + ' has joined your compatibility quiz!',
            { type: 'partner_joined', sessionId: sessionId },
            ctx, logger
        );

        logger.info('[CompatibilityQuiz] User ' + userId + ' joined session ' + sessionId);

        return JSON.stringify({
            success: true,
            message: 'Successfully joined session',
            data: compatibilitySessionToUnityFormat(session)
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] Join session error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

/**
 * RPC: Get session details
 * Payload: { sessionId: string, userId?: string } or { shareCode: string, userId?: string }
 */
function rpcCompatibilityGetSession(ctx, logger, nk, payload) {
    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var sessionId = request.sessionId;
        var creatorId = null;

        if (!sessionId && request.shareCode) {
            var shareCode = request.shareCode.toUpperCase().trim();
            var codeResults = nk.storageRead([{
                collection: COLLECTION_COMPATIBILITY_SESSIONS,
                key: 'code_' + shareCode,
                userId: '00000000-0000-0000-0000-000000000000'
            }]);

            if (codeResults.length === 0) {
                return JSON.stringify({ success: false, message: 'Session not found', data: null });
            }

            sessionId = codeResults[0].value.sessionId;
            creatorId = codeResults[0].value.creatorId;
        }

        var sessionResults = nk.storageRead([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: userId
        }]);

        if (sessionResults.length === 0 && creatorId) {
            sessionResults = nk.storageRead([{
                collection: COLLECTION_COMPATIBILITY_SESSIONS,
                key: sessionId,
                userId: creatorId
            }]);
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session not found', data: null });
        }

        var session = sessionResults[0].value;

        if (session.creatorId !== userId && session.partnerId !== userId) {
            return JSON.stringify({ success: false, message: 'Not authorized to view this session', data: null });
        }

        return JSON.stringify({
            success: true,
            message: 'Session retrieved',
            data: compatibilitySessionToUnityFormat(session)
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] Get session error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

/**
 * RPC: Submit quiz answers
 * Payload: { sessionId, answers[], traitScores{} }
 */
function rpcCompatibilitySubmitAnswers(ctx, logger, nk, payload) {
    logger.debug('[CompatibilityQuiz] User ' + ctx.userId + ' submitting answers');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var sessionId = request.sessionId;
        var answers = request.answers || [];
        var traitScores = request.traitScores || {};

        if (!sessionId) {
            return JSON.stringify({ success: false, message: 'Session ID required', data: null });
        }

        var sessionResults = nk.storageRead([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: userId
        }]);

        var isCreator = sessionResults.length > 0;
        var creatorId = isCreator ? userId : null;

        if (!isCreator) {
            var listResults = nk.storageList(null, COLLECTION_COMPATIBILITY_SESSIONS, 100, '');
            var objects = listResults.objects || [];

            for (var i = 0; i < objects.length; i++) {
                var obj = objects[i];
                if (obj.value.sessionId === sessionId && obj.value.partnerId === userId) {
                    creatorId = obj.value.creatorId;
                    break;
                }
            }

            if (creatorId) {
                sessionResults = nk.storageRead([{
                    collection: COLLECTION_COMPATIBILITY_SESSIONS,
                    key: sessionId,
                    userId: creatorId
                }]);
            }
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session not found', data: null });
        }

        var session = sessionResults[0].value;

        var isPartner = session.partnerId === userId;
        isCreator = session.creatorId === userId;

        if (!isCreator && !isPartner) {
            return JSON.stringify({ success: false, message: 'Not authorized for this session', data: null });
        }

        var now = Date.now();
        if (isCreator) {
            session.creatorAnswers = answers;
            session.creatorTraitScores = traitScores;
            session.creatorCompleted = true;
            session.creatorCompletedAt = now;
            session.creatorResultId = request.resultId || null;
            session.creatorPersonalityTitle = request.personalityTitle || null;
            session.creatorPersonalityEmoji = request.personalityEmoji || null;
        } else {
            session.partnerAnswers = answers;
            session.partnerTraitScores = traitScores;
            session.partnerCompleted = true;
            session.partnerCompletedAt = now;
            session.partnerResultId = request.resultId || null;
            session.partnerPersonalityTitle = request.personalityTitle || null;
            session.partnerPersonalityEmoji = request.personalityEmoji || null;
        }

        // Update status using numeric values
        if (session.creatorCompleted && session.partnerCompleted) {
            session.status = 2; // BothCompleted
        } else if (session.creatorCompleted || session.partnerCompleted) {
            session.status = 1; // PartnerJoined (or waiting for other)
        }

        nk.storageWrite([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: session.creatorId,
            value: session,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        if (isCreator && session.partnerId && !session.partnerCompleted) {
            compatibilitySendNotification(nk, session.partnerId,
                'Your partner finished!',
                session.creatorName + ' completed the quiz. Your turn!',
                { type: 'creator_completed', sessionId: sessionId, screen: 'compatibility' },
                ctx, logger
            );
        } else if (isPartner && !session.creatorCompleted) {
            compatibilitySendNotification(nk, session.creatorId,
                'Your partner finished!',
                session.partnerName + ' completed the quiz. Your turn!',
                { type: 'partner_completed', sessionId: sessionId, screen: 'compatibility' },
                ctx, logger
            );
        } else if (session.creatorCompleted && session.partnerCompleted) {
            var bothMsg = 'Both of you finished — check your compatibility results!';
            compatibilitySendNotification(nk, session.creatorId,
                'Compatibility Results!', bothMsg,
                { type: 'results_ready', sessionId: sessionId, screen: 'compatibility' },
                ctx, logger
            );
            if (session.partnerId) {
                compatibilitySendNotification(nk, session.partnerId,
                    'Compatibility Results!', bothMsg,
                    { type: 'results_ready', sessionId: sessionId, screen: 'compatibility' },
                    ctx, logger
                );
            }
        }

        logger.info('[CompatibilityQuiz] Answers submitted for session ' + sessionId);

        return JSON.stringify({
            success: true,
            message: 'Answers submitted successfully',
            data: compatibilitySessionToUnityFormat(session)
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] Submit answers error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

/**
 * RPC: Calculate compatibility between two players
 * Payload: { sessionId: string }
 */
function rpcCompatibilityCalculate(ctx, logger, nk, payload) {
    logger.debug('[CompatibilityQuiz] Calculating compatibility for user ' + ctx.userId);

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var sessionId = request.sessionId;
        if (!sessionId) {
            return JSON.stringify({ success: false, message: 'Session ID required', data: null });
        }

        var sessionResults = nk.storageRead([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: userId
        }]);

        var creatorId = userId;

        if (sessionResults.length === 0) {
            var listResults = nk.storageList(null, COLLECTION_COMPATIBILITY_SESSIONS, 100, '');
            var objects = listResults.objects || [];

            for (var i = 0; i < objects.length; i++) {
                var obj = objects[i];
                if (obj.value.sessionId === sessionId) {
                    creatorId = obj.value.creatorId;
                    break;
                }
            }

            sessionResults = nk.storageRead([{
                collection: COLLECTION_COMPATIBILITY_SESSIONS,
                key: sessionId,
                userId: creatorId
            }]);
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session not found', data: null });
        }

        var session = sessionResults[0].value;

        if (!session.creatorCompleted || !session.partnerCompleted) {
            return JSON.stringify({ success: false, message: 'Both players must complete the quiz first', data: null });
        }

        // If already calculated, return cached result
        if (session.compatibilityResult) {
            session.status = 2; // BothCompleted
            return JSON.stringify({
                success: true,
                message: 'Compatibility result retrieved',
                data: compatibilitySessionToUnityFormat(session)
            });
        }

        var creatorTraits = session.creatorTraitScores || {};
        var partnerTraits = session.partnerTraitScores || {};
        var creatorAnswers = session.creatorAnswers || [];
        var partnerAnswers = session.partnerAnswers || [];

        var result = compatibilityComputeScore(creatorTraits, partnerTraits, creatorAnswers, partnerAnswers);

        session.compatibilityResult = result;
        session.status = 2; // BothCompleted

        nk.storageWrite([{
            collection: COLLECTION_COMPATIBILITY_SESSIONS,
            key: sessionId,
            userId: creatorId,
            value: session,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        var resultMessage = 'Your compatibility score: ' + result.score.toFixed(0) + '%!';

        compatibilitySendNotification(nk, session.creatorId,
            'Compatibility Results!',
            resultMessage,
            { type: 'results_ready', sessionId: sessionId, screen: 'compatibility' },
            ctx, logger
        );

        if (session.partnerId) {
            compatibilitySendNotification(nk, session.partnerId,
                'Compatibility Results!',
                resultMessage,
                { type: 'results_ready', sessionId: sessionId, screen: 'compatibility' },
                ctx, logger
            );
        }

        logger.info('[CompatibilityQuiz] Compatibility calculated: ' + result.score + '%');

        return JSON.stringify({
            success: true,
            message: 'Compatibility calculated',
            data: compatibilitySessionToUnityFormat(session)
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] Calculate error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

/**
 * RPC: List user's compatibility sessions
 * Payload: { limit?: number, includeExpired?: boolean, userId?: string }
 */
function rpcCompatibilityListSessions(ctx, logger, nk, payload) {
    var request = {};
    try {
        if (payload) {
            request = JSON.parse(payload);
        }
    } catch (e) {
        // Use defaults
    }

    try {
        // CRITICAL: Validate userId - use from context or fallback to payload
        var userId = ctx.userId;
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            userId = request.userId;
        }
        if (!userId || typeof userId !== 'string' || userId.length < 10) {
            return JSON.stringify({
                success: false,
                message: 'User authentication required. Please ensure you are logged in.',
                data: [],
                errorCode: 'AUTH_REQUIRED'
            });
        }

        var limit = Math.min(request.limit || 20, 100);
        var includeExpired = request.includeExpired || false;

        var creatorSessions = nk.storageList(userId, COLLECTION_COMPATIBILITY_SESSIONS, limit, '');

        var sessions = [];
        var now = Date.now();
        var objects = creatorSessions.objects || [];

        for (var i = 0; i < objects.length; i++) {
            var obj = objects[i];
            var session = obj.value;

            if (obj.key.indexOf('code_') === 0) continue;

            // Convert status to numeric
            var numericStatus = typeof session.status === 'number' ? session.status : 0;
            var isExpired = numericStatus === 3 || now > session.expiresAt;

            if (!includeExpired && isExpired) {
                continue;
            }

            sessions.push(compatibilitySessionToUnityFormat(session));
        }

        return JSON.stringify({
            success: true,
            message: 'Sessions retrieved',
            data: sessions
        });
    } catch (err) {
        logger.error('[CompatibilityQuiz] List sessions error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: [] });
    }
}


// ============================================================================
// ASYNC CHALLENGE SYSTEM - Universal Asynchronous Multiplayer (QuizVerse)
// ============================================================================
// World-class async challenge system supporting all quiz modes
// Features: Create, Join, Submit, Get, List, Cancel, Rematch, Stats, Rewards, Leaderboards
// Status: 0=WaitingForOpponent, 1=OpponentJoined, 2=BothCompleted, 3=Expired, 4=Cancelled
// ============================================================================

var COLLECTION_ASYNC_CHALLENGES = 'async_challenges';
var COLLECTION_ASYNC_STATS = 'async_challenge_stats';
var COLLECTION_ASYNC_INDEX = 'async_challenge_index';
var ASYNC_CHALLENGE_SYSTEM_USER = '00000000-0000-0000-0000-000000000000';
var ASYNC_CHALLENGE_EXPIRY_HOURS = 168; // 7 days (1 week max)
var ASYNC_CHALLENGE_MAX_PER_USER = 10;
// Min time between consecutive challenge creations (in minutes).
// 1 min was too aggressive — a user who cancels and retries within 60 s
// hits RATE_LIMITED even though they have zero active challenges.
// 10 seconds prevents spam while not punishing normal cancel-and-retry flows.
var ASYNC_CHALLENGE_RATE_LIMIT_MINUTES = 10 / 60; // ~10 seconds
var ASYNC_CHALLENGE_WIN_COINS = 50; // Coins for winning
var ASYNC_CHALLENGE_PARTICIPATION_COINS = 10; // Coins for completing (loser)
var ASYNC_CHALLENGE_WIN_XP = 100; // XP for winning
var ASYNC_CHALLENGE_PARTICIPATION_XP = 25; // XP for completing (loser)

// Status constants
var ASYNC_STATUS_WAITING = 0;
var ASYNC_STATUS_OPPONENT_JOINED = 1;
var ASYNC_STATUS_BOTH_COMPLETED = 2;
var ASYNC_STATUS_EXPIRED = 3;
var ASYNC_STATUS_CANCELLED = 4;
// CREATOR_PLAYED (5): creator has submitted their score but no opponent has joined yet.
// Clients can show "Your results are in — share the code so your opponent can play!" instead
// of showing the generic "waiting" state that looks identical to "not started".
var ASYNC_STATUS_CREATOR_PLAYED = 5;

/**
 * Get or create user async challenge statistics
 * @param {object} nk - Nakama runtime context
 * @param {string} userId - User ID
 * @returns {object} User stats
 */
function asyncChallengeGetStats(nk, userId) {
    try {
        var statsResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_STATS,
            key: 'stats_' + userId,
            userId: userId
        }]);

        if (statsResults.length > 0) {
            return statsResults[0].value;
        }
    } catch (err) {
        // Return default stats
    }

    return {
        userId: userId,
        totalChallenges: 0,
        totalWins: 0,
        totalLosses: 0,
        totalDraws: 0,
        currentWinStreak: 0,
        bestWinStreak: 0,
        totalCoinsWon: 0,
        totalXpEarned: 0,
        lastChallengeAt: 0,
        createdAt: Date.now()
    };
}

/**
 * Update user async challenge statistics
 * @param {object} nk - Nakama runtime context
 * @param {string} userId - User ID
 * @param {object} stats - Updated stats object
 */
function asyncChallengeSaveStats(nk, userId, stats) {
    try {
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_STATS,
            key: 'stats_' + userId,
            userId: userId,
            value: stats,
            permissionRead: 2,
            permissionWrite: 1
        }]);
    } catch (err) {
        // Silent fail - stats are non-critical
    }
}

/**
 * SQL fallback to find a challenge session by its storage key when the opponent index
 * doesn't have an entry (e.g. sessions created before the index was deployed).
 * Returns the session storage object or null.
 * @param {object} nk - Nakama runtime context
 * @param {object} logger - Logger instance
 * @param {string} sessionId - The session key to look up
 * @returns {object|null} The session value, or null if not found
 */
function asyncChallengeFindSessionByKey(nk, logger, sessionId) {
    try {
        var rows = nk.sqlQuery(
            "SELECT user_id, value FROM storage WHERE collection = $1 AND key = $2 LIMIT 1",
            [COLLECTION_ASYNC_CHALLENGES, sessionId]
        );
        if (rows && rows.length > 0) {
            var val = typeof rows[0].value === 'string' ? JSON.parse(rows[0].value) : rows[0].value;
            // Backfill the opponent index so future lookups are O(1)
            if (val.opponentId) {
                try {
                    asyncChallengeIndexOpponent(nk, val.opponentId, sessionId, val.creatorId);
                } catch (backfillErr) {
                    // Non-critical
                }
            }
            return val;
        }
    } catch (err) {
        logger.warn('[AsyncChallenge] SQL session lookup failed: ' + err.message);
    }
    return null;
}

/**
 * Add session to opponent index for fast lookups
 * @param {object} nk - Nakama runtime context
 * @param {string} opponentId - Opponent user ID
 * @param {string} sessionId - Challenge session ID
 * @param {string} creatorId - Creator user ID
 */
function asyncChallengeIndexOpponent(nk, opponentId, sessionId, creatorId) {
    // Retry up to 3 times on OCC version conflict so concurrent joins for different sessions
    // by the same opponent don't silently drop entries from the index.
    var maxRetries = 3;
    for (var attempt = 0; attempt < maxRetries; attempt++) {
        try {
            var indexResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_INDEX,
                key: 'opponent_' + opponentId,
                userId: opponentId
            }]);

            var index = { sessions: [] };
            var indexVersion = null;
            if (indexResults.length > 0) {
                index = indexResults[0].value;
                indexVersion = indexResults[0].version;
            }

            // Skip if entry already present.
            var exists = false;
            for (var i = 0; i < index.sessions.length; i++) {
                if (index.sessions[i].sessionId === sessionId) { exists = true; break; }
            }
            if (exists) return;

            index.sessions.push({ sessionId: sessionId, creatorId: creatorId, addedAt: Date.now() });

            // Keep only the most recent 100 entries (pruning keeps the doc small).
            if (index.sessions.length > 100) {
                index.sessions = index.sessions.slice(-100);
            }

            var writeObj = {
                collection: COLLECTION_ASYNC_INDEX,
                key: 'opponent_' + opponentId,
                userId: opponentId,
                value: index,
                permissionRead: 1,
                permissionWrite: 1
            };
            // OCC guard: only write if index hasn't changed since we read it.
            if (indexVersion !== null) writeObj.version = indexVersion;

            nk.storageWrite([writeObj]);
            return; // success
        } catch (err) {
            // Version conflict from a concurrent index update — retry with fresh read.
            if (attempt === maxRetries - 1) {
                // Give up silently; lookup will fall back to SQL for this session.
            }
        }
    }
}

/**
 * Award rewards to a user (coins, XP)
 * @param {object} nk - Nakama runtime context
 * @param {object} logger - Logger instance
 * @param {string} userId - User ID
 * @param {number} coins - Coins to award
 * @param {number} xp - XP to award
 * @param {string} reason - Reward reason for logging
 */
function asyncChallengeAwardRewards(nk, logger, userId, coins, xp, reason) {
    try {
        // Award coins AND xp atomically via a single wallet update.
        // Using walletUpdate (server-side ledger) avoids the race condition that existed
        // when XP was stored in account metadata (read-modify-write with no OCC).
        var changeset = {};
        if (coins > 0) changeset.coins = coins;
        if (xp > 0)    changeset.xp    = xp;

        if (Object.keys(changeset).length > 0) {
            nk.walletUpdate(userId, changeset, { reason: reason }, true);
            logger.debug('[AsyncChallenge] Awarded coins=' + (coins || 0) + ' xp=' + (xp || 0) + ' to ' + userId + ' for: ' + reason);
        }
    } catch (err) {
        logger.warn('[AsyncChallenge] Reward error for ' + userId + ': ' + err.message);
    }
}

/**
 * Process challenge completion - award rewards and update stats
 * @param {object} nk - Nakama runtime context
 * @param {object} logger - Logger instance
 * @param {object} session - Completed session
 */
function asyncChallengeProcessCompletion(nk, logger, session) {
    if (!session.creatorCompleted || !session.opponentCompleted) {
        return; // Not both completed
    }

    var creatorScore = session.creatorScore || 0;
    var opponentScore = session.opponentScore || 0;
    var isDraw = creatorScore === opponentScore;
    var creatorWins = creatorScore > opponentScore;

    // Update creator stats
    var creatorStats = asyncChallengeGetStats(nk, session.creatorId);
    creatorStats.totalChallenges++;

    // Update opponent stats
    var opponentStats = asyncChallengeGetStats(nk, session.opponentId);
    opponentStats.totalChallenges++;

    if (isDraw) {
        // Draw - both get participation rewards
        creatorStats.totalDraws++;
        creatorStats.currentWinStreak = 0;
        opponentStats.totalDraws++;
        opponentStats.currentWinStreak = 0;

        var drawCoins = Math.floor(ASYNC_CHALLENGE_PARTICIPATION_COINS * 1.5);
        asyncChallengeAwardRewards(nk, logger, session.creatorId, drawCoins, ASYNC_CHALLENGE_PARTICIPATION_XP, 'async_challenge_draw');
        asyncChallengeAwardRewards(nk, logger, session.opponentId, drawCoins, ASYNC_CHALLENGE_PARTICIPATION_XP, 'async_challenge_draw');
        creatorStats.totalCoinsWon += drawCoins;
        creatorStats.totalXpEarned += ASYNC_CHALLENGE_PARTICIPATION_XP;
        opponentStats.totalCoinsWon += drawCoins;
        opponentStats.totalXpEarned += ASYNC_CHALLENGE_PARTICIPATION_XP;
    } else if (creatorWins) {
        // Creator wins
        creatorStats.totalWins++;
        creatorStats.currentWinStreak++;
        if (creatorStats.currentWinStreak > creatorStats.bestWinStreak) {
            creatorStats.bestWinStreak = creatorStats.currentWinStreak;
        }
        opponentStats.totalLosses++;
        opponentStats.currentWinStreak = 0;

        // Streak bonus
        var streakBonus = Math.min(creatorStats.currentWinStreak - 1, 5) * 10;
        var winCoins = ASYNC_CHALLENGE_WIN_COINS + streakBonus;

        asyncChallengeAwardRewards(nk, logger, session.creatorId, winCoins, ASYNC_CHALLENGE_WIN_XP, 'async_challenge_win');
        asyncChallengeAwardRewards(nk, logger, session.opponentId, ASYNC_CHALLENGE_PARTICIPATION_COINS, ASYNC_CHALLENGE_PARTICIPATION_XP, 'async_challenge_loss');

        creatorStats.totalCoinsWon += winCoins;
        creatorStats.totalXpEarned += ASYNC_CHALLENGE_WIN_XP;
        opponentStats.totalCoinsWon += ASYNC_CHALLENGE_PARTICIPATION_COINS;
        opponentStats.totalXpEarned += ASYNC_CHALLENGE_PARTICIPATION_XP;
    } else {
        // Opponent wins
        opponentStats.totalWins++;
        opponentStats.currentWinStreak++;
        if (opponentStats.currentWinStreak > opponentStats.bestWinStreak) {
            opponentStats.bestWinStreak = opponentStats.currentWinStreak;
        }
        creatorStats.totalLosses++;
        creatorStats.currentWinStreak = 0;

        // Streak bonus
        var opStreakBonus = Math.min(opponentStats.currentWinStreak - 1, 5) * 10;
        var opWinCoins = ASYNC_CHALLENGE_WIN_COINS + opStreakBonus;

        asyncChallengeAwardRewards(nk, logger, session.opponentId, opWinCoins, ASYNC_CHALLENGE_WIN_XP, 'async_challenge_win');
        asyncChallengeAwardRewards(nk, logger, session.creatorId, ASYNC_CHALLENGE_PARTICIPATION_COINS, ASYNC_CHALLENGE_PARTICIPATION_XP, 'async_challenge_loss');

        opponentStats.totalCoinsWon += opWinCoins;
        opponentStats.totalXpEarned += ASYNC_CHALLENGE_WIN_XP;
        creatorStats.totalCoinsWon += ASYNC_CHALLENGE_PARTICIPATION_COINS;
        creatorStats.totalXpEarned += ASYNC_CHALLENGE_PARTICIPATION_XP;
    }

    // Save updated stats
    asyncChallengeSaveStats(nk, session.creatorId, creatorStats);
    asyncChallengeSaveStats(nk, session.opponentId, opponentStats);

    logger.info('[AsyncChallenge] Processed completion - Creator: ' + creatorScore + ', Opponent: ' + opponentScore + ', Winner: ' + (isDraw ? 'Draw' : (creatorWins ? 'Creator' : 'Opponent')));
}

/**
 * Generate a unique 6-digit numeric share code (100000–999999).
 * Numeric-only so the 6-box join-code input field on the client (Phantom Arena)
 * can capture every character without an alphabetic keyboard. Collisions are
 * checked against the active code mapping in storage; on the rare event of 10
 * back-to-back collisions we fall back to a time-seeded 6-digit value.
 * @param {object} nk - Nakama runtime (for storageRead collision check)
 * @returns {string} 6-digit numeric share code
 */
function asyncChallengeGenerateShareCode(nk) {
    for (var attempt = 0; attempt < 10; attempt++) {
        var code = String(100000 + Math.floor(Math.random() * 900000));
        try {
            var existing = nk.storageRead([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key:        'code_' + code,
                userId:     ASYNC_CHALLENGE_SYSTEM_USER
            }]);
            if (!existing || existing.length === 0) return code;
        } catch (_) {
            return code;
        }
    }
    return String(100000 + (Date.now() % 900000));
}

/**
 * Send a push notification to a user for async challenges
 * @param {object} nk - Nakama runtime context
 * @param {string} userId - Target user ID
 * @param {string} subject - Notification subject
 * @param {string} content - Notification message
 * @param {object} data - Additional notification data
 */
function asyncChallengeSendNotification(ctx, nk, userId, subject, content, data, logger) {
    try {
        // ES5 object merge — Goja rejects object-spread (...data) and would abort
        // the calling RPC (e.g. async_challenge_create with challengedUserId).
        // Mirror compatibilitySendNotification: pass content as an object, not JSON.stringify.
        var merged = { message: content };
        if (data && typeof data === 'object') {
            for (var k in data) {
                if (Object.prototype.hasOwnProperty.call(data, k)) {
                    merged[k] = data[k];
                }
            }
        }
        nk.notificationsSend([{
            userId: userId,
            subject: subject,
            content: merged,
            code: 101, // Async challenge notification code
            persistent: true
        }]);
        if (logger) {
            logger.debug('[AsyncChallenge] notify code=101 type=' + (data && data.type ? data.type : 'unknown') +
                ' target=' + userId + ' session=' + (data && data.sessionId ? data.sessionId : '?'));
        }
    } catch (e) {
        if (logger) {
            logger.warn('[AsyncChallenge] notify failed type=' + (data && data.type ? data.type : 'unknown') + ' target=' + userId + ' err=' + (e.message || String(e)));
        }
    }

    // ── Device push bridge (2026-07-06, PHANTOM_ARENA_LAYMANS_GUIDE Phase 1) ──
    // The in-app notification above only reaches the Nakama inbox + open
    // sockets — offline players never knew it was their turn, which killed
    // the async loop ("silent room" problem). Bridge to the LegacyPush global
    // (same pattern as friends/friend_invites.js) for the four POSITIVE
    // lifecycle events. opponent_left / challenge_cancelled stay in-app-only
    // (AP-001: never push negative events; social push budget applies).
    // ctx may be null (helpers without RPC scope) — push is skipped, in-app
    // tier above already fired. Isolated try/catch — push failure must never
    // affect the in-app tier.
    try {
        if (!ctx || !data || typeof LegacyPush === 'undefined' || !LegacyPush.sendLocalizedPushToUser) return;
        var t = data.type;
        var pushData = {
            eventType:       'async_challenge',
            screen:          'phantom_arena',
            type:            String(t || ''),
            sessionId:       String(data.sessionId || ''),
            // iOS UNNotificationCategory identifier (AsyncChallengePushCategoryRegistrar.CategoryId).
            // Firebase's APNs bridge maps this to the aps.category field so iOS presents
            // "Play Now" / "Remind Me Later" action buttons on the lock screen.
            action_category: 'async_challenge'
        };
        if (data.shareCode) {
            pushData.shareCode = String(data.shareCode);
            pushData.deepLink  = 'quizverse://challenge/join/' + String(data.shareCode);
        }
        var who = data.challengerName || data.opponentName || data.name || 'Someone';
        if (t === 'challenge_received' || t === 'rematch_requested') {
            LegacyPush.sendLocalizedPushToUser(ctx, logger, nk, userId,
                'async_challenge_received',
                'friend_challenge_title', 'friend_challenge_body',
                { name: who, mode: data.quizModeName || 'a quiz battle' },
                { skipInAppNotification: true, data: pushData });
        } else if (t === 'opponent_joined') {
            LegacyPush.sendLocalizedPushToUser(ctx, logger, nk, userId,
                'async_challenge_joined',
                'ac_opponent_joined_title', 'ac_opponent_joined_body',
                { name: who, mode: (data.quizModeName || '') },
                { skipInAppNotification: true, data: pushData });
        } else if (t === 'opponent_completed') {
            LegacyPush.sendLocalizedPushToUser(ctx, logger, nk, userId,
                'async_challenge_your_turn',
                'ac_your_turn_title', 'ac_your_turn_body',
                { name: who, score: String(data.score !== undefined ? data.score : '') },
                { skipInAppNotification: true, data: pushData });
        } else if (t === 'results_ready') {
            LegacyPush.sendLocalizedPushToUser(ctx, logger, nk, userId,
                'async_challenge_results',
                'ac_results_title', 'ac_results_body',
                { name: who, score: String(data.score !== undefined ? data.score : '') },
                { skipInAppNotification: true, data: pushData });
        }
    } catch (pushErr) {
        if (logger) {
            logger.warn('[AsyncChallenge] device push failed (non-fatal) type=' + (data && data.type) + ': ' + (pushErr.message || String(pushErr)));
        }
    }
}

/**
 * Get user display name with fallback
 * @param {object} nk - Nakama runtime context
 * @param {string} userId - User ID
 * @param {string} fallback - Fallback display name
 * @returns {string} Display name
 */
/**
 * Returns true if `name` looks like a machine-generated login ID rather than
 * a human display name — e.g. a UUID, an email address, or a Nakama auto-
 * username like "xyzabc123" with no vowels / no spaces / all lowercase alnum.
 * Used to decide whether to prefer a client-supplied name over the Nakama
 * account name when they differ.
 */
function asyncChallengeIsLoginIdName(name) {
    if (!name || typeof name !== 'string') return true;
    var s = name.trim();
    if (s.length === 0) return true;
    // Generic placeholders used by the client SDKs
    var lower = s.toLowerCase();
    if (lower === 'player' || lower === 'player a' || lower === 'player b'
        || lower === 'unknown' || lower === 'unknown player' || lower === 'user') return true;
    // Contains @ → email / Firebase UID style
    if (s.indexOf('@') >= 0) return true;
    // UUID pattern (8-4-4-4-12 hex)
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s)) return true;
    // Long pure hex string (Firebase / Supabase UID)
    if (/^[0-9a-f]{20,}$/i.test(s)) return true;
    // All digits (numeric UID)
    if (/^\d+$/.test(s)) return true;
    return false;
}

/**
 * QVBF_304: batched profile-name lookup. Reads each user's
 * `player_metadata/metadata` record — the same profile store every device
 * renders its OWN player from — and returns a map of userId → human display
 * name. Names failing asyncChallengeIsLoginIdName are omitted. Any storage
 * error returns whatever was resolved so far (or an empty map), so name
 * resolution can never fail an RPC.
 */
function asyncChallengeReadProfileNames(nk, userIds) {
    var names = {};
    if (!nk || !userIds || userIds.length === 0) return names;
    try {
        var reads = [];
        for (var i = 0; i < userIds.length; i++) {
            if (userIds[i]) {
                reads.push({ collection: 'player_metadata', key: 'metadata', userId: userIds[i] });
            }
        }
        if (reads.length === 0) return names;
        var records = nk.storageRead(reads) || [];
        for (var r = 0; r < records.length; r++) {
            var rec = records[r];
            if (!rec || !rec.value || !rec.userId) continue;
            var value = typeof rec.value === 'string' ? JSON.parse(rec.value) : rec.value;
            if (!value || value.displayName === undefined || value.displayName === null) continue;
            var name = String(value.displayName).trim();
            if (name.length > 0 && !asyncChallengeIsLoginIdName(name)) {
                names[rec.userId] = name;
            }
        }
    } catch (err) {
        // Non-fatal: fall through to session/account names.
    }
    return names;
}

/**
 * QVBF_304 read-time authority chain for one player slot:
 *   1. player_metadata.displayName (what the player's own device shows) — pre-filtered human
 *   2. stored session name (client-supplied at create/join) if human
 *   3. Nakama account displayName/username if human
 *   4. keep stored value, else account value (placeholder handled downstream)
 */
function asyncChallengeResolveReadName(profileName, storedName, accountName) {
    if (profileName) return profileName;
    if (storedName && !asyncChallengeIsLoginIdName(storedName)) return storedName;
    if (accountName && !asyncChallengeIsLoginIdName(accountName)) return accountName;
    return storedName || accountName || '';
}

function asyncChallengeGetDisplayName(nk, userId, fallback) {
    // QVBF_304: if the caller already supplied a real human name (not a
    // generic placeholder or machine-generated login ID), use it directly.
    // Nakama's account displayName / username fields are often email-derived
    // or auto-generated, so the client-supplied name is the more reliable source.
    if (fallback && !asyncChallengeIsLoginIdName(fallback)) {
        return fallback;
    }

    // QVBF_304: prefer the profile store (player_metadata.displayName) — the
    // name the player's own device renders — over the Nakama account name.
    var profileNames = asyncChallengeReadProfileNames(nk, [userId]);
    if (profileNames[userId]) {
        return profileNames[userId];
    }

    // Fallback is absent or looks machine-generated — try the Nakama account.
    try {
        var users = nk.usersGetId([userId]);
        if (users && users.length > 0) {
            var nakamaName = users[0].displayName || users[0].username || '';
            // Prefer the Nakama name only if it looks like a real human name.
            if (nakamaName && !asyncChallengeIsLoginIdName(nakamaName)) {
                return nakamaName;
            }
            // Nakama name is also generic — fall back to whatever the caller gave us.
            if (fallback && fallback.length > 0) return fallback;
            if (nakamaName && nakamaName.length > 0) return nakamaName;
        }
    } catch (err) {
        // Return fallback on error
    }
    return fallback || 'Unknown Player';
}

/**
 * Validate user ID from context or payload
 * @param {object} ctx - Request context
 * @param {object} request - Parsed request payload
 * @returns {object} { valid: boolean, userId: string, error: string }
 */
function asyncChallengeValidateUser(ctx, request) {
    var userId = ctx.userId;
    if (!userId || typeof userId !== 'string' || userId.length < 10) {
        userId = request.userId;
    }
    if (!userId || typeof userId !== 'string' || userId.length < 10) {
        return {
            valid: false,
            userId: null,
            error: 'User authentication required. Please ensure you are logged in.'
        };
    }
    return { valid: true, userId: userId, error: null };
}

/**
 * Convert internal session storage to Unity-compatible response format
 * @param {object} session - Internal session storage object
 * @returns {object} Unity-compatible session data
 */
function asyncChallengeSessionToUnityFormat(session, nk) {
    // QVBF_154: re-resolve player names at read time so a renamed player is
    // never shown with the name snapshotted into the session at create/join.
    // Lookup failure (deleted account, transient error) keeps stored names.
    // QVBF_304: authority chain per player — profile store (player_metadata,
    // what each player's own device shows) → stored session name → Nakama
    // account name → stored value/placeholder. The account name is demoted so
    // it can never clobber the profile name and cause cross-device mismatch.
    if (nk) {
        try {
            var freshIds = [];
            if (session.creatorId) freshIds.push(session.creatorId);
            if (session.opponentId) freshIds.push(session.opponentId);
            if (freshIds.length > 0) {
                var profileNames = asyncChallengeReadProfileNames(nk, freshIds);
                var accountNames = {};
                try {
                    var freshUsers = nk.usersGetId(freshIds) || [];
                    for (var fu = 0; fu < freshUsers.length; fu++) {
                        accountNames[freshUsers[fu].userId] =
                            freshUsers[fu].displayName || freshUsers[fu].username || '';
                    }
                } catch (acctErr) {
                    // non-fatal: resolve without account names
                }
                if (session.creatorId) {
                    var creatorResolved = asyncChallengeResolveReadName(
                        profileNames[session.creatorId],
                        session.creatorName,
                        accountNames[session.creatorId]);
                    if (creatorResolved) session.creatorName = creatorResolved;
                }
                if (session.opponentId) {
                    var opponentResolved = asyncChallengeResolveReadName(
                        profileNames[session.opponentId],
                        session.opponentName,
                        accountNames[session.opponentId]);
                    if (opponentResolved) session.opponentName = opponentResolved;
                }
            }
        } catch (freshErr) {
            // non-fatal: fall back to snapshotted names
        }
    }

    var now = Date.now();
    var status = typeof session.status === 'number' ? session.status : 0;

    // Auto-expire if past expiry time
    if (status < ASYNC_STATUS_BOTH_COMPLETED && now > session.expiresAt) {
        status = ASYNC_STATUS_EXPIRED;
    }

    // Build player A (creator)
    var playerA = {
        userId: session.creatorId || '',
        displayName: session.creatorName || 'Player A',
        isComplete: session.creatorCompleted || false,
        score: session.creatorScore || 0,
        correctAnswers: session.creatorCorrectAnswers || 0,
        totalQuestions: session.creatorTotalQuestions || 0,
        timeTaken: session.creatorTimeTaken || 0,
        completedAt: session.creatorCompletedAt || 0,
        accuracy: session.creatorTotalQuestions > 0
            ? (session.creatorCorrectAnswers / session.creatorTotalQuestions) * 100
            : 0
    };

    // Build player B (opponent) - null if not joined
    var playerB = null;
    if (session.opponentId) {
        playerB = {
            userId: session.opponentId || '',
            displayName: session.opponentName || 'Player B',
            isComplete: session.opponentCompleted || false,
            score: session.opponentScore || 0,
            correctAnswers: session.opponentCorrectAnswers || 0,
            totalQuestions: session.opponentTotalQuestions || 0,
            timeTaken: session.opponentTimeTaken || 0,
            completedAt: session.opponentCompletedAt || 0,
            accuracy: session.opponentTotalQuestions > 0
                ? (session.opponentCorrectAnswers / session.opponentTotalQuestions) * 100
                : 0
        };
    }

    // Build final result if both completed
    var finalResult = null;
    if (session.creatorCompleted && session.opponentCompleted) {
        var creatorScore = session.creatorScore || 0;
        var opponentScore = session.opponentScore || 0;
        var isDraw = creatorScore === opponentScore;
        var creatorWins = creatorScore > opponentScore;

        var message;
        if (isDraw) {
            message = "It's a draw! Both players showed impressive skills!";
        } else if (creatorWins) {
            message = session.creatorName + " wins by " + (creatorScore - opponentScore) + " points!";
        } else {
            message = session.opponentName + " wins by " + (opponentScore - creatorScore) + " points!";
        }

        finalResult = {
            winnerId: isDraw ? null : (creatorWins ? session.creatorId : session.opponentId),
            winnerName: isDraw ? null : (creatorWins ? session.creatorName : session.opponentName),
            loserId: isDraw ? null : (creatorWins ? session.opponentId : session.creatorId),
            loserName: isDraw ? null : (creatorWins ? session.opponentName : session.creatorName),
            isDraw: isDraw,
            scoreDifference: Math.abs(creatorScore - opponentScore),
            creatorScore: creatorScore,
            opponentScore: opponentScore,
            creatorAccuracy: playerA.accuracy,
            opponentAccuracy: playerB ? playerB.accuracy : 0,
            creatorTimeTaken: session.creatorTimeTaken || 0,
            opponentTimeTaken: session.opponentTimeTaken || 0,
            message: message
        };
    }

    return {
        sessionId: session.sessionId || '',
        shareCode: session.shareCode || '',
        quizModeType: session.quizModeType || 0,
        quizModeName: session.quizModeName || 'Quiz',
        quizConfig: session.quizConfig || {},
        questions: session.questions || null,
        gameId: session.gameId || '',
        status: status,
        createdAt: session.createdAt || 0,
        expiresAt: session.expiresAt || 0,
        challengedUserId: session.challengedUserId || null,
        playerA: playerA,
        playerB: playerB,
        finalResult: finalResult
    };
}

/**
 * Count active challenges for a user (to enforce limits)
 * @param {object} nk - Nakama runtime context
 * @param {string} userId - User ID
 * @returns {number} Count of active challenges
 */
// ============================================================================
// ASYNC CHALLENGE STATE MACHINE
// ============================================================================
// Single source of truth for all session state transitions.
//
// RULE: No RPC may mutate session.status or session.*Completed directly.
//       All transitions MUST go through asyncChallengeTransitionState().
//       Adding new behavior? Add a new case here — nowhere else.
//
// Return shape: { ok, session, errorCode, error, shouldProcessRewards }
// The function is PURE — no storage I/O. RPCs own the read and OCC write.
// ============================================================================

var AC_EVT_JOIN            = 'JOIN';
var AC_EVT_CREATOR_SUBMIT  = 'CREATOR_SUBMIT';
var AC_EVT_OPPONENT_SUBMIT = 'OPPONENT_SUBMIT';
var AC_EVT_CANCEL          = 'CANCEL';
var AC_EVT_OPPONENT_LEAVE  = 'OPPONENT_LEAVE';

function asyncChallengeTransitionState(session, event, data) {
    var now = Date.now();
    var status = typeof session.status === 'number' ? session.status : 0;
    var userId = data.userId;

    // ── Guard: terminal states ──────────────────────────────────────────────
    if (status === ASYNC_STATUS_CANCELLED)
        return { ok: false, errorCode: 'TERMINAL', error: 'This challenge has been cancelled.' };
    if (status === ASYNC_STATUS_EXPIRED)
        return { ok: false, errorCode: 'TERMINAL', error: 'This challenge has expired.' };
    if (status === ASYNC_STATUS_BOTH_COMPLETED) {
        // Submit is idempotent even on completed sessions (offline-queue retry path).
        // CANCEL falls through to its own case below instead of being swallowed here —
        // that case returns the more specific errorCode='ALREADY_COMPLETED' (vs. this
        // guard's generic 'TERMINAL'), which is what async_challenge_state_machine_test.js
        // asserts. Before this fix the CANCEL case's ALREADY_COMPLETED branch (below) was
        // unreachable dead code because this guard always intercepted it first.
        if (event !== AC_EVT_CREATOR_SUBMIT && event !== AC_EVT_OPPONENT_SUBMIT && event !== AC_EVT_CANCEL)
            return { ok: false, errorCode: 'TERMINAL', error: 'Challenge is already completed.' };
    }

    // ── Guard: auto-expire non-terminal sessions ────────────────────────────
    if (status !== ASYNC_STATUS_BOTH_COMPLETED && now > session.expiresAt) {
        session.status = ASYNC_STATUS_EXPIRED;
        return { ok: false, errorCode: 'EXPIRED', error: 'This challenge has expired.' };
    }

    switch (event) {
        // ── JOIN ─────────────────────────────────────────────────────────────
        case AC_EVT_JOIN: {
            if (session.creatorId === userId)
                return { ok: false, errorCode: 'SELF_JOIN', error: 'You cannot join your own challenge.' };

            // Idempotent: this user is already the opponent.
            if (session.opponentId === userId)
                return { ok: true, session: session, errorCode: 'ALREADY_JOINED', error: null, shouldProcessRewards: false };

            if (session.opponentId !== null)
                return { ok: false, errorCode: 'ALREADY_FULL', error: 'This challenge already has an opponent.' };

            // Targeted invite: only specific user may join.
            if (session.challengedUserId && session.challengedUserId !== userId)
                return { ok: false, errorCode: 'WRONG_PLAYER', error: 'This challenge is meant for a specific player.' };

            // Only joinable from WAITING or CREATOR_PLAYED.
            if (status !== ASYNC_STATUS_WAITING && status !== ASYNC_STATUS_CREATOR_PLAYED)
                return { ok: false, errorCode: 'INVALID_STATE', error: 'Cannot join challenge in its current state.' };

            session.opponentId   = userId;
            session.opponentName = data.displayName || 'Player B';
            session.opponentJoinedAt = now;
            session.opponentLobbySeenAt = now;
            session.opponentLobbyHeartbeatCount = 0;
            // Keep CREATOR_PLAYED so clients know the creator already has a score waiting.
            if (status !== ASYNC_STATUS_CREATOR_PLAYED)
                session.status = ASYNC_STATUS_OPPONENT_JOINED;

            return { ok: true, session: session, errorCode: null, error: null, shouldProcessRewards: false };
        }

        // ── CREATOR_SUBMIT ────────────────────────────────────────────────────
        case AC_EVT_CREATOR_SUBMIT: {
            if (session.creatorId !== userId)
                return { ok: false, errorCode: 'NOT_PARTICIPANT', error: 'Not authorized for this challenge.' };

            // Idempotent: creator already submitted — return existing state unchanged.
            if (session.creatorCompleted)
                return { ok: true, session: session, errorCode: 'ALREADY_SUBMITTED', error: null, shouldProcessRewards: false };

            session.creatorCompleted      = true;
            session.creatorScore          = data.score;
            session.creatorCorrectAnswers = data.correctAnswers;
            session.creatorTotalQuestions = data.totalQuestions;
            session.creatorTimeTaken      = data.timeTaken;
            session.creatorCompletedAt    = now;

            var cRewards = false;
            if (session.opponentCompleted) {
                session.status = ASYNC_STATUS_BOTH_COMPLETED;
                if (!session.rewardsProcessed) { session.rewardsProcessed = true; cRewards = true; }
            } else if (!session.opponentId) {
                // Creator played solo (nobody joined yet) — surface this state to clients.
                session.status = ASYNC_STATUS_CREATOR_PLAYED;
            }
            // If opponentId exists but opponent hasn't completed, status stays OPPONENT_JOINED.
            return { ok: true, session: session, errorCode: null, error: null, shouldProcessRewards: cRewards };
        }

        // ── OPPONENT_SUBMIT ──────────────────────────────────────────────────
        case AC_EVT_OPPONENT_SUBMIT: {
            if (session.opponentId !== userId)
                return { ok: false, errorCode: 'NOT_PARTICIPANT', error: 'Not authorized for this challenge.' };

            // Idempotent: opponent already submitted.
            if (session.opponentCompleted)
                return { ok: true, session: session, errorCode: 'ALREADY_SUBMITTED', error: null, shouldProcessRewards: false };

            session.opponentCompleted      = true;
            session.opponentScore          = data.score;
            session.opponentCorrectAnswers = data.correctAnswers;
            session.opponentTotalQuestions = data.totalQuestions;
            session.opponentTimeTaken      = data.timeTaken;
            session.opponentCompletedAt    = now;

            var oRewards = false;
            if (session.creatorCompleted) {
                session.status = ASYNC_STATUS_BOTH_COMPLETED;
                if (!session.rewardsProcessed) { session.rewardsProcessed = true; oRewards = true; }
            }
            // If creator hasn't submitted yet, status stays OPPONENT_JOINED.
            return { ok: true, session: session, errorCode: null, error: null, shouldProcessRewards: oRewards };
        }

        // ── CANCEL ──────────────────────────────────────────────────────────
        case AC_EVT_CANCEL: {
            if (session.creatorId !== userId)
                return { ok: false, errorCode: 'NOT_CREATOR', error: 'Only the challenge creator can cancel.' };
            if (status === ASYNC_STATUS_BOTH_COMPLETED)
                return { ok: false, errorCode: 'ALREADY_COMPLETED', error: 'Cannot cancel a completed challenge.' };

            session.status = ASYNC_STATUS_CANCELLED;
            return { ok: true, session: session, errorCode: null, error: null, shouldProcessRewards: false };
        }

        // ── OPPONENT_LEAVE ────────────────────────────────────────────────────
        // Opponent voluntarily leaves the lobby before any quiz is played.
        // Resets the session back to WaitingForOpponent so the room becomes
        // joinable again. Only allowed while no quiz results have been submitted.
        case AC_EVT_OPPONENT_LEAVE: {
            if (session.opponentId !== userId)
                return { ok: false, errorCode: 'NOT_PARTICIPANT', error: 'Only the joined opponent can leave.' };

            // Cannot leave if the opponent has already submitted results.
            if (session.opponentCompleted)
                return { ok: false, errorCode: 'ALREADY_SUBMITTED', error: 'Cannot leave after submitting results.' };

            // Revert status: if creator has played solo, keep CreatorPlayed; otherwise back to Waiting.
            session.status       = (status === ASYNC_STATUS_CREATOR_PLAYED)
                                   ? ASYNC_STATUS_CREATOR_PLAYED
                                   : ASYNC_STATUS_WAITING;
            session.opponentId   = null;
            session.opponentName = null;

            return { ok: true, session: session, errorCode: null, error: null, shouldProcessRewards: false };
        }

        default:
            return { ok: false, errorCode: 'UNKNOWN_EVENT', error: 'Unknown event: ' + event };
    }
}

// ============================================================================
// IDEMPOTENCY HELPERS
// ============================================================================
// Prevents double processing of the same user action (double-tap, network retry,
// offline queue replay). Key format: `idem_{rpcId}_{userId}_{scopeId}`.
// TTL = 30 minutes (enough for any retry window; stale entries auto-ignored).
// Storage writes are non-blocking — a miss is safe (just re-processes idempotently
// via the state machine's own ALREADY_SUBMITTED/ALREADY_JOINED guards).
// ============================================================================

var COLLECTION_ASYNC_IDEMPOTENCY = 'async_idempotency';
var ASYNC_IDEMPOTENCY_TTL_MS = 30 * 60 * 1000; // 30 minutes

function asyncChallengeReadIdempotency(nk, key) {
    try {
        var r = nk.storageRead([{ collection: COLLECTION_ASYNC_IDEMPOTENCY, key: key, userId: ASYNC_CHALLENGE_SYSTEM_USER }]);
        if (r.length > 0 && r[0].value && (Date.now() - (r[0].value.at || 0)) < ASYNC_IDEMPOTENCY_TTL_MS)
            return r[0].value.resp; // cached JSON response string
    } catch (_) {}
    return null;
}

function asyncChallengeWriteIdempotency(nk, key, responseJson) {
    try {
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_IDEMPOTENCY,
            key: key,
            userId: ASYNC_CHALLENGE_SYSTEM_USER,
            value: { resp: responseJson, at: Date.now() },
            permissionRead: 0,
            permissionWrite: 0
        }]);
    } catch (_) {}
}

/**
 * Resolve session id from RPC payload (Unity docs use challengeId alias).
 * @param {object} request - Parsed JSON payload
 * @returns {string|null}
 */
function asyncChallengeResolveSessionId(request) {
    if (!request) return null;
    return request.sessionId || request.SessionId || request.challengeId || request.ChallengeId || null;
}

/**
 * Purge cached join idempotency so a user can rejoin after leaving.
 */
function asyncChallengePurgeJoinIdempotency(nk, logger, opponentId, sessionId) {
    var idemKey = 'join_' + opponentId + '_' + sessionId;
    try {
        nk.storageDelete([{
            collection: COLLECTION_ASYNC_IDEMPOTENCY,
            key: idemKey,
            userId: ASYNC_CHALLENGE_SYSTEM_USER
        }]);
        if (logger) logger.debug('[AsyncChallenge] idempotency purge key=' + idemKey);
    } catch (err) {
        if (logger) logger.warn('[AsyncChallenge] idempotency purge failed key=' + idemKey + ' err=' + err.message);
    }
}

/**
 * Read canonical player presence record (player_presence/status).
 */
function asyncChallengeReadOpponentPresence(nk, opponentId) {
    try {
        var results = nk.storageRead([{
            collection: 'player_presence',
            key: 'status',
            userId: opponentId
        }]);
        if (results.length > 0 && results[0].value) return results[0].value;
    } catch (_) {}
    return null;
}

/**
 * True when a lobby opponent should be evicted (conservative rules — no time-only eviction).
 */
function asyncChallengeIsLobbyOpponentStale(nk, logger, session) {
    if (!session || !session.opponentId || session.opponentCompleted) return false;

    var status = typeof session.status === 'number' ? session.status : 0;
    var inLobby = status === ASYNC_STATUS_OPPONENT_JOINED ||
        (status === ASYNC_STATUS_CREATOR_PLAYED && session.opponentId);
    if (!inLobby) return false;

    var now = Date.now();
    var joinedAt = session.opponentJoinedAt || 0;
    if (joinedAt > 0 && (now - joinedAt) < 10000) return false;

    var presence = asyncChallengeReadOpponentPresence(nk, session.opponentId);
    var lobbySeenAt = session.opponentLobbySeenAt || 0;
    var heartbeatCount = session.opponentLobbyHeartbeatCount || 0;
    var hasHeartbeated = heartbeatCount > 0 || (joinedAt > 0 && lobbySeenAt > joinedAt + 5000);
    var stale = false;

    if (presence && presence.online === false) {
        stale = true;
    } else if (presence && typeof presence.lastSeenMs === 'number' && presence.lastSeenMs > 0 &&
        (now - presence.lastSeenMs) > 90000 && hasHeartbeated) {
        stale = true;
    } else if (hasHeartbeated && lobbySeenAt > 0 && (now - lobbySeenAt) > 45000) {
        stale = true;
    }

    if (logger) {
        logger.debug('[AsyncChallenge] stale_check session=' + (session.sessionId || '?') +
            ' opponent=' + session.opponentId +
            ' online=' + (presence ? String(presence.online) : 'unknown') +
            ' lastSeenMs=' + (presence && presence.lastSeenMs ? presence.lastSeenMs : 0) +
            ' lobbySeenAgeMs=' + (lobbySeenAt > 0 ? (now - lobbySeenAt) : -1) +
            ' heartbeatCount=' + heartbeatCount +
            ' stale=' + stale);
    }

    return stale;
}

/**
 * Single write path for opponent leave (explicit or stale eviction).
 */
function asyncChallengeCommitOpponentLeave(nk, logger, sessionId, creatorId, session, version, leavingOpponentId, leavingOpponentName, reason) {
    var leaveTransition = asyncChallengeTransitionState(session, AC_EVT_OPPONENT_LEAVE, { userId: leavingOpponentId });
    if (!leaveTransition.ok) {
        return {
            ok: false,
            errorCode: leaveTransition.errorCode,
            error: leaveTransition.error,
            session: session,
            version: version
        };
    }

    var updatedSession = leaveTransition.session;

    try {
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: creatorId,
            value: updatedSession,
            version: version,
            permissionRead: 2,
            permissionWrite: 1
        }]);
    } catch (versionErr) {
        return {
            ok: false,
            errorCode: 'VERSION_CONFLICT',
            error: 'Conflict leaving — please try again.',
            session: session,
            version: version
        };
    }

    try {
        var idxRead = nk.storageRead([{
            collection: COLLECTION_ASYNC_INDEX,
            key: 'opponent_' + leavingOpponentId,
            userId: leavingOpponentId
        }]);
        if (idxRead.length > 0) {
            var idxVal = idxRead[0].value;
            idxVal.sessions = (idxVal.sessions || []).filter(function(s) { return s.sessionId !== sessionId; });
            nk.storageWrite([{
                collection: COLLECTION_ASYNC_INDEX,
                key: 'opponent_' + leavingOpponentId,
                userId: leavingOpponentId,
                value: idxVal,
                version: idxRead[0].version,
                permissionRead: 1,
                permissionWrite: 1
            }]);
        }
    } catch (idxCleanErr) {
        logger.warn('[AsyncChallenge] Leave: could not clean opponent index: ' + idxCleanErr.message);
    }

    asyncChallengePurgeJoinIdempotency(nk, logger, leavingOpponentId, sessionId);

    var formattedSession = asyncChallengeSessionToUnityFormat(updatedSession, nk);
    // ctx not in scope in this helper — null skips the device-push bridge,
    // which is correct: opponent_left is an in-app-only event (AP-001 budget).
    asyncChallengeSendNotification(null, nk, updatedSession.creatorId,
        'Opponent Left',
        (leavingOpponentName || 'Player B') + ' has left your ' + updatedSession.quizModeName + ' challenge room. Waiting for a new opponent.',
        {
            type: 'opponent_left',
            sessionId: sessionId,
            opponentId: leavingOpponentId,
            opponentName: leavingOpponentName || 'Player B',
            session: formattedSession
        },
        logger
    );

    logger.info('[AsyncChallenge] leave ok reason=' + reason + ' session=' + sessionId +
        ' creator=' + creatorId + ' opponent=' + leavingOpponentId);

    return { ok: true, session: updatedSession, version: null, errorCode: null, error: null };
}

function asyncChallengeCountActive(nk, userId) {
    // Active = not yet terminal (BothCompleted=2, Expired=3, Cancelled=4) AND not past expiresAt.
    // CreatorPlayed (5) IS an active room (creator has played, waiting for opponent) and must
    // be counted. Using IN list instead of < avoids accidentally counting future status codes.
    var ACTIVE_STATUSES = [
        ASYNC_STATUS_WAITING,          // 0
        ASYNC_STATUS_OPPONENT_JOINED,  // 1
        ASYNC_STATUS_CREATOR_PLAYED    // 5
    ];
    var nowMs = Date.now();

    try {
        var rows = nk.sqlQuery(
            "SELECT COUNT(*) AS cnt FROM storage " +
            "WHERE collection = $1 AND user_id = $2 " +
            "AND (value->>'status')::int = ANY($3::int[]) " +
            "AND (value->>'expiresAt')::bigint > $4 " +
            "AND key NOT LIKE 'code_%'",
            [COLLECTION_ASYNC_CHALLENGES, userId, '{' + ACTIVE_STATUSES.join(',') + '}', nowMs]
        );
        if (rows && rows.length > 0) {
            return parseInt(rows[0].cnt, 10) || 0;
        }
    } catch (sqlErr) {
        // SQL failed — fall back to in-memory scan.
        try {
            var result = nk.storageList(userId, COLLECTION_ASYNC_CHALLENGES, 200, '');
            var count = 0;
            var objects = result.objects || [];
            for (var i = 0; i < objects.length; i++) {
                var obj = objects[i];
                if (obj.key.indexOf('code_') === 0) continue;
                var s = obj.value;
                if (typeof s.status === 'number'
                    && ACTIVE_STATUSES.indexOf(s.status) >= 0
                    && nowMs < s.expiresAt) {
                    count++;
                }
            }
            return count;
        } catch (_) { return 0; }
    }
    return 0;
}

// ============================================================================
// RPC: async_challenge_create - Create a new async challenge
// ============================================================================
/**
 * Create a new async challenge session
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { quizModeType, quizModeName, quizConfig?, challengedUserId?, challengedDisplayName?, playerDisplayName?, userId? }
 * @returns {string} JSON response with session data
 */
function rpcAsyncChallengeCreate(ctx, logger, nk, payload) {
    logger.info('[SZ-DIAG][SERVER][AsyncChallengeCreate] start user=' + ctx.userId);

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            logger.warn('[SZ-DIAG][SERVER][AsyncChallengeCreate] auth failed: ' + userValidation.error);
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        // Check active challenge limit
        var activeCount = asyncChallengeCountActive(nk, userId);
        if (activeCount >= ASYNC_CHALLENGE_MAX_PER_USER) {
            logger.warn('[SZ-DIAG][SERVER][AsyncChallengeCreate] MAX_CHALLENGES user=' + userId + ' active=' + activeCount);
            return JSON.stringify({
                success: false,
                message: 'Maximum active challenges reached (' + ASYNC_CHALLENGE_MAX_PER_USER + '). Please complete or cancel existing challenges.',
                data: null,
                errorCode: 'MAX_CHALLENGES'
            });
        }

        // Rate-limit: enforce minimum gap between consecutive challenge creations.
        // Guards against spamming without blocking normal cancel-and-retry flows.
        if (ASYNC_CHALLENGE_RATE_LIMIT_MINUTES > 0) {
            try {
                var rlStats = asyncChallengeGetStats(nk, userId);
                var minGapMs = ASYNC_CHALLENGE_RATE_LIMIT_MINUTES * 60 * 1000;
                var msSinceLast = Date.now() - (rlStats.lastChallengeAt || 0);
                // Guard: if msSinceLast is negative the stored timestamp is in the future
                // (server clock drift / data anomaly). Reset silently — don't block the user.
                if (msSinceLast < 0) msSinceLast = minGapMs + 1;
                if (msSinceLast < minGapMs) {
                    var secsLeft = Math.ceil((minGapMs - msSinceLast) / 1000);
                    logger.warn('[SZ-DIAG][SERVER][AsyncChallengeCreate] RATE_LIMITED user=' + userId + ' waitSec=' + secsLeft);
                    return JSON.stringify({
                        success: false,
                        message: 'Please wait ' + secsLeft + ' second(s) before creating another challenge.',
                        data: null,
                        errorCode: 'RATE_LIMITED'
                    });
                }
            } catch (rlErr) {
                // Stats read failure — allow the create to proceed (non-critical gate).
            }
        }

        // Extract challenge parameters
        var quizModeType = request.quizModeType || request.QuizModeType || 0;
        var quizModeName = request.quizModeName || request.QuizModeName || 'Quiz';
        var quizConfig = request.quizConfig || request.QuizConfig || {};
        var challengedUserId = request.challengedUserId || request.ChallengedUserId || null;
        var challengedDisplayName = request.challengedDisplayName || request.ChallengedDisplayName || null;
        var playerDisplayName = request.playerDisplayName || request.PlayerDisplayName || 'Unknown';

        logger.info(
            '[SZ-DIAG][SERVER][AsyncChallengeCreate] params user=' + userId +
            ' modeType=' + quizModeType +
            ' modeName=' + quizModeName +
            ' challengedUserId=' + (challengedUserId || '<none>') +
            ' challengedDisplayName=' + (challengedDisplayName || '<none>')
        );

        // Generate session ID and share code
        var sessionId = nk.uuidv4();
        var shareCode = asyncChallengeGenerateShareCode(nk);
        var now = Date.now();
        var expiresAt = now + (ASYNC_CHALLENGE_EXPIRY_HOURS * 60 * 60 * 1000);

        // Fetch creator display name
        var creatorName = asyncChallengeGetDisplayName(nk, userId, playerDisplayName);

        // Build session storage object
        var sessionStorage = {
            sessionId: sessionId,
            shareCode: shareCode,
            quizModeType: quizModeType,
            quizModeName: quizModeName,
            quizConfig: quizConfig,
            gameId: quizConfig.gameId || '',
            questions: null,
            creatorId: userId,
            creatorName: creatorName,
            opponentId: null,
            opponentName: null,
            challengedUserId: challengedUserId,
            challengedDisplayName: challengedDisplayName,
            status: ASYNC_STATUS_WAITING,
            createdAt: now,
            expiresAt: expiresAt,
            // Creator results
            creatorCompleted: false,
            creatorScore: 0,
            creatorCorrectAnswers: 0,
            creatorTotalQuestions: 0,
            creatorTimeTaken: 0,
            creatorCompletedAt: 0,
            // Opponent results
            opponentCompleted: false,
            opponentScore: 0,
            opponentCorrectAnswers: 0,
            opponentTotalQuestions: 0,
            opponentTimeTaken: 0,
            opponentCompletedAt: 0
        };

        // Store session with creator's user ID
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId,
            value: sessionStorage,
            permissionRead: 2, // Public read
            permissionWrite: 1 // Owner write
        }]);

        // Store share code mapping for public lookup
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: 'code_' + shareCode,
            userId: ASYNC_CHALLENGE_SYSTEM_USER,
            value: { sessionId: sessionId, creatorId: userId },
            permissionRead: 2,
            permissionWrite: 0
        }]);

        // Send notification to challenged user if specified
        if (challengedUserId && challengedUserId !== userId) {
            asyncChallengeSendNotification(ctx, nk, challengedUserId,
                'Challenge Received!',
                creatorName + ' challenges you to a ' + quizModeName + ' battle!',
                {
                    type: 'challenge_received',
                    sessionId: sessionId,
                    shareCode: shareCode,
                    challengerId: userId,
                    challengerName: creatorName,
                    quizModeName: quizModeName
                }
            );
        }

        // Stamp lastChallengeAt for rate-limiting on the next create attempt.
        try {
            var createStats = asyncChallengeGetStats(nk, userId);
            createStats.lastChallengeAt = now;
            asyncChallengeSaveStats(nk, userId, createStats);
        } catch (stampErr) {
            // Non-critical — rate limit just won't fire on the very next attempt.
        }

        logger.info('[AsyncChallenge] Session created: ' + sessionId + ' code: ' + shareCode + ' by user: ' + userId);
        logger.info(
            '[SZ-DIAG][SERVER][AsyncChallengeCreate] OK sessionId=' + sessionId +
            ' shareCode=' + shareCode +
            ' creatorId=' + userId +
            ' challengedUserId=' + (challengedUserId || '<none>') +
            ' opponentId=null_until_join' +
            ' notified=' + !!(challengedUserId && challengedUserId !== userId) +
            ' NOTE: Unity HandleChallengeCreated checks PlayerB (null here) not ChallengedUserId'
        );

        return JSON.stringify({
            success: true,
            message: 'Challenge created successfully',
            data: asyncChallengeSessionToUnityFormat(sessionStorage, nk)
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Create error: ' + err.message);
        logger.error('[SZ-DIAG][SERVER][AsyncChallengeCreate] FAIL user=' + (ctx && ctx.userId) + ' err=' + err.message);
        logRpcError(nk, logger, 'async_challenge_create', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_join - Join an existing async challenge
// ============================================================================
/**
 * Join an existing async challenge by share code
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { shareCode, playerDisplayName?, userId? }
 * @returns {string} JSON response with session data
 */
function rpcAsyncChallengeJoin(ctx, logger, nk, payload) {
    logger.debug('[AsyncChallenge] User ' + ctx.userId + ' attempting to join challenge');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        // Validate share code
        var shareCode = (request.shareCode || request.ShareCode || '').toUpperCase().trim();
        if (!shareCode || shareCode.length < 6) {
            return JSON.stringify({
                success: false,
                message: 'Invalid share code. Please enter a valid 6-character code.',
                data: null
            });
        }

        // Look up session by share code
        var codeResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: 'code_' + shareCode,
            userId: ASYNC_CHALLENGE_SYSTEM_USER
        }]);

        if (codeResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Challenge not found. Please check the code and try again.',
                data: null
            });
        }

        var codeRecord = codeResults[0].value;
        var sessionId = codeRecord.sessionId;
        var creatorId = codeRecord.creatorId;

        // Read the session
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: creatorId
        }]);

        if (sessionResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Challenge session not found.',
                data: null
            });
        }

        var session = sessionResults[0].value;
        var sessionVersion = sessionResults[0].version; // for OCC write

        // ── Idempotency check ─────────────────────────────────────────────────
        // Key: join attempts are scoped to userId+sessionId so a double-tap by the
        // same user on the same session returns the cached success immediately.
        var idemKey = 'join_' + userId + '_' + sessionId;
        var cached = asyncChallengeReadIdempotency(nk, idemKey);
        if (cached) return cached;

        // ── Resolve display name ──────────────────────────────────────────────
        var playerDisplayName = request.playerDisplayName || request.PlayerDisplayName || 'Unknown';
        var opponentName = asyncChallengeGetDisplayName(nk, userId, playerDisplayName);

        // ── State machine transition ──────────────────────────────────────────
        var transition = asyncChallengeTransitionState(session, AC_EVT_JOIN, { userId: userId, displayName: opponentName });
        var staleEvictJoinAttempt = 0;

        while (!transition.ok && transition.errorCode === 'ALREADY_FULL' &&
               session.opponentId && session.opponentId !== userId && staleEvictJoinAttempt < 1) {
            if (!asyncChallengeIsLobbyOpponentStale(nk, logger, session)) break;

            var staleJoinOppId = session.opponentId;
            var staleJoinOppName = session.opponentName || 'Player B';
            logger.info('[AsyncChallenge] stale_evict reason=stale_evict_join session=' + sessionId +
                ' opponent=' + staleJoinOppId + ' triggerUser=' + userId);
            var evictJoinResult = asyncChallengeCommitOpponentLeave(
                nk, logger, sessionId, creatorId, session, sessionVersion,
                staleJoinOppId, staleJoinOppName, 'stale_evict_join'
            );
            if (!evictJoinResult.ok) break;

            staleEvictJoinAttempt++;
            logger.info('[AsyncChallenge] join retry after stale_evict session=' + sessionId + ' newJoiner=' + userId);
            var retryJoinRead = nk.storageRead([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: sessionId,
                userId: creatorId
            }]);
            if (retryJoinRead.length === 0) break;
            session = retryJoinRead[0].value;
            sessionVersion = retryJoinRead[0].version;
            transition = asyncChallengeTransitionState(session, AC_EVT_JOIN, { userId: userId, displayName: opponentName });
        }

        if (!transition.ok) {
            if (transition.errorCode === 'ALREADY_FULL') {
                logger.warn('[AsyncChallenge] join ALREADY_FULL session=' + sessionId +
                    ' opponent=' + (session.opponentId || '?') + ' joiner=' + userId);
            }
            return JSON.stringify({
                success: false,
                message: transition.error,
                data: null,
                errorCode: transition.errorCode
            });
        }

        // ALREADY_JOINED = idempotent success (no write needed)
        if (transition.errorCode === 'ALREADY_JOINED') {
            var alreadyResp = JSON.stringify({ success: true, message: 'Already joined this challenge', data: asyncChallengeSessionToUnityFormat(session, nk) });
            asyncChallengeWriteIdempotency(nk, idemKey, alreadyResp);
            return alreadyResp;
        }

        // ── OCC write ─────────────────────────────────────────────────────────
        try {
            nk.storageWrite([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: sessionId,
                userId: creatorId,
                value: transition.session,
                version: sessionVersion,
                permissionRead: 2,
                permissionWrite: 1
            }]);
        } catch (versionErr) {
            // Concurrent join — re-read and check if WE are now the recorded opponent.
            var freshRead = nk.storageRead([{ collection: COLLECTION_ASYNC_CHALLENGES, key: sessionId, userId: creatorId }]);
            var freshSess = freshRead.length > 0 ? freshRead[0].value : null;
            if (freshSess && freshSess.opponentId === userId) {
                var concurrentOkResp = JSON.stringify({ success: true, message: 'Joined this challenge', data: asyncChallengeSessionToUnityFormat(freshSess, nk) });
                asyncChallengeWriteIdempotency(nk, idemKey, concurrentOkResp);
                return concurrentOkResp;
            }
            return JSON.stringify({ success: false, message: 'Someone else joined at the same time. Please try again.', data: null, errorCode: 'CONCURRENT_JOIN' });
        }

        session = transition.session;

        // Index opponent so they can be found via O(1) lookup instead of full scan
        try {
            asyncChallengeIndexOpponent(nk, userId, sessionId, creatorId);
        } catch (indexErr) {
            logger.warn('[AsyncChallenge] Failed to index opponent: ' + indexErr.message);
            // Non-fatal: session is already saved, just lookup will be slower
        }

        // Notify creator that opponent joined
        asyncChallengeSendNotification(ctx, nk, session.creatorId,
            'Challenge Accepted!',
            opponentName + ' has joined your ' + session.quizModeName + ' challenge!',
            {
                type: 'opponent_joined',
                sessionId: sessionId,
                opponentId: userId,
                opponentName: opponentName
            }
        );

        logger.info('[AsyncChallenge] User ' + userId + ' joined session: ' + sessionId);

        var joinResp = JSON.stringify({
            success: true,
            message: 'Successfully joined challenge',
            data: asyncChallengeSessionToUnityFormat(session, nk)
        });
        asyncChallengeWriteIdempotency(nk, idemKey, joinResp);
        return joinResp;
    } catch (err) {
        logger.error('[AsyncChallenge] Join error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_join', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_get - Get challenge session details
// ============================================================================
/**
 * Get async challenge session details
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { sessionId?, shareCode?, userId? }
 * @returns {string} JSON response with session data
 */
function rpcAsyncChallengeGet(ctx, logger, nk, payload) {
    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        var sessionId = asyncChallengeResolveSessionId(request);
        var creatorId = null;

        // If no sessionId, try to find by share code
        if (!sessionId && (request.shareCode || request.ShareCode)) {
            var shareCode = (request.shareCode || request.ShareCode).toUpperCase().trim();
            var codeResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: 'code_' + shareCode,
                userId: ASYNC_CHALLENGE_SYSTEM_USER
            }]);

            if (codeResults.length === 0) {
                return JSON.stringify({
                    success: false,
                    message: 'Challenge not found.',
                    data: null
                });
            }

            sessionId = codeResults[0].value.sessionId;
            creatorId = codeResults[0].value.creatorId;
        }

        if (!sessionId) {
            return JSON.stringify({
                success: false,
                message: 'Session ID or share code required.',
                data: null
            });
        }

        // Try reading with user ID first
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId
        }]);

        // If not found as owner, try with creator ID
        if (sessionResults.length === 0 && creatorId) {
            sessionResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: sessionId,
                userId: creatorId
            }]);
        }

        // If still not found, check opponent index (O(1) instead of full scan)
        if (sessionResults.length === 0) {
            try {
                var indexResults = nk.storageRead([{
                    collection: COLLECTION_ASYNC_INDEX,
                    key: 'opponent_' + userId,
                    userId: userId
                }]);
                if (indexResults.length > 0) {
                    var index = indexResults[0].value;
                    for (var idx = 0; idx < index.sessions.length; idx++) {
                        if (index.sessions[idx].sessionId === sessionId) {
                            sessionResults = nk.storageRead([{
                                collection: COLLECTION_ASYNC_CHALLENGES,
                                key: sessionId,
                                userId: index.sessions[idx].creatorId
                            }]);
                            break;
                        }
                    }
                }
            } catch (indexErr) {
                logger.warn('[AsyncChallenge] Opponent index lookup failed: ' + indexErr.message);
            }
        }

        // SQL fallback for old sessions without index entries
        if (sessionResults.length === 0) {
            var fallbackSession = asyncChallengeFindSessionByKey(nk, logger, sessionId);
            if (fallbackSession) {
                sessionResults = [{ value: fallbackSession }];
            }
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Challenge not found.',
                data: null
            });
        }

        var session = sessionResults[0].value;
        var sessionVersion = sessionResults[0].version;

        // Authorization check - user must be creator or opponent
        if (session.creatorId !== userId && session.opponentId !== userId) {
            return JSON.stringify({
                success: false,
                message: 'Not authorized to view this challenge.',
                data: null
            });
        }

        // Stale opponent eviction (creator poll path).
        if (session.creatorId === userId && asyncChallengeIsLobbyOpponentStale(nk, logger, session)) {
            var staleGetOppId = session.opponentId;
            var staleGetOppName = session.opponentName || 'Player B';
            logger.info('[AsyncChallenge] stale_evict reason=stale_evict_get session=' + sessionId +
                ' opponent=' + staleGetOppId + ' triggerUser=' + userId);
            var evictGetResult = asyncChallengeCommitOpponentLeave(
                nk, logger, sessionId, session.creatorId, session, sessionVersion,
                staleGetOppId, staleGetOppName, 'stale_evict_get'
            );
            if (evictGetResult.ok) {
                var refreshedGetRead = nk.storageRead([{
                    collection: COLLECTION_ASYNC_CHALLENGES,
                    key: sessionId,
                    userId: session.creatorId
                }]);
                if (refreshedGetRead.length > 0) {
                    session = refreshedGetRead[0].value;
                    sessionVersion = refreshedGetRead[0].version;
                } else {
                    session = evictGetResult.session;
                }
            }
        }

        // Opponent lobby heartbeat — bump seen-at on get polls (pre-play only).
        if (session.opponentId === userId && !session.opponentCompleted) {
            var getStatus = typeof session.status === 'number' ? session.status : 0;
            var inPrePlayLobby = getStatus === ASYNC_STATUS_OPPONENT_JOINED ||
                getStatus === ASYNC_STATUS_CREATOR_PLAYED;
            if (inPrePlayLobby) {
                session.opponentLobbySeenAt = Date.now();
                session.opponentLobbyHeartbeatCount = (session.opponentLobbyHeartbeatCount || 0) + 1;
                try {
                    nk.storageWrite([{
                        collection: COLLECTION_ASYNC_CHALLENGES,
                        key: sessionId,
                        userId: session.creatorId,
                        value: session,
                        version: sessionVersion,
                        permissionRead: 2,
                        permissionWrite: 1
                    }]);
                } catch (hbErr) {
                    // Non-fatal on version conflict — serve the read snapshot.
                }
            }
        }

        return JSON.stringify({
            success: true,
            message: 'Challenge retrieved',
            data: asyncChallengeSessionToUnityFormat(session, nk)
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Get error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_get', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_submit - Submit quiz results for a challenge
// ============================================================================
/**
 * Submit quiz results for an async challenge
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { sessionId, score, correctAnswers, totalQuestions, timeTaken, accuracy?, userId? }
 * @returns {string} JSON response with updated session data
 */
function rpcAsyncChallengeSubmit(ctx, logger, nk, payload) {
    logger.debug('[AsyncChallenge] User ' + ctx.userId + ' submitting results');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        // Validate required fields
        var sessionId = request.sessionId || request.SessionId;
        if (!sessionId) {
            return JSON.stringify({
                success: false,
                message: 'Session ID required.',
                data: null
            });
        }

        var score = typeof request.score === 'number' ? request.score : (request.Score || 0);
        var correctAnswers = typeof request.correctAnswers === 'number' ? request.correctAnswers : (request.CorrectAnswers || 0);
        var totalQuestions = typeof request.totalQuestions === 'number' ? request.totalQuestions : (request.TotalQuestions || 0);
        var timeTaken = typeof request.timeTaken === 'number' ? request.timeTaken : (request.TimeTaken || 0);

        // Server-side score validation: reject obviously impossible values
        if (score < 0 || score > 100000 || correctAnswers < 0 || totalQuestions < 0 || timeTaken < 0) {
            return JSON.stringify({
                success: false,
                message: 'Invalid score data.',
                data: null
            });
        }
        if (correctAnswers > totalQuestions) {
            return JSON.stringify({
                success: false,
                message: 'Correct answers cannot exceed total questions.',
                data: null
            });
        }

        // Find the session — first try as owner (creator)
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId
        }]);

        var creatorId = userId;
        var isCreator = sessionResults.length > 0;

        // If not found as owner, use opponent index to find the creator
        if (!isCreator) {
            var foundViaIndex = false;
            // Method 1: Check opponent index (fast O(1) lookup)
            try {
                var indexResults = nk.storageRead([{
                    collection: COLLECTION_ASYNC_INDEX,
                    key: 'opponent_' + userId,
                    userId: userId
                }]);
                if (indexResults.length > 0) {
                    var index = indexResults[0].value;
                    for (var idx = 0; idx < index.sessions.length; idx++) {
                        if (index.sessions[idx].sessionId === sessionId) {
                            creatorId = index.sessions[idx].creatorId;
                            sessionResults = nk.storageRead([{
                                collection: COLLECTION_ASYNC_CHALLENGES,
                                key: sessionId,
                                userId: creatorId
                            }]);
                            foundViaIndex = true;
                            break;
                        }
                    }
                }
            } catch (indexErr) {
                logger.warn('[AsyncChallenge] Opponent index lookup failed: ' + indexErr.message);
            }

            // Method 2: SQL fallback for old sessions without index entries
            if (!foundViaIndex || sessionResults.length === 0) {
                var fallbackSession = asyncChallengeFindSessionByKey(nk, logger, sessionId);
                if (fallbackSession) {
                    creatorId = fallbackSession.creatorId;
                    sessionResults = [{ value: fallbackSession }];
                }
            }
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Challenge not found.',
                data: null
            });
        }

        var session = sessionResults[0].value;
        var submitVersion = sessionResults[0].version; // for OCC write

        // ── Participant check (fast-fail before idempotency store) ────────────
        var isCreator  = session.creatorId  === userId;
        var isOpponent = session.opponentId === userId;
        if (!isCreator && !isOpponent) {
            return JSON.stringify({ success: false, message: 'Not authorized for this challenge.', data: null });
        }

        // ── Idempotency check ─────────────────────────────────────────────────
        // Key scoped to userId+sessionId: a retry of the exact same submit returns
        // the cached response instead of hitting the OCC write again.
        var submitIdemKey = 'submit_' + userId + '_' + sessionId;
        var submitCached = asyncChallengeReadIdempotency(nk, submitIdemKey);
        if (submitCached) return submitCached;

        // ── Score bounds validation ───────────────────────────────────────────
        // When the host stored questions server-side, we can verify the submission
        // doesn't claim more questions than were served, which catches stale retries
        // and obviously spoofed payloads.
        if (session.questions && session.questions.length > 0) {
            var storedQCount = session.questions.length;
            if (totalQuestions > storedQCount) {
                logger.warn('[AsyncChallenge] Submit totalQuestions ' + totalQuestions + ' > stored ' + storedQCount + ' for session ' + sessionId);
                return JSON.stringify({ success: false, message: 'Question count exceeds the stored question set.', data: null, errorCode: 'SCORE_TAMPERED' });
            }
            // Maximum achievable score heuristic: no quiz awards more than 1000 pts/question.
            var maxScore = storedQCount * 1000;
            if (score > maxScore) {
                logger.warn('[AsyncChallenge] Submit score ' + score + ' > maxPossible ' + maxScore + ' for session ' + sessionId);
                return JSON.stringify({ success: false, message: 'Score exceeds maximum possible for this quiz.', data: null, errorCode: 'SCORE_TAMPERED' });
            }
        }

        // ── State machine transition ──────────────────────────────────────────
        var submitData = { userId: userId, score: score, correctAnswers: correctAnswers, totalQuestions: totalQuestions, timeTaken: timeTaken };
        var submitEvent = isCreator ? AC_EVT_CREATOR_SUBMIT : AC_EVT_OPPONENT_SUBMIT;
        var submitTransition = asyncChallengeTransitionState(session, submitEvent, submitData);

        if (!submitTransition.ok) {
            return JSON.stringify({ success: false, message: submitTransition.error, data: null, errorCode: submitTransition.errorCode });
        }

        // ALREADY_SUBMITTED = idempotent success (score already in, no write needed)
        if (submitTransition.errorCode === 'ALREADY_SUBMITTED') {
            var alreadyResp = JSON.stringify({ success: true, message: 'Results already submitted', data: asyncChallengeSessionToUnityFormat(session, nk), errorCode: 'ALREADY_SUBMITTED' });
            asyncChallengeWriteIdempotency(nk, submitIdemKey, alreadyResp);
            return alreadyResp;
        }

        // ── OCC write ─────────────────────────────────────────────────────────
        try {
            nk.storageWrite([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: sessionId,
                userId: submitTransition.session.creatorId,
                value: submitTransition.session,
                version: submitVersion,
                permissionRead: 2,
                permissionWrite: 1
            }]);
        } catch (vErr) {
            // Version conflict — another write landed first (network retry or concurrent).
            var reRead = nk.storageRead([{ collection: COLLECTION_ASYNC_CHALLENGES, key: sessionId, userId: session.creatorId }]);
            var reSession = reRead.length > 0 ? reRead[0].value : null;
            var alreadyIn = reSession && ((isCreator && reSession.creatorCompleted) || (isOpponent && reSession.opponentCompleted));
            if (alreadyIn) {
                var alreadyInResp = JSON.stringify({ success: true, message: 'Results already submitted', data: asyncChallengeSessionToUnityFormat(reSession, nk), errorCode: 'ALREADY_SUBMITTED' });
                asyncChallengeWriteIdempotency(nk, submitIdemKey, alreadyInResp);
                return alreadyInResp;
            }
            logger.warn('[AsyncChallenge] Submit version conflict session=' + sessionId);
            return JSON.stringify({ success: false, message: 'Submission conflict — please try again.', data: null, errorCode: 'VERSION_CONFLICT' });
        }

        session = submitTransition.session;
        var shouldProcessRewards = submitTransition.shouldProcessRewards;

        // Process completion rewards only once (guarded by rewardsProcessed flag in state machine).
        if (shouldProcessRewards) {
            asyncChallengeProcessCompletion(nk, logger, session);
        }

        // Send notifications — subjects fixed so they make sense from the recipient's POV.
        if (isCreator && session.opponentId) {
            // Creator finished; notify the opponent who hasn't played yet.
            asyncChallengeSendNotification(ctx, nk, session.opponentId,
                'Your Opponent Has Played!',
                session.creatorName + ' scored ' + score + ' points — your turn!',
                {
                    type: 'opponent_completed',
                    sessionId: sessionId,
                    score: score,
                    name: session.creatorName || '',
                    shareCode: session.shareCode || ''
                }
            );
        } else if (isCreator && !session.opponentId) {
            // Creator played but nobody has joined yet — no notification to send.
            // The CREATOR_PLAYED status update above is the signal for anyone who polls.
        } else if (isOpponent) {
            // Both have now played — notify creator that final results are ready.
            asyncChallengeSendNotification(ctx, nk, session.creatorId,
                'Challenge Results Ready!',
                session.opponentName + ' scored ' + score + ' points — see who won!',
                {
                    type: 'results_ready',
                    sessionId: sessionId,
                    score: score,
                    name: session.opponentName || '',
                    shareCode: session.shareCode || ''
                }
            );
        }

        logger.info('[AsyncChallenge] Results submitted for session: ' + sessionId + ' by user: ' + userId + ' score: ' + score);

        // ── Knowledge Map history ─────────────────────────────────────────────
        // Append a per-quiz aggregate entry to the knowledge-map rolling window.
        // Uses the globalThis.__kmAppendHistory bridge registered by quiz_results.js
        // so this module has no hard dependency on it (graceful no-op if absent).
        //
        // Category resolution order (most to least specific):
        //   1. session.quizConfig.categoryName / topicName
        //   2. session.quizConfig.CategoryName / TopicName  (Unity PascalCase)
        //   3. session.quizModeName                          (mode as category)
        //   4. "general"                                     (guaranteed fallback)
        if (typeof globalThis.__kmAppendHistory === 'function') {
            try {
                var qc = (session && session.quizConfig) ? session.quizConfig : {};
                var kmCategoryName = qc.categoryName || qc.topicName
                                  || qc.CategoryName || qc.TopicName
                                  || (session && session.quizModeName) || null;
                var kmCategoryId   = qc.categoryId || qc.CategoryId || null;
                var kmGameId       = (session && session.gameId) ? session.gameId : 'quiz-verse';

                // Build lightweight data/result objects that match the shape
                // appendKnowledgeMapHistory expects from quiz_submit_result.
                var kmData = {
                    gameId:          kmGameId,
                    categoryName:    kmCategoryName,
                    categoryId:      kmCategoryId,
                    questionHistory: null          // per-question data not available here
                };
                var kmResult = {
                    timeTakenSeconds: timeTaken,
                    totalQuestions:   totalQuestions
                };
                var kmMetrics = {
                    accuracy: totalQuestions > 0
                        ? (correctAnswers / totalQuestions) * 100 : 0
                };

                globalThis.__kmAppendHistory(nk, logger, userId, kmData, kmResult, kmMetrics);
            } catch (kmErr) {
                logger.warn('[AsyncChallenge] KM history append failed (non-critical): ' + kmErr.message);
            }
        }

        var submitResp = JSON.stringify({
            success: true,
            message: 'Results submitted successfully',
            data: asyncChallengeSessionToUnityFormat(session, nk)
        });
        asyncChallengeWriteIdempotency(nk, submitIdemKey, submitResp);
        return submitResp;
    } catch (err) {
        logger.error('[AsyncChallenge] Submit error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_submit', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_list - List user's async challenges
// ============================================================================
/**
 * List user's async challenges
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { limit?, includeExpired?, status?, userId? }
 * @returns {string} JSON response with array of sessions
 */
function rpcAsyncChallengeList(ctx, logger, nk, payload) {
    var request = {};
    try {
        if (payload) {
            request = JSON.parse(payload);
        }
    } catch (e) {
        // Use defaults
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: [],
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        var limit = Math.min(request.limit || request.Limit || 20, 100);
        var includeExpired = request.includeExpired || request.IncludeExpired || false;
        var statusFilter = request.status !== undefined ? request.status : null;

        var rawSessions = []; // raw session storage objects (not yet formatted)
        var seenIds = {};
        var now = Date.now();

        // ── Step 1: Collect raw session objects ─────────────────────────────────

        // Creator sessions (storageList only returns items owned by this user, no code_ entries)
        var creatorSessions = nk.storageList(userId, COLLECTION_ASYNC_CHALLENGES, 200, '');
        var objects = creatorSessions.objects || [];
        for (var i = 0; i < objects.length; i++) {
            var obj = objects[i];
            if (obj.key.indexOf('code_') === 0) continue; // skip code mappings
            var s = obj.value;
            var st = typeof s.status === 'number' ? s.status : 0;
            var exp = st === ASYNC_STATUS_EXPIRED || now > s.expiresAt;
            if (!includeExpired && exp && st < ASYNC_STATUS_BOTH_COMPLETED) continue;
            if (statusFilter !== null && st !== statusFilter) continue;
            if (!seenIds[s.sessionId]) {
                seenIds[s.sessionId] = true;
                rawSessions.push(s);
            }
        }

        // Opponent sessions via index (O(1) per entry, single index read)
        try {
            var opponentIndexResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_INDEX,
                key: 'opponent_' + userId,
                userId: userId
            }]);
            var hasIndex = opponentIndexResults.length > 0 && (opponentIndexResults[0].value.sessions || []).length > 0;

            if (hasIndex) {
                var indexedSessions = opponentIndexResults[0].value.sessions;
                // Batch-read all indexed sessions in one call (max 100 keys per batch).
                var batchKeys = [];
                for (var j = 0; j < indexedSessions.length; j++) {
                    var e = indexedSessions[j];
                    if (!seenIds[e.sessionId]) {
                        batchKeys.push({ collection: COLLECTION_ASYNC_CHALLENGES, key: e.sessionId, userId: e.creatorId });
                    }
                }
                if (batchKeys.length > 0) {
                    var batchResults = nk.storageRead(batchKeys);
                    for (var br = 0; br < batchResults.length; br++) {
                        var bs = batchResults[br].value;
                        if (!bs || bs.opponentId !== userId) continue;
                        var bst = typeof bs.status === 'number' ? bs.status : 0;
                        var bexp = bst === ASYNC_STATUS_EXPIRED || now > bs.expiresAt;
                        if (!includeExpired && bexp && bst < ASYNC_STATUS_BOTH_COMPLETED) continue;
                        if (statusFilter !== null && bst !== statusFilter) continue;
                        if (!seenIds[bs.sessionId]) {
                            seenIds[bs.sessionId] = true;
                            rawSessions.push(bs);
                        }
                    }
                }
            } else {
                // SQL fallback for users who joined before the index was deployed.
                var sqlRows = nk.sqlQuery(
                    "SELECT value FROM storage WHERE collection = $1 AND value->>'opponentId' = $2 LIMIT $3",
                    [COLLECTION_ASYNC_CHALLENGES, userId, limit]
                );
                if (sqlRows && sqlRows.length > 0) {
                    for (var sq = 0; sq < sqlRows.length; sq++) {
                        var sqVal = typeof sqlRows[sq].value === 'string' ? JSON.parse(sqlRows[sq].value) : sqlRows[sq].value;
                        if (!sqVal || sqVal.opponentId !== userId) continue;
                        var sqSt = typeof sqVal.status === 'number' ? sqVal.status : 0;
                        var sqExp = sqSt === ASYNC_STATUS_EXPIRED || now > sqVal.expiresAt;
                        if (!includeExpired && sqExp && sqSt < ASYNC_STATUS_BOTH_COMPLETED) continue;
                        if (statusFilter !== null && sqSt !== statusFilter) continue;
                        if (!seenIds[sqVal.sessionId]) {
                            seenIds[sqVal.sessionId] = true;
                            rawSessions.push(sqVal);
                            // Backfill index so future calls are O(1).
                            try { asyncChallengeIndexOpponent(nk, userId, sqVal.sessionId, sqVal.creatorId); } catch (_) {}
                        }
                    }
                }
            }
        } catch (searchErr) {
            logger.warn('[AsyncChallenge] List opponent sessions error: ' + searchErr.message);
        }

        // ── Step 2: Sort + trim before expensive formatting ──────────────────────
        rawSessions.sort(function(a, b) { return (b.createdAt || 0) - (a.createdAt || 0); });
        if (rawSessions.length > limit) rawSessions = rawSessions.slice(0, limit);

        // ── Step 3: ONE batched user lookup for all unique player IDs ─────────────
        // Previously asyncChallengeSessionToUnityFormat did nk.usersGetId() per session,
        // meaning 20 sessions × 2 players = 40 serial Nakama user lookups.
        // We do it once here and inject names before calling the formatter (with nk=null
        // to skip the per-session lookup inside the formatter).
        var playerIdSet = {};
        for (var pi = 0; pi < rawSessions.length; pi++) {
            if (rawSessions[pi].creatorId)  playerIdSet[rawSessions[pi].creatorId]  = true;
            if (rawSessions[pi].opponentId) playerIdSet[rawSessions[pi].opponentId] = true;
        }
        var uniquePlayerIds = Object.keys(playerIdSet);
        var nameMap = {};
        if (uniquePlayerIds.length > 0) {
            try {
                var freshUsers = nk.usersGetId(uniquePlayerIds) || [];
                for (var fu = 0; fu < freshUsers.length; fu++) {
                    var fn = freshUsers[fu].displayName || freshUsers[fu].username || '';
                    if (fn) nameMap[freshUsers[fu].userId] = fn;
                }
            } catch (_) { /* non-fatal: fall back to snapshotted names */ }
        }

        // ── Step 4: Inject fresh names and format ────────────────────────────────
        var sessions = [];
        for (var fi = 0; fi < rawSessions.length; fi++) {
            var rs = rawSessions[fi];
            if (nameMap[rs.creatorId])  rs.creatorName  = nameMap[rs.creatorId];
            if (nameMap[rs.opponentId]) rs.opponentName = nameMap[rs.opponentId];
            // Pass nk=null to suppress the per-session usersGetId inside the formatter.
            sessions.push(asyncChallengeSessionToUnityFormat(rs, null));
        }

        return JSON.stringify({
            success: true,
            message: 'Challenges retrieved',
            data: sessions,
            total: sessions.length
        });
    } catch (err) {
        logger.error('[AsyncChallenge] List error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_list', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: [] });
    }
}

// ============================================================================
// RPC: async_challenge_cancel - Cancel an async challenge
// ============================================================================
/**
 * Cancel an async challenge session
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { sessionId, userId? }
 * @returns {string} JSON response with updated session data
 */
function rpcAsyncChallengeCancel(ctx, logger, nk, payload) {
    logger.debug('[AsyncChallenge] User ' + ctx.userId + ' cancelling challenge');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        var sessionId = request.sessionId || request.SessionId;
        if (!sessionId) {
            return JSON.stringify({
                success: false,
                message: 'Session ID required.',
                data: null
            });
        }

        // Try to read as owner first
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId
        }]);

        var creatorId = userId;

        // If not found as owner, use opponent index (O(1) instead of full scan)
        if (sessionResults.length === 0) {
            try {
                var indexResults = nk.storageRead([{
                    collection: COLLECTION_ASYNC_INDEX,
                    key: 'opponent_' + userId,
                    userId: userId
                }]);
                if (indexResults.length > 0) {
                    var oppIndex = indexResults[0].value;
                    for (var idx = 0; idx < oppIndex.sessions.length; idx++) {
                        if (oppIndex.sessions[idx].sessionId === sessionId) {
                            creatorId = oppIndex.sessions[idx].creatorId;
                            sessionResults = nk.storageRead([{
                                collection: COLLECTION_ASYNC_CHALLENGES,
                                key: sessionId,
                                userId: creatorId
                            }]);
                            break;
                        }
                    }
                }
            } catch (indexErr) {
                logger.warn('[AsyncChallenge] Cancel index lookup failed: ' + indexErr.message);
            }
        }

        // SQL fallback for old sessions without index entries
        if (sessionResults.length === 0) {
            var cancelFallback = asyncChallengeFindSessionByKey(nk, logger, sessionId);
            if (cancelFallback) {
                creatorId = cancelFallback.creatorId;
                sessionResults = [{ value: cancelFallback }];
            }
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Challenge not found.',
                data: null
            });
        }

        var session = sessionResults[0].value;
        var cancelVersion = sessionResults[0].version;

        // ── State machine transition ──────────────────────────────────────────
        var cancelTransition = asyncChallengeTransitionState(session, AC_EVT_CANCEL, { userId: userId });
        if (!cancelTransition.ok) {
            return JSON.stringify({ success: false, message: cancelTransition.error, data: null, errorCode: cancelTransition.errorCode });
        }
        session = cancelTransition.session;

        // ── OCC write ─────────────────────────────────────────────────────────
        try {
            nk.storageWrite([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: sessionId,
                userId: session.creatorId,
                value: session,
                version: cancelVersion,
                permissionRead: 2,
                permissionWrite: 1
            }]);
        } catch (cancelVErr) {
            logger.warn('[AsyncChallenge] Cancel version conflict session=' + sessionId);
            return JSON.stringify({ success: false, message: 'Conflict cancelling — please try again.', data: null, errorCode: 'VERSION_CONFLICT' });
        }

        // Delete the share code mapping so the 6-digit code space is freed and
        // re-joiners get a clear "not found" instead of a "challenge has been cancelled" surprise.
        if (session.shareCode) {
            try {
                nk.storageDelete([{
                    collection: COLLECTION_ASYNC_CHALLENGES,
                    key: 'code_' + session.shareCode,
                    userId: ASYNC_CHALLENGE_SYSTEM_USER
                }]);
            } catch (delErr) {
                logger.warn('[AsyncChallenge] Could not delete share code mapping: ' + delErr.message);
            }
        }

        // Notify opponent if any
        if (session.opponentId) {
            asyncChallengeSendNotification(ctx, nk, session.opponentId,
                'Challenge Cancelled',
                session.creatorName + ' has cancelled the ' + session.quizModeName + ' challenge.',
                {
                    type: 'challenge_cancelled',
                    sessionId: sessionId
                }
            );
        }

        logger.info('[AsyncChallenge] Session cancelled: ' + sessionId + ' by user: ' + userId);

        return JSON.stringify({
            success: true,
            message: 'Challenge cancelled successfully',
            data: asyncChallengeSessionToUnityFormat(session, nk)
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Cancel error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_cancel', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_leave - Opponent leaves the lobby before playing
// ============================================================================
/**
 * Opponent (joiner) voluntarily leaves a Phantom Arena room before any quiz
 * results have been submitted. Resets the session back to WaitingForOpponent
 * so the room becomes joinable again by a different player.
 *
 * Only the current opponent may call this. The creator uses cancel instead.
 *
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { sessionId, userId? }
 * @returns {string} JSON response with updated session data
 */
function rpcAsyncChallengeLeave(ctx, logger, nk, payload) {
    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({ success: false, message: userValidation.error, data: null, errorCode: 'AUTH_REQUIRED' });
        }
        var userId = userValidation.userId;

        var sessionId = asyncChallengeResolveSessionId(request);
        var payloadKeys = Object.keys(request).join(',');
        logger.debug('[AsyncChallenge] leave attempt user=' + userId + ' payloadKeys=' + payloadKeys +
            ' resolvedSessionId=' + (sessionId || 'MISSING'));

        if (!sessionId && (request.shareCode || request.ShareCode)) {
            var shareCode = (request.shareCode || request.ShareCode).toUpperCase().trim();
            var codeResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_CHALLENGES,
                key: 'code_' + shareCode,
                userId: ASYNC_CHALLENGE_SYSTEM_USER
            }]);
            if (codeResults.length > 0) {
                sessionId = codeResults[0].value.sessionId;
            }
        }

        if (!sessionId) {
            return JSON.stringify({ success: false, message: 'Session ID or share code required.', data: null });
        }

        // ── Locate session via opponent index (O(1)) ─────────────────────────
        var leaveCreatorId = null;
        var leaveResults   = [];

        try {
            var leaveIndexResults = nk.storageRead([{
                collection: COLLECTION_ASYNC_INDEX,
                key: 'opponent_' + userId,
                userId: userId
            }]);
            if (leaveIndexResults.length > 0) {
                var leaveOppIndex = leaveIndexResults[0].value;
                for (var li = 0; li < leaveOppIndex.sessions.length; li++) {
                    if (leaveOppIndex.sessions[li].sessionId === sessionId) {
                        leaveCreatorId = leaveOppIndex.sessions[li].creatorId;
                        leaveResults = nk.storageRead([{
                            collection: COLLECTION_ASYNC_CHALLENGES,
                            key: sessionId,
                            userId: leaveCreatorId
                        }]);
                        break;
                    }
                }
            }
        } catch (leaveIdxErr) {
            logger.warn('[AsyncChallenge] Leave index lookup failed: ' + leaveIdxErr.message);
        }

        // SQL fallback
        if (leaveResults.length === 0) {
            var leaveFallback = asyncChallengeFindSessionByKey(nk, logger, sessionId);
            if (leaveFallback) {
                leaveCreatorId = leaveFallback.creatorId;
                leaveResults = [{ value: leaveFallback }];
            }
        }

        if (leaveResults.length === 0) {
            logger.warn('[AsyncChallenge] leave noop reason=session_not_found session=' + sessionId + ' caller=' + userId);
            return JSON.stringify({ success: true, message: 'Session not found; nothing to leave.', data: null });
        }

        var leaveSession = leaveResults[0].value;
        var leaveVersion = leaveResults[0].version;

        if (leaveSession.opponentId !== userId) {
            if (leaveSession.opponentId) {
                logger.warn('[AsyncChallenge] leave noop reason=not_opponent session=' + sessionId +
                    ' caller=' + userId + ' currentOpponent=' + leaveSession.opponentId);
                return JSON.stringify({
                    success: false,
                    message: 'Not the current opponent.',
                    data: null,
                    errorCode: 'NOT_OPPONENT'
                });
            }
            logger.warn('[AsyncChallenge] leave noop reason=already_left session=' + sessionId + ' caller=' + userId);
            return JSON.stringify({
                success: true,
                message: 'Already left the challenge.',
                data: asyncChallengeSessionToUnityFormat(leaveSession, nk)
            });
        }

        var leavingOpponentName = leaveSession.opponentName || 'Player B';
        var commitResult = asyncChallengeCommitOpponentLeave(
            nk, logger, sessionId, leaveSession.creatorId, leaveSession, leaveVersion,
            userId, leavingOpponentName, 'explicit_leave'
        );

        if (!commitResult.ok) {
            if (commitResult.errorCode === 'VERSION_CONFLICT') {
                logger.warn('[AsyncChallenge] leave version_conflict session=' + sessionId + ' user=' + userId);
                var freshLeave = nk.storageRead([{
                    collection: COLLECTION_ASYNC_CHALLENGES,
                    key: sessionId,
                    userId: leaveSession.creatorId
                }]);
                if (freshLeave.length > 0 && freshLeave[0].value.opponentId !== userId) {
                    return JSON.stringify({ success: true, message: 'Already left the challenge.', data: null });
                }
                return JSON.stringify({
                    success: false,
                    message: commitResult.error,
                    data: null,
                    errorCode: 'VERSION_CONFLICT'
                });
            }
            logger.warn('[AsyncChallenge] leave transition fail session=' + sessionId +
                ' errorCode=' + commitResult.errorCode + ' msg=' + commitResult.error);
            return JSON.stringify({
                success: false,
                message: commitResult.error,
                data: null,
                errorCode: commitResult.errorCode
            });
        }

        return JSON.stringify({
            success: true,
            message: 'Left challenge lobby successfully',
            data: asyncChallengeSessionToUnityFormat(commitResult.session, nk)
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Leave error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_leave', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_stats - Get user's async challenge statistics
// ============================================================================
/**
 * Get user's async challenge statistics
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { targetUserId?, userId? }
 * @returns {string} JSON response with user stats
 */
function rpcAsyncChallengeStats(ctx, logger, nk, payload) {
    var request = {};
    try {
        if (payload) {
            request = JSON.parse(payload);
        }
    } catch (e) {
        // Use defaults
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        // Allow fetching other user's stats (for comparison)
        var targetUserId = request.targetUserId || request.TargetUserId || userId;

        var stats = asyncChallengeGetStats(nk, targetUserId);

        // Add computed fields
        var totalGames = stats.totalWins + stats.totalLosses + stats.totalDraws;
        stats.winRate = totalGames > 0 ? Math.round((stats.totalWins / totalGames) * 100) : 0;
        stats.gamesPlayed = totalGames;

        // Get display name
        stats.displayName = asyncChallengeGetDisplayName(nk, targetUserId, 'Unknown Player');

        return JSON.stringify({
            success: true,
            message: 'Stats retrieved',
            data: stats
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Stats error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_rematch - Create a rematch from a completed challenge
// ============================================================================
/**
 * Create a rematch from a completed challenge (swaps challenger/opponent roles)
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { sessionId, userId? }
 * @returns {string} JSON response with new session data
 */
function rpcAsyncChallengeRematch(ctx, logger, nk, payload) {
    logger.debug('[AsyncChallenge] User ' + ctx.userId + ' requesting rematch');

    var request;
    try {
        request = JSON.parse(payload || '{}');
    } catch (e) {
        return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null });
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: null,
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        var originalSessionId = request.sessionId || request.SessionId;
        if (!originalSessionId) {
            return JSON.stringify({
                success: false,
                message: 'Original session ID required.',
                data: null
            });
        }

        // Check active challenge limit
        var activeCount = asyncChallengeCountActive(nk, userId);
        if (activeCount >= ASYNC_CHALLENGE_MAX_PER_USER) {
            return JSON.stringify({
                success: false,
                message: 'Maximum active challenges reached. Complete or cancel existing challenges first.',
                data: null,
                errorCode: 'MAX_CHALLENGES'
            });
        }

        // Find the original session
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: originalSessionId,
            userId: userId
        }]);

        // If not found as owner, use opponent index (O(1) instead of full scan)
        if (sessionResults.length === 0) {
            try {
                var rematchIndexResults = nk.storageRead([{
                    collection: COLLECTION_ASYNC_INDEX,
                    key: 'opponent_' + userId,
                    userId: userId
                }]);
                if (rematchIndexResults.length > 0) {
                    var rematchIndex = rematchIndexResults[0].value;
                    for (var ridx = 0; ridx < rematchIndex.sessions.length; ridx++) {
                        if (rematchIndex.sessions[ridx].sessionId === originalSessionId) {
                            sessionResults = nk.storageRead([{
                                collection: COLLECTION_ASYNC_CHALLENGES,
                                key: originalSessionId,
                                userId: rematchIndex.sessions[ridx].creatorId
                            }]);
                            break;
                        }
                    }
                }
            } catch (rmIndexErr) {
                logger.warn('[AsyncChallenge] Rematch index lookup failed: ' + rmIndexErr.message);
            }
        }

        // SQL fallback for old sessions without index entries
        if (sessionResults.length === 0) {
            var rematchFallback = asyncChallengeFindSessionByKey(nk, logger, originalSessionId);
            if (rematchFallback) {
                sessionResults = [{ value: rematchFallback }];
            }
        }

        if (sessionResults.length === 0) {
            return JSON.stringify({
                success: false,
                message: 'Original challenge not found.',
                data: null
            });
        }

        var originalSession = sessionResults[0].value;

        // Verify user was part of original challenge
        var wasCreator = originalSession.creatorId === userId;
        var wasOpponent = originalSession.opponentId === userId;

        if (!wasCreator && !wasOpponent) {
            return JSON.stringify({
                success: false,
                message: 'Not authorized to create rematch for this challenge.',
                data: null
            });
        }

        // Must be completed to rematch
        if (originalSession.status !== ASYNC_STATUS_BOTH_COMPLETED) {
            return JSON.stringify({
                success: false,
                message: 'Can only rematch completed challenges.',
                data: null
            });
        }

        // Determine the opponent for rematch (the other player becomes challenged)
        var challengedUserId = wasCreator ? originalSession.opponentId : originalSession.creatorId;
        var challengedDisplayName = wasCreator ? originalSession.opponentName : originalSession.creatorName;

        // Generate new session
        var newSessionId = nk.uuidv4();
        var shareCode = asyncChallengeGenerateShareCode(nk);
        var now = Date.now();
        var expiresAt = now + (ASYNC_CHALLENGE_EXPIRY_HOURS * 60 * 60 * 1000);

        var creatorName = asyncChallengeGetDisplayName(nk, userId, 'Unknown');

        var newSessionStorage = {
            sessionId: newSessionId,
            shareCode: shareCode,
            quizModeType: originalSession.quizModeType,
            quizModeName: originalSession.quizModeName,
            quizConfig: originalSession.quizConfig,
            gameId: originalSession.gameId || '',
            creatorId: userId,
            creatorName: creatorName,
            opponentId: null,
            opponentName: null,
            challengedUserId: challengedUserId,
            challengedDisplayName: challengedDisplayName,
            status: ASYNC_STATUS_WAITING,
            createdAt: now,
            expiresAt: expiresAt,
            isRematch: true,
            originalSessionId: originalSessionId,
            // Creator results
            creatorCompleted: false,
            creatorScore: 0,
            creatorCorrectAnswers: 0,
            creatorTotalQuestions: 0,
            creatorTimeTaken: 0,
            creatorCompletedAt: 0,
            // Opponent results
            opponentCompleted: false,
            opponentScore: 0,
            opponentCorrectAnswers: 0,
            opponentTotalQuestions: 0,
            opponentTimeTaken: 0,
            opponentCompletedAt: 0
        };

        // Store new session
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: newSessionId,
            userId: userId,
            value: newSessionStorage,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        // Store share code mapping
        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: 'code_' + shareCode,
            userId: ASYNC_CHALLENGE_SYSTEM_USER,
            value: { sessionId: newSessionId, creatorId: userId },
            permissionRead: 2,
            permissionWrite: 0
        }]);

        // Notify challenged player
        asyncChallengeSendNotification(ctx, nk, challengedUserId,
            'Rematch Challenge!',
            creatorName + ' wants a rematch in ' + originalSession.quizModeName + '!',
            {
                type: 'rematch_requested',
                sessionId: newSessionId,
                shareCode: shareCode,
                challengerId: userId,
                challengerName: creatorName,
                quizModeName: originalSession.quizModeName,
                originalSessionId: originalSessionId
            }
        );

        logger.info('[AsyncChallenge] Rematch created: ' + newSessionId + ' from: ' + originalSessionId + ' by user: ' + userId);

        return JSON.stringify({
            success: true,
            message: 'Rematch challenge created',
            data: asyncChallengeSessionToUnityFormat(newSessionStorage, nk)
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Rematch error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_leaderboard - Get async challenge leaderboard
// ============================================================================
/**
 * Get async challenge leaderboard (top players by wins)
 * @param {object} ctx - Request context
 * @param {object} logger - Logger instance
 * @param {object} nk - Nakama runtime context
 * @param {string} payload - JSON payload: { limit?, sortBy?, userId? }
 * @returns {string} JSON response with leaderboard data
 */
function rpcAsyncChallengeLeaderboard(ctx, logger, nk, payload) {
    var request = {};
    try {
        if (payload) {
            request = JSON.parse(payload);
        }
    } catch (e) {
        // Use defaults
    }

    try {
        // Validate user
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({
                success: false,
                message: userValidation.error,
                data: [],
                errorCode: 'AUTH_REQUIRED'
            });
        }
        var userId = userValidation.userId;

        var limit = Math.min(request.limit || request.Limit || 20, 100);
        var sortBy = request.sortBy || request.SortBy || 'wins'; // wins, winRate, streak

        // Use SQL query instead of full collection scan — much more efficient
        // This queries the storage table directly with proper filtering and sorting
        var sortColumn;
        var sortExpression;
        if (sortBy === 'winRate') {
            // Win rate = wins / (wins + losses + draws) * 100
            sortExpression = "CASE WHEN (CAST(value->>'totalWins' AS INTEGER) + CAST(value->>'totalLosses' AS INTEGER) + CAST(value->>'totalDraws' AS INTEGER)) > 0 THEN CAST(value->>'totalWins' AS FLOAT) / (CAST(value->>'totalWins' AS INTEGER) + CAST(value->>'totalLosses' AS INTEGER) + CAST(value->>'totalDraws' AS INTEGER)) ELSE 0 END";
            sortColumn = 'win_rate';
        } else if (sortBy === 'streak') {
            sortExpression = "CAST(value->>'bestWinStreak' AS INTEGER)";
            sortColumn = 'best_streak';
        } else {
            sortExpression = "CAST(value->>'totalWins' AS INTEGER)";
            sortColumn = 'total_wins';
        }

        var leaderboard = [];
        try {
            var query = "SELECT value, user_id FROM storage " +
                "WHERE collection = $1 AND key LIKE 'stats_%' " +
                "AND (CAST(value->>'totalWins' AS INTEGER) + CAST(value->>'totalLosses' AS INTEGER) + CAST(value->>'totalDraws' AS INTEGER)) >= 3 " +
                "ORDER BY " + sortExpression + " DESC " +
                "LIMIT $2";

            var rows = nk.sqlQuery(query, [COLLECTION_ASYNC_STATS, limit]);

            for (var i = 0; i < rows.length; i++) {
                var row = rows[i];
                var stats;
                if (typeof row.value === 'string') {
                    stats = JSON.parse(row.value);
                } else {
                    stats = row.value;
                }
                stats.userId = stats.userId || row.user_id;
                stats.displayName = asyncChallengeGetDisplayName(nk, stats.userId, 'Unknown');
                var totalGames = (stats.totalWins || 0) + (stats.totalLosses || 0) + (stats.totalDraws || 0);
                stats.winRate = totalGames > 0 ? Math.round((stats.totalWins / totalGames) * 100) : 0;
                stats.gamesPlayed = totalGames;
                stats.rank = i + 1;
                stats.isCurrentUser = stats.userId === userId;
                leaderboard.push(stats);
            }
        } catch (sqlErr) {
            logger.warn('[AsyncChallenge] SQL leaderboard query failed, using fallback: ' + sqlErr.message);
            // Fallback: read only current user's friends stats instead of full scan
            // This is still bounded by friend count rather than total players
            try {
                var friendsList = nk.friendsList(userId, 500, 0, '');
                var friends = friendsList.friends || [];
                var readOps = [];
                for (var fi = 0; fi < friends.length; fi++) {
                    readOps.push({
                        collection: COLLECTION_ASYNC_STATS,
                        key: 'stats_' + friends[fi].user.userId,
                        userId: friends[fi].user.userId
                    });
                }
                // Also include current user
                readOps.push({
                    collection: COLLECTION_ASYNC_STATS,
                    key: 'stats_' + userId,
                    userId: userId
                });

                if (readOps.length > 0) {
                    var friendStats = nk.storageRead(readOps);
                    for (var fsi = 0; fsi < friendStats.length; fsi++) {
                        var fs = friendStats[fsi].value;
                        var fTotal = (fs.totalWins || 0) + (fs.totalLosses || 0) + (fs.totalDraws || 0);
                        if (fTotal >= 3) {
                            fs.displayName = asyncChallengeGetDisplayName(nk, fs.userId, 'Unknown');
                            fs.winRate = fTotal > 0 ? Math.round((fs.totalWins / fTotal) * 100) : 0;
                            fs.gamesPlayed = fTotal;
                            leaderboard.push(fs);
                        }
                    }
                    // Sort
                    if (sortBy === 'winRate') {
                        leaderboard.sort(function(a, b) { return b.winRate - a.winRate; });
                    } else if (sortBy === 'streak') {
                        leaderboard.sort(function(a, b) { return (b.bestWinStreak || 0) - (a.bestWinStreak || 0); });
                    } else {
                        leaderboard.sort(function(a, b) { return (b.totalWins || 0) - (a.totalWins || 0); });
                    }
                    // Apply limit and rank
                    leaderboard = leaderboard.slice(0, limit);
                    for (var rk = 0; rk < leaderboard.length; rk++) {
                        leaderboard[rk].rank = rk + 1;
                        leaderboard[rk].isCurrentUser = leaderboard[rk].userId === userId;
                    }
                }
            } catch (fallbackErr) {
                logger.error('[AsyncChallenge] Fallback leaderboard also failed: ' + fallbackErr.message);
            }
        }

        // Find current user's stats if not in top
        var currentUserRank = -1;
        var currentUserStats = null;
        for (var k = 0; k < leaderboard.length; k++) {
            if (leaderboard[k].userId === userId) {
                currentUserRank = leaderboard[k].rank;
                currentUserStats = leaderboard[k];
                break;
            }
        }

        // If current user not in leaderboard, fetch their stats separately
        if (!currentUserStats) {
            try {
                var myStats = nk.storageRead([{
                    collection: COLLECTION_ASYNC_STATS,
                    key: 'stats_' + userId,
                    userId: userId
                }]);
                if (myStats.length > 0) {
                    currentUserStats = myStats[0].value;
                    var myTotal = (currentUserStats.totalWins || 0) + (currentUserStats.totalLosses || 0) + (currentUserStats.totalDraws || 0);
                    currentUserStats.winRate = myTotal > 0 ? Math.round((currentUserStats.totalWins / myTotal) * 100) : 0;
                    currentUserStats.gamesPlayed = myTotal;
                    currentUserStats.displayName = asyncChallengeGetDisplayName(nk, userId, 'Unknown');
                    // Rank unknown when not in top results
                    currentUserStats.rank = -1;
                    currentUserRank = -1;
                }
            } catch (myStatsErr) {
                // User has no stats yet — that's fine
            }
        }

        return JSON.stringify({
            success: true,
            message: 'Leaderboard retrieved',
            data: {
                entries: leaderboard,
                currentUser: currentUserStats,
                currentUserRank: currentUserRank,
                totalPlayers: leaderboard.length,
                sortBy: sortBy
            }
        });
    } catch (err) {
        logger.error('[AsyncChallenge] Leaderboard error: ' + err.message);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// RPC: async_challenge_store_questions - Host stores fetched questions
// ============================================================================
function rpcAsyncChallengeStoreQuestions(ctx, logger, nk, payload) {
    var request;
    try { request = JSON.parse(payload || '{}'); }
    catch (e) { return JSON.stringify({ success: false, message: 'Invalid JSON payload', data: null }); }

    try {
        var userValidation = asyncChallengeValidateUser(ctx, request);
        if (!userValidation.valid) {
            return JSON.stringify({ success: false, message: userValidation.error, data: null });
        }
        var userId = userValidation.userId;

        var sessionId = request.sessionId || request.SessionId;
        if (!sessionId) {
            return JSON.stringify({ success: false, message: 'sessionId required', data: null });
        }

        var questions = request.questions;
        if (!questions || !Array.isArray(questions) || questions.length === 0) {
            return JSON.stringify({ success: false, message: 'questions array required', data: null });
        }

        // Read session — only creator (host) can store questions
        var sessionResults = nk.storageRead([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId
        }]);

        if (sessionResults.length === 0) {
            return JSON.stringify({ success: false, message: 'Session not found or not owner', data: null });
        }

        var session = sessionResults[0].value;

        // Authorization: only creator can store questions
        if (session.creatorId !== userId) {
            return JSON.stringify({ success: false, message: 'Only the challenge creator can store questions', data: null });
        }

        // Don't overwrite if already stored (idempotency guard)
        if (session.questions && session.questions.length > 0) {
            logger.debug('[AsyncChallenge] Questions already stored for session: ' + sessionId);
            return JSON.stringify({ success: true, message: 'Questions already stored', data: { count: session.questions.length, schemaVersion: (session.questionsSchema && session.questionsSchema.schemaVersion) || 1 } });
        }

        // Store questions in session.
        // questionsSchema is a parallel metadata blob (Gap 8 / cross-platform parity fix):
        //   schemaVersion 1 = legacy plain array (no schema tag, Unity compact q/o/c/e)
        //   schemaVersion 2 = tagged blob with explicit format field (2026-07-07+)
        // Existing clients ignore questionsSchema; new clients use it to select a parser.
        // The `format` field defaults to 'compact' (Unity shorthand); web sends 'verbose'
        // when it submits questions in question/options/correctIndex/explanation form.
        session.questions = questions;
        session.questionsSchema = {
            schemaVersion: 2,
            format:        request.format || request.Format || 'compact',
            storedAt:      new Date().toISOString(),
            count:         questions.length
        };

        nk.storageWrite([{
            collection: COLLECTION_ASYNC_CHALLENGES,
            key: sessionId,
            userId: userId,
            value: session,
            permissionRead: 2,
            permissionWrite: 1
        }]);

        logger.info('[AsyncChallenge] Stored ' + questions.length + ' questions for session: ' + sessionId);
        return JSON.stringify({ success: true, message: 'Questions stored', data: { count: questions.length } });
    } catch (err) {
        logger.error('[AsyncChallenge] StoreQuestions error: ' + err.message);
        logRpcError(nk, logger, 'async_challenge_store_questions', err.message, ctx.userId, null);
        return JSON.stringify({ success: false, message: err.message, data: null });
    }
}

// ============================================================================
// BADGES & COLLECTABLES SYSTEM
// Supports per-game badges and collectables with player tracking
// ============================================================================
var BADGE_COLLECTION = "badges";
var BADGE_PROGRESS_COLLECTION = "badge_progress";
var COLLECTABLE_COLLECTION = "collectables";
var COLLECTABLE_INVENTORY_COLLECTION = "collectable_inventory";
var BADGE_SYSTEM_USER_ID = "00000000-0000-0000-0000-000000000000";

var BADGE_CATEGORIES = {
    COMBAT: "combat",
    QUIZ: "quiz",
    SOCIAL: "social",
    STREAK: "streak",
    SPECIAL: "special",
    SEASONAL: "seasonal"
};

var RARITY_TIERS = {
    COMMON: "common",
    RARE: "rare",
    EPIC: "epic",
    LEGENDARY: "legendary"
};

/**
 * RPC: badges_get_all - Get all badges for a game with player progress
 */
function rpcBadgesGetAll(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');
        if (!data.game_id) {
            throw Error("game_id is required");
        }

        var userId = ctx.userId;
        var gameId = data.game_id;

        logger.info("[Badges] Getting all badges for game: " + gameId + ", user: " + userId);

        // Get badge definitions
        var definitionsKey = "definitions_" + gameId;
        var definitions = [];

        try {
            var defRecords = nk.storageRead([{
                collection: BADGE_COLLECTION,
                key: definitionsKey,
                userId: BADGE_SYSTEM_USER_ID
            }]);

            if (defRecords && defRecords.length > 0 && defRecords[0].value) {
                definitions = defRecords[0].value.badges || [];
            }
        } catch (err) {
            logger.warn("[Badges] No definitions found for game: " + gameId);
        }

        // Get player progress
        var progressKey = "progress_" + userId + "_" + gameId;
        var progress = {};

        try {
            var progRecords = nk.storageRead([{
                collection: BADGE_PROGRESS_COLLECTION,
                key: progressKey,
                userId: userId
            }]);

            if (progRecords && progRecords.length > 0 && progRecords[0].value) {
                progress = progRecords[0].value;
            }
        } catch (err) {
            logger.debug("[Badges] No progress found for user: " + userId);
        }

        // Merge definitions with progress
        var badges = [];
        for (var i = 0; i < definitions.length; i++) {
            var def = definitions[i];
            var prog = progress[def.badge_id] || {
                progress: 0,
                unlocked: false,
                unlock_date: null,
                displayed: false
            };

            // Hide secret badges if not unlocked
            if (def.hidden && !prog.unlocked) {
                badges.push({
                    badge_id: def.badge_id,
                    title: "???",
                    description: "Hidden badge",
                    icon_url: "badges/mystery.png",
                    category: def.category,
                    rarity: def.rarity,
                    progress: 0,
                    target: def.target,
                    unlocked: false,
                    hidden: true,
                    points: def.points,
                    order: def.order || 999
                });
            } else {
                badges.push({
                    badge_id: def.badge_id,
                    title: def.title,
                    description: def.description,
                    icon_url: def.icon_url,
                    category: def.category,
                    rarity: def.rarity,
                    type: def.type,
                    progress: prog.progress,
                    target: def.target,
                    unlocked: prog.unlocked,
                    unlock_date: prog.unlock_date,
                    displayed: prog.displayed,
                    rewards: def.rewards,
                    hidden: def.hidden || false,
                    points: def.points,
                    order: def.order || 999
                });
            }
        }

        // Sort by order, then by unlocked status
        badges.sort(function(a, b) {
            if (a.unlocked !== b.unlocked) return b.unlocked ? 1 : -1;
            return a.order - b.order;
        });

        // Calculate stats
        var totalPoints = 0;
        var unlockedPoints = 0;
        var unlockedCount = 0;

        for (var j = 0; j < badges.length; j++) {
            totalPoints += badges[j].points || 0;
            if (badges[j].unlocked) {
                unlockedPoints += badges[j].points || 0;
                unlockedCount++;
            }
        }

        return JSON.stringify({
            success: true,
            badges: badges,
            stats: {
                total_badges: badges.length,
                unlocked: unlockedCount,
                total_points: totalPoints,
                unlocked_points: unlockedPoints,
                completion_percentage: badges.length > 0
                    ? Math.round((unlockedCount / badges.length) * 100)
                    : 0
            }
        });

    } catch (err) {
        logger.error("[Badges] Get all error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * Grant badge rewards (coins, XP, items)
 */
function grantBadgeRewardsInternal(nk, logger, userId, gameId, rewards) {
    var granted = { coins: 0, xp: 0, items: [] };

    try {
        if (rewards.coins && rewards.coins > 0) {
            try {
                var walletUpdate = {};
                walletUpdate["coins"] = rewards.coins;
                nk.walletUpdate(userId, walletUpdate, { source: "badge_reward", game_id: gameId });
                granted.coins = rewards.coins;
                logger.info("[Badges] Granted " + rewards.coins + " coins to user: " + userId);
            } catch (walletErr) {
                logger.warn("[Badges] Wallet update failed: " + walletErr.message);
            }
        }

        if (rewards.xp && rewards.xp > 0) {
            try {
                var account = nk.accountGetId(userId);
                var metadata = account.user.metadata || {};
                metadata.total_xp = (metadata.total_xp || 0) + rewards.xp;
                nk.accountUpdateId(userId, null, null, null, null, null, null, metadata);
                granted.xp = rewards.xp;
            } catch (xpErr) {
                logger.warn("[Badges] XP grant failed: " + xpErr.message);
            }
        }

        if (rewards.collectables && rewards.collectables.length > 0) {
            for (var i = 0; i < rewards.collectables.length; i++) {
                granted.items.push(rewards.collectables[i]);
            }
        }

        return granted;
    } catch (err) {
        logger.error("[Badges] Reward grant error: " + err.message);
        return granted;
    }
}

/**
 * RPC: badges_update_progress - Update progress towards a badge
 */
function rpcBadgesUpdateProgress(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.badge_id || data.progress === undefined) {
            throw Error("game_id, badge_id, and progress are required");
        }

        var userId = ctx.userId;
        var gameId = data.game_id;
        var badgeId = data.badge_id;
        var newProgress = data.progress;
        var increment = data.increment || false;

        logger.info("[Badges] Updating progress for " + badgeId + ": " + newProgress);

        // Get badge definition
        var definitionsKey = "definitions_" + gameId;
        var badge = null;

        var defRecords = nk.storageRead([{
            collection: BADGE_COLLECTION,
            key: definitionsKey,
            userId: BADGE_SYSTEM_USER_ID
        }]);

        if (defRecords && defRecords.length > 0 && defRecords[0].value) {
            var definitions = defRecords[0].value.badges || [];
            for (var i = 0; i < definitions.length; i++) {
                if (definitions[i].badge_id === badgeId) {
                    badge = definitions[i];
                    break;
                }
            }
        }

        if (!badge) {
            throw Error("Badge not found: " + badgeId);
        }

        // Get or create progress record
        var progressKey = "progress_" + userId + "_" + gameId;
        var progressData = {};

        try {
            var progRecords = nk.storageRead([{
                collection: BADGE_PROGRESS_COLLECTION,
                key: progressKey,
                userId: userId
            }]);

            if (progRecords && progRecords.length > 0 && progRecords[0].value) {
                progressData = progRecords[0].value;
            }
        } catch (err) {
            logger.debug("[Badges] Creating new progress record");
        }

        // Initialize badge progress if doesn't exist
        if (!progressData[badgeId]) {
            progressData[badgeId] = {
                progress: 0,
                unlocked: false,
                unlock_date: null,
                displayed: false
            };
        }

        var badgeProgress = progressData[badgeId];

        // Don't update if already unlocked
        if (badgeProgress.unlocked) {
            return JSON.stringify({
                success: true,
                badge: {
                    badge_id: badgeId,
                    progress: badgeProgress.progress,
                    target: badge.target,
                    unlocked: true,
                    already_unlocked: true
                }
            });
        }

        // Update progress
        if (increment) {
            badgeProgress.progress += newProgress;
        } else {
            badgeProgress.progress = Math.max(badgeProgress.progress, newProgress);
        }

        // Check if unlocked
        var justUnlocked = false;
        if (badgeProgress.progress >= badge.target) {
            badgeProgress.unlocked = true;
            badgeProgress.unlock_date = new Date().toISOString();
            justUnlocked = true;

            logger.info("[Badges] Badge unlocked: " + badgeId + " for user: " + userId);

            try {
                nk.notificationsSend([{
                    userId: userId,
                    subject: "Badge Unlocked!",
                    content: {
                        type: "badge_unlocked",
                        badge_id: badgeId,
                        title: badge.title,
                        icon_url: badge.icon_url,
                        rarity: badge.rarity,
                        rewards: badge.rewards
                    },
                    code: 100,
                    persistent: true
                }]);
            } catch (notifErr) {
                logger.warn("[Badges] Failed to send notification: " + notifErr.message);
            }
        }

        // Save progress
        progressData[badgeId] = badgeProgress;

        nk.storageWrite([{
            collection: BADGE_PROGRESS_COLLECTION,
            key: progressKey,
            userId: userId,
            value: progressData,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Grant rewards if unlocked
        var rewardsGranted = null;
        if (justUnlocked && badge.rewards) {
            rewardsGranted = grantBadgeRewardsInternal(nk, logger, userId, gameId, badge.rewards);
        }

        return JSON.stringify({
            success: true,
            badge: {
                badge_id: badgeId,
                title: badge.title,
                progress: badgeProgress.progress,
                target: badge.target,
                unlocked: badgeProgress.unlocked,
                just_unlocked: justUnlocked,
                unlock_date: badgeProgress.unlock_date
            },
            rewards_granted: rewardsGranted
        });

    } catch (err) {
        logger.error("[Badges] Update progress error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: badges_check_event - Check and update badges based on a game event
 */
function rpcBadgesCheckEvent(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.event_type) {
            var __callerId = (ctx && ctx.userId) ? ctx.userId : "anonymous";
            logger.warn("[Badges] Check event missing required fields (caller=" + __callerId + " game_id=" + (data.game_id || "<missing>") + " event_type=" + (data.event_type || "<missing>") + ")");
            return JSON.stringify({
                success: false,
                error: "game_id and event_type are required"
            });
        }

        var userId = ctx.userId;
        var gameId = data.game_id;
        var eventType = data.event_type;
        var eventData = data.event_data || {};

        logger.info("[Badges] Checking event: " + eventType + " for game: " + gameId);

        // Get all badge definitions
        var definitionsKey = "definitions_" + gameId;
        var definitions = [];

        try {
            var defRecords = nk.storageRead([{
                collection: BADGE_COLLECTION,
                key: definitionsKey,
                userId: BADGE_SYSTEM_USER_ID
            }]);

            if (defRecords && defRecords.length > 0 && defRecords[0].value) {
                definitions = defRecords[0].value.badges || [];
            }
        } catch (err) {
            return JSON.stringify({
                success: true,
                badges_updated: [],
                badges_unlocked: [],
                message: "No badges configured"
            });
        }

        // Get player progress
        var progressKey = "progress_" + userId + "_" + gameId;
        var progressData = {};

        try {
            var progRecords = nk.storageRead([{
                collection: BADGE_PROGRESS_COLLECTION,
                key: progressKey,
                userId: userId
            }]);

            if (progRecords && progRecords.length > 0 && progRecords[0].value) {
                progressData = progRecords[0].value;
            }
        } catch (err) {
            // New player, no progress yet
        }

        var badgesUpdated = [];
        var badgesUnlocked = [];

        // Check each badge that matches this event
        for (var i = 0; i < definitions.length; i++) {
            var badge = definitions[i];

            // Skip if already unlocked
            if (progressData[badge.badge_id] && progressData[badge.badge_id].unlocked) {
                continue;
            }

            // Check if this badge matches the event
            if (badge.unlock_criteria && badge.unlock_criteria.event === eventType) {
                // Initialize progress if needed
                if (!progressData[badge.badge_id]) {
                    progressData[badge.badge_id] = {
                        progress: 0,
                        unlocked: false,
                        unlock_date: null,
                        displayed: false
                    };
                }

                var prog = progressData[badge.badge_id];
                var badgeIncrement = eventData.count || 1;
                prog.progress += badgeIncrement;

                badgesUpdated.push({
                    badge_id: badge.badge_id,
                    title: badge.title,
                    progress: prog.progress,
                    target: badge.target
                });

                // Check if unlocked
                if (prog.progress >= badge.target) {
                    prog.unlocked = true;
                    prog.unlock_date = new Date().toISOString();

                    badgesUnlocked.push({
                        badge_id: badge.badge_id,
                        title: badge.title,
                        icon_url: badge.icon_url,
                        rarity: badge.rarity,
                        rewards: badge.rewards
                    });

                    // Grant rewards
                    if (badge.rewards) {
                        grantBadgeRewardsInternal(nk, logger, userId, gameId, badge.rewards);
                    }

                    // Send notification
                    try {
                        nk.notificationsSend([{
                            userId: userId,
                            subject: "Badge Unlocked: " + badge.title,
                            content: {
                                type: "badge_unlocked",
                                badge_id: badge.badge_id,
                                title: badge.title,
                                icon_url: badge.icon_url,
                                rarity: badge.rarity
                            },
                            code: 100,
                            persistent: true
                        }]);
                    } catch (notifErr) {
                        logger.warn("[Badges] Notification error: " + notifErr.message);
                    }
                }

                progressData[badge.badge_id] = prog;
            }
        }

        // Save updated progress
        if (badgesUpdated.length > 0) {
            nk.storageWrite([{
                collection: BADGE_PROGRESS_COLLECTION,
                key: progressKey,
                userId: userId,
                value: progressData,
                permissionRead: 1,
                permissionWrite: 0
            }]);
        }

        return JSON.stringify({
            success: true,
            badges_updated: badgesUpdated,
            badges_unlocked: badgesUnlocked
        });

    } catch (err) {
        logger.error("[Badges] Check event error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: badges_set_displayed - Set which badge the player wants to display
 */
function rpcBadgesSetDisplayed(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.badge_id) {
            throw Error("game_id and badge_id are required");
        }

        var userId = ctx.userId;
        var gameId = data.game_id;
        var badgeId = data.badge_id;

        // Get progress
        var progressKey = "progress_" + userId + "_" + gameId;
        var progressData = {};

        var progRecords = nk.storageRead([{
            collection: BADGE_PROGRESS_COLLECTION,
            key: progressKey,
            userId: userId
        }]);

        if (progRecords && progRecords.length > 0 && progRecords[0].value) {
            progressData = progRecords[0].value;
        }

        // Check if badge is unlocked
        if (!progressData[badgeId] || !progressData[badgeId].unlocked) {
            throw Error("Badge not unlocked");
        }

        // Clear all displayed flags, set the new one
        for (var key in progressData) {
            if (progressData.hasOwnProperty(key)) {
                progressData[key].displayed = (key === badgeId);
            }
        }

        // Save
        nk.storageWrite([{
            collection: BADGE_PROGRESS_COLLECTION,
            key: progressKey,
            userId: userId,
            value: progressData,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Also update account metadata for quick access
        var account = nk.accountGetId(userId);
        var metadata = account.user.metadata || {};
        metadata.displayed_badge = badgeId;
        metadata.displayed_badge_game = gameId;

        nk.accountUpdateId(userId, null, null, null, null, null, null, metadata);

        return JSON.stringify({
            success: true,
            displayed_badge: badgeId
        });

    } catch (err) {
        logger.error("[Badges] Set displayed error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: badges_bulk_create - Create multiple badge definitions (Admin)
 */
function rpcBadgesBulkCreate(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.badges || !Array.isArray(data.badges)) {
            throw Error("game_id and badges array are required");
        }

        var gameId = data.game_id;
        var badgesToCreate = data.badges;
        var definitionsKey = "definitions_" + gameId;

        // Get existing definitions
        var definitions = { badges: [] };

        try {
            var records = nk.storageRead([{
                collection: BADGE_COLLECTION,
                key: definitionsKey,
                userId: BADGE_SYSTEM_USER_ID
            }]);

            if (records && records.length > 0 && records[0].value) {
                definitions = records[0].value;
            }
        } catch (err) {
            logger.debug("[Badges] Creating new definitions collection");
        }

        var created = [];
        var updated = [];
        var errors = [];

        for (var i = 0; i < badgesToCreate.length; i++) {
            var badgeData = badgesToCreate[i];

            try {
                if (!badgeData.badge_id || !badgeData.title) {
                    throw Error("badge_id and title are required");
                }

                // Check if exists
                var existingIndex = -1;
                for (var j = 0; j < definitions.badges.length; j++) {
                    if (definitions.badges[j].badge_id === badgeData.badge_id) {
                        existingIndex = j;
                        break;
                    }
                }

                var badge = {
                    badge_id: badgeData.badge_id,
                    game_id: gameId,
                    title: badgeData.title,
                    description: badgeData.description || "",
                    icon_url: badgeData.icon_url || "badges/default.png",
                    category: badgeData.category || "general",
                    rarity: badgeData.rarity || "common",
                    type: badgeData.type || "progressive",
                    target: badgeData.target || 1,
                    unlock_criteria: badgeData.unlock_criteria || null,
                    rewards: badgeData.rewards || { coins: 100 },
                    hidden: badgeData.hidden || false,
                    points: badgeData.points || 10,
                    order: badgeData.order || (definitions.badges.length + i + 1),
                    created_at: new Date().toISOString(),
                    updated_at: new Date().toISOString()
                };

                if (existingIndex >= 0) {
                    badge.created_at = definitions.badges[existingIndex].created_at;
                    definitions.badges[existingIndex] = badge;
                    updated.push(badge.badge_id);
                } else {
                    definitions.badges.push(badge);
                    created.push(badge.badge_id);
                }

            } catch (err) {
                errors.push({
                    badge_id: badgeData.badge_id,
                    error: err.message
                });
            }
        }

        // Save definitions
        if (created.length > 0 || updated.length > 0) {
            nk.storageWrite([{
                collection: BADGE_COLLECTION,
                key: definitionsKey,
                userId: BADGE_SYSTEM_USER_ID,
                value: definitions,
                permissionRead: 2,
                permissionWrite: 0
            }]);
        }

        logger.info("[Badges] Bulk create completed - created: " + created.length + ", updated: " + updated.length);

        return JSON.stringify({
            success: true,
            created: created,
            updated: updated,
            errors: errors,
            total_badges: definitions.badges.length
        });

    } catch (err) {
        logger.error("[Badges] Bulk create error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: collectables_get_all - Get all collectables for a game with player inventory
 */
function rpcCollectablesGetAll(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id) {
            throw Error("game_id is required");
        }

        var userId = ctx.userId;
        var gameId = data.game_id;

        logger.info("[Collectables] Getting all for game: " + gameId + ", user: " + userId);

        // Get collectable definitions
        var definitionsKey = "definitions_" + gameId;
        var definitions = [];

        try {
            var defRecords = nk.storageRead([{
                collection: COLLECTABLE_COLLECTION,
                key: definitionsKey,
                userId: BADGE_SYSTEM_USER_ID
            }]);

            if (defRecords && defRecords.length > 0 && defRecords[0].value) {
                definitions = defRecords[0].value.collectables || [];
            }
        } catch (err) {
            logger.warn("[Collectables] No definitions found for game: " + gameId);
        }

        // Get player inventory
        var inventoryKey = "inventory_" + userId + "_" + gameId;
        var inventory = {};

        try {
            var invRecords = nk.storageRead([{
                collection: COLLECTABLE_INVENTORY_COLLECTION,
                key: inventoryKey,
                userId: userId
            }]);

            if (invRecords && invRecords.length > 0 && invRecords[0].value) {
                inventory = invRecords[0].value;
            }
        } catch (err) {
            logger.debug("[Collectables] No inventory found for user: " + userId);
        }

        // Merge definitions with inventory
        var collectables = [];
        var ownedCount = 0;
        var totalCount = definitions.length;

        for (var i = 0; i < definitions.length; i++) {
            var def = definitions[i];
            var inv = inventory[def.collectable_id] || {
                quantity: 0,
                acquired_date: null,
                equipped: false
            };

            var owned = inv.quantity > 0;
            if (owned) ownedCount++;

            collectables.push({
                collectable_id: def.collectable_id,
                title: def.title,
                description: def.description,
                icon_url: def.icon_url,
                category: def.category,
                rarity: def.rarity,
                max_quantity: def.max_quantity,
                tradeable: def.tradeable,
                source: def.source,
                metadata: def.metadata,
                quantity: inv.quantity,
                owned: owned,
                acquired_date: inv.acquired_date,
                equipped: inv.equipped
            });
        }

        // Sort by owned status, then rarity, then name
        var rarityOrder = { legendary: 0, epic: 1, rare: 2, common: 3 };
        collectables.sort(function(a, b) {
            if (a.owned !== b.owned) return b.owned ? 1 : -1;
            var rarityDiff = (rarityOrder[a.rarity] || 3) - (rarityOrder[b.rarity] || 3);
            if (rarityDiff !== 0) return rarityDiff;
            return a.title.localeCompare(b.title);
        });

        return JSON.stringify({
            success: true,
            collectables: collectables,
            inventory_stats: {
                total_collectables: totalCount,
                owned: ownedCount,
                completion_percentage: totalCount > 0
                    ? Math.round((ownedCount / totalCount) * 100)
                    : 0
            }
        });

    } catch (err) {
        logger.error("[Collectables] Get all error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: collectables_grant - Grant a collectable to a player
 */
function rpcCollectablesGrant(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.collectable_id) {
            throw Error("game_id and collectable_id are required");
        }

        var userId = data.user_id || ctx.userId;
        var gameId = data.game_id;
        var collectableId = data.collectable_id;
        var quantity = data.quantity || 1;
        var source = data.source || "system";

        logger.info("[Collectables] Granting " + collectableId + " (x" + quantity + ") to user: " + userId);

        // Verify collectable exists
        var definitionsKey = "definitions_" + gameId;
        var collectable = null;

        var defRecords = nk.storageRead([{
            collection: COLLECTABLE_COLLECTION,
            key: definitionsKey,
            userId: BADGE_SYSTEM_USER_ID
        }]);

        if (defRecords && defRecords.length > 0 && defRecords[0].value) {
            var definitions = defRecords[0].value.collectables || [];
            for (var i = 0; i < definitions.length; i++) {
                if (definitions[i].collectable_id === collectableId) {
                    collectable = definitions[i];
                    break;
                }
            }
        }

        if (!collectable) {
            throw Error("Collectable not found: " + collectableId);
        }

        // Get or create inventory
        var inventoryKey = "inventory_" + userId + "_" + gameId;
        var inventory = {};

        try {
            var invRecords = nk.storageRead([{
                collection: COLLECTABLE_INVENTORY_COLLECTION,
                key: inventoryKey,
                userId: userId
            }]);

            if (invRecords && invRecords.length > 0 && invRecords[0].value) {
                inventory = invRecords[0].value;
            }
        } catch (err) {
            // New inventory
        }

        // Initialize if needed
        if (!inventory[collectableId]) {
            inventory[collectableId] = {
                quantity: 0,
                acquired_date: null,
                equipped: false,
                acquisition_history: []
            };
        }

        var item = inventory[collectableId];
        var isFirstAcquisition = item.quantity === 0;

        // Check max quantity
        var maxQty = collectable.max_quantity || 999;
        var newQuantity = Math.min(item.quantity + quantity, maxQty);
        var actualGranted = newQuantity - item.quantity;

        if (actualGranted <= 0) {
            return JSON.stringify({
                success: true,
                collectable_id: collectableId,
                quantity_granted: 0,
                current_quantity: item.quantity,
                at_max: true
            });
        }

        // Update inventory
        item.quantity = newQuantity;
        if (isFirstAcquisition) {
            item.acquired_date = new Date().toISOString();
        }
        if (!item.acquisition_history) {
            item.acquisition_history = [];
        }
        item.acquisition_history.push({
            date: new Date().toISOString(),
            quantity: actualGranted,
            source: source
        });

        inventory[collectableId] = item;

        // Save inventory
        nk.storageWrite([{
            collection: COLLECTABLE_INVENTORY_COLLECTION,
            key: inventoryKey,
            userId: userId,
            value: inventory,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Send notification for new collectables
        if (isFirstAcquisition) {
            try {
                nk.notificationsSend([{
                    userId: userId,
                    subject: "New Collectable!",
                    content: {
                        type: "collectable_acquired",
                        collectable_id: collectableId,
                        title: collectable.title,
                        icon_url: collectable.icon_url,
                        rarity: collectable.rarity
                    },
                    code: 101,
                    persistent: true
                }]);
            } catch (notifErr) {
                logger.warn("[Collectables] Notification error: " + notifErr.message);
            }
        }

        return JSON.stringify({
            success: true,
            collectable_id: collectableId,
            title: collectable.title,
            quantity_granted: actualGranted,
            current_quantity: newQuantity,
            is_new: isFirstAcquisition
        });

    } catch (err) {
        logger.error("[Collectables] Grant error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

/**
 * RPC: collectables_equip - Equip a collectable (e.g., profile frame)
 */
function rpcCollectablesEquip(ctx, logger, nk, payload) {
    try {
        var data = JSON.parse(payload || '{}');

        if (!data.game_id || !data.collectable_id) {
            throw Error("game_id and collectable_id are required");
        }

        var userId = ctx.userId;
        var gameId = data.game_id;
        var collectableId = data.collectable_id;

        // Get inventory
        var inventoryKey = "inventory_" + userId + "_" + gameId;
        var inventory = {};

        var invRecords = nk.storageRead([{
            collection: COLLECTABLE_INVENTORY_COLLECTION,
            key: inventoryKey,
            userId: userId
        }]);

        if (invRecords && invRecords.length > 0 && invRecords[0].value) {
            inventory = invRecords[0].value;
        }

        // Check if owned
        if (!inventory[collectableId] || inventory[collectableId].quantity <= 0) {
            throw Error("Collectable not owned");
        }

        // Get collectable definition for category
        var definitionsKey = "definitions_" + gameId;
        var collectable = null;
        var definitions = [];

        var defRecords = nk.storageRead([{
            collection: COLLECTABLE_COLLECTION,
            key: definitionsKey,
            userId: BADGE_SYSTEM_USER_ID
        }]);

        if (defRecords && defRecords.length > 0 && defRecords[0].value) {
            definitions = defRecords[0].value.collectables || [];
            for (var i = 0; i < definitions.length; i++) {
                if (definitions[i].collectable_id === collectableId) {
                    collectable = definitions[i];
                    break;
                }
            }
        }

        if (!collectable) {
            throw Error("Collectable definition not found");
        }

        // Unequip any other items in the same category
        for (var key in inventory) {
            if (inventory.hasOwnProperty(key) && inventory[key].equipped) {
                for (var j = 0; j < definitions.length; j++) {
                    if (definitions[j].collectable_id === key &&
                        definitions[j].category === collectable.category) {
                        inventory[key].equipped = false;
                    }
                }
            }
        }

        // Equip the selected item
        inventory[collectableId].equipped = true;
        inventory[collectableId].equipped_date = new Date().toISOString();

        // Save inventory
        nk.storageWrite([{
            collection: COLLECTABLE_INVENTORY_COLLECTION,
            key: inventoryKey,
            userId: userId,
            value: inventory,
            permissionRead: 1,
            permissionWrite: 0
        }]);

        // Update account metadata for quick profile access
        var account = nk.accountGetId(userId);
        var metadata = account.user.metadata || {};

        if (!metadata.equipped_collectables) {
            metadata.equipped_collectables = {};
        }
        metadata.equipped_collectables[collectable.category] = {
            collectable_id: collectableId,
            icon_url: collectable.icon_url,
            game_id: gameId
        };

        nk.accountUpdateId(userId, null, null, null, null, null, null, metadata);

        return JSON.stringify({
            success: true,
            equipped: collectableId,
            category: collectable.category
        });

    } catch (err) {
        logger.error("[Collectables] Equip error: " + err.message);
        return JSON.stringify({
            success: false,
            error: err.message
        });
    }
}

