        var storage = nk.storageRead([{ collection: 'cross_game_messages', key: 'inbox', userId: ctx.userId }]);
        var inbox = (storage && storage.length > 0) ? JSON.parse(storage[0].value) : { messages: [] };
        var msgs = inbox.messages || [];
