        logAdminAudit(nk, ctx, "satori_experiment_setup", { id: data.id, gameId: gameId || Constants.DEFAULT_GAME_ID, key: key }, { action: action });
        return RpcHelpers.successResponse({ experiment: newExp, action: action });
