                        timestamp: parseInt("" + (v.timestamp || 0), 10) || 0,
                        correctAnswers: parseInt("" + (v.correctAnswers || 0), 10) || 0,
                        totalQuestions: parseInt("" + (v.totalQuestions || 0), 10) || 0,
                        category: "" + (v.category || ""),
