        var types = ["fortune", "emoji", "prediction", "health", "personal_finance"];
        var langs = ["en", "ar", "de", "es", "fr", "hi", "id", "ja", "ko", "pt", "ru", "zh-Hans", "zu"];
        // Per-(type,lang) signature = weekId|themeId; skip pushing when unchanged.
        var changedByType = {};
