                        coins: bcBalance,
                        unix_ts: wallet.updated_at,
                        date: new Date().toISOString().slice(0, 10),
                        source: "wallet_guest_sync",
                        trace_id: data.trace_id || null,
                        idempotency_key: idemKey,
                        guest_wallet_id: guestWalletId,
