        fields.push({
            name: "🔗 Source citation",
            value: "`storage://" + SAMPLE_COLLECTION + "` window " +
                new Date(slotStartMs).toISOString() + "..." + new Date(slotEndMs).toISOString(),
            inline: false,
        });
