            title: "🎮 Nakama RPC Summary — last 3h",
            description: "Aggregated analytics across all Nakama RPCs.",
            color: color,
            timestamp: new Date().toISOString(),
            footer: { text: "Pod " + podId + " · slot " + new Date(slotStartMs).toISOString() },
