            return [];
        var out = [];
        for (var i = 0; i < rounds.length; i++) {
            var round = rounds[i];
            if (!round)
                continue;
            var ans = String(round.answer || "").trim();
            if (!ans)
                continue;
            out.push({
                question: String(round.question || ("Question " + (i + 1))).trim(),
                answer: ans,
                acceptedAnswers: Array.isArray(round.acceptedAnswers) ? round.acceptedAnswers : undefined,
            });
        }
        return out;
