            return [];
        var out = llmGenerateQuestions(ctx, nk, logger, basis, topic || title || "video", mode, count);
        for (var i = 0; i < out.length; i++) {
            out[i].citation = videoUrl ? ("YouTube — " + videoUrl + (title ? " ('" + title + "')" : "")) : out[i].citation;
        }
        return out;
