            idempotency_key: idempotencyKey,
            tournament_slug: slug,
            pack_id: packId,
            user_id: userId,
            answers_count: total,
            score: effectiveScore,
            correct: correct,
            total: total,
            latency_ms: latencyMs,
            duration_ms: durationMs,
