                appId: data.appId,
                templateId: data.templateId,
                name: data.name || data.templateId,
                packId: data.packId,
                assets: data.assets || {},
                spawnPoint: data.spawnPoint ? validateVec3(data.spawnPoint, "spawnPoint") : { x: 0, y: 0, z: 0 },
                checkpoints: checkpoints,
                scavengerVolumes: volumes,
