                score: session.score,
                correctCount: session.correctCount,
                wrongCount: session.wrongCount,
                objectsFound: session.objectsFound.length,
                totalObjects: session.objects.length,
                durationMs: entry.durationMs,
                rank: rank,
                reward: reward
